import React, { useEffect, useState } from 'react';
import { supabase } from '../supabaseClient';
import { Guru } from '../types';

interface CrudGuruProps {
  showToast: (msg: string, type: 'success' | 'error') => void;
}

export const CrudGuru: React.FC<CrudGuruProps> = ({ showToast }) => {
  const [data, setData] = useState<Guru[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Guru>>({});
  const [isEditing, setIsEditing] = useState(false);

  const fetchData = async () => {
    try {
      const { data: guruData, error } = await supabase
        .from('guru')
        .select('*')
        .order('nama', { ascending: true });

      if (error) throw error;
      setData(guruData || []);
    } catch (error) {
      showToast('Gagal memuat data guru', 'error');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();

    // Realtime subscription
    const channel = supabase
      .channel('guru_changes')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'guru' }, () => {
        fetchData();
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
     // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleDelete = async (id: string) => {
    if (!window.confirm('Yakin ingin menghapus data ini?')) return;

    try {
      const { error } = await supabase.from('guru').delete().eq('id', id);
      if (error) throw error;
      showToast('Data guru berhasil dihapus', 'success');
    } catch (error) {
      showToast('Gagal menghapus data', 'error');
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (isEditing && formData.id) {
        // Update
        const { error } = await supabase
          .from('guru')
          .update({
            nip: formData.nip,
            nama: formData.nama,
            jenis_kelamin: formData.jenis_kelamin,
            no_hp: formData.no_hp,
            username: formData.username,
            password: formData.password, // In a real app, handle carefully
            peran: formData.peran
          })
          .eq('id', formData.id);
        if (error) throw error;
        showToast('Guru berhasil diperbarui', 'success');
      } else {
        // Create
        const { error } = await supabase
          .from('guru')
          .insert([{
            nip: formData.nip,
            nama: formData.nama,
            jenis_kelamin: formData.jenis_kelamin,
            no_hp: formData.no_hp,
            username: formData.username,
            password: formData.password,
            peran: formData.peran || 'GURU_WALI'
          }]);
        if (error) throw error;
        showToast('Guru berhasil ditambahkan', 'success');
      }
      setIsModalOpen(false);
      setFormData({});
    } catch (error: any) {
        const msg = error.code === '23505' ? 'Username sudah digunakan' : 'Gagal menyimpan data';
        showToast(msg, 'error');
    }
  };

  const openModal = (guru?: Guru) => {
    if (guru) {
      setIsEditing(true);
      setFormData(guru);
    } else {
      setIsEditing(false);
      setFormData({ peran: 'GURU_WALI', jenis_kelamin: 'L' });
    }
    setIsModalOpen(true);
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-gray-800">Manajemen Guru</h2>
        <button
          onClick={() => openModal()}
          className="bg-primary text-white px-4 py-2 rounded hover:bg-secondary transition"
        >
          + Tambah Guru
        </button>
      </div>

      {loading ? (
        <p>Memuat data...</p>
      ) : (
        <div className="bg-white shadow overflow-x-auto rounded-lg">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Nama / NIP</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">L/P</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">No HP</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Akun</th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">Aksi</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {data.map((guru) => (
                <tr key={guru.id}>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="text-sm font-medium text-gray-900">{guru.nama}</div>
                    <div className="text-sm text-gray-500">{guru.nip || '-'}</div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{guru.jenis_kelamin}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{guru.no_hp}</td>
                  <td className="px-6 py-4 whitespace-nowrap">
                     <div className="text-sm text-gray-900">{guru.username}</div>
                     <span className={`text-xs inline-flex px-2 py-1 rounded-full ${guru.peran === 'ADMIN' ? 'bg-purple-100 text-purple-800' : 'bg-green-100 text-green-800'}`}>
                        {guru.peran}
                     </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                    <button onClick={() => openModal(guru)} className="text-indigo-600 hover:text-indigo-900 mr-4">Edit</button>
                    <button onClick={() => handleDelete(guru.id)} className="text-red-600 hover:text-red-900">Hapus</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* Modal Form */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg shadow-lg w-full max-w-lg p-6 max-h-[90vh] overflow-y-auto">
            <h3 className="text-lg font-bold mb-4">{isEditing ? 'Edit Guru' : 'Tambah Guru'}</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700">NIP</label>
                  <input
                    type="text"
                    value={formData.nip || ''}
                    onChange={(e) => setFormData({ ...formData, nip: e.target.value })}
                    className="mt-1 block w-full border border-gray-300 rounded-md p-2 shadow-sm focus:ring-primary focus:border-primary"
                  />
                </div>
                <div>
                   <label className="block text-sm font-medium text-gray-700">Peran</label>
                   <select
                      value={formData.peran || 'GURU_WALI'}
                      onChange={(e) => setFormData({ ...formData, peran: e.target.value })}
                      className="mt-1 block w-full border border-gray-300 rounded-md p-2"
                   >
                     <option value="GURU_WALI">Guru Wali</option>
                     <option value="ADMIN">Admin</option>
                   </select>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700">Nama Lengkap *</label>
                <input
                  type="text"
                  required
                  value={formData.nama || ''}
                  onChange={(e) => setFormData({ ...formData, nama: e.target.value })}
                  className="mt-1 block w-full border border-gray-300 rounded-md p-2 shadow-sm focus:ring-primary focus:border-primary"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700">Jenis Kelamin</label>
                  <select
                    value={formData.jenis_kelamin || 'L'}
                    onChange={(e) => setFormData({ ...formData, jenis_kelamin: e.target.value as 'L' | 'P' })}
                    className="mt-1 block w-full border border-gray-300 rounded-md p-2 shadow-sm"
                  >
                    <option value="L">Laki-laki</option>
                    <option value="P">Perempuan</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700">No HP</label>
                  <input
                    type="text"
                    value={formData.no_hp || ''}
                    onChange={(e) => setFormData({ ...formData, no_hp: e.target.value })}
                    className="mt-1 block w-full border border-gray-300 rounded-md p-2 shadow-sm"
                  />
                </div>
              </div>

              <div className="border-t pt-4 mt-4">
                <p className="text-xs text-gray-500 mb-2">Informasi Login</p>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700">Username *</label>
                    <input
                      type="text"
                      required
                      value={formData.username || ''}
                      onChange={(e) => setFormData({ ...formData, username: e.target.value })}
                      className="mt-1 block w-full border border-gray-300 rounded-md p-2 shadow-sm"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700">Password *</label>
                    <input
                      type="text"
                      required={!isEditing}
                      value={formData.password || ''}
                      onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                      placeholder={isEditing ? 'Isi untuk ubah password' : ''}
                      className="mt-1 block w-full border border-gray-300 rounded-md p-2 shadow-sm"
                    />
                  </div>
                </div>
              </div>

              <div className="flex justify-end space-x-3 pt-4">
                <button
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="px-4 py-2 bg-gray-200 text-gray-700 rounded hover:bg-gray-300"
                >
                  Batal
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-primary text-white rounded hover:bg-secondary"
                >
                  Simpan
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../supabaseClient';
import { Siswa, Kelas } from '../types';

interface CrudSiswaProps {
  showToast: (msg: string, type: 'success' | 'error') => void;
}

export const CrudSiswa: React.FC<CrudSiswaProps> = ({ showToast }) => {
  const [data, setData] = useState<Siswa[]>([]);
  const [kelasOptions, setKelasOptions] = useState<Kelas[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Siswa>>({});
  const [isEditing, setIsEditing] = useState(false);

  const fetchData = async () => {
    try {
      // Fetch Siswa with Kelas info (Join)
      const { data: siswaData, error: siswaError } = await supabase
        .from('siswa')
        .select('*, kelas(nama)')
        .order('nama', { ascending: true });

      if (siswaError) throw siswaError;
      // @ts-ignore - Supabase type inference for join is tricky here without generated types
      setData(siswaData || []);

      // Fetch Kelas options
      const { data: kelasData, error: kelasError } = await supabase
        .from('kelas')
        .select('*')
        .order('nama', { ascending: true });

      if (kelasError) throw kelasError;
      setKelasOptions(kelasData || []);

    } catch (error) {
      showToast('Gagal memuat data', 'error');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();

    const channel = supabase
      .channel('siswa_changes')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'siswa' }, () => {
        fetchData();
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
     // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleDelete = async (id: string) => {
    if (!window.confirm('Yakin ingin menghapus siswa ini?')) return;
    try {
      const { error } = await supabase.from('siswa').delete().eq('id', id);
      if (error) throw error;
      showToast('Siswa berhasil dihapus', 'success');
    } catch (error) {
      showToast('Gagal menghapus siswa', 'error');
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const payload = {
        nisn: formData.nisn,
        nama: formData.nama,
        jenis_kelamin: formData.jenis_kelamin,
        tanggal_lahir: formData.tanggal_lahir,
        no_hp: formData.no_hp,
        id_kelas: formData.id_kelas === '' ? null : formData.id_kelas
    };

    try {
      if (isEditing && formData.id) {
        const { error } = await supabase.from('siswa').update(payload).eq('id', formData.id);
        if (error) throw error;
        showToast('Siswa diperbarui', 'success');
      } else {
        const { error } = await supabase.from('siswa').insert([payload]);
        if (error) throw error;
        showToast('Siswa ditambahkan', 'success');
      }
      setIsModalOpen(false);
      setFormData({});
    } catch (error: any) {
        const msg = error.code === '23505' ? 'NISN sudah digunakan' : 'Gagal menyimpan data';
        showToast(msg, 'error');
    }
  };

  const openModal = (siswa?: Siswa) => {
    if (siswa) {
      setIsEditing(true);
      setFormData(siswa);
    } else {
      setIsEditing(false);
      setFormData({ jenis_kelamin: 'L', id_kelas: '' });
    }
    setIsModalOpen(true);
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-gray-800">Manajemen Siswa</h2>
        <button
          onClick={() => openModal()}
          className="bg-primary text-white px-4 py-2 rounded hover:bg-secondary transition"
        >
          + Tambah Siswa
        </button>
      </div>

      {loading ? (
        <p>Memuat data...</p>
      ) : (
        <div className="bg-white shadow overflow-x-auto rounded-lg">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Nama / NISN</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Kelas</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">L/P</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Tgl Lahir</th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">Aksi</th>
              </tr>
