import React, { useEffect, useState } from 'react';
import { supabase } from '../supabaseClient';
import { Kelas } from '../types';

interface CrudKelasProps {
  showToast: (msg: string, type: 'success' | 'error') => void;
}

export const CrudKelas: React.FC<CrudKelasProps> = ({ showToast }) => {
  const [data, setData] = useState<Kelas[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Kelas>>({});
  const [isEditing, setIsEditing] = useState(false);

  const fetchData = async () => {
    try {
      const { data: kelasData, error } = await supabase.from('kelas').select('*').order('nama', { ascending: true });
      if (error) throw error;
      setData(kelasData || []);
    } catch (error) {
      showToast('Gagal memuat data kelas', 'error');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
    const channel = supabase
      .channel('kelas_changes')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'kelas' }, () => fetchData())
      .subscribe();
    return () => { supabase.removeChannel(channel); };
     // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleDelete = async (id: string) => {
    if (!window.confirm('Hapus kelas? Perhatian: Siswa di kelas ini akan kehilangan referensi kelas.')) return;
    try {
      const { error } = await supabase.from('kelas').delete().eq('id', id);
      if (error) throw error;
      showToast('Kelas dihapus', 'success');
    } catch (error) {
      showToast('Gagal menghapus (mungkin masih ada siswa terkait)', 'error');
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (isEditing && formData.id) {
        const { error } = await supabase.from('kelas').update({ kode: formData.kode, nama: formData.nama }).eq('id', formData.id);
        if (error) throw error;
        showToast('Kelas diperbarui', 'success');
      } else {
        const { error } = await supabase.from('kelas').insert([{ kode: formData.kode, nama: formData.nama }]);
        if (error) throw error;
        showToast('Kelas ditambahkan', 'success');
      }
      setIsModalOpen(false);
      setFormData({});
    } catch (error: any) {
       const msg = error.code === '23505' ? 'Kode kelas sudah digunakan' : 'Gagal menyimpan data';
       showToast(msg, 'error');
    }
  };

  const openModal = (item?: Kelas) => {
    if (item) { setIsEditing(true); setFormData(item); }
    else { setIsEditing(false); setFormData({}); }
    setIsModalOpen(true);
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-gray-800">Manajemen Kelas</h2>
        <button onClick={() => openModal()} className="bg-primary text-white px-4 py-2 rounded hover:bg-secondary transition">+ Tambah Kelas</button>
      </div>

      {loading ? <p>Memuat data...</p> : (
        <div className="bg-white shadow overflow-hidden rounded-lg">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Kode</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Nama Kelas</th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">Aksi</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {data.map((item) => (
                <tr key={item.id}>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900 font-bold">{item.kode}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">{item.nama}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                    <button onClick={() => openModal(item)} className="text-indigo-600 hover:text-indigo-900 mr-4">Edit</button>
                    <button onClick={() => handleDelete(item.id)} className="text-red-600 hover:text-red-900">Hapus</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg shadow-lg w-full max-w-md p-6">
            <h3 className="text-lg font-bold mb-4">{isEditing ? 'Edit Kelas' : 'Tambah Kelas'}</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700">Kode Kelas (Unik) *</label>
                <input
                  type="text"
                  required
                  value={formData.kode || ''}
                  onChange={(e) => setFormData({ ...formData, kode: e.target.value })}
                  placeholder="Contoh: X-IPA-1"
                  className="mt-1 block w-full border border-gray-300 rounded-md p-2 shadow-sm"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700">Nama Kelas *</label>
                <input
                  type="text"
                  required
                  value={formData.nama || ''}
                  onChange={(e) => setFormData({ ...formData, nama: e.target.value })}
                  placeholder="Contoh: Sepuluh IPA Satu"
                  className="mt-1 block w-full border border-gray-300 rounded-md p-2 shadow-sm"
                />
              </div>
              <div className="flex justify-end space-x-3 pt-4">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 bg-gray-200 text-gray-700 rounded">Batal</button>
                <button type="submit" className="px-4 py-2 bg-primary text-white rounded hover:bg-secondary">Simpan</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

