import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Login } from './components/Login';
import { CrudGuru } from './components/CrudGuru';
import { CrudSiswa } from './components/CrudSiswa';
import { CrudKelas } from './components/CrudKelas';
import { CrudMapel } from './components/CrudMapel';
import { Toast } from './components/Toast';
import { Guru, ViewState } from './types';

function App() {
  const [session, setSession] = useState<Guru | null>(null);
  const [currentView, setCurrentView] = useState<ViewState>('DASHBOARD');
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

  useEffect(() => {
    // Check localStorage for persisted session
    const storedUser = localStorage.getItem('gurwal_admin_user');
    if (storedUser) {
      try {
        setSession(JSON.parse(storedUser));
      } catch (e) {
        localStorage.removeItem('gurwal_admin_user');
      }
    }
  }, []);

  const handleLoginSuccess = (user: Guru) => {
    setSession(user);
    localStorage.setItem('gurwal_admin_user', JSON.stringify(user));
    setCurrentView('DASHBOARD');
  };

  const handleLogout = () => {
    setSession(null);
    localStorage.removeItem('gurwal_admin_user');
    showToast('Anda telah keluar', 'success');
  };

  const showToast = (message: string, type: 'success' | 'error') => {
    setToast({ message, type });
  };

  // Render Logic
  if (!session) {
    return (
      <>
        <Login onLoginSuccess={handleLoginSuccess} showToast={showToast} />
        {toast && (
          <Toast
            message={toast.message}
            type={toast.type}
            onClose={() => setToast(null)}
          />
        )}
      </>
    );
  }

  const renderContent = () => {
    switch (currentView) {
      case 'GURU':
        return <CrudGuru showToast={showToast} />;
      case 'SISWA':
        return <CrudSiswa showToast={showToast} />;
      case 'KELAS':
        return <CrudKelas showToast={showToast} />;
      case 'MAPEL':
        return <CrudMapel showToast={showToast} />;
      case 'DASHBOARD':
      default:
        return (
          <div className="p-4">
             <h2 className="text-3xl font-bold text-gray-800 mb-6">Dashboard</h2>
             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
               {/* Quick Stats Cards Placeholder */}
               <div className="bg-white p-6 rounded-lg shadow border-l-4 border-indigo-500">
                  <h3 className="text-gray-500 text-sm font-medium">Total Modul</h3>
                  <p className="text-2xl font-bold text-gray-800 mt-1">4 Aktif</p>
                  <p className="text-xs text-gray-400 mt-2">Guru, Siswa, Kelas, Mapel</p>
               </div>
               <div className="bg-white p-6 rounded-lg shadow border-l-4 border-green-500">
                  <h3 className="text-gray-500 text-sm font-medium">Status System</h3>
                  <p className="text-2xl font-bold text-green-600 mt-1">Online</p>
                  <p className="text-xs text-gray-400 mt-2">Supabase Connected</p>
               </div>
             </div>
             <div className="mt-8 bg-blue-50 p-6 rounded-lg border border-blue-100">
                <h3 className="text-lg font-semibold text-blue-800">Selamat Datang di GurWal v1.0</h3>
                <p className="text-blue-600 mt-2">
                  Silakan gunakan menu di sidebar sebelah kiri untuk mengelola data Guru, Siswa, Kelas, dan Mata Pelajaran.
                  Semua perubahan data akan tersimpan secara otomatis dan realtime.
                </p>
             </div>
          </div>
        );
    }
  };

  return (
    <Layout
      currentUser={session}
      currentView={currentView}
      onChangeView={setCurrentView}
      onLogout={handleLogout}
    >
      {renderContent()}
      {toast && (
        <Toast
          message={toast.message}
          type={toast.type}
          onClose={() => setToast(null)}
        />
      )}
    </Layout>
  );
}

export default App;

import React, { useState } from 'react';
import { supabase } from '../supabaseClient';
import { Guru } from '../types';

interface LoginProps {
  onLoginSuccess: (user: Guru) => void;
  showToast: (msg: string, type: 'success' | 'error') => void;
}

export const Login: React.FC<LoginProps> = ({ onLoginSuccess, showToast }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      // Direct query to guru table as requested (Simulated Auth)
      const { data, error } = await supabase
        .from('guru')
        .select('*')
        .eq('username', username)
        .eq('password', password)
        .single();

      if (error || !data) {
        showToast('Username atau password salah', 'error');
        setLoading(false);
        return;
      }

      if (data.peran !== 'ADMIN') {
        showToast('Akses ditolak. Hanya Admin yang boleh masuk.', 'error');
        setLoading(false);
        return;
      }

      showToast(`Selamat datang, ${data.nama}`, 'success');
      onLoginSuccess(data);

    } catch (err) {
      showToast('Terjadi kesalahan sistem', 'error');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-900">
      <div className="bg-gray-800 p-8 rounded-lg shadow-md w-full max-w-md border border-gray-700">
        <h2 className="text-2xl font-bold text-center text-white mb-6">Login Admin GurWal</h2>
        <form onSubmit={handleLogin} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-300">Username</label>
            <input
              type="text"
              required
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              className="mt-1 block w-full rounded-md bg-gray-700 border-gray-600 text-white placeholder-gray-400 border p-2 shadow-sm focus:border-primary focus:ring-primary"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-300">Password</label>
            <input
              type="password"
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="mt-1 block w-full rounded-md bg-gray-700 border-gray-600 text-white placeholder-gray-400 border p-2 shadow-sm focus:border-primary focus:ring-primary"
            />
          </div>
          <button
            type="submit"
            disabled={loading}
            className="w-full flex justify-center py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-primary hover:bg-secondary focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary disabled:opacity-50"
          >
            {loading ? 'Memproses...' : 'Masuk'}
          </button>
        </form>
      </div>
    </div>
  );
};

