import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Login } from './components/Login';
import { CrudGuru } from './components/CrudGuru';
import { CrudSiswa } from './components/CrudSiswa';
import { CrudKelas } from './components/CrudKelas';
import { CrudMapel } from './components/CrudMapel';
import { Toast } from './components/Toast';
import { Guru, ViewState } from './types';

function App() {
  const [session, setSession] = useState<Guru | null>(null);
  const [currentView, setCurrentView] = useState<ViewState>('DASHBOARD');
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

  useEffect(() => {
    // Check localStorage for persisted session
    const storedUser = localStorage.getItem('gurwal_admin_user');
    if (storedUser) {
      try {
        setSession(JSON.parse(storedUser));
      } catch (e) {
        localStorage.removeItem('gurwal_admin_user');
      }
    }
  }, []);

  const handleLoginSuccess = (user: Guru) => {
    setSession(user);
    localStorage.setItem('gurwal_admin_user', JSON.stringify(user));
    setCurrentView('DASHBOARD');
  };

  const handleLogout = () => {
    setSession(null);
    localStorage.removeItem('gurwal_admin_user');
    showToast('Anda telah keluar', 'success');
  };

  const showToast = (message: string, type: 'success' | 'error') => {
    setToast({ message, type });
  };

  // Render Logic
  if (!session) {
    return (
      <>
        <Login onLoginSuccess={handleLoginSuccess} showToast={showToast} />
        {toast && (
          <Toast
            message={toast.message}
            type={toast.type}
            onClose={() => setToast(null)}
          />
        )}
      </>
    );
  }

  const renderContent = () => {
    switch (currentView) {
      case 'GURU':
        return <CrudGuru showToast={showToast} />;
      case 'SISWA':
        return <CrudSiswa showToast={showToast} />;
      case 'KELAS':
        return <CrudKelas showToast={showToast} />;
      case 'MAPEL':
        return <CrudMapel showToast={showToast} />;
      case 'DASHBOARD':
      default:
        return (
          <div className="p-4">
             <h2 className="text-3xl font-bold text-white mb-6">Dashboard</h2>
             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
               {/* Quick Stats Cards Placeholder */}
               <div className="bg-gray-800 p-6 rounded-lg shadow border-l-4 border-indigo-500">
                  <h3 className="text-gray-400 text-sm font-medium">Total Modul</h3>
                  <p className="text-2xl font-bold text-white mt-1">4 Aktif</p>
                  <p className="text-xs text-gray-500 mt-2">Guru, Siswa, Kelas, Mapel</p>
               </div>
               <div className="bg-gray-800 p-6 rounded-lg shadow border-l-4 border-green-500">
                  <h3 className="text-gray-400 text-sm font-medium">Status System</h3>
                  <p className="text-2xl font-bold text-green-500 mt-1">Online</p>
                  <p className="text-xs text-gray-500 mt-2">Supabase Connected</p>
               </div>
             </div>
             <div className="mt-8 bg-gray-800 p-6 rounded-lg border border-gray-700">
                <h3 className="text-lg font-semibold text-blue-400">Selamat Datang di GurWal v1.0</h3>
                <p className="text-gray-300 mt-2">
                  Silakan gunakan menu di sidebar sebelah kiri untuk mengelola data Guru, Siswa, Kelas, dan Mata Pelajaran.
                  Semua perubahan data akan tersimpan secara otomatis dan realtime.
                </p>
             </div>
          </div>
        );
    }
  };

  return (
    <Layout
      currentUser={session}
      currentView={currentView}
      onChangeView={setCurrentView}
      onLogout={handleLogout}
    >
      {renderContent()}
      {toast && (
        <Toast
          message={toast.message}
          type={toast.type}
          onClose={() => setToast(null)}
        />
      )}
    </Layout>
  );
}

export default App;

import React, { useEffect, useState } from 'react';
import { supabase } from '../supabaseClient';
import { Guru } from '../types';

interface CrudGuruProps {
  showToast: (msg: string, type: 'success' | 'error') => void;
}

export const CrudGuru: React.FC<CrudGuruProps> = ({ showToast }) => {
  const [data, setData] = useState<Guru[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Guru>>({});
  const [isEditing, setIsEditing] = useState(false);

  const fetchData = async () => {
    try {
      const { data: guruData, error } = await supabase
        .from('guru')
        .select('*')
        .order('nama', { ascending: true });

      if (error) throw error;
      setData(guruData || []);
    } catch (error) {
      showToast('Gagal memuat data guru', 'error');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();

    // Realtime subscription
    const channel = supabase
      .channel('guru_changes')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'guru' }, () => {
        fetchData();
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
     // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleDelete = async (id: string) => {
    if (!window.confirm('Yakin ingin menghapus data ini?')) return;

    try {
      const { error } = await supabase.from('guru').delete().eq('id', id);
      if (error) throw error;
      showToast('Data guru berhasil dihapus', 'success');
    } catch (error) {
      showToast('Gagal menghapus data', 'error');
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (isEditing && formData.id) {
        // Update
        const { error } = await supabase
          .from('guru')
          .update({
            nip: formData.nip,
            nama: formData.nama,
            jenis_kelamin: formData.jenis_kelamin,
            no_hp: formData.no_hp,
            username: formData.username,
            password: formData.password, // In a real app, handle carefully
            peran: formData.peran
          })
          .eq('id', formData.id);
        if (error) throw error;
        showToast('Guru berhasil diperbarui', 'success');
      } else {
        // Create
        const { error } = await supabase
          .from('guru')
          .insert([{
            nip: formData.nip,
            nama: formData.nama,
            jenis_kelamin: formData.jenis_kelamin,
            no_hp: formData.no_hp,
            username: formData.username,
            password: formData.password,
            peran: formData.peran || 'GURU_WALI'
          }]);
        if (error) throw error;
        showToast('Guru berhasil ditambahkan', 'success');
      }
      setIsModalOpen(false);
      setFormData({});
    } catch (error: any) {
        const msg = error.code === '23505' ? 'Username sudah digunakan' : 'Gagal menyimpan data';
        showToast(msg, 'error');
    }
  };

  const openModal = (guru?: Guru) => {
    if (guru) {
      setIsEditing(true);
      setFormData(guru);
    } else {
      setIsEditing(false);
      setFormData({ peran: 'GURU_WALI', jenis_kelamin: 'L' });
    }
    setIsModalOpen(true);
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-white">Manajemen Guru</h2>
        <button
          onClick={() => openModal()}
          className="bg-primary text-white px-4 py-2 rounded hover:bg-secondary transition"
        >
          + Tambah Guru
        </button>
      </div>

      {loading ? (
        <p className="text-gray-400">Memuat data...</p>
      ) : (
        <div className="bg-gray-800 shadow overflow-x-auto rounded-lg border border-gray-700">
          <table className="min-w-full divide-y divide-gray-700">
            <thead className="bg-gray-700">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">Nama / NIP</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">L/P</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">No HP</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">Akun</th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-300 uppercase tracking-wider">Aksi</th>
              </tr>
            </thead>
            <tbody className="bg-gray-800 divide-y divide-gray-700">
              {data.map((guru) => (
                <tr key={guru.id}>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="text-sm font-medium text-white">{guru.nama}</div>
                    <div className="text-sm text-gray-400">{guru.nip || '-'}</div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">{guru.jenis_kelamin}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">{guru.no_hp}</td>
                  <td className="px-6 py-4 whitespace-nowrap">
                     <div className="text-sm text-white">{guru.username}</div>
                     <span className={`text-xs inline-flex px-2 py-1 rounded-full ${guru.peran === 'ADMIN' ? 'bg-purple-900 text-purple-200' : 'bg-green-900 text-green-200'}`}>
                        {guru.peran}
