import { Guru } from '../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, Legend, ResponsiveContainer, CartesianGrid } from 'recharts';

interface GwLaporanProps {
  currentUser: Guru;
}

export const GwLaporan: React.FC<GwLaporanProps> = ({ currentUser }) => {
  const [summary, setSummary] = useState({ hadir: 0, sakit: 0, izin: 0, alpha: 0, pelanggaran: 0, prestasi: 0 });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);

      // 1. Get attendance stats
      const { data: attData } = await supabase
        .from('kehadiran')
        .select('status')
        .eq('id_guru', currentUser.id);

      const hadir = attData?.filter(x => x.status === 'HADIR').length || 0;
      const sakit = attData?.filter(x => x.status === 'SAKIT').length || 0;
      const izin = attData?.filter(x => x.status === 'IZIN').length || 0;
      const alpha = attData?.filter(x => x.status === 'ALPHA').length || 0;

      // 2. Get violations count
      const { count: pelCount } = await supabase
        .from('pelanggaran')
        .select('*', { count: 'exact', head: true })
        .eq('id_guru', currentUser.id);

      // 3. Get achievements count
      const { count: presCount } = await supabase
        .from('prestasi')
        .select('*', { count: 'exact', head: true })
        .eq('id_guru', currentUser.id);

      setSummary({
          hadir, sakit, izin, alpha,
          pelanggaran: pelCount || 0,
          prestasi: presCount || 0
      });
      setLoading(false);
    };

    fetchData();
  }, [currentUser.id]);

  const chartData = [
    { name: 'Hadir', jumlah: summary.hadir, fill: '#10B981' },
    { name: 'Sakit', jumlah: summary.sakit, fill: '#F59E0B' },
    { name: 'Izin', jumlah: summary.izin, fill: '#3B82F6' },
    { name: 'Alpha', jumlah: summary.alpha, fill: '#EF4444' },
  ];

  return (
    <div>
      <h2 className="text-2xl font-bold text-white mb-6">Laporan Rekapitulasi</h2>

      {loading ? <p className="text-gray-400">Menghitung data...</p> : (
        <div className="space-y-8">
            {/* Cards */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <div className="bg-gray-800 p-4 rounded border border-gray-700">
                    <p className="text-gray-400 text-sm">Total Pelanggaran</p>
                    <p className="text-2xl font-bold text-red-500">{summary.pelanggaran}</p>
                </div>
                <div className="bg-gray-800 p-4 rounded border border-gray-700">
                    <p className="text-gray-400 text-sm">Total Prestasi</p>
                    <p className="text-2xl font-bold text-green-500">{summary.prestasi}</p>
                </div>
                <div className="bg-gray-800 p-4 rounded border border-gray-700">
                    <p className="text-gray-400 text-sm">Total Alpha</p>
                    <p className="text-2xl font-bold text-red-400">{summary.alpha}</p>
                </div>
                 <div className="bg-gray-800 p-4 rounded border border-gray-700">
                    <p className="text-gray-400 text-sm">Total Kehadiran</p>
                    <p className="text-2xl font-bold text-blue-400">{summary.hadir}</p>
                </div>
            </div>

            {/* Chart */}
            <div className="bg-gray-800 p-6 rounded-lg border border-gray-700">
                <h3 className="text-lg font-semibold text-white mb-4">Grafik Kehadiran Siswa Binaan</h3>
                <div className="h-80 w-full">
                    <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={chartData}>
                            <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
                            <XAxis dataKey="name" stroke="#9CA3AF" />
                            <YAxis stroke="#9CA3AF" />
                            <Tooltip 
                                contentStyle={{ backgroundColor: '#1F2937', borderColor: '#374151', color: '#F3F4F6' }} 
                                itemStyle={{ color: '#F3F4F6' }}
                            />
                            <Bar dataKey="jumlah" radius={[4, 4, 0, 0]} />
                        </BarChart>
                    </ResponsiveContainer>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { supabase } from '../supabaseClient';
import { Guru } from '../types';

interface LoginProps {
  onLoginSuccess: (user: Guru) => void;
  showToast: (msg: string, type: 'success' | 'error') => void;
}

export const Login: React.FC<LoginProps> = ({ onLoginSuccess, showToast }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const { data, error } = await supabase
        .from('guru')
        .select('*')
        .eq('username', username)
        .eq('password', password)
        .single();

      if (error || !data) {
        showToast('Username atau password salah', 'error');
        setLoading(false);
        return;
      }

      // Check role
      if (data.peran === 'ADMIN' || data.peran === 'GURU_WALI') {
        showToast(`Selamat datang, ${data.nama} (${data.peran})`, 'success');
        onLoginSuccess(data);
      } else {
         showToast('Peran pengguna tidak dikenali.', 'error');
      }

    } catch (err) {
      showToast('Terjadi kesalahan sistem', 'error');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-900">
      <div className="bg-gray-800 p-8 rounded-lg shadow-md w-full max-w-md border border-gray-700">
        <h2 className="text-2xl font-bold text-center text-white mb-6">Login GurWal</h2>
        <form onSubmit={handleLogin} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-300">Username</label>
            <input
              type="text"
              required
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              className="mt-1 block w-full rounded-md bg-gray-700 border-gray-600 text-white placeholder-gray-400 border p-2 shadow-sm focus:border-primary focus:ring-primary"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-300">Password</label>
            <input
              type="password"
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="mt-1 block w-full rounded-md bg-gray-700 border-gray-600 text-white placeholder-gray-400 border p-2 shadow-sm focus:border-primary focus:ring-primary"
            />
          </div>
          <button
            type="submit"
            disabled={loading}
            className="w-full flex justify-center py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-primary hover:bg-secondary focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary disabled:opacity-50"
          >
            {loading ? 'Memproses...' : 'Masuk'}
          </button>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Login } from './components/Login';
// Admin Components
import { CrudGuru } from './components/CrudGuru';
import { CrudSiswa } from './components/CrudSiswa';
import { CrudKelas } from './components/CrudKelas';
import { CrudMapel } from './components/CrudMapel';
// Guru Wali Components
import { GwDashboard } from './components/GwDashboard';
import { GwSiswa } from './components/GwSiswa';
import { GwKehadiran } from './components/GwKehadiran';
import { GwPelanggaran } from './components/GwPelanggaran';
import { GwPrestasi } from './components/GwPrestasi';
import { GwLaporan } from './components/GwLaporan';

import { Toast } from './components/Toast';
import { Guru, ViewState } from './types';

function App() {
  const [session, setSession] = useState<Guru | null>(null);
  const [currentView, setCurrentView] = useState<ViewState>('DASHBOARD');
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

  useEffect(() => {
    // Check localStorage for persisted session
    const storedUser = localStorage.getItem('gurwal_admin_user');
    if (storedUser) {
      try {
        const user = JSON.parse(storedUser);
        setSession(user);
        // Set initial view based on role
        if (user.peran === 'GURU_WALI') setCurrentView('GW_DASHBOARD');
        else setCurrentView('DASHBOARD');
      } catch (e) {
        localStorage.removeItem('gurwal_admin_user');
      }
    }
  }, []);

  const handleLoginSuccess = (user: Guru) => {
    setSession(user);
    localStorage.setItem('gurwal_admin_user', JSON.stringify(user));
    if (user.peran === 'GURU_WALI') setCurrentView('GW_DASHBOARD');
    else setCurrentView('DASHBOARD');
  };

  const handleLogout = () => {
    setSession(null);
    localStorage.removeItem('gurwal_admin_user');
    showToast('Anda telah keluar', 'success');
  };

  const showToast = (message: string, type: 'success' | 'error') => {
    setToast({ message, type });
  };

  // Render Logic
  if (!session) {
    return (
      <>
        <Login onLoginSuccess={handleLoginSuccess} showToast={showToast} />
        {toast && (
          <Toast
            message={toast.message}
            type={toast.type}
            onClose={() => setToast(null)}
          />
        )}
      </>
    );
  }

  const renderContent = () => {
    switch (currentView) {
      // ADMIN
      case 'GURU':
        return <CrudGuru showToast={showToast} />;
      case 'SISWA':
        return <CrudSiswa showToast={showToast} />;
      case 'KELAS':
        return <CrudKelas showToast={showToast} />;
      case 'MAPEL':
        return <CrudMapel showToast={showToast} />;
      case 'DASHBOARD':
        return (
          <div className="p-4">
             <h2 className="text-3xl font-bold text-white mb-6">Dashboard Admin</h2>
             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
               <div className="bg-gray-800 p-6 rounded-lg shadow border-l-4 border-indigo-500">
                  <h3 className="text-gray-400 text-sm font-medium">Mode</h3>
                  <p className="text-2xl font-bold text-white mt-1">Administrator</p>
               </div>
               <div className="bg-gray-800 p-6 rounded-lg shadow border-l-4 border-green-500">
                  <h3 className="text-gray-400 text-sm font-medium">Status System</h3>
                  <p className="text-2xl font-bold text-green-500 mt-1">Online</p>
               </div>
             </div>
          </div>
        );

      // GURU WALI
      case 'GW_DASHBOARD':
        return <GwDashboard currentUser={session} />;
      case 'GW_SISWA':
        return <GwSiswa currentUser={session} showToast={showToast} />;
      case 'GW_KEHADIRAN':
        return <GwKehadiran currentUser={session} showToast={showToast} />;
      case 'GW_PELANGGARAN':
        return <GwPelanggaran currentUser={session} showToast={showToast} />;
      case 'GW_PRESTASI':
        return <GwPrestasi currentUser={session} showToast={showToast} />;
      case 'GW_LAPORAN':
        return <GwLaporan currentUser={session} />;

      default:
        return <div className="p-6 text-white">Halaman tidak ditemukan</div>;
    }
  };

  return (
    <Layout
      currentUser={session}
      currentView={currentView}
      onChangeView={setCurrentView}
      onLogout={handleLogout}
    >
      {renderContent()}
      {toast && (
        <Toast
          message={toast.message}
          type={toast.type}
          onClose={() => setToast(null)}
        />
      )}
    </Layout>
  );
}

export default App;

