interface PengajarPenilaianProps {
  currentUser: Guru;
  showToast: (msg: string, type: 'success' | 'error') => void;
}

export const PengajarPenilaian: React.FC<PengajarPenilaianProps> = ({ currentUser, showToast }) => {
  const [kelasOptions, setKelasOptions] = useState<Kelas[]>([]);
  const [mapelOptions, setMapelOptions] = useState<Mapel[]>([]);

  const [selectedKelas, setSelectedKelas] = useState<string>('');
  const [selectedMapel, setSelectedMapel] = useState<string>('');

  const [students, setStudents] = useState<Siswa[]>([]);
  const [existingGrades, setExistingGrades] = useState<Nilai[]>([]);
  const [loading, setLoading] = useState(false);

  // Load Teaching Assignment (Pengajaran) to filter dropdowns
  useEffect(() => {
    const fetchAssignments = async () => {
      const { data, error } = await supabase
        .from('pengajaran')
        .select('*, kelas(*), mapel(*)')
        .eq('id_guru', currentUser.id);

      if (!error && data) {
        // Extract unique Kelas
        const uniqueKelas = Array.from(new Map(data.map(item => [item.id_kelas, item.kelas])).values());
        // Extract unique Mapel
        const uniqueMapel = Array.from(new Map(data.map(item => [item.id_mapel, item.mapel])).values());

        // @ts-ignore
        setKelasOptions(uniqueKelas);
        // @ts-ignore
        setMapelOptions(uniqueMapel);
      }
    };
    fetchAssignments();
  }, [currentUser.id]);

  // Fetch Students and Grades when filter changes
  useEffect(() => {
    if (selectedKelas && selectedMapel) {
      setLoading(true);
      Promise.all([
        supabase.from('siswa').select('*').eq('id_kelas', selectedKelas).order('nama'),
        supabase.from('nilai')
          .select('*')
          .eq('id_guru', currentUser.id)
          .eq('id_mapel', selectedMapel)
          .in('id_siswa', (await supabase.from('siswa').select('id').eq('id_kelas', selectedKelas)).data?.map(s=>s.id) || [])
      ]).then(([siswaRes, nilaiRes]) => {
        if (siswaRes.data) setStudents(siswaRes.data);
        if (nilaiRes.data) setExistingGrades(nilaiRes.data);
        setLoading(false);
      });
    } else {
      setStudents([]);
      setExistingGrades([]);
    }
  }, [selectedKelas, selectedMapel, currentUser.id]);

  // Helper to get grade value
  const getGradeValue = (studentId: string, type: 'FORMATIF' | 'SUMATIF' | 'AKHIR_SUMATIF') => {
    const grade = existingGrades.find(g => g.id_siswa === studentId && g.jenis === type);
    return grade ? grade.nilai : '';
  };

  const handleGradeChange = async (studentId: string, type: 'FORMATIF' | 'SUMATIF' | 'AKHIR_SUMATIF', value: string) => {
    const numVal = parseFloat(value);
    if (value !== '' && (isNaN(numVal) || numVal < 0 || numVal > 100)) {
        return; // Validation simple
    }

    const numericValue = value === '' ? null : numVal;

    // Optimistic UI Update (local state only for UI fluidity, real save is separate or debounced ideally)
    // For simplicity in this prompt, we save onBlur or specific button. 
    // Let's implement individual save/upsert logic on blur/change.

    // Find existing grade record
    const existing = existingGrades.find(g => g.id_siswa === studentId && g.jenis === type);

    try {
        if (numericValue === null) {
            // Do nothing if empty? Or delete? Let's assume just update.
            return;
        }

        let error;
        if (existing) {
             const { error: err } = await supabase
                .from('nilai')
                .update({ nilai: numericValue, tanggal: new Date().toISOString().split('T')[0] })
                .eq('id', existing.id);
             error = err;
        } else {
             const { error: err } = await supabase
                .from('nilai')
                .insert([{
                    id_guru: currentUser.id,
                    id_siswa: studentId,
                    id_mapel: selectedMapel,
                    jenis: type,
                    nilai: numericValue,
                    tanggal: new Date().toISOString().split('T')[0]
                }]);
             error = err;
        }

        if (error) throw error;

        // Refresh grades in background
        const { data: newVal } = await supabase.from('nilai').select('*').eq('id_guru', currentUser.id).eq('id_mapel', selectedMapel);
        if(newVal) setExistingGrades(newVal);

    } catch (e) {
        showToast('Gagal menyimpan nilai', 'error');
    }
  };

  return (
    <div>
      <h2 className="text-2xl font-bold text-white mb-6">Input Penilaian</h2>

      {/* Filters */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6 bg-gray-800 p-4 rounded-lg border border-gray-700">
        <div>
           <label className="block text-sm font-medium text-gray-300 mb-1">Pilih Kelas</label>
           <select 
             className="w-full bg-gray-700 border border-gray-600 rounded p-2 text-white"
             value={selectedKelas}
             onChange={(e) => setSelectedKelas(e.target.value)}
           >
             <option value="">-- Pilih Kelas --</option>
             {kelasOptions.map(k => <option key={k.id} value={k.id}>{k.nama}</option>)}
           </select>
        </div>
        <div>
           <label className="block text-sm font-medium text-gray-300 mb-1">Pilih Mata Pelajaran</label>
           <select 
             className="w-full bg-gray-700 border border-gray-600 rounded p-2 text-white"
             value={selectedMapel}
             onChange={(e) => setSelectedMapel(e.target.value)}
           >
             <option value="">-- Pilih Mapel --</option>
             {mapelOptions.map(m => <option key={m.id} value={m.id}>{m.nama}</option>)}
           </select>
        </div>
      </div>

      {/* Table */}
      {selectedKelas && selectedMapel ? (
         <div className="bg-gray-800 shadow overflow-hidden rounded-lg border border-gray-700">
            {loading ? <p className="p-4 text-gray-400">Memuat data siswa...</p> : (
            <table className="min-w-full divide-y divide-gray-700">
                <thead className="bg-gray-700">
                <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Nama Siswa</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase w-32">Formatif</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase w-32">Sumatif</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase w-32">Akhir Sumatif</th>
                </tr>
                </thead>
                <tbody className="bg-gray-800 divide-y divide-gray-700">
                {students.map((student) => (
                    <tr key={student.id}>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-white">{student.nama}</td>
                    <td className="px-6 py-4">
                        <input 
                            type="number" min="0" max="100"
                            className="w-24 bg-gray-900 border border-gray-600 rounded px-2 py-1 text-white text-center"
                            placeholder="0-100"
                            defaultValue={getGradeValue(student.id, 'FORMATIF')}
                            onBlur={(e) => handleGradeChange(student.id, 'FORMATIF', e.target.value)}
                        />
                    </td>
                    <td className="px-6 py-4">
                        <input 
                            type="number" min="0" max="100"
                            className="w-24 bg-gray-900 border border-gray-600 rounded px-2 py-1 text-white text-center"
                            placeholder="0-100"
                            defaultValue={getGradeValue(student.id, 'SUMATIF')}
                            onBlur={(e) => handleGradeChange(student.id, 'SUMATIF', e.target.value)}
                        />
                    </td>
                    <td className="px-6 py-4">
                         <input 
                            type="number" min="0" max="100"
                            className="w-24 bg-gray-900 border border-gray-600 rounded px-2 py-1 text-white text-center"
                            placeholder="0-100"
                            defaultValue={getGradeValue(student.id, 'AKHIR_SUMATIF')}
                            onBlur={(e) => handleGradeChange(student.id, 'AKHIR_SUMATIF', e.target.value)}
                        />
                    </td>
                    </tr>
                ))}
                {students.length === 0 && (
                    <tr><td colSpan={4} className="p-6 text-center text-gray-500">Tidak ada siswa di kelas ini.</td></tr>
                )}
                </tbody>
            </table>
            )}
         </div>
      ) : (
          <div className="p-10 text-center text-gray-500 border-2 border-dashed border-gray-700 rounded-lg">
              Silakan pilih Kelas dan Mata Pelajaran terlebih dahulu.
          </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../supabaseClient';
import { Guru, Siswa, Kelas, Mapel, Nilai } from '../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, Legend, ResponsiveContainer, CartesianGrid } from 'recharts';

interface PengajarRekapNilaiProps {
  currentUser: Guru;
}

export const PengajarRekapNilai: React.FC<PengajarRekapNilaiProps> = ({ currentUser }) => {
  const [kelasOptions, setKelasOptions] = useState<Kelas[]>([]);
  const [mapelOptions, setMapelOptions] = useState<Mapel[]>([]);
  const [selectedKelas, setSelectedKelas] = useState<string>('');
  const [selectedMapel, setSelectedMapel] = useState<string>('');
  const [reportData, setReportData] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const fetchAssignments = async () => {
      const { data } = await supabase
        .from('pengajaran')
        .select('*, kelas(*), mapel(*)')
        .eq('id_guru', currentUser.id);

      if (data) {
        // @ts-ignore
        setKelasOptions(Array.from(new Map(data.map(item => [item.id_kelas, item.kelas])).values()));
        // @ts-ignore
        setMapelOptions(Array.from(new Map(data.map(item => [item.id_mapel, item.mapel])).values()));
      }
    };
    fetchAssignments();
  }, [currentUser.id]);

  useEffect(() => {
    if (selectedKelas && selectedMapel) {
       setLoading(true);
       const loadData = async () => {
           // Fetch students
           const { data: students } = await supabase.from('siswa').select('*').eq('id_kelas', selectedKelas).order('nama');
           // Fetch grades
           const { data: grades } = await supabase.from('nilai')
             .select('*')
             .eq('id_guru', currentUser.id)
             .eq('id_mapel', selectedMapel);

           if (students && grades) {
               const processed = students.map(s => {
                   const sGrades = grades.filter(g => g.id_siswa === s.id);
                   const formatif = sGrades.find(g => g.jenis === 'FORMATIF')?.nilai || 0;
                   const sumatif = sGrades.find(g => g.jenis === 'SUMATIF')?.nilai || 0;
                   const akhir = sGrades.find(g => g.jenis === 'AKHIR_SUMATIF')?.nilai || 0;
                   const avg = (Number(formatif) + Number(sumatif) + Number(akhir)) / 3;

                   return {
                       nama: s.nama,
                       formatif: Number(formatif),
                       sumatif: Number(sumatif),
                       akhir: Number(akhir),
                       rata: parseFloat(avg.toFixed(1))
                   };
               });
               setReportData(processed);
           }
           setLoading(false);
       };
       loadData();
    } else {
        setReportData([]);
    }
  }, [selectedKelas, selectedMapel, currentUser.id]);

  return (
    <div>
      <h2 className="text-2xl font-bold text-white mb-6">Rekap Nilai Siswa</h2>

      {/* Filters */}
      <div className="flex flex-col md:flex-row gap-4 mb-6">
           <select 
             className="bg-gray-700 border border-gray-600 rounded p-2 text-white flex-1"
             value={selectedKelas}
             onChange={(e) => setSelectedKelas(e.target.value)}
           >
             <option value="">-- Pilih Kelas --</option>
             {kelasOptions.map(k => <option key={k.id} value={k.id}>{k.nama}</option>)}
           </select>
           <select 
             className="bg-gray-700 border border-gray-600 rounded p-2 text-white flex-1"
             value={selectedMapel}
             onChange={(e) => setSelectedMapel(e.target.value)}
           >
             <option value="">-- Pilih Mapel --</option>
             {mapelOptions.map(m => <option key={m.id} value={m.id}>{m.nama}</option>)}
           </select>
      </div>

      {loading ? <p className="text-gray-400">Menghitung...</p> : (
         selectedKelas && selectedMapel ? (
             <div className="space-y-8">
                 {/* Chart */}
                 <div className="bg-gray-800 p-4 rounded-lg border border-gray-700 h-80">
                    <h3 className="text-white mb-4 text-sm font-semibold">Grafik Rata-rata Nilai</h3>
                    <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={reportData}>
                            <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
                            <XAxis dataKey="nama" stroke="#9CA3AF" hide />
                            <YAxis stroke="#9CA3AF" domain={[0, 100]} />
                            <Tooltip 
                                contentStyle={{ backgroundColor: '#1F2937', borderColor: '#374151', color: '#F3F4F6' }} 
                            />
                            <Legend />
                            <Bar dataKey="formatif" fill="#3B82F6" name="Formatif" />
                            <Bar dataKey="sumatif" fill="#10B981" name="Sumatif" />
                            <Bar dataKey="akhir" fill="#F59E0B" name="Akhir" />
                        </BarChart>
                    </ResponsiveContainer>
                 </div>

                 {/* Table */}
                 <div className="bg-gray-800 shadow overflow-x-auto rounded-lg border border-gray-700">
                    <table className="min-w-full divide-y divide-gray-700">
                        <thead className="bg-gray-700">
                            <tr>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Nama Siswa</th>
                                <th className="px-6 py-3 text-center text-xs font-medium text-gray-300 uppercase">Formatif</th>
                                <th className="px-6 py-3 text-center text-xs font-medium text-gray-300 uppercase">Sumatif</th>
                                <th className="px-6 py-3 text-center text-xs font-medium text-gray-300 uppercase">Akhir</th>
                                <th className="px-6 py-3 text-center text-xs font-medium text-gray-300 uppercase font-bold text-white">Rata-rata</th>
                            </tr>
                        </thead>
                        <tbody className="bg-gray-800 divide-y divide-gray-700">
                            {reportData.map((row, idx) => (
                                <tr key={idx}>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-white">{row.nama}</td>
                                    <td className="px-6 py-4 text-center text-sm text-gray-300">{row.formatif}</td>
                                    <td className="px-6 py-4 text-center text-sm text-gray-300">{row.sumatif}</td>
                                    <td className="px-6 py-4 text-center text-sm text-gray-300">{row.akhir}</td>
                                    <td className="px-6 py-4 text-center text-sm font-bold text-blue-400">{row.rata}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                 </div>
             </div>
         ) : (
            <div className="p-10 text-center text-gray-500 border-2 border-dashed border-gray-700 rounded-lg">
                Pilih filter di atas untuk melihat rekap nilai.
            </div>
         )
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Login } from './components/Login';
// Admin Components
import { CrudGuru } from './components/CrudGuru';
import { CrudSiswa } from './components/CrudSiswa';
import { CrudKelas } from './components/CrudKelas';
import { CrudMapel } from './components/CrudMapel';
// Guru Wali Components
import { GwDashboard } from './components/GwDashboard';
import { GwSiswa } from './components/GwSiswa';
import { GwKehadiran } from './components/GwKehadiran';
import { GwPelanggaran } from './components/GwPelanggaran';
import { GwPrestasi } from './components/GwPrestasi';
import { GwLaporan } from './components/GwLaporan';
// Guru Pengajar Components
import { PengajarDashboard } from './components/PengajarDashboard';
import { PengajarPenilaian } from './components/PengajarPenilaian';
import { PengajarRekapNilai } from './components/PengajarRekapNilai';

import { Toast } from './components/Toast';
import { Guru, ViewState } from './types';

function App() {
  const [session, setSession] = useState<Guru | null>(null);
  const [currentView, setCurrentView] = useState<ViewState>('DASHBOARD');
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

  useEffect(() => {
    // Check localStorage for persisted session
    const storedUser = localStorage.getItem('gurwal_admin_user');
    if (storedUser) {
      try {
        const user = JSON.parse(storedUser);
        setSession(user);
        // Set initial view based on role
        if (user.peran === 'GURU_WALI') setCurrentView('GW_DASHBOARD');
        else if (user.peran === 'GURU_PENGAJAR') setCurrentView('PENGAJAR_DASHBOARD');
        else setCurrentView('DASHBOARD');
      } catch (e) {
        localStorage.removeItem('gurwal_admin_user');
      }
    }
  }, []);

  const handleLoginSuccess = (user: Guru) => {
    setSession(user);
    localStorage.setItem('gurwal_admin_user', JSON.stringify(user));
    if (user.peran === 'GURU_WALI') setCurrentView('GW_DASHBOARD');
    else if (user.peran === 'GURU_PENGAJAR') setCurrentView('PENGAJAR_DASHBOARD');
    else setCurrentView('DASHBOARD');
  };

  const handleLogout = () => {
    setSession(null);
    localStorage.removeItem('gurwal_admin_user');
    showToast('Anda telah keluar', 'success');
  };

  const showToast = (message: string, type: 'success' | 'error') => {
    setToast({ message, type });
  };

  // Render Logic
  if (!session) {
    return (
      <>
        <Login onLoginSuccess={handleLoginSuccess} showToast={showToast} />
        {toast && (
          <Toast
            message={toast.message}
            type={toast.type}
            onClose={() => setToast(null)}
          />
        )}
      </>
    );
  }

  const renderContent = () => {
    switch (currentView) {
      // ADMIN
      case 'GURU':
        return <CrudGuru showToast={showToast} />;
      case 'SISWA':
        return <CrudSiswa showToast={showToast} />;
      case 'KELAS':
        return <CrudKelas showToast={showToast} />;
      case 'MAPEL':
        return <CrudMapel showToast={showToast} />;
      case 'DASHBOARD':
        return (
          <div className="p-4">
             <h2 className="text-3xl font-bold text-white mb-6">Dashboard Admin</h2>
             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
               <div className="bg-gray-800 p-6 rounded-lg shadow border-l-4 border-indigo-500">
                  <h3 className="text-gray-400 text-sm font-medium">Mode</h3>
                  <p className="text-2xl font-bold text-white mt-1">Administrator</p>
               </div>
               <div className="bg-gray-800 p-6 rounded-lg shadow border-l-4 border-green-500">
                  <h3 className="text-gray-400 text-sm font-medium">Status System</h3>
                  <p className="text-2xl font-bold text-green-500 mt-1">Online</p>
               </div>
             </div>
          </div>
        );

      // GURU WALI
      case 'GW_DASHBOARD':
        return <GwDashboard currentUser={session} />;
      case 'GW_SISWA':
        return <GwSiswa currentUser={session} showToast={showToast} />;
      case 'GW_KEHADIRAN':
        return <GwKehadiran currentUser={session} showToast={showToast} />;
      case 'GW_PELANGGARAN':
        return <GwPelanggaran currentUser={session} showToast={showToast} />;
      case 'GW_PRESTASI':
        return <GwPrestasi currentUser={session} showToast={showToast} />;
      case 'GW_LAPORAN':
        return <GwLaporan currentUser={session} />;

      // GURU PENGAJAR
      case 'PENGAJAR_DASHBOARD':
        return <PengajarDashboard currentUser={session} />;
      case 'PENGAJAR_PENILAIAN':
        return <PengajarPenilaian currentUser={session} showToast={showToast} />;
      case 'PENGAJAR_REKAP':
        return <PengajarRekapNilai currentUser={session} />;

      default:
        return <div className="p-6 text-white">Halaman tidak ditemukan</div>;
    }
  };

  return (
    <Layout
      currentUser={session}
      currentView={currentView}
      onChangeView={setCurrentView}
      onLogout={handleLogout}
    >
      {renderContent()}
      {toast && (
        <Toast
          message={toast.message}
          type={toast.type}
          onClose={() => setToast(null)}
        />
      )}
    </Layout>
  );
}

export default App;

import React, { useEffect, useState } from 'react';
import { supabase } from '../supabaseClient';
import { Guru, Siswa, Kelas, Mapel, Nilai } from '../types';

interface PengajarPenilaianProps {
  currentUser: Guru;
  showToast: (msg: string, type: 'success' | 'error') => void;
}

export const PengajarPenilaian: React.FC<PengajarPenilaianProps> = ({ currentUser, showToast }) => {
  const [kelasOptions, setKelasOptions] = useState<Kelas[]>([]);
  const [mapelOptions, setMapelOptions] = useState<Mapel[]>([]);

  const [selectedKelas, setSelectedKelas] = useState<string>('');
  const [selectedMapel, setSelectedMapel] = useState<string>('');

  const [students, setStudents] = useState<Siswa[]>([]);
  const [existingGrades, setExistingGrades] = useState<Nilai[]>([]);
  const [loading, setLoading] = useState(false);

  // Load Teaching Assignment (Pengajaran) to filter dropdowns
  useEffect(() => {
    const fetchAssignments = async () => {
      const { data, error } = await supabase
        .from('pengajaran')
        .select('*, kelas(*), mapel(*)')
        .eq('id_guru', currentUser.id);

      if (!error && data) {
        // Extract unique Kelas
        const uniqueKelas = Array.from(new Map(data.map(item => [item.id_kelas, item.kelas])).values());
        // Extract unique Mapel
        const uniqueMapel = Array.from(new Map(data.map(item => [item.id_mapel, item.mapel])).values());

        // @ts-ignore
        setKelasOptions(uniqueKelas);
        // @ts-ignore
        setMapelOptions(uniqueMapel);
      }
    };
    fetchAssignments();
  }, [currentUser.id]);

  // Fetch Students and Grades when filter changes
  useEffect(() => {
    if (selectedKelas && selectedMapel) {
      const fetchData = async () => {
        setLoading(true);
        try {
          // Fetch students first
          const { data: studentsData, error: studentsError } = await supabase
            .from('siswa')
            .select('*')
            .eq('id_kelas', selectedKelas)
            .order('nama');

          if (studentsError) throw studentsError;

          const studentIds = studentsData?.map(s => s.id) || [];
          let gradesData: Nilai[] = [];

          if (studentIds.length > 0) {
            const { data: grades, error: gradesError } = await supabase
              .from('nilai')
              .select('*')
              .eq('id_guru', currentUser.id)
              .eq('id_mapel', selectedMapel)
              .in('id_siswa', studentIds);

            if (gradesError) throw gradesError;
            gradesData = grades || [];
          }

          setStudents(studentsData || []);
          setExistingGrades(gradesData);
        } catch (error) {
          showToast('Gagal memuat data siswa/nilai', 'error');
        } finally {
          setLoading(false);
        }
      };

      fetchData();
    } else {
      setStudents([]);
      setExistingGrades([]);
    }
  }, [selectedKelas, selectedMapel, currentUser.id]);

  // Helper to get grade value
  const getGradeValue = (studentId: string, type: 'FORMATIF' | 'SUMATIF' | 'AKHIR_SUMATIF') => {
    const grade = existingGrades.find(g => g.id_siswa === studentId && g.jenis === type);
    return grade ? grade.nilai : '';
  };

  const handleGradeChange = async (studentId: string, type: 'FORMATIF' | 'SUMATIF' | 'AKHIR_SUMATIF', value: string) => {
    const numVal = parseFloat(value);
    if (value !== '' && (isNaN(numVal) || numVal < 0 || numVal > 100)) {
        return; // Validation simple
    }

    const numericValue = value === '' ? null : numVal;

    // Optimistic UI Update (local state only for UI fluidity, real save is separate or debounced ideally)
    // For simplicity in this prompt, we save onBlur or specific button. 
    // Let's implement individual save/upsert logic on blur/change.

    // Find existing grade record
    const existing = existingGrades.find(g => g.id_siswa === studentId && g.jenis === type);

    try {
        if (numericValue === null) {
            // Do nothing if empty? Or delete? Let's assume just update.
            return;
        }

        let error;
        if (existing) {
             const { error: err } = await supabase
                .from('nilai')
                .update({ nilai: numericValue, tanggal: new Date().toISOString().split('T')[0] })
                .eq('id', existing.id);
             error = err;
        } else {
             const { error: err } = await supabase
                .from('nilai')
                .insert([{
                    id_guru: currentUser.id,
                    id_siswa: studentId,
                    id_mapel: selectedMapel,
                    jenis: type,
                    nilai: numericValue,
                    tanggal: new Date().toISOString().split('T')[0]
                }]);
             error = err;
        }

        if (error) throw error;

        // Refresh grades in background
        const { data: newVal } = await supabase.from('nilai').select('*').eq('id_guru', currentUser.id).eq('id_mapel', selectedMapel);
        if(newVal) setExistingGrades(newVal);

    } catch (e) {
        showToast('Gagal menyimpan nilai', 'error');
    }
  };

  return (
    <div>
      <h2 className="text-2xl font-bold text-white mb-6">Input Penilaian</h2>

      {/* Filters */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6 bg-gray-800 p-4 rounded-lg border border-gray-700">
        <div>
           <label className="block text-sm font-medium text-gray-300 mb-1">Pilih Kelas</label>
           <select 
             className="w-full bg-gray-700 border border-gray-600 rounded p-2 text-white"
             value={selectedKelas}
             onChange={(e) => setSelectedKelas(e.target.value)}
           >
             <option value="">-- Pilih Kelas --</option>
             {kelasOptions.map(k => <option key={k.id} value={k.id}>{k.nama}</option>)}
           </select>
        </div>
        <div>
           <label className="block text-sm font-medium text-gray-300 mb-1">Pilih Mata Pelajaran</label>
           <select 
             className="w-full bg-gray-700 border border-gray-600 rounded p-2 text-white"
             value={selectedMapel}
             onChange={(e) => setSelectedMapel(e.target.value)}
           >
             <option value="">-- Pilih Mapel --</option>
             {mapelOptions.map(m => <option key={m.id} value={m.id}>{m.nama}</option>)}
           </select>
        </div>
      </div>

      {/* Table */}
      {selectedKelas && selectedMapel ? (
         <div className="bg-gray-800 shadow overflow-hidden rounded-lg border border-gray-700">
            {loading ? <p className="p-4 text-gray-400">Memuat data siswa...</p> : (
            <table className="min-w-full divide-y divide-gray-700">
                <thead className="bg-gray-700">
                <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Nama Siswa</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase w-32">Formatif</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase w-32">Sumatif</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase w-32">Akhir Sumatif</th>
                </tr>
                </thead>
                <tbody className="bg-gray-800 divide-y divide-gray-700">
                {students.map((student) => (
                    <tr key={student.id}>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-white">{student.nama}</td>
                    <td className="px-6 py-4">
                        <input 
                            type="number" min="0" max="100"
                            className="w-24 bg-gray-900 border border-gray-600 rounded px-2 py-1 text-white text-center"
                            placeholder="0-100"
                            defaultValue={getGradeValue(student.id, 'FORMATIF')}
                            onBlur={(e) => handleGradeChange(student.id, 'FORMATIF', e.target.value)}
                        />
                    </td>
                    <td className="px-6 py-4">
                        <input 
                            type="number" min="0" max="100"
                            className="w-24 bg-gray-900 border border-gray-600 rounded px-2 py-1 text-white text-center"
                            placeholder="0-100"
                            defaultValue={getGradeValue(student.id, 'SUMATIF')}
                            onBlur={(e) => handleGradeChange(student.id, 'SUMATIF', e.target.value)}
                        />
                    </td>
                    <td className="px-6 py-4">
                         <input 
                            type="number" min="0" max="100"
                            className="w-24 bg-gray-900 border border-gray-600 rounded px-2 py-1 text-white text-center"
                            placeholder="0-100"
                            defaultValue={getGradeValue(student.id, 'AKHIR_SUMATIF')}
                            onBlur={(e) => handleGradeChange(student.id, 'AKHIR_SUMATIF', e.target.value)}
                        />
                    </td>
                    </tr>
                ))}
                {students.length === 0 && (
                    <tr><td colSpan={4} className="p-6 text-center text-gray-500">Tidak ada siswa di kelas ini.</td></tr>
                )}
                </tbody>
            </table>
            )}
         </div>
      ) : (
          <div className="p-10 text-center text-gray-500 border-2 border-dashed border-gray-700 rounded-lg">
              Silakan pilih Kelas dan Mata Pelajaran terlebih dahulu.
          </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useRef } from 'react';
import { supabase } from '../supabaseClient';
import { Guru } from '../types';
import Papa from 'papaparse';

interface CrudGuruProps {
  showToast: (msg: string, type: 'success' | 'error') => void;
}

export const CrudGuru: React.FC<CrudGuruProps> = ({ showToast }) => {
  const [data, setData] = useState<Guru[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Guru>>({});
  const [isEditing, setIsEditing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const fetchData = async () => {
    try {
      const { data: guruData, error } = await supabase
        .from('guru')
        .select('*')
        .order('nama', { ascending: true });

      if (error) throw error;
      setData(guruData || []);
    } catch (error) {
      showToast('Gagal memuat data guru', 'error');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();

    // Realtime subscription
    const channel = supabase
      .channel('guru_changes')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'guru' }, () => {
        fetchData();
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
     // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleDelete = async (id: string) => {
    if (!window.confirm('Yakin ingin menghapus data ini?')) return;

    try {
      const { error } = await supabase.from('guru').delete().eq('id', id);
      if (error) throw error;
      showToast('Data guru berhasil dihapus', 'success');
    } catch (error) {
      showToast('Gagal menghapus data', 'error');
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (isEditing && formData.id) {
        // Update
        const { error } = await supabase
          .from('guru')
          .update({
            nip: formData.nip,
            nama: formData.nama,
            jenis_kelamin: formData.jenis_kelamin,
            no_hp: formData.no_hp,
            username: formData.username,
            password: formData.password, // In a real app, handle carefully
            peran: formData.peran
          })
          .eq('id', formData.id);
        if (error) throw error;
        showToast('Guru berhasil diperbarui', 'success');
      } else {
        // Create
        const { error } = await supabase
          .from('guru')
          .insert([{
            nip: formData.nip,
            nama: formData.nama,
            jenis_kelamin: formData.jenis_kelamin,
            no_hp: formData.no_hp,
            username: formData.username,
            password: formData.password,
            peran: formData.peran || 'GURU_WALI'
          }]);
        if (error) throw error;
        showToast('Guru berhasil ditambahkan', 'success');
      }
      setIsModalOpen(false);
      setFormData({});
    } catch (error: any) {
        const msg = error.code === '23505' ? 'Username sudah digunakan' : 'Gagal menyimpan data';
        showToast(msg, 'error');
    }
  };

  const openModal = (guru?: Guru) => {
    if (guru) {
      setIsEditing(true);
      setFormData(guru);
    } else {
      setIsEditing(false);
      setFormData({ peran: 'GURU_WALI', jenis_kelamin: 'L' });
    }
    setIsModalOpen(true);
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: async (results) => {
        try {
          const parsedData = results.data.map((row: any) => ({
            nip: row.nip || null,
            nama: row.nama,
            jenis_kelamin: row.jenis_kelamin || 'L',
            no_hp: row.no_hp || null,
            username: row.username,
            password: row.password || '123456', // Default password if missing
            peran: row.peran || 'GURU_WALI'
          }));

          const { error } = await supabase.from('guru').upsert(parsedData, { onConflict: 'username' });

          if (error) throw error;

          showToast(`Berhasil mengimport ${parsedData.length} data guru`, 'success');
          fetchData();
        } catch (error) {
          console.error(error);
          showToast('Gagal mengimport CSV. Pastikan format benar.', 'error');
        } finally {
          if (fileInputRef.current) fileInputRef.current.value = '';
        }
      },
      error: (error) => {
        showToast('Gagal membaca file CSV', 'error');
      }
    });
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-white">Manajemen Guru</h2>
        <div className="flex gap-2">
            <input 
              type="file" 
              accept=".csv" 
              ref={fileInputRef} 
              onChange={handleFileUpload} 
              className="hidden" 
            />
            <button
              onClick={() => fileInputRef.current?.click()}
              className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700 transition"
            >
              📂 Import CSV
            </button>
            <button
              onClick={() => openModal()}
              className="bg-primary text-white px-4 py-2 rounded hover:bg-secondary transition"
            >
              + Tambah Guru
            </button>
        </div>
      </div>

      {loading ? (
        <p className="text-gray-400">Memuat data...</p>
      ) : (
        <div className="bg-gray-800 shadow overflow-x-auto rounded-lg border border-gray-700">
          <table className="min-w-full divide-y divide-gray-700">
            <thead className="bg-gray-700">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">Nama / NIP</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">L/P</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">No HP</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">Akun</th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-300 uppercase tracking-wider">Aksi</th>
              </tr>
            </thead>
            <tbody className="bg-gray-800 divide-y divide-gray-700">
              {data.map((guru) => (
                <tr key={guru.id}>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="text-sm font-medium text-white">{guru.nama}</div>
                    <div className="text-sm text-gray-400">{guru.nip || '-'}</div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">{guru.jenis_kelamin}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">{guru.no_hp}</td>
                  <td className="px-6 py-4 whitespace-nowrap">
                     <div className="text-sm text-white">{guru.username}</div>
                     <span className={`text-xs inline-flex px-2 py-1 rounded-full ${guru.peran === 'ADMIN' ? 'bg-purple-900 text-purple-200' : 'bg-green-900 text-green-200'}`}>
                        {guru.peran}
                     </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                    <button onClick={() => openModal(guru)} className="text-indigo-400 hover:text-indigo-300 mr-4">Edit</button>
                    <button onClick={() => handleDelete(guru.id)} className="text-red-400 hover:text-red-300">Hapus</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* Modal Form */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50 p-4">
          <div className="bg-gray-800 rounded-lg shadow-lg w-full max-w-lg p-6 max-h-[90vh] overflow-y-auto border border-gray-700">
            <h3 className="text-lg font-bold mb-4 text-white">{isEditing ? 'Edit Guru' : 'Tambah Guru'}</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-300">NIP</label>
                  <input
                    type="text"
                    value={formData.nip || ''}
