              showToast('Data CSV kosong atau format salah.', 'error');
              return;
          }

          const { error } = await supabase.from('kelas').upsert(parsedData, { onConflict: 'kode' });

          if (error) throw error;

          showToast(`Berhasil mengimport ${parsedData.length} data kelas`, 'success');
          fetchData();
        } catch (error) {
          console.error(error);
          showToast('Gagal mengimport CSV.', 'error');
        } finally {
          if (fileInputRef.current) fileInputRef.current.value = '';
        }
      },
      error: (error) => {
        showToast('Gagal membaca file CSV', 'error');
      }
    });
  };

  return (
