        .eq('id_guru', currentUser.id);

      if (data) {
        // @ts-ignore
        setKelasOptions(Array.from(new Map(data.map(item => [item.id_kelas, item.kelas])).values()));
        // @ts-ignore
        setMapelOptions(Array.from(new Map(data.map(item => [item.id_mapel, item.mapel])).values()));
      }
    };
    fetchAssignments();
  }, [currentUser.id]);

  useEffect(() => {
    if (selectedKelas && selectedMapel) {
       setLoading(true);
       const loadData = async () => {
           // Fetch students
           const { data: students } = await supabase.from('siswa').select('*').eq('id_kelas', selectedKelas).order('nama');
           // Fetch grades
           const { data: grades } = await supabase.from('nilai')
             .select('*')
             .eq('id_guru', currentUser.id)
             .eq('id_mapel', selectedMapel);

           if (students && grades) {
               const processed = students.map(s => {
                   const sGrades = grades.filter(g => g.id_siswa === s.id);
                   const formatif = sGrades.find(g => g.jenis === 'FORMATIF')?.nilai || 0;
                   const sumatif = sGrades.find(g => g.jenis === 'SUMATIF')?.nilai || 0;
                   const akhir = sGrades.find(g => g.jenis === 'AKHIR_SUMATIF')?.nilai || 0;
                   const avg = (Number(formatif) + Number(sumatif) + Number(akhir)) / 3;

                   return {
                       nama: s.nama,
                       formatif: Number(formatif),
                       sumatif: Number(sumatif),
                       akhir: Number(akhir),
                       rata: parseFloat(avg.toFixed(1))
                   };
               });
               setReportData(processed);
           }
           setLoading(false);
       };
       loadData();
    } else {
        setReportData([]);
    }
  }, [selectedKelas, selectedMapel, currentUser.id]);

  const handleExport = () => {
    if (reportData.length === 0) return;

    // Get Class and Mapel Name for filename
    const clsName = kelasOptions.find(k => k.id === selectedKelas)?.nama || 'Kelas';
    const mapelName = mapelOptions.find(m => m.id === selectedMapel)?.nama || 'Mapel';
    const filename = `rekap_nilai_${clsName.replace(/\s+/g, '_')}_${mapelName.replace(/\s+/g, '_')}.csv`;

    const csv = Papa.unparse(reportData);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');

    link.href = url;
    link.setAttribute('download', filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
          <h2 className="text-2xl font-bold text-white">Rekap Nilai Siswa</h2>
          {reportData.length > 0 && (
            <button 
                onClick={handleExport}
                className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700 transition flex items-center gap-2"
            >
                <span>📊</span> Ekspor Excel
            </button>
          )}
      </div>

      {/* Filters */}
      <div className="flex flex-col md:flex-row gap-4 mb-6">
           <select 
             className="bg-gray-700 border border-gray-600 rounded p-2 text-white flex-1"
             value={selectedKelas}
             onChange={(e) => setSelectedKelas(e.target.value)}
           >
             <option value="">-- Pilih Kelas --</option>
             {kelasOptions.map(k => <option key={k.id} value={k.id}>{k.nama}</option>)}
           </select>
           <select 
             className="bg-gray-700 border border-gray-600 rounded p-2 text-white flex-1"
             value={selectedMapel}
             onChange={(e) => setSelectedMapel(e.target.value)}
           >
             <option value="">-- Pilih Mapel --</option>
             {mapelOptions.map(m => <option key={m.id} value={m.id}>{m.nama}</option>)}
           </select>
      </div>

      {loading ? <p className="text-gray-400">Menghitung...</p> : (
         selectedKelas && selectedMapel ? (
             <div className="space-y-8">
                 {/* Chart */}
                 <div className="bg-gray-800 p-4 rounded-lg border border-gray-700 h-80">
                    <h3 className="text-white mb-4 text-sm font-semibold">Grafik Rata-rata Nilai</h3>
                    <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={reportData}>
                            <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
                            <XAxis dataKey="nama" stroke="#9CA3AF" hide />
                            <YAxis stroke="#9CA3AF" domain={[0, 100]} />
                            <Tooltip 
                                contentStyle={{ backgroundColor: '#1F2937', borderColor: '#374151', color: '#F3F4F6' }} 
                            />
                            <Legend />
                            <Bar dataKey="formatif" fill="#3B82F6" name="Formatif" />
                            <Bar dataKey="sumatif" fill="#10B981" name="Sumatif" />
                            <Bar dataKey="akhir" fill="#F59E0B" name="Akhir" />
                        </BarChart>
                    </ResponsiveContainer>
                 </div>

                 {/* Table */}
                 <div className="bg-gray-800 shadow overflow-x-auto rounded-lg border border-gray-700">
                    <table className="min-w-full divide-y divide-gray-700">
                        <thead className="bg-gray-700">
                            <tr>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Nama Siswa</th>
                                <th className="px-6 py-3 text-center text-xs font-medium text-gray-300 uppercase">Formatif</th>
                                <th className="px-6 py-3 text-center text-xs font-medium text-gray-300 uppercase">Sumatif</th>
                                <th className="px-6 py-3 text-center text-xs font-medium text-gray-300 uppercase">Akhir</th>
                                <th className="px-6 py-3 text-center text-xs font-medium text-gray-300 uppercase font-bold text-white">Rata-rata</th>
                            </tr>
                        </thead>
                        <tbody className="bg-gray-800 divide-y divide-gray-700">
                            {reportData.map((row, idx) => (
                                <tr key={idx}>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-white">{row.nama}</td>
                                    <td className="px-6 py-4 text-center text-sm text-gray-300">{row.formatif}</td>
                                    <td className="px-6 py-4 text-center text-sm text-gray-300">{row.sumatif}</td>
                                    <td className="px-6 py-4 text-center text-sm text-gray-300">{row.akhir}</td>
                                    <td className="px-6 py-4 text-center text-sm font-bold text-blue-400">{row.rata}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                 </div>
             </div>
         ) : (
            <div className="p-10 text-center text-gray-500 border-2 border-dashed border-gray-700 rounded-lg">
                Pilih filter di atas untuk melihat rekap nilai.
            </div>
         )
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../supabaseClient';
import { Guru } from '../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, Legend, ResponsiveContainer, CartesianGrid } from 'recharts';
import Papa from 'papaparse';

interface GwLaporanProps {
  currentUser: Guru;
}

export const GwLaporan: React.FC<GwLaporanProps> = ({ currentUser }) => {
  const [summary, setSummary] = useState({ hadir: 0, sakit: 0, izin: 0, alpha: 0, pelanggaran: 0, prestasi: 0 });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);

      // 1. Get attendance stats
      const { data: attData } = await supabase
        .from('kehadiran')
        .select('status')
        .eq('id_guru', currentUser.id);

      const hadir = attData?.filter(x => x.status === 'HADIR').length || 0;
      const sakit = attData?.filter(x => x.status === 'SAKIT').length || 0;
      const izin = attData?.filter(x => x.status === 'IZIN').length || 0;
      const alpha = attData?.filter(x => x.status === 'ALPHA').length || 0;

      // 2. Get violations count
      const { count: pelCount } = await supabase
        .from('pelanggaran')
        .select('*', { count: 'exact', head: true })
        .eq('id_guru', currentUser.id);

      // 3. Get achievements count
      const { count: presCount } = await supabase
        .from('prestasi')
        .select('*', { count: 'exact', head: true })
        .eq('id_guru', currentUser.id);

      setSummary({
          hadir, sakit, izin, alpha,
          pelanggaran: pelCount || 0,
          prestasi: presCount || 0
      });
      setLoading(false);
    };

    fetchData();
  }, [currentUser.id]);

  const chartData = [
    { name: 'Hadir', jumlah: summary.hadir, fill: '#10B981' },
    { name: 'Sakit', jumlah: summary.sakit, fill: '#F59E0B' },
    { name: 'Izin', jumlah: summary.izin, fill: '#3B82F6' },
    { name: 'Alpha', jumlah: summary.alpha, fill: '#EF4444' },
  ];

  const handleExport = () => {
    const dataToExport = [
        { Kategori: 'Total Kehadiran', Jumlah: summary.hadir },
        { Kategori: 'Total Sakit', Jumlah: summary.sakit },
        { Kategori: 'Total Izin', Jumlah: summary.izin },
        { Kategori: 'Total Alpha', Jumlah: summary.alpha },
        { Kategori: 'Total Pelanggaran', Jumlah: summary.pelanggaran },
        { Kategori: 'Total Prestasi', Jumlah: summary.prestasi },
        { Kategori: 'Tanggal Cetak', Jumlah: new Date().toLocaleDateString('id-ID') }
    ];

    const csv = Papa.unparse(dataToExport);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');

    link.href = url;
    link.setAttribute('download', `laporan_wali_kelas_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-white">Laporan Rekapitulasi</h2>
        <button 
            onClick={handleExport}
            disabled={loading}
            className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700 transition flex items-center gap-2 disabled:opacity-50"
        >
            <span>📊</span> Ekspor Excel
        </button>
      </div>

      {loading ? <p className="text-gray-400">Menghitung data...</p> : (
        <div className="space-y-8">
            {/* Cards */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <div className="bg-gray-800 p-4 rounded border border-gray-700">
                    <p className="text-gray-400 text-sm">Total Pelanggaran</p>
                    <p className="text-2xl font-bold text-red-500">{summary.pelanggaran}</p>
                </div>
                <div className="bg-gray-800 p-4 rounded border border-gray-700">
                    <p className="text-gray-400 text-sm">Total Prestasi</p>
                    <p className="text-2xl font-bold text-green-500">{summary.prestasi}</p>
                </div>
                <div className="bg-gray-800 p-4 rounded border border-gray-700">
                    <p className="text-gray-400 text-sm">Total Alpha</p>
                    <p className="text-2xl font-bold text-red-400">{summary.alpha}</p>
                </div>
                 <div className="bg-gray-800 p-4 rounded border border-gray-700">
                    <p className="text-gray-400 text-sm">Total Kehadiran</p>
                    <p className="text-2xl font-bold text-blue-400">{summary.hadir}</p>
                </div>
            </div>

            {/* Chart */}
            <div className="bg-gray-800 p-6 rounded-lg border border-gray-700">
                <h3 className="text-lg font-semibold text-white mb-4">Grafik Kehadiran Siswa Binaan</h3>
                <div className="h-80 w-full">
                    <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={chartData}>
                            <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
                            <XAxis dataKey="name" stroke="#9CA3AF" />
                            <YAxis stroke="#9CA3AF" />
                            <Tooltip 
                                contentStyle={{ backgroundColor: '#1F2937', borderColor: '#374151', color: '#F3F4F6' }} 
                                itemStyle={{ color: '#F3F4F6' }}
                            />
                            <Bar dataKey="jumlah" radius={[4, 4, 0, 0]} />
                        </BarChart>
                    </ResponsiveContainer>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useRef } from 'react';
import { supabase } from '../supabaseClient';
import { Guru } from '../types';
import Papa from 'papaparse';

interface CrudGuruProps {
  showToast: (msg: string, type: 'success' | 'error') => void;
}

export const CrudGuru: React.FC<CrudGuruProps> = ({ showToast }) => {
  const [data, setData] = useState<Guru[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Guru>>({});
  const [isEditing, setIsEditing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Filter States
  const [searchTerm, setSearchTerm] = useState('');
  const [filterPeran, setFilterPeran] = useState('');

  const fetchData = async () => {
    try {
      const { data: guruData, error } = await supabase
        .from('guru')
        .select('*')
        .order('nama', { ascending: true });

      if (error) throw error;
      setData(guruData || []);
    } catch (error) {
      showToast('Gagal memuat data guru', 'error');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();

    // Realtime subscription
    const channel = supabase
      .channel('guru_changes')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'guru' }, () => {
        fetchData();
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
     // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleDelete = async (id: string) => {
    if (!window.confirm('Yakin ingin menghapus data ini?')) return;

    try {
      const { error } = await supabase.from('guru').delete().eq('id', id);
      if (error) throw error;
      showToast('Data guru berhasil dihapus', 'success');
    } catch (error) {
      showToast('Gagal menghapus data', 'error');
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (isEditing && formData.id) {
        // Update
        const { error } = await supabase
          .from('guru')
          .update({
            nip: formData.nip,
            nama: formData.nama,
            jenis_kelamin: formData.jenis_kelamin,
            no_hp: formData.no_hp,
            username: formData.username,
            password: formData.password, // In a real app, handle carefully
            peran: formData.peran
          })
          .eq('id', formData.id);
        if (error) throw error;
        showToast('Guru berhasil diperbarui', 'success');
      } else {
        // Create
        const { error } = await supabase
          .from('guru')
          .insert([{
            nip: formData.nip,
            nama: formData.nama,
            jenis_kelamin: formData.jenis_kelamin,
            no_hp: formData.no_hp,
            username: formData.username,
            password: formData.password,
            peran: formData.peran || 'GURU_WALI'
          }]);
        if (error) throw error;
        showToast('Guru berhasil ditambahkan', 'success');
      }
      setIsModalOpen(false);
      setFormData({});
    } catch (error: any) {
        const msg = error.code === '23505' ? 'Username sudah digunakan' : 'Gagal menyimpan data';
        showToast(msg, 'error');
    }
  };

  const openModal = (guru?: Guru) => {
    if (guru) {
      setIsEditing(true);
      setFormData(guru);
    } else {
      setIsEditing(false);
      setFormData({ peran: 'GURU_WALI', jenis_kelamin: 'L' });
    }
    setIsModalOpen(true);
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: async (results) => {
        try {
          const parsedData = results.data.map((row: any) => ({
            nip: row.nip || null,
            nama: row.nama,
            jenis_kelamin: row.jenis_kelamin || 'L',
            no_hp: row.no_hp || null,
            username: row.username,
            password: row.password || '123456', // Default password if missing
            peran: row.peran || 'GURU_WALI'
          }));

          const { error } = await supabase.from('guru').upsert(parsedData, { onConflict: 'username' });

          if (error) throw error;

          showToast(`Berhasil mengimport ${parsedData.length} data guru`, 'success');
          fetchData();
        } catch (error) {
          console.error(error);
          showToast('Gagal mengimport CSV. Pastikan format benar.', 'error');
        } finally {
          if (fileInputRef.current) fileInputRef.current.value = '';
        }
      },
      error: (error) => {
        showToast('Gagal membaca file CSV', 'error');
      }
    });
  };

  // Filter Logic
  const filteredData = data.filter(guru => {
    const matchesSearch = 
      guru.nama.toLowerCase().includes(searchTerm.toLowerCase()) || 
      (guru.nip && guru.nip.includes(searchTerm)) ||
      guru.username.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesRole = filterPeran === '' || guru.peran === filterPeran;

    return matchesSearch && matchesRole;
  });

  return (
    <div>
      <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
        <h2 className="text-2xl font-bold text-white">Manajemen Guru</h2>
        <div className="flex flex-wrap gap-2">
            <input 
              type="file" 
              accept=".csv" 
              ref={fileInputRef} 
              onChange={handleFileUpload} 
              className="hidden" 
            />
            <button
              onClick={() => fileInputRef.current?.click()}
              className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700 transition"
            >
              📂 Import CSV
            </button>
            <button
              onClick={() => openModal()}
              className="bg-primary text-white px-4 py-2 rounded hover:bg-secondary transition"
            >
              + Tambah Guru
            </button>
        </div>
      </div>

      {/* Filter Bar */}
      <div className="flex flex-col md:flex-row gap-4 mb-6 bg-gray-800 p-4 rounded-lg border border-gray-700">
        <div className="flex-1">
          <input
            type="text"
            placeholder="Cari Nama / NIP / Username..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white placeholder-gray-400 focus:outline-none focus:border-primary"
          />
        </div>
        <div className="w-full md:w-64">
           <select
             value={filterPeran}
             onChange={(e) => setFilterPeran(e.target.value)}
             className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white focus:outline-none focus:border-primary"
           >
             <option value="">Semua Peran</option>
             <option value="ADMIN">Admin</option>
             <option value="GURU_WALI">Guru Wali</option>
             <option value="GURU_PENGAJAR">Guru Pengajar</option>
           </select>
        </div>
      </div>

      {loading ? (
        <p className="text-gray-400">Memuat data...</p>
      ) : (
        <div className="bg-gray-800 shadow overflow-x-auto rounded-lg border border-gray-700">
          <table className="min-w-full divide-y divide-gray-700">
            <thead className="bg-gray-700">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">Nama / NIP</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">L/P</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">No HP</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">Akun</th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-300 uppercase tracking-wider">Aksi</th>
              </tr>
            </thead>
            <tbody className="bg-gray-800 divide-y divide-gray-700">
              {filteredData.map((guru) => (
                <tr key={guru.id}>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="text-sm font-medium text-white">{guru.nama}</div>
                    <div className="text-sm text-gray-400">{guru.nip || '-'}</div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">{guru.jenis_kelamin}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">{guru.no_hp}</td>
                  <td className="px-6 py-4 whitespace-nowrap">
                     <div className="text-sm text-white">{guru.username}</div>
                     <span className={`text-xs inline-flex px-2 py-1 rounded-full ${guru.peran === 'ADMIN' ? 'bg-purple-900 text-purple-200' : 'bg-green-900 text-green-200'}`}>
                        {guru.peran}
                     </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                    <button onClick={() => openModal(guru)} className="text-indigo-400 hover:text-indigo-300 mr-4">Edit</button>
                    <button onClick={() => handleDelete(guru.id)} className="text-red-400 hover:text-red-300">Hapus</button>
                  </td>
                </tr>
              ))}
              {filteredData.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-6 py-4 text-center text-gray-500">
                    Tidak ada data guru yang cocok.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      )}

      {/* Modal Form */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50 p-4">
          <div className="bg-gray-800 rounded-lg shadow-lg w-full max-w-lg p-6 max-h-[90vh] overflow-y-auto border border-gray-700">
            <h3 className="text-lg font-bold mb-4 text-white">{isEditing ? 'Edit Guru' : 'Tambah Guru'}</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-300">NIP</label>
                  <input
                    type="text"
                    value={formData.nip || ''}
                    onChange={(e) => setFormData({ ...formData, nip: e.target.value })}
                    className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm focus:ring-primary focus:border-primary text-white"
                  />
                </div>
                <div>
                   <label className="block text-sm font-medium text-gray-300">Peran</label>
                   <select
                      value={formData.peran || 'GURU_WALI'}
                      onChange={(e) => setFormData({ ...formData, peran: e.target.value })}
                      className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 text-white"
                   >
                     <option value="GURU_WALI">Guru Wali</option>
                     <option value="ADMIN">Admin</option>
                     <option value="GURU_PENGAJAR">Guru Pengajar</option>
                   </select>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-300">Nama Lengkap *</label>
                <input
                  type="text"
                  required
                  value={formData.nama || ''}
