              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../supabaseClient';
import { Guru } from '../types';

interface PengajarDashboardProps {
  currentUser: Guru;
}

export const PengajarDashboard: React.FC<PengajarDashboardProps> = ({ currentUser }) => {
  const [stats, setStats] = useState({
    kelasAjar: 0,
    mapelAjar: 0,
    totalNilai: 0,
    rataRata: 0
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchStats = async () => {
      try {
        // 1. Get unique classes & mapel from assignments
        const { data: pengajaran } = await supabase
          .from('pengajaran')
          .select('id_kelas, id_mapel')
          .eq('id_guru', currentUser.id);

        const uniqueKelas = new Set(pengajaran?.map(p => p.id_kelas)).size;
        const uniqueMapel = new Set(pengajaran?.map(p => p.id_mapel)).size;

        // 2. Get grades stats (count & avg)
        const { data: nilaiData } = await supabase
          .from('nilai')
          .select('nilai')
          .eq('id_guru', currentUser.id);

        const totalNilai = nilaiData?.length || 0;
        const sumNilai = nilaiData?.reduce((acc, curr) => acc + (curr.nilai || 0), 0) || 0;
        const avg = totalNilai > 0 ? parseFloat((sumNilai / totalNilai).toFixed(1)) : 0;

        // @ts-ignore
        setStats({
          kelasAjar: uniqueKelas,
          mapelAjar: uniqueMapel,
          totalNilai,
          rataRata: avg
        });

      } catch (error) {
        console.error("Error fetching pengajar stats", error);
      } finally {
        setLoading(false);
      }
    };

    fetchStats();
  }, [currentUser.id]);

  const Card = ({ title, count, color, icon, subtext }: any) => (
    <div className={`bg-gray-800 p-6 rounded-lg shadow border-l-4 ${color} flex items-center justify-between`}>
      <div>
        <h3 className="text-gray-400 text-sm font-medium uppercase">{title}</h3>
        <p className="text-3xl font-bold text-white mt-1">{loading ? '...' : count}</p>
        {subtext && <p className="text-xs text-gray-500 mt-1">{subtext}</p>}
      </div>
      <div className="text-3xl opacity-50">{icon}</div>
    </div>
  );

  return (
    <div className="p-4">
      <h2 className="text-3xl font-bold text-white mb-2">Dashboard Pengajar</h2>
      <p className="text-gray-400 mb-8">Ringkasan aktivitas pengajaran Anda.</p>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
        <Card title="Kelas Diajar" count={stats.kelasAjar} icon="🏫" color="border-indigo-500" subtext="Kelas Aktif" />
        <Card title="Mapel Diampu" count={stats.mapelAjar} icon="📘" color="border-blue-500" subtext="Mata Pelajaran" />
        <Card title="Data Nilai" count={stats.totalNilai} icon="📊" color="border-green-500" subtext="Total Input" />
        <Card title="Rata-rata Nilai" count={stats.rataRata} icon="📈" color="border-yellow-500" subtext="Seluruh Siswa" />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="col-span-2 bg-gray-800 p-6 rounded-lg border border-gray-700">
          <h3 className="text-lg font-semibold text-white mb-3">Panduan Penilaian</h3>
          <ul className="list-disc list-inside text-gray-300 space-y-2 text-sm">
             <li>Gunakan menu <strong>Penilaian</strong> untuk input nilai Formatif dan Sumatif.</li>
             <li>Nilai tersimpan otomatis saat Anda berpindah kolom input (auto-save).</li>
             <li>Gunakan menu <strong>Rekap Nilai</strong> untuk melihat grafik perkembangan siswa dan mengekspor ke Excel.</li>
          </ul>
        </div>

        <div className="bg-gray-800 p-6 rounded-lg border border-gray-700">
          <h3 className="text-lg font-semibold text-white mb-2">Akun</h3>
          <p className="text-sm text-gray-400">Pengajar: <span className="text-white font-bold">{currentUser.nama}</span></p>
          <p className="text-sm text-gray-400">NIP: {currentUser.nip || '-'}</p>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Login } from './components/Login';
// Admin Components
import { AdminDashboard } from './components/AdminDashboard';
import { CrudGuru } from './components/CrudGuru';
import { CrudSiswa } from './components/CrudSiswa';
import { CrudKelas } from './components/CrudKelas';
import { CrudMapel } from './components/CrudMapel';
// Guru Wali Components
import { GwDashboard } from './components/GwDashboard';
import { GwSiswa } from './components/GwSiswa';
import { GwKehadiran } from './components/GwKehadiran';
import { GwPelanggaran } from './components/GwPelanggaran';
import { GwPrestasi } from './components/GwPrestasi';
import { GwLaporan } from './components/GwLaporan';
// Guru Pengajar Components
import { PengajarDashboard } from './components/PengajarDashboard';
import { PengajarPenilaian } from './components/PengajarPenilaian';
import { PengajarRekapNilai } from './components/PengajarRekapNilai';

import { Toast } from './components/Toast';
import { Guru, ViewState } from './types';

function App() {
  const [session, setSession] = useState<Guru | null>(null);
  const [currentView, setCurrentView] = useState<ViewState>('DASHBOARD');
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

  useEffect(() => {
    // Check localStorage for persisted session
    const storedUser = localStorage.getItem('gurwal_admin_user');
    const storedView = localStorage.getItem('gurwal_current_view') as ViewState;

    if (storedUser) {
      try {
        const user = JSON.parse(storedUser);
        setSession(user);

        // Restore view if available, otherwise default based on role
        if (storedView) {
          setCurrentView(storedView);
        } else {
          if (user.peran === 'GURU_WALI') setCurrentView('GW_DASHBOARD');
          else if (user.peran === 'GURU_PENGAJAR') setCurrentView('PENGAJAR_DASHBOARD');
          else setCurrentView('DASHBOARD');
        }
      } catch (e) {
        localStorage.removeItem('gurwal_admin_user');
        localStorage.removeItem('gurwal_current_view');
      }
    }
  }, []);

  const handleLoginSuccess = (user: Guru) => {
    setSession(user);
    localStorage.setItem('gurwal_admin_user', JSON.stringify(user));

    let defaultView: ViewState = 'DASHBOARD';
    if (user.peran === 'GURU_WALI') defaultView = 'GW_DASHBOARD';
    else if (user.peran === 'GURU_PENGAJAR') defaultView = 'PENGAJAR_DASHBOARD';

    setCurrentView(defaultView);
    localStorage.setItem('gurwal_current_view', defaultView);
  };

  const handleLogout = () => {
    setSession(null);
    localStorage.removeItem('gurwal_admin_user');
    localStorage.removeItem('gurwal_current_view');
    showToast('Anda telah keluar', 'success');
  };

  const handleChangeView = (view: ViewState) => {
    setCurrentView(view);
    localStorage.setItem('gurwal_current_view', view);
  };

  const showToast = (message: string, type: 'success' | 'error') => {
    setToast({ message, type });
  };

  // Render Logic
  if (!session) {
    return (
      <>
        <Login onLoginSuccess={handleLoginSuccess} showToast={showToast} />
        {toast && (
          <Toast
            message={toast.message}
            type={toast.type}
            onClose={() => setToast(null)}
          />
        )}
      </>
    );
  }

  const renderContent = () => {
    switch (currentView) {
      // ADMIN
      case 'GURU':
        return <CrudGuru showToast={showToast} />;
      case 'SISWA':
        return <CrudSiswa showToast={showToast} />;
      case 'KELAS':
        return <CrudKelas showToast={showToast} />;
      case 'MAPEL':
        return <CrudMapel showToast={showToast} />;
      case 'DASHBOARD':
        return <AdminDashboard />;

      // GURU WALI
      case 'GW_DASHBOARD':
        return <GwDashboard currentUser={session} />;
      case 'GW_SISWA':
        return <GwSiswa currentUser={session} showToast={showToast} />;
      case 'GW_KEHADIRAN':
        return <GwKehadiran currentUser={session} showToast={showToast} />;
      case 'GW_PELANGGARAN':
        return <GwPelanggaran currentUser={session} showToast={showToast} />;
      case 'GW_PRESTASI':
        return <GwPrestasi currentUser={session} showToast={showToast} />;
      case 'GW_LAPORAN':
        return <GwLaporan currentUser={session} />;

      // GURU PENGAJAR
      case 'PENGAJAR_DASHBOARD':
        return <PengajarDashboard currentUser={session} />;
      case 'PENGAJAR_PENILAIAN':
        return <PengajarPenilaian currentUser={session} showToast={showToast} />;
      case 'PENGAJAR_REKAP':
        return <PengajarRekapNilai currentUser={session} />;

      default:
        return <div className="p-6 text-white">Halaman tidak ditemukan</div>;
    }
  };

  return (
    <Layout
      currentUser={session}
      currentView={currentView}
      onChangeView={handleChangeView}
      onLogout={handleLogout}
    >
      {renderContent()}
      {toast && (
        <Toast
          message={toast.message}
          type={toast.type}
          onClose={() => setToast(null)}
        />
      )}
    </Layout>
  );
}

export default App;

import React, { useEffect, useState, useRef } from 'react';
import { supabase } from '../supabaseClient';
import { Guru } from '../types';
import Papa from 'papaparse';

interface CrudGuruProps {
  showToast: (msg: string, type: 'success' | 'error') => void;
}

export const CrudGuru: React.FC<CrudGuruProps> = ({ showToast }) => {
  const [data, setData] = useState<Guru[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Guru>>({});
  const [isEditing, setIsEditing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Filter States
  const [searchTerm, setSearchTerm] = useState('');
  const [filterPeran, setFilterPeran] = useState('');

  const fetchData = async () => {
    try {
      const { data: guruData, error } = await supabase
        .from('guru')
        .select('*')
        .order('nama', { ascending: true });

      if (error) throw error;
      setData(guruData || []);
    } catch (error) {
      // Silent error or toast if needed
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();

    // Realtime subscription
    const channel = supabase
      .channel('guru_changes')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'guru' }, () => {
        fetchData();
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
     // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleDelete = async (id: string) => {
    if (!window.confirm('Yakin ingin menghapus data ini?')) return;

    try {
      const { error } = await supabase.from('guru').delete().eq('id', id);
      if (error) throw error;
      showToast('Data guru berhasil dihapus', 'success');
      fetchData(); // Instant update
    } catch (error) {
      showToast('Gagal menghapus data', 'error');
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (isEditing && formData.id) {
        // Update
        const { error } = await supabase
          .from('guru')
          .update({
            nip: formData.nip,
            nama: formData.nama,
            jenis_kelamin: formData.jenis_kelamin,
            no_hp: formData.no_hp,
            username: formData.username,
            password: formData.password, // In a real app, handle carefully
            peran: formData.peran
          })
          .eq('id', formData.id);
        if (error) throw error;
        showToast('Guru berhasil diperbarui', 'success');
      } else {
        // Create
        const { error } = await supabase
          .from('guru')
          .insert([{
            nip: formData.nip,
            nama: formData.nama,
            jenis_kelamin: formData.jenis_kelamin,
            no_hp: formData.no_hp,
            username: formData.username,
            password: formData.password,
            peran: formData.peran || 'GURU_WALI'
          }]);
        if (error) throw error;
        showToast('Guru berhasil ditambahkan', 'success');
      }
      setIsModalOpen(false);
      setFormData({});
      fetchData(); // Instant update
    } catch (error: any) {
        const msg = error.code === '23505' ? 'Username sudah digunakan' : 'Gagal menyimpan data';
        showToast(msg, 'error');
    }
  };

  const openModal = (guru?: Guru) => {
    if (guru) {
      setIsEditing(true);
      setFormData(guru);
    } else {
      setIsEditing(false);
      setFormData({ peran: 'GURU_WALI', jenis_kelamin: 'L' });
    }
    setIsModalOpen(true);
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: async (results) => {
        try {
          const parsedData = results.data.map((row: any) => ({
            nip: row.nip || null,
            nama: row.nama,
            jenis_kelamin: row.jenis_kelamin || 'L',
            no_hp: row.no_hp || null,
            username: row.username,
            password: row.password || '123456', // Default password if missing
            peran: row.peran || 'GURU_WALI'
          }));

          const { error } = await supabase.from('guru').upsert(parsedData, { onConflict: 'username' });

          if (error) throw error;

          showToast(`Berhasil mengimport ${parsedData.length} data guru`, 'success');
          fetchData();
        } catch (error) {
          console.error(error);
          showToast('Gagal mengimport CSV. Pastikan format benar.', 'error');
        } finally {
          if (fileInputRef.current) fileInputRef.current.value = '';
        }
      },
      error: (error) => {
        showToast('Gagal membaca file CSV', 'error');
      }
    });
  };

  // Filter Logic
  const filteredData = data.filter(guru => {
    const matchesSearch = 
      guru.nama.toLowerCase().includes(searchTerm.toLowerCase()) || 
      (guru.nip && guru.nip.includes(searchTerm)) ||
      guru.username.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesRole = filterPeran === '' || guru.peran === filterPeran;

    return matchesSearch && matchesRole;
