import React, { useEffect, useState, useRef } from 'react';
import { supabase } from '../supabaseClient';
import { Kelas } from '../types';
import Papa from 'papaparse';
import { ConfirmDialog } from './ConfirmDialog';

interface CrudKelasProps {
  showToast: (msg: string, type: 'success' | 'error') => void;
}

export const CrudKelas: React.FC<CrudKelasProps> = ({ showToast }) => {
  const [data, setData] = useState<Kelas[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Kelas>>({});
  const [isEditing, setIsEditing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Import State
  const [isImporting, setIsImporting] = useState(false);
  const [importProgress, setImportProgress] = useState(0);

  // Delete State
  const [deleteId, setDeleteId] = useState<string | null>(null);

  const fetchData = async () => {
    try {
      const { data: kelasData, error } = await supabase.from('kelas').select('*').order('nama', { ascending: true });
      if (error) throw error;
      setData(kelasData || []);
    } catch (error) {
      showToast('Gagal memuat data kelas', 'error');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
    const channel = supabase
      .channel('kelas_changes')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'kelas' }, () => fetchData())
      .subscribe();
    return () => { supabase.removeChannel(channel); };
     // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleDeleteClick = (id: string) => {
    setDeleteId(id);
  };

  const confirmDelete = async () => {
    if (!deleteId) return;
    try {
      const { error } = await supabase.from('kelas').delete().eq('id', deleteId);
      if (error) throw error;
      showToast('Kelas dihapus', 'success');
      fetchData();
    } catch (error) {
      showToast('Gagal menghapus (mungkin masih ada siswa terkait)', 'error');
    } finally {
      setDeleteId(null);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (isEditing && formData.id) {
        const { error } = await supabase.from('kelas').update({ kode: formData.kode, nama: formData.nama }).eq('id', formData.id);
        if (error) throw error;
        showToast('Kelas diperbarui', 'success');
      } else {
        const { error } = await supabase.from('kelas').insert([{ kode: formData.kode, nama: formData.nama }]);
        if (error) throw error;
        showToast('Kelas ditambahkan', 'success');
      }
      setIsModalOpen(false);
      setFormData({});
      fetchData();
    } catch (error: any) {
       const msg = error.code === '23505' ? 'Kode kelas sudah digunakan' : 'Gagal menyimpan data';
       showToast(msg, 'error');
    }
  };

  const openModal = (item?: Kelas) => {
    if (item) { setIsEditing(true); setFormData(item); }
    else { setIsEditing(false); setFormData({}); }
    setIsModalOpen(true);
  };

  const handleExport = () => {
    if (data.length === 0) {
      showToast('Tidak ada data untuk diekspor', 'error');
      return;
    }

    const exportData = data.map(item => ({
      'Kode Kelas': item.kode,
      'Nama Kelas': item.nama
    }));

    const csv = Papa.unparse(exportData);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');

    const timestamp = new Date().toISOString().split('T')[0];
    link.href = url;
    link.setAttribute('download', `data_kelas_gurwal_${timestamp}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleDownloadTemplate = () => {
    const templateData = [
      { kode: 'X-IPA-1', nama: 'Sepuluh IPA Satu' },
      { kode: 'X-IPA-2', nama: 'Sepuluh IPA Dua' },
      { kode: 'XI-IPS-1', nama: 'Sebelas IPS Satu' }
    ];

    const csv = Papa.unparse(templateData);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');

    link.href = url;
    link.setAttribute('download', 'template_import_kelas.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsImporting(true);
    setImportProgress(0);

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: async (results) => {
        try {
          // Expected columns: kode, nama
          const parsedData = results.data.map((row: any) => ({
            kode: row.kode ? String(row.kode).trim() : '',
            nama: row.nama ? String(row.nama).trim() : ''
          })).filter((row: any) => row.kode !== '' && row.nama !== '');

          if (parsedData.length === 0) {
              throw new Error('Data CSV kosong');
          }

          // Batch Processing
          const BATCH_SIZE = 50;
          const total = parsedData.length;

          for (let i = 0; i < total; i += BATCH_SIZE) {
             const batch = parsedData.slice(i, i + BATCH_SIZE);
             const { error } = await supabase.from('kelas').upsert(batch, { onConflict: 'kode' });

             if (error) throw error;

             // Update Progress
             const currentProgress = Math.min(Math.round(((i + batch.length) / total) * 100), 100);
             setImportProgress(currentProgress);
          }

          showToast(`Berhasil mengimport ${total} data kelas`, 'success');
          fetchData();
        } catch (error) {
          console.error(error);
          showToast('Gagal mengimport CSV. Pastikan format benar.', 'error');
        } finally {
          setIsImporting(false);
          setImportProgress(0);
          if (fileInputRef.current) fileInputRef.current.value = '';
        }
      },
      error: (error) => {
        setIsImporting(false);
        showToast('Gagal membaca file CSV', 'error');
      }
    });
  };

  return (
    <div>
      <ConfirmDialog
        isOpen={!!deleteId}
        message="Hapus kelas? Perhatian: Siswa di kelas ini akan kehilangan referensi kelas."
        onConfirm={confirmDelete}
        onCancel={() => setDeleteId(null)}
      />

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-white">Manajemen Kelas</h2>
        <div className="flex gap-2">
            <button
              onClick={handleExport}
              className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 transition flex items-center gap-2"
            >
              📤 Ekspor Data
            </button>
            <button
              onClick={handleDownloadTemplate}
              className="bg-gray-600 text-white px-4 py-2 rounded hover:bg-gray-500 transition flex items-center gap-2"
            >
              📥 Template
            </button>
            <input 
              type="file" 
              accept=".csv" 
              ref={fileInputRef} 
              onChange={handleFileUpload} 
              className="hidden" 
            />
            <button
              onClick={() => fileInputRef.current?.click()}
              className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700 transition"
            >
              📂 Import CSV
            </button>
            <button onClick={() => openModal()} className="bg-primary text-white px-4 py-2 rounded hover:bg-secondary transition">+ Tambah Kelas</button>
        </div>
      </div>

      {/* Import Progress Overlay */}
      {isImporting && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-80">
          <div className="bg-gray-800 p-6 rounded-lg border border-gray-700 w-80 md:w-96 text-center">
            <h3 className="text-white font-bold mb-4 text-lg">Mengimport Data...</h3>
            <div className="w-full bg-gray-700 rounded-full h-4 mb-2 overflow-hidden">
               <div 
                 className="bg-green-500 h-4 rounded-full transition-all duration-300" 
                 style={{ width: `${importProgress}%` }}
               ></div>
            </div>
            <p className="text-gray-300 font-medium">{importProgress}%</p>
            <p className="text-gray-500 text-sm mt-1">Mohon jangan tutup halaman ini.</p>
          </div>
        </div>
      )}

      {loading ? <p className="text-gray-400">Memuat data...</p> : (
        <div className="bg-gray-800 shadow overflow-hidden rounded-lg border border-gray-700">
          <table className="min-w-full divide-y divide-gray-700">
            <thead className="bg-gray-700">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Kode</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Nama Kelas</th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-300 uppercase">Aksi</th>
              </tr>
            </thead>
            <tbody className="bg-gray-800 divide-y divide-gray-700">
              {data.map((item) => (
                <tr key={item.id}>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-white font-bold">{item.kode}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-white">{item.nama}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                    <button onClick={() => openModal(item)} className="text-indigo-400 hover:text-indigo-300 mr-4">Edit</button>
                    <button onClick={() => handleDeleteClick(item.id)} className="text-red-400 hover:text-red-300">Hapus</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50 p-4">
          <div className="bg-gray-800 rounded-lg shadow-lg w-full max-w-md p-6 border border-gray-700">
            <h3 className="text-lg font-bold mb-4 text-white">{isEditing ? 'Edit Kelas' : 'Tambah Kelas'}</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-300">Kode Kelas (Unik) *</label>
                <input
                  type="text"
                  required
                  value={formData.kode || ''}
                  onChange={(e) => setFormData({ ...formData, kode: e.target.value })}
                  placeholder="Contoh: X-IPA-1"
                  className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm text-white placeholder-gray-400 focus:ring-primary focus:border-primary"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-300">Nama Kelas *</label>
                <input
                  type="text"
                  required
                  value={formData.nama || ''}
                  onChange={(e) => setFormData({ ...formData, nama: e.target.value })}
                  placeholder="Contoh: Sepuluh IPA Satu"
                  className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm text-white placeholder-gray-400 focus:ring-primary focus:border-primary"
                />
              </div>
              <div className="flex justify-end space-x-3 pt-4">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 bg-gray-600 text-gray-200 rounded hover:bg-gray-500">Batal</button>
                <button type="submit" className="px-4 py-2 bg-primary text-white rounded hover:bg-secondary">Simpan</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect } from 'react';

interface ToastProps {
  message: string;
  type: 'success' | 'error';
  duration?: number;
  position?: 'top-right' | 'center';
  onClose: () => void;
}

export const Toast: React.FC<ToastProps> = ({ 
  message, 
  type, 
  duration = 3000, 
  position = 'top-right', 
  onClose 
}) => {
  useEffect(() => {
    const timer = setTimeout(() => {
      onClose();
    }, duration);
    return () => clearTimeout(timer);
  }, [onClose, duration]);

  const bgColor = type === 'success' ? 'bg-green-600' : 'bg-red-600';

  // Base classes
  const baseClasses = `fixed z-[100] ${bgColor} text-white rounded shadow-2xl flex items-start gap-3 transition-all duration-300`;

  // Position classes
  let positionClasses = '';
  let containerClasses = '';

  if (position === 'center') {
    // For center, we want a modal-like appearance but auto-dismissing
    containerClasses = "fixed inset-0 z-[100] flex items-center justify-center pointer-events-none"; // Container centers it
    positionClasses = "pointer-events-auto max-w-lg p-6 text-lg border-2 border-white/20 animate-bounce-in"; // Box style
  } else {
    // Default top-right
    positionClasses = "top-4 right-4 px-6 py-3 max-w-sm animate-slide-in";
  }

  const content = (
    <div className={`${baseClasses} ${positionClasses}`}>
      <span className="text-2xl">{type === 'success' ? '✅' : '⚠️'}</span>
      <div className="flex-1">
        <h4 className="font-bold mb-1">{type === 'success' ? 'Berhasil' : 'Peringatan'}</h4>
        <p className="font-medium whitespace-pre-wrap leading-relaxed">{message}</p>
      </div>
      <button onClick={onClose} className="opacity-75 hover:opacity-100 text-xl font-bold p-1">✕</button>
    </div>
  );

  if (position === 'center') {
    return (
      <div className={containerClasses}>
        {content}
      </div>
    );
  }

  return content;
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Login } from './components/Login';
// Admin Components
import { AdminDashboard } from './components/AdminDashboard';
import { CrudGuru } from './components/CrudGuru';
import { CrudSiswa } from './components/CrudSiswa';
import { CrudKelas } from './components/CrudKelas';
import { CrudMapel } from './components/CrudMapel';
import { CrudAnggotaGurwal } from './components/CrudAnggotaGurwal';
import { CrudDataPengajar } from './components/CrudDataPengajar';
// Guru Wali Components
import { GwDashboard } from './components/GwDashboard';
import { GwSiswa } from './components/GwSiswa';
import { GwKehadiran } from './components/GwKehadiran';
import { GwPelanggaran } from './components/GwPelanggaran';
import { GwPrestasi } from './components/GwPrestasi';
import { GwLaporan } from './components/GwLaporan';
// Guru Pengajar Components
import { PengajarDashboard } from './components/PengajarDashboard';
import { PengajarPenilaian } from './components/PengajarPenilaian';
import { PengajarRekapNilai } from './components/PengajarRekapNilai';

import { Toast } from './components/Toast';
import { Guru, ViewState } from './types';

interface ToastState {
  message: string;
  type: 'success' | 'error';
  duration?: number;
  position?: 'top-right' | 'center';
}

function App() {
  const [session, setSession] = useState<Guru | null>(null);
  const [currentView, setCurrentView] = useState<ViewState>('DASHBOARD');
  const [toast, setToast] = useState<ToastState | null>(null);

  useEffect(() => {
    // Check localStorage for persisted session
    const storedUser = localStorage.getItem('gurwal_admin_user');
    const storedView = localStorage.getItem('gurwal_current_view') as ViewState;

    if (storedUser) {
      try {
        const user = JSON.parse(storedUser);
        setSession(user);

        // Restore view if available, otherwise default based on role
        if (storedView) {
          setCurrentView(storedView);
        } else {
          if (user.peran === 'GURU_WALI') setCurrentView('GW_DASHBOARD');
          else if (user.peran === 'GURU_PENGAJAR') setCurrentView('PENGAJAR_DASHBOARD');
          else setCurrentView('DASHBOARD');
        }
      } catch (e) {
        localStorage.removeItem('gurwal_admin_user');
        localStorage.removeItem('gurwal_current_view');
      }
    }
  }, []);

  const handleLoginSuccess = (user: Guru) => {
    setSession(user);
    localStorage.setItem('gurwal_admin_user', JSON.stringify(user));

    let defaultView: ViewState = 'DASHBOARD';
    if (user.peran === 'GURU_WALI') defaultView = 'GW_DASHBOARD';
    else if (user.peran === 'GURU_PENGAJAR') defaultView = 'PENGAJAR_DASHBOARD';

    setCurrentView(defaultView);
    localStorage.setItem('gurwal_current_view', defaultView);
  };

  const handleLogout = () => {
    setSession(null);
    localStorage.removeItem('gurwal_admin_user');
    localStorage.removeItem('gurwal_current_view');
    showToast('Anda telah keluar', 'success');
  };

  const handleChangeView = (view: ViewState) => {
    setCurrentView(view);
    localStorage.setItem('gurwal_current_view', view);
  };

  const showToast = (
    message: string, 
    type: 'success' | 'error', 
    duration: number = 3000, 
    position: 'top-right' | 'center' = 'top-right'
  ) => {
    setToast({ message, type, duration, position });
  };

  // Render Logic
  if (!session) {
    return (
      <>
        <Login onLoginSuccess={handleLoginSuccess} showToast={showToast} />
        {toast && (
          <Toast
            message={toast.message}
            type={toast.type}
            duration={toast.duration}
            position={toast.position}
            onClose={() => setToast(null)}
          />
        )}
      </>
    );
  }

  const renderContent = () => {
    switch (currentView) {
      // ADMIN
      case 'GURU':
        return <CrudGuru showToast={showToast} />;
      case 'SISWA':
        return <CrudSiswa showToast={showToast} />;
      case 'KELAS':
        return <CrudKelas showToast={showToast} />;
      case 'MAPEL':
        return <CrudMapel showToast={showToast} />;
      case 'ANGGOTA_GURWAL':
        return <CrudAnggotaGurwal showToast={showToast} />;
      case 'DATA_PENGAJAR':
        return <CrudDataPengajar showToast={showToast} />;
      case 'DASHBOARD':
        return <AdminDashboard />;

      // GURU WALI
      case 'GW_DASHBOARD':
        return <GwDashboard currentUser={session} />;
      case 'GW_SISWA':
        return <GwSiswa currentUser={session} showToast={showToast} />;
      case 'GW_KEHADIRAN':
        return <GwKehadiran currentUser={session} showToast={showToast} />;
      case 'GW_PELANGGARAN':
        return <GwPelanggaran currentUser={session} showToast={showToast} />;
      case 'GW_PRESTASI':
        return <GwPrestasi currentUser={session} showToast={showToast} />;
      case 'GW_LAPORAN':
        return <GwLaporan currentUser={session} />;

      // GURU PENGAJAR
      case 'PENGAJAR_DASHBOARD':
        return <PengajarDashboard currentUser={session} />;
      case 'PENGAJAR_PENILAIAN':
        return <PengajarPenilaian currentUser={session} showToast={showToast} />;
      case 'PENGAJAR_REKAP':
        return <PengajarRekapNilai currentUser={session} />;

      default:
        return <div className="p-6 text-white">Halaman tidak ditemukan</div>;
    }
  };

  return (
    <Layout
      currentUser={session}
      currentView={currentView}
      onChangeView={handleChangeView}
      onLogout={handleLogout}
    >
      {renderContent()}
      {toast && (
        <Toast
          message={toast.message}
          type={toast.type}
          duration={toast.duration}
          position={toast.position}
          onClose={() => setToast(null)}
        />
      )}
    </Layout>
  );
}

export default App;

import React, { useEffect, useState, useRef } from 'react';
import { supabase } from '../supabaseClient';
import { Siswa, Kelas } from '../types';
import Papa from 'papaparse';
import { ConfirmDialog } from './ConfirmDialog';

interface CrudSiswaProps {
  showToast: (msg: string, type: 'success' | 'error', duration?: number, position?: 'top-right' | 'center') => void;
}

export const CrudSiswa: React.FC<CrudSiswaProps> = ({ showToast }) => {
  const [data, setData] = useState<Siswa[]>([]);
  const [kelasOptions, setKelasOptions] = useState<Kelas[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Siswa>>({});
  const [isEditing, setIsEditing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Import State
  const [isImporting, setIsImporting] = useState(false);
  const [importProgress, setImportProgress] = useState(0);
  const [showPreview, setShowPreview] = useState(false);
  const [previewData, setPreviewData] = useState<any[]>([]);

  // Filters
  const [searchTerm, setSearchTerm] = useState('');
  const [filterKelas, setFilterKelas] = useState('');

  // Delete State
  const [deleteId, setDeleteId] = useState<string | null>(null);

  const fetchData = async () => {
    try {
      // Fetch Siswa with Kelas info (Join)
      const { data: siswaData, error: siswaError } = await supabase
        .from('siswa')
        .select('*, kelas(nama)')
        .order('nama', { ascending: true });

      if (siswaError) throw siswaError;
      // @ts-ignore - Supabase type inference for join is tricky here without generated types
      setData(siswaData || []);

      // Fetch Kelas options
      const { data: kelasData, error: kelasError } = await supabase
        .from('kelas')
        .select('*')
        .order('nama', { ascending: true });

      if (kelasError) throw kelasError;
      setKelasOptions(kelasData || []);

    } catch (error) {
      // console.error(error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();

    const channel = supabase
      .channel('siswa_changes')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'siswa' }, () => {
        fetchData();
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
     // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleDeleteClick = (id: string) => {
    setDeleteId(id);
  };

  const confirmDelete = async () => {
    if (!deleteId) return;
    try {
      const { error } = await supabase.from('siswa').delete().eq('id', deleteId);
      if (error) throw error;
      showToast('Siswa berhasil dihapus', 'success');
      fetchData();
    } catch (error) {
      showToast('Gagal menghapus siswa', 'error');
    } finally {
      setDeleteId(null);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const payload = {
        nisn: formData.nisn,
        nama: formData.nama,
        jenis_kelamin: formData.jenis_kelamin,
        tanggal_lahir: formData.tanggal_lahir,
        no_hp: formData.no_hp,
        id_kelas: formData.id_kelas === '' ? null : formData.id_kelas
    };

    try {
      if (isEditing && formData.id) {
        const { error } = await supabase.from('siswa').update(payload).eq('id', formData.id);
        if (error) throw error;
        showToast('Siswa diperbarui', 'success');
      } else {
        const { error } = await supabase.from('siswa').insert([payload]);
        if (error) throw error;
        showToast('Siswa ditambahkan', 'success');
      }
      setIsModalOpen(false);
      setFormData({});
      fetchData();
    } catch (error: any) {
        const msg = error.code === '23505' ? 'NISN sudah digunakan' : 'Gagal menyimpan data';
        showToast(msg, 'error');
    }
  };

  const openModal = (siswa?: Siswa) => {
    if (siswa) {
      setIsEditing(true);
      setFormData(siswa);
    } else {
      setIsEditing(false);
      setFormData({ jenis_kelamin: 'L', id_kelas: '' });
    }
    setIsModalOpen(true);
  };

  const handleExport = () => {
    if (data.length === 0) {
      showToast('Tidak ada data untuk diekspor', 'error');
      return;
    }

    // Format data for CSV
    const exportData = data.map(siswa => ({
      'NISN': `'${siswa.nisn}`, // Add quote to force text format in Excel for long numbers
      'Nama Lengkap': siswa.nama,
      'Kelas': siswa.kelas?.nama || '-',
      'Jenis Kelamin': siswa.jenis_kelamin,
      'Tanggal Lahir': siswa.tanggal_lahir || '-',
      'No HP': siswa.no_hp ? `'${siswa.no_hp}` : '-'
    }));

    const csv = Papa.unparse(exportData);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');

    const timestamp = new Date().toISOString().split('T')[0];
    link.href = url;
    link.setAttribute('download', `data_siswa_gurwal_${timestamp}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleDownloadTemplate = () => {
    const templateData = [
      {
        nisn: '1234567890',
        nama: 'Ahmad Santoso',
        jenis_kelamin: 'L',
        tanggal_lahir: '2008-05-20',
        no_hp: '08123456789',
        nama_kelas: 'X-IPA-1'
      },
      {
        nisn: '0987654321',
        nama: 'Siti Aminah',
        jenis_kelamin: 'P',
        tanggal_lahir: '2008-11-15',
        no_hp: '08987654321',
        nama_kelas: 'X-IPA-2'
      }
    ];

    const csv = Papa.unparse(templateData);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');

    link.href = url;
    link.setAttribute('download', 'template_import_siswa.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Step 1: Read CSV and Show Preview
  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    // Build map for class lookup
    const classMap = new Map();
    kelasOptions.forEach(k => {
        classMap.set(k.nama.toLowerCase().trim(), k.id);
        classMap.set(k.kode.toLowerCase().trim(), k.id);
    });

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        const errorMessages: string[] = [];

        const parsedData = results.data.map((row: any, index: number) => {
             const rowNum = index + 2; // Assuming header is row 1

             // 1. Sanitize Class
             const rawClass = row.nama_kelas || row.kelas || '';
             const classKey = String(rawClass).toLowerCase().trim();
             const foundClassId = classMap.get(classKey) || null;

             // 2. Sanitize Mandatory Fields
             const nisn = row.nisn ? String(row.nisn).replace(/['"]/g, '').trim() : '';
             const nama = row.nama ? String(row.nama).trim() : '';

             // Validation checks
             if (!nisn) errorMessages.push(`Baris ${rowNum}: NISN kosong.`);
             if (!nama) errorMessages.push(`Baris ${rowNum}: Nama kosong.`);
             if (rawClass && !foundClassId) {
                // Warning only? Or error? Let's treat as warning but let them see in preview
                // errorMessages.push(`Baris ${rowNum}: Kelas '${rawClass}' tidak ditemukan di database.`);
             }

             // 3. Sanitize Optional Fields
             const rawJk = row.jenis_kelamin ? String(row.jenis_kelamin).trim().toUpperCase() : 'L';
             const jenis_kelamin = rawJk === 'P' ? 'P' : 'L';

             let tanggal_lahir = null;
             if (row.tanggal_lahir && row.tanggal_lahir.trim() !== '') {
                 const dateStr = row.tanggal_lahir.trim();
                 if (/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
                     tanggal_lahir = dateStr;
                 }
             }

             const rawHp = row.no_hp ? String(row.no_hp).replace(/['"]/g, '').trim() : '';
             const no_hp = rawHp !== '' ? rawHp : null;

             return {
                nisn,
                nama,
                jenis_kelamin,
                tanggal_lahir,
                no_hp,
                id_kelas: foundClassId,
                _rawClass: rawClass // Keep purely for display in preview
             };
        }).filter((row: any) => row.nisn !== '' && row.nama !== '');

        if (errorMessages.length > 0) {
            // Show detailed error toast in center for 10 seconds
            const maxErrors = 5;
            const displayErrors = errorMessages.slice(0, maxErrors).join('\n');
            const suffix = errorMessages.length > maxErrors ? `\n...dan ${errorMessages.length - maxErrors} kesalahan lainnya.` : '';

            showToast(
                `Gagal Membaca CSV. Perbaiki data berikut:\n${displayErrors}${suffix}`, 
                'error', 
                10000, 
                'center'
            );

            if (fileInputRef.current) fileInputRef.current.value = '';
            return;
        }

        if (parsedData.length === 0) {
            showToast('File CSV kosong atau format salah', 'error');
        } else {
            setPreviewData(parsedData);
            setShowPreview(true);
        }

        if (fileInputRef.current) fileInputRef.current.value = '';
      },
      error: (error) => {
        showToast('Gagal membaca file CSV: ' + error.message, 'error', 5000, 'center');
      }
    });
  };

  // Step 2: Save Data to DB
  const handleSaveImport = async () => {
    setIsImporting(true);
    setImportProgress(0);
    setShowPreview(false);

    try {
        const total = previewData.length;
        const BATCH_SIZE = 50;

        for (let i = 0; i < total; i += BATCH_SIZE) {
            // Extract ONLY columns that exist in DB
            const batch = previewData.slice(i, i + BATCH_SIZE).map(item => ({
                nisn: item.nisn,
                nama: item.nama,
                jenis_kelamin: item.jenis_kelamin,
                tanggal_lahir: item.tanggal_lahir,
                no_hp: item.no_hp,
                id_kelas: item.id_kelas
            }));

            const { error } = await supabase.from('siswa').upsert(batch, { onConflict: 'nisn' });

            if (error) {
                console.error("Batch Import Error:", error);
                throw error;
            }

            const currentProgress = Math.min(Math.round(((i + batch.length) / total) * 100), 100);
            setImportProgress(currentProgress);
        }

        showToast(`Sukses mengimport ${total} siswa`, 'success');
        setPreviewData([]);
        fetchData();
    } catch (error: any) {
        showToast('Gagal menyimpan data ke database: ' + (error.message || 'Unknown error'), 'error', 10000, 'center');
    } finally {
        setIsImporting(false);
        setImportProgress(0);
    }
  };

  // Filter Logic
  const filteredData = data.filter(siswa => {
    const matchesSearch = 
      siswa.nama.toLowerCase().includes(searchTerm.toLowerCase()) || 
      siswa.nisn.includes(searchTerm);

    const matchesKelas = filterKelas === '' || siswa.id_kelas === filterKelas;

    return matchesSearch && matchesKelas;
  });

  return (
    <div>
      <ConfirmDialog
        isOpen={!!deleteId}
        message="Yakin ingin menghapus siswa ini?"
        onConfirm={confirmDelete}
        onCancel={() => setDeleteId(null)}
      />

      <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
        <h2 className="text-2xl font-bold text-white">Manajemen Siswa</h2>
        <div className="flex flex-wrap gap-2">
            <button
              onClick={handleExport}
              className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 transition flex items-center gap-2"
            >
              📤 Ekspor Data
            </button>
            <button
              onClick={handleDownloadTemplate}
              className="bg-gray-600 text-white px-4 py-2 rounded hover:bg-gray-500 transition flex items-center gap-2"
            >
              📥 Template
            </button>
            <input 
              type="file" 
              accept=".csv" 
              ref={fileInputRef} 
              onChange={handleFileUpload} 
              className="hidden" 
            />
            <button
              onClick={() => fileInputRef.current?.click()}
              className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700 transition"
            >
              📂 Import CSV
            </button>
            <button
              onClick={() => openModal()}
              className="bg-primary text-white px-4 py-2 rounded hover:bg-secondary transition"
            >
              + Tambah Siswa
            </button>
        </div>
      </div>

      {/* Import Progress Overlay */}
      {isImporting && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black bg-opacity-80">
          <div className="bg-gray-800 p-6 rounded-lg border border-gray-700 w-80 md:w-96 text-center">
            <h3 className="text-white font-bold mb-4 text-lg">Menyimpan ke Database...</h3>
            <div className="w-full bg-gray-700 rounded-full h-4 mb-2 overflow-hidden">
               <div 
                 className="bg-green-500 h-4 rounded-full transition-all duration-300" 
                 style={{ width: `${importProgress}%` }}
               ></div>
            </div>
            <p className="text-gray-300 font-medium">{importProgress}%</p>
            <p className="text-gray-500 text-sm mt-1">Mohon tunggu sebentar...</p>
          </div>
        </div>
      )}

      {/* Preview Modal */}
      {showPreview && (
        <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50 p-4">
            <div className="bg-gray-800 rounded-lg shadow-lg w-full max-w-4xl p-6 border border-gray-700 max-h-[90vh] flex flex-col">
                <h3 className="text-xl font-bold mb-4 text-white">Preview Data Import ({previewData.length} Siswa)</h3>
                <div className="flex-1 overflow-auto border border-gray-700 rounded mb-4">
                    <table className="min-w-full divide-y divide-gray-700">
                        <thead className="bg-gray-700 sticky top-0">
                            <tr>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">NISN</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">Nama</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">Kelas (CSV)</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">Status Kelas</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">L/P</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">Tgl Lahir</th>
                            </tr>
                        </thead>
                        <tbody className="bg-gray-800 divide-y divide-gray-700">
                            {previewData.slice(0, 100).map((row, idx) => (
                                <tr key={idx} className="hover:bg-gray-700">
                                    <td className="px-4 py-2 text-sm text-gray-300">{row.nisn}</td>
                                    <td className="px-4 py-2 text-sm text-white">{row.nama}</td>
                                    <td className="px-4 py-2 text-sm text-gray-400">{row._rawClass || '-'}</td>
                                    <td className="px-4 py-2 text-sm">
                                        {row.id_kelas ? (
                                            <span className="text-green-400">✅ Ditemukan</span>
                                        ) : (
                                            <span className="text-red-400">❌ Tidak Ditemukan</span>
                                        )}
                                    </td>
                                    <td className="px-4 py-2 text-sm text-gray-300">{row.jenis_kelamin}</td>
                                    <td className="px-4 py-2 text-sm text-gray-300">{row.tanggal_lahir || '-'}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                    {previewData.length > 100 && (
                        <div className="p-2 text-center text-gray-500 text-sm bg-gray-700">
                            ... dan {previewData.length - 100} baris lainnya.
                        </div>
                    )}
                </div>
                <div className="flex justify-end space-x-3">
                    <button 
                        onClick={() => { setShowPreview(false); setPreviewData([]); }}
                        className="px-4 py-2 bg-gray-600 text-white rounded hover:bg-gray-500"
                    >
                        Batal
                    </button>
                    <button 
                        onClick={handleSaveImport}
                        className="px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700 font-bold"
                    >
                        📥 Simpan ke Database
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Filter Bar */}
      <div className="flex flex-col md:flex-row gap-4 mb-6 bg-gray-800 p-4 rounded-lg border border-gray-700">
        <div className="flex-1">
          <input
            type="text"
            placeholder="Cari Nama / NISN..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white placeholder-gray-400 focus:outline-none focus:border-primary"
          />
        </div>
        <div className="w-full md:w-64">
           <select
             value={filterKelas}
             onChange={(e) => setFilterKelas(e.target.value)}
             className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white focus:outline-none focus:border-primary"
           >
             <option value="">Semua Kelas</option>
             {kelasOptions.map(k => (
                 <option key={k.id} value={k.id}>{k.nama}</option>
             ))}
           </select>
        </div>
      </div>

      {loading ? (
        <p className="text-gray-400">Memuat data...</p>
      ) : (
        <div className="bg-gray-800 shadow overflow-x-auto rounded-lg border border-gray-700">
          <table className="min-w-full divide-y divide-gray-700">
            <thead className="bg-gray-700">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">Nama / NISN</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">Kelas</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">L/P</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">Kontak</th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-300 uppercase tracking-wider">Aksi</th>
              </tr>
            </thead>
            <tbody className="bg-gray-800 divide-y divide-gray-700">
              {filteredData.map((siswa) => (
                <tr key={siswa.id}>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="text-sm font-medium text-white">{siswa.nama}</div>
                    <div className="text-sm text-gray-400">{siswa.nisn}</div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">
                      {siswa.kelas?.nama || '-'}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">{siswa.jenis_kelamin}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">
                      {siswa.no_hp || '-'}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                    <button onClick={() => openModal(siswa)} className="text-indigo-400 hover:text-indigo-300 mr-4">Edit</button>
                    <button onClick={() => handleDeleteClick(siswa.id)} className="text-red-400 hover:text-red-300">Hapus</button>
                  </td>
                </tr>
              ))}
              {filteredData.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-6 py-4 text-center text-gray-500">
                    Tidak ada data siswa yang cocok.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      )}

      {/* Modal Form */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50 p-4">
          <div className="bg-gray-800 rounded-lg shadow-lg w-full max-w-lg p-6 max-h-[90vh] overflow-y-auto border border-gray-700">
            <h3 className="text-lg font-bold mb-4 text-white">{isEditing ? 'Edit Siswa' : 'Tambah Siswa'}</h3>
            <form onSubmit={handleSubmit} className="space-y-4">

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-300">NISN *</label>
                  <input
                    type="text"
                    required
                    value={formData.nisn || ''}
                    onChange={(e) => setFormData({ ...formData, nisn: e.target.value })}
                    className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm focus:ring-primary focus:border-primary text-white"
                  />
                </div>
                <div>
                    <label className="block text-sm font-medium text-gray-300">Kelas</label>
                    <select
                        value={formData.id_kelas || ''}
                        onChange={(e) => setFormData({ ...formData, id_kelas: e.target.value })}
                        className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 text-white"
                    >
                        <option value="">-- Pilih Kelas --</option>
                        {kelasOptions.map(k => (
                            <option key={k.id} value={k.id}>{k.nama}</option>
                        ))}
                    </select>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-300">Nama Lengkap *</label>
                <input
                  type="text"
                  required
                  value={formData.nama || ''}
                  onChange={(e) => setFormData({ ...formData, nama: e.target.value })}
                  className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm focus:ring-primary focus:border-primary text-white"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-300">Jenis Kelamin</label>
                  <select
                    value={formData.jenis_kelamin || 'L'}
                    onChange={(e) => setFormData({ ...formData, jenis_kelamin: e.target.value as 'L' | 'P' })}
                    className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm text-white"
                  >
                    <option value="L">Laki-laki</option>
                    <option value="P">Perempuan</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-300">Tanggal Lahir</label>
                  <input
                    type="date"
                    value={formData.tanggal_lahir || ''}
                    onChange={(e) => setFormData({ ...formData, tanggal_lahir: e.target.value })}
                    className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm text-white"
                  />
                </div>
              </div>

               <div>
                  <label className="block text-sm font-medium text-gray-300">No HP</label>
                  <input
                    type="text"
                    value={formData.no_hp || ''}
                    onChange={(e) => setFormData({ ...formData, no_hp: e.target.value })}
                    className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm text-white"
                  />
                </div>

              <div className="flex justify-end space-x-3 pt-4">
                <button
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="px-4 py-2 bg-gray-600 text-gray-200 rounded hover:bg-gray-500"
                >
                  Batal
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-primary text-white rounded hover:bg-secondary"
                >
                  Simpan
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useRef } from 'react';
import { supabase } from '../supabaseClient';
import { Guru } from '../types';
import Papa from 'papaparse';
import { ConfirmDialog } from './ConfirmDialog';

interface CrudGuruProps {
  showToast: (msg: string, type: 'success' | 'error', duration?: number, position?: 'top-right' | 'center') => void;
}

export const CrudGuru: React.FC<CrudGuruProps> = ({ showToast }) => {
  const [data, setData] = useState<Guru[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Guru>>({});
  const [isEditing, setIsEditing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Import State
  const [isImporting, setIsImporting] = useState(false);
  const [importProgress, setImportProgress] = useState(0);
  const [showPreview, setShowPreview] = useState(false);
  const [previewData, setPreviewData] = useState<any[]>([]);

  // Filter States
  const [searchTerm, setSearchTerm] = useState('');
  const [filterPeran, setFilterPeran] = useState('');

  // Delete Confirmation State
  const [deleteId, setDeleteId] = useState<string | null>(null);

  const fetchData = async () => {
    try {
      const { data: guruData, error } = await supabase
        .from('guru')
        .select('*')
        .order('nama', { ascending: true });

      if (error) throw error;
      setData(guruData || []);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();

    // Realtime subscription
    const channel = supabase
      .channel('guru_changes')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'guru' }, () => {
        fetchData();
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
     // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleDeleteClick = (id: string) => {
    setDeleteId(id);
  };

  const confirmDelete = async () => {
    if (!deleteId) return;
    try {
      const { error } = await supabase.from('guru').delete().eq('id', deleteId);
      if (error) throw error;
      showToast('Data guru berhasil dihapus', 'success');
      fetchData(); // Instant update
    } catch (error) {
      showToast('Gagal menghapus data', 'error');
    } finally {
      setDeleteId(null);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (isEditing && formData.id) {
        // Update
        const { error } = await supabase
          .from('guru')
          .update({
            nip: formData.nip,
            nama: formData.nama,
            jenis_kelamin: formData.jenis_kelamin,
            no_hp: formData.no_hp,
            username: formData.username,
            password: formData.password, 
            peran: formData.peran
          })
          .eq('id', formData.id);
        if (error) throw error;
        showToast('Guru berhasil diperbarui', 'success');
      } else {
        // Create
        const { error } = await supabase
          .from('guru')
          .insert([{
            nip: formData.nip,
            nama: formData.nama,
            jenis_kelamin: formData.jenis_kelamin,
            no_hp: formData.no_hp,
            username: formData.username,
            password: formData.password,
            peran: formData.peran || 'GURU_WALI'
          }]);
        if (error) throw error;
        showToast('Guru berhasil ditambahkan', 'success');
      }
      setIsModalOpen(false);
      setFormData({});
      fetchData(); // Instant update
    } catch (error: any) {
        const msg = error.code === '23505' ? 'Username sudah digunakan' : 'Gagal menyimpan data';
        showToast(msg, 'error');
    }
  };

  const openModal = (guru?: Guru) => {
    if (guru) {
      setIsEditing(true);
      setFormData(guru);
    } else {
      setIsEditing(false);
      setFormData({ peran: 'GURU_WALI', jenis_kelamin: 'L' });
    }
    setIsModalOpen(true);
  };

  const handleDownloadTemplate = () => {
    const templateData = [
      {
        nip: '198001012005011001',
        nama: 'Contoh Guru Wali',
        jenis_kelamin: 'L',
        no_hp: '081234567890',
        username: 'guruwali01',
        password: 'password123',
        peran: 'GURU_WALI'
      },
      {
        nip: '198502022010012002',
        nama: 'Contoh Guru Pengajar',
        jenis_kelamin: 'P',
        no_hp: '089876543210',
        username: 'pengajar01',
        password: 'password123',
        peran: 'GURU_PENGAJAR'
      }
    ];

    const csv = Papa.unparse(templateData);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');

    link.href = url;
    link.setAttribute('download', 'template_import_guru.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Step 1: Parse and Validate
  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: async (results) => {
        const errorMessages: string[] = [];

        const parsedData = results.data.map((row: any, index: number) => {
            const rowNum = index + 2;

            // Sanitize
            const nama = row.nama ? String(row.nama).trim() : '';
            const username = row.username ? String(row.username).trim() : '';
            const nip = row.nip ? String(row.nip).replace(/['"]/g, '').trim() : null;
            const no_hp = row.no_hp ? String(row.no_hp).replace(/['"]/g, '').trim() : null;
            const jenis_kelamin = row.jenis_kelamin ? String(row.jenis_kelamin).trim().toUpperCase() : 'L';
            const peran = row.peran ? String(row.peran).trim() : 'GURU_WALI';
            const password = row.password ? String(row.password).trim() : '123456';

            // Validation
            if (!nama) errorMessages.push(`Baris ${rowNum}: Nama kosong.`);
            if (!username) errorMessages.push(`Baris ${rowNum}: Username kosong (Wajib untuk login).`);

            return {
              nip: nip === '' ? null : nip,
              nama,
              jenis_kelamin: jenis_kelamin === 'P' ? 'P' : 'L',
              no_hp: no_hp === '' ? null : no_hp,
              username,
              password, 
              peran
            };
        }).filter((row: any) => row.nama !== '');

        if (errorMessages.length > 0) {
            // Show detailed error toast in center
            const maxErrors = 5;
            const displayErrors = errorMessages.slice(0, maxErrors).join('\n');
            const suffix = errorMessages.length > maxErrors ? `\n...dan ${errorMessages.length - maxErrors} kesalahan lainnya.` : '';

            showToast(
                `Gagal Membaca CSV. Perbaiki data berikut:\n${displayErrors}${suffix}`, 
                'error', 
                10000, 
                'center'
            );

            if (fileInputRef.current) fileInputRef.current.value = '';
            return;
        }

        if (parsedData.length === 0) {
            showToast('File CSV kosong atau format salah', 'error');
        } else {
            setPreviewData(parsedData);
            setShowPreview(true);
        }

        if (fileInputRef.current) fileInputRef.current.value = '';
      },
      error: (error) => {
        showToast('Gagal membaca file CSV: ' + error.message, 'error');
      }
    });
  };

  // Step 2: Save to DB
  const handleSaveImport = async () => {
    setIsImporting(true);
    setImportProgress(0);
    setShowPreview(false);

    try {
        const total = previewData.length;
        const BATCH_SIZE = 50;

        for (let i = 0; i < total; i += BATCH_SIZE) {
             const batch = previewData.slice(i, i + BATCH_SIZE);
             const { error } = await supabase.from('guru').upsert(batch, { onConflict: 'username' });

             if (error) throw error;

             // Update Progress
             const currentProgress = Math.min(Math.round(((i + batch.length) / total) * 100), 100);
             setImportProgress(currentProgress);
        }

        showToast(`Berhasil mengimport ${total} data guru`, 'success');
        setPreviewData([]);
        fetchData();
    } catch (error: any) {
        showToast('Gagal menyimpan data ke database: ' + (error.message || 'Unknown'), 'error', 10000, 'center');
    } finally {
        setIsImporting(false);
        setImportProgress(0);
    }
  };

  // Filter Logic
  const filteredData = data.filter(guru => {
    const matchesSearch = 
      guru.nama.toLowerCase().includes(searchTerm.toLowerCase()) || 
      (guru.nip && guru.nip.includes(searchTerm)) ||
      guru.username.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesRole = filterPeran === '' || guru.peran === filterPeran;

    return matchesSearch && matchesRole;
  });

  return (
    <div>
      <ConfirmDialog 
        isOpen={!!deleteId}
        message="Yakin ingin menghapus data guru ini?"
        onConfirm={confirmDelete}
        onCancel={() => setDeleteId(null)}
      />

      <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
        <h2 className="text-2xl font-bold text-white">Manajemen Guru</h2>
        <div className="flex flex-wrap gap-2">
            <button
              onClick={handleDownloadTemplate}
              className="bg-gray-600 text-white px-4 py-2 rounded hover:bg-gray-500 transition flex items-center gap-2"
            >
              📥 Template
            </button>
            <input 
              type="file" 
              accept=".csv" 
              ref={fileInputRef} 
              onChange={handleFileUpload} 
              className="hidden" 
            />
            <button
              onClick={() => fileInputRef.current?.click()}
              className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700 transition"
            >
              📂 Import CSV
            </button>
            <button
              onClick={() => openModal()}
              className="bg-primary text-white px-4 py-2 rounded hover:bg-secondary transition"
            >
              + Tambah Guru
            </button>
        </div>
      </div>

      {/* Import Progress Overlay */}
      {isImporting && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black bg-opacity-80">
          <div className="bg-gray-800 p-6 rounded-lg border border-gray-700 w-80 md:w-96 text-center">
            <h3 className="text-white font-bold mb-4 text-lg">Mengimport Data...</h3>
            <div className="w-full bg-gray-700 rounded-full h-4 mb-2 overflow-hidden">
               <div 
                 className="bg-green-500 h-4 rounded-full transition-all duration-300" 
                 style={{ width: `${importProgress}%` }}
               ></div>
            </div>
            <p className="text-gray-300 font-medium">{importProgress}%</p>
            <p className="text-gray-500 text-sm mt-1">Mohon jangan tutup halaman ini.</p>
          </div>
        </div>
      )}

      {/* Preview Modal */}
      {showPreview && (
        <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50 p-4">
            <div className="bg-gray-800 rounded-lg shadow-lg w-full max-w-5xl p-6 border border-gray-700 max-h-[90vh] flex flex-col">
                <h3 className="text-xl font-bold mb-4 text-white">Preview Data Import ({previewData.length} Guru)</h3>
                <div className="flex-1 overflow-auto border border-gray-700 rounded mb-4">
                    <table className="min-w-full divide-y divide-gray-700">
                        <thead className="bg-gray-700 sticky top-0">
                            <tr>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">NIP</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">Nama Lengkap</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">Username</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">Password</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">Peran</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">L/P</th>
                            </tr>
                        </thead>
                        <tbody className="bg-gray-800 divide-y divide-gray-700">
                            {previewData.slice(0, 100).map((row, idx) => (
                                <tr key={idx} className="hover:bg-gray-700">
                                    <td className="px-4 py-2 text-sm text-gray-300">{row.nip || '-'}</td>
                                    <td className="px-4 py-2 text-sm text-white font-medium">{row.nama}</td>
                                    <td className="px-4 py-2 text-sm text-blue-300">{row.username}</td>
                                    <td className="px-4 py-2 text-sm text-gray-400">{row.password}</td>
                                    <td className="px-4 py-2 text-sm text-gray-300">{row.peran}</td>
                                    <td className="px-4 py-2 text-sm text-gray-300">{row.jenis_kelamin}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                    {previewData.length > 100 && (
                        <div className="p-2 text-center text-gray-500 text-sm bg-gray-700">
                            ... dan {previewData.length - 100} baris lainnya.
                        </div>
                    )}
                </div>
                <div className="flex justify-end space-x-3">
                    <button 
                        onClick={() => { setShowPreview(false); setPreviewData([]); }}
                        className="px-4 py-2 bg-gray-600 text-white rounded hover:bg-gray-500"
                    >
                        Batal
                    </button>
                    <button 
                        onClick={handleSaveImport}
                        className="px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700 font-bold"
                    >
                        📥 Simpan ke Database
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Filter Bar */}
      <div className="flex flex-col md:flex-row gap-4 mb-6 bg-gray-800 p-4 rounded-lg border border-gray-700">
        <div className="flex-1">
          <input
            type="text"
            placeholder="Cari Nama / NIP / Username..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white placeholder-gray-400 focus:outline-none focus:border-primary"
          />
        </div>
        <div className="w-full md:w-64">
           <select
             value={filterPeran}
             onChange={(e) => setFilterPeran(e.target.value)}
             className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white focus:outline-none focus:border-primary"
           >
             <option value="">Semua Peran</option>
             <option value="ADMIN">Admin</option>
             <option value="GURU_WALI">Guru Wali</option>
             <option value="GURU_PENGAJAR">Guru Pengajar</option>
           </select>
        </div>
      </div>

      {loading ? (
        <p className="text-gray-400">Memuat data...</p>
      ) : (
        <div className="bg-gray-800 shadow overflow-x-auto rounded-lg border border-gray-700">
          <table className="min-w-full divide-y divide-gray-700">
            <thead className="bg-gray-700">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">Nama / NIP</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">L/P</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">No HP</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">Akun</th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-300 uppercase tracking-wider">Aksi</th>
              </tr>
            </thead>
            <tbody className="bg-gray-800 divide-y divide-gray-700">
              {filteredData.map((guru) => (
                <tr key={guru.id}>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="text-sm font-medium text-white">{guru.nama}</div>
                    <div className="text-sm text-gray-400">{guru.nip || '-'}</div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">{guru.jenis_kelamin}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">{guru.no_hp}</td>
                  <td className="px-6 py-4 whitespace-nowrap">
                     <div className="text-sm text-white">{guru.username}</div>
                     <span className={`text-xs inline-flex px-2 py-1 rounded-full ${guru.peran === 'ADMIN' ? 'bg-purple-900 text-purple-200' : 'bg-green-900 text-green-200'}`}>
                        {guru.peran}
                     </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                    <button onClick={() => openModal(guru)} className="text-indigo-400 hover:text-indigo-300 mr-4">Edit</button>
                    <button onClick={() => handleDeleteClick(guru.id)} className="text-red-400 hover:text-red-300">Hapus</button>
                  </td>
                </tr>
              ))}
              {filteredData.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-6 py-4 text-center text-gray-500">
                    Tidak ada data guru yang cocok.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      )}

      {/* Modal Form */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50 p-4">
          <div className="bg-gray-800 rounded-lg shadow-lg w-full max-w-lg p-6 max-h-[90vh] overflow-y-auto border border-gray-700">
            <h3 className="text-lg font-bold mb-4 text-white">{isEditing ? 'Edit Guru' : 'Tambah Guru'}</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-300">NIP</label>
                  <input
                    type="text"
                    value={formData.nip || ''}
                    onChange={(e) => setFormData({ ...formData, nip: e.target.value })}
                    className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm focus:ring-primary focus:border-primary text-white"
                  />
                </div>
                <div>
                   <label className="block text-sm font-medium text-gray-300">Peran</label>
                   <select
                      value={formData.peran || 'GURU_WALI'}
                      onChange={(e) => setFormData({ ...formData, peran: e.target.value })}
                      className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 text-white"
                   >
                     <option value="GURU_WALI">Guru Wali</option>
                     <option value="ADMIN">Admin</option>
                     <option value="GURU_PENGAJAR">Guru Pengajar</option>
                   </select>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-300">Nama Lengkap *</label>
                <input
                  type="text"
                  required
                  value={formData.nama || ''}
                  onChange={(e) => setFormData({ ...formData, nama: e.target.value })}
                  className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm focus:ring-primary focus:border-primary text-white"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-300">Jenis Kelamin</label>
                  <select
                    value={formData.jenis_kelamin || 'L'}
                    onChange={(e) => setFormData({ ...formData, jenis_kelamin: e.target.value as 'L' | 'P' })}
                    className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm text-white"
                  >
                    <option value="L">Laki-laki</option>
                    <option value="P">Perempuan</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-300">No HP</label>
                  <input
                    type="text"
                    value={formData.no_hp || ''}
                    onChange={(e) => setFormData({ ...formData, no_hp: e.target.value })}
                    className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm text-white"
                  />
                </div>
              </div>

              <div className="border-t border-gray-700 pt-4 mt-4">
                <p className="text-xs text-gray-400 mb-2">Informasi Login</p>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-300">Username *</label>
                    <input
                      type="text"
                      required
                      value={formData.username || ''}
                      onChange={(e) => setFormData({ ...formData, username: e.target.value })}
                      className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm text-white"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-300">Password *</label>
                    <input
                      type="text"
                      required={!isEditing}
                      value={formData.password || ''}
                      onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                      placeholder={isEditing ? 'Isi untuk ubah password' : ''}
                      className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm text-white placeholder-gray-400"
                    />
                  </div>
                </div>
              </div>

              <div className="flex justify-end space-x-3 pt-4">
                <button
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="px-4 py-2 bg-gray-600 text-gray-200 rounded hover:bg-gray-500"
                >
                  Batal
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-primary text-white rounded hover:bg-secondary"
                >
                  Simpan
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useRef } from 'react';
import { supabase } from '../supabaseClient';
import { Guru } from '../types';
import Papa from 'papaparse';
import { ConfirmDialog } from './ConfirmDialog';

interface CrudGuruProps {
  showToast: (msg: string, type: 'success' | 'error', duration?: number, position?: 'top-right' | 'center') => void;
}

export const CrudGuru: React.FC<CrudGuruProps> = ({ showToast }) => {
  const [data, setData] = useState<Guru[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Guru>>({});
  const [isEditing, setIsEditing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Import State
  const [isImporting, setIsImporting] = useState(false);
  const [importProgress, setImportProgress] = useState(0);
  const [showPreview, setShowPreview] = useState(false);
  const [previewData, setPreviewData] = useState<any[]>([]);

  // Filter States
  const [searchTerm, setSearchTerm] = useState('');
  const [filterPeran, setFilterPeran] = useState('');

  // Delete Confirmation State
  const [deleteId, setDeleteId] = useState<string | null>(null);

  const fetchData = async () => {
    try {
      const { data: guruData, error } = await supabase
        .from('guru')
        .select('*')
        .order('nama', { ascending: true });

      if (error) throw error;
      setData(guruData || []);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();

    // Realtime subscription
    const channel = supabase
      .channel('guru_changes')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'guru' }, () => {
        fetchData();
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
     // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleDeleteClick = (id: string) => {
    setDeleteId(id);
  };

  const confirmDelete = async () => {
    if (!deleteId) return;
    try {
      const { error } = await supabase.from('guru').delete().eq('id', deleteId);
      if (error) throw error;
      showToast('Data guru berhasil dihapus', 'success');
      fetchData(); // Instant update
    } catch (error) {
      showToast('Gagal menghapus data', 'error');
    } finally {
      setDeleteId(null);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (isEditing && formData.id) {
        // Update
        const { error } = await supabase
          .from('guru')
          .update({
            nip: formData.nip,
            nama: formData.nama,
            jenis_kelamin: formData.jenis_kelamin,
            no_hp: formData.no_hp,
            username: formData.username,
            password: formData.password, 
            peran: formData.peran
          })
          .eq('id', formData.id);
        if (error) throw error;
        showToast('Guru berhasil diperbarui', 'success');
      } else {
        // Create
        const { error } = await supabase
          .from('guru')
          .insert([{
            nip: formData.nip,
            nama: formData.nama,
            jenis_kelamin: formData.jenis_kelamin,
            no_hp: formData.no_hp,
            username: formData.username,
            password: formData.password,
            peran: formData.peran || 'GURU_WALI'
          }]);
        if (error) throw error;
        showToast('Guru berhasil ditambahkan', 'success');
      }
      setIsModalOpen(false);
      setFormData({});
      fetchData(); // Instant update
    } catch (error: any) {
        const msg = error.code === '23505' ? 'Username sudah digunakan' : 'Gagal menyimpan data';
        showToast(msg, 'error');
    }
  };

  const openModal = (guru?: Guru) => {
    if (guru) {
      setIsEditing(true);
      setFormData(guru);
    } else {
      setIsEditing(false);
      setFormData({ peran: 'GURU_WALI', jenis_kelamin: 'L' });
    }
    setIsModalOpen(true);
  };

  const handleExport = () => {
    if (data.length === 0) {
      showToast('Tidak ada data untuk diekspor', 'error');
      return;
    }

    const exportData = data.map(guru => ({
      'NIP': guru.nip ? `'${guru.nip}` : '-', // Kutip agar terbaca text di Excel
      'Nama Lengkap': guru.nama,
      'Username': guru.username,
      'Password': guru.password || '',
      'Peran': guru.peran,
      'Jenis Kelamin': guru.jenis_kelamin,
      'No HP': guru.no_hp ? `'${guru.no_hp}` : '-'
    }));

    const csv = Papa.unparse(exportData);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');

    const timestamp = new Date().toISOString().split('T')[0];
    link.href = url;
    link.setAttribute('download', `data_guru_gurwal_${timestamp}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleDownloadTemplate = () => {
    const templateData = [
      {
        nip: '198001012005011001',
        nama: 'Contoh Guru Wali',
        jenis_kelamin: 'L',
        no_hp: '081234567890',
        username: 'guruwali01',
        password: 'password123',
        peran: 'GURU_WALI'
      },
      {
        nip: '198502022010012002',
        nama: 'Contoh Guru Pengajar',
        jenis_kelamin: 'P',
        no_hp: '089876543210',
        username: 'pengajar01',
        password: 'password123',
        peran: 'GURU_PENGAJAR'
      }
    ];

    const csv = Papa.unparse(templateData);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');

    link.href = url;
    link.setAttribute('download', 'template_import_guru.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Step 1: Parse and Validate
  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: async (results) => {
        const errorMessages: string[] = [];

        const parsedData = results.data.map((row: any, index: number) => {
            const rowNum = index + 2;

            // Sanitize
            const nama = row.nama ? String(row.nama).trim() : '';
            const username = row.username ? String(row.username).trim() : '';
            const nip = row.nip ? String(row.nip).replace(/['"]/g, '').trim() : null;
            const no_hp = row.no_hp ? String(row.no_hp).replace(/['"]/g, '').trim() : null;
            const jenis_kelamin = row.jenis_kelamin ? String(row.jenis_kelamin).trim().toUpperCase() : 'L';
            const peran = row.peran ? String(row.peran).trim() : 'GURU_WALI';
            const password = row.password ? String(row.password).trim() : '123456';

            // Validation
            if (!nama) errorMessages.push(`Baris ${rowNum}: Nama kosong.`);
            if (!username) errorMessages.push(`Baris ${rowNum}: Username kosong (Wajib untuk login).`);

            return {
              nip: nip === '' ? null : nip,
              nama,
              jenis_kelamin: jenis_kelamin === 'P' ? 'P' : 'L',
              no_hp: no_hp === '' ? null : no_hp,
              username,
              password, 
              peran
            };
        }).filter((row: any) => row.nama !== '');

        if (errorMessages.length > 0) {
            // Show detailed error toast in center
            const maxErrors = 5;
            const displayErrors = errorMessages.slice(0, maxErrors).join('\n');
            const suffix = errorMessages.length > maxErrors ? `\n...dan ${errorMessages.length - maxErrors} kesalahan lainnya.` : '';

            showToast(
                `Gagal Membaca CSV. Perbaiki data berikut:\n${displayErrors}${suffix}`, 
                'error', 
                10000, 
                'center'
            );

            if (fileInputRef.current) fileInputRef.current.value = '';
            return;
        }

        if (parsedData.length === 0) {
            showToast('File CSV kosong atau format salah', 'error');
        } else {
            setPreviewData(parsedData);
            setShowPreview(true);
        }

        if (fileInputRef.current) fileInputRef.current.value = '';
      },
      error: (error) => {
        showToast('Gagal membaca file CSV: ' + error.message, 'error');
      }
    });
  };

  // Step 2: Save to DB
  const handleSaveImport = async () => {
    setIsImporting(true);
    setImportProgress(0);
    setShowPreview(false);

    try {
        const total = previewData.length;
        const BATCH_SIZE = 50;

        for (let i = 0; i < total; i += BATCH_SIZE) {
             const batch = previewData.slice(i, i + BATCH_SIZE);
             const { error } = await supabase.from('guru').upsert(batch, { onConflict: 'username' });

             if (error) throw error;

             // Update Progress
             const currentProgress = Math.min(Math.round(((i + batch.length) / total) * 100), 100);
             setImportProgress(currentProgress);
        }

        showToast(`Berhasil mengimport ${total} data guru`, 'success');
        setPreviewData([]);
        fetchData();
    } catch (error: any) {
        showToast('Gagal menyimpan data ke database: ' + (error.message || 'Unknown'), 'error', 10000, 'center');
    } finally {
        setIsImporting(false);
        setImportProgress(0);
    }
  };

  // Filter Logic
  const filteredData = data.filter(guru => {
    const matchesSearch = 
      guru.nama.toLowerCase().includes(searchTerm.toLowerCase()) || 
      (guru.nip && guru.nip.includes(searchTerm)) ||
      guru.username.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesRole = filterPeran === '' || guru.peran === filterPeran;

    return matchesSearch && matchesRole;
  });

  return (
    <div>
      <ConfirmDialog 
        isOpen={!!deleteId}
        message="Yakin ingin menghapus data guru ini?"
        onConfirm={confirmDelete}
        onCancel={() => setDeleteId(null)}
      />

      <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
        <h2 className="text-2xl font-bold text-white">Manajemen Guru</h2>
        <div className="flex flex-wrap gap-2">
            <button
              onClick={handleExport}
              className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 transition flex items-center gap-2"
            >
              📥 Ekspor Data
            </button>
            <button
              onClick={handleDownloadTemplate}
              className="bg-gray-600 text-white px-4 py-2 rounded hover:bg-gray-500 transition flex items-center gap-2"
            >
              📥 Template
            </button>
            <input 
              type="file" 
              accept=".csv" 
              ref={fileInputRef} 
              onChange={handleFileUpload} 
              className="hidden" 
            />
            <button
              onClick={() => fileInputRef.current?.click()}
              className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700 transition"
            >
              📂 Import CSV
            </button>
            <button
              onClick={() => openModal()}
              className="bg-primary text-white px-4 py-2 rounded hover:bg-secondary transition"
            >
              + Tambah Guru
            </button>
        </div>
      </div>

      {/* Import Progress Overlay */}
      {isImporting && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black bg-opacity-80">
          <div className="bg-gray-800 p-6 rounded-lg border border-gray-700 w-80 md:w-96 text-center">
            <h3 className="text-white font-bold mb-4 text-lg">Mengimport Data...</h3>
            <div className="w-full bg-gray-700 rounded-full h-4 mb-2 overflow-hidden">
               <div 
                 className="bg-green-500 h-4 rounded-full transition-all duration-300" 
                 style={{ width: `${importProgress}%` }}
               ></div>
            </div>
            <p className="text-gray-300 font-medium">{importProgress}%</p>
            <p className="text-gray-500 text-sm mt-1">Mohon jangan tutup halaman ini.</p>
          </div>
        </div>
      )}

      {/* Preview Modal */}
      {showPreview && (
        <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50 p-4">
            <div className="bg-gray-800 rounded-lg shadow-lg w-full max-w-5xl p-6 border border-gray-700 max-h-[90vh] flex flex-col">
                <h3 className="text-xl font-bold mb-4 text-white">Preview Data Import ({previewData.length} Guru)</h3>
                <div className="flex-1 overflow-auto border border-gray-700 rounded mb-4">
                    <table className="min-w-full divide-y divide-gray-700">
                        <thead className="bg-gray-700 sticky top-0">
                            <tr>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">NIP</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">Nama Lengkap</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">Username</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">Password</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">Peran</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">L/P</th>
                            </tr>
                        </thead>
                        <tbody className="bg-gray-800 divide-y divide-gray-700">
                            {previewData.slice(0, 100).map((row, idx) => (
                                <tr key={idx} className="hover:bg-gray-700">
                                    <td className="px-4 py-2 text-sm text-gray-300">{row.nip || '-'}</td>
                                    <td className="px-4 py-2 text-sm text-white font-medium">{row.nama}</td>
                                    <td className="px-4 py-2 text-sm text-blue-300">{row.username}</td>
                                    <td className="px-4 py-2 text-sm text-gray-400">{row.password}</td>
                                    <td className="px-4 py-2 text-sm text-gray-300">{row.peran}</td>
                                    <td className="px-4 py-2 text-sm text-gray-300">{row.jenis_kelamin}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                    {previewData.length > 100 && (
                        <div className="p-2 text-center text-gray-500 text-sm bg-gray-700">
                            ... dan {previewData.length - 100} baris lainnya.
                        </div>
                    )}
                </div>
                <div className="flex justify-end space-x-3">
                    <button 
                        onClick={() => { setShowPreview(false); setPreviewData([]); }}
                        className="px-4 py-2 bg-gray-600 text-white rounded hover:bg-gray-500"
                    >
                        Batal
                    </button>
                    <button 
                        onClick={handleSaveImport}
                        className="px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700 font-bold"
                    >
                        📥 Simpan ke Database
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Filter Bar */}
      <div className="flex flex-col md:flex-row gap-4 mb-6 bg-gray-800 p-4 rounded-lg border border-gray-700">
        <div className="flex-1">
          <input
            type="text"
            placeholder="Cari Nama / NIP / Username..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white placeholder-gray-400 focus:outline-none focus:border-primary"
          />
        </div>
        <div className="w-full md:w-64">
           <select
             value={filterPeran}
             onChange={(e) => setFilterPeran(e.target.value)}
             className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white focus:outline-none focus:border-primary"
           >
             <option value="">Semua Peran</option>
             <option value="ADMIN">Admin</option>
             <option value="GURU_WALI">Guru Wali</option>
             <option value="GURU_PENGAJAR">Guru Pengajar</option>
           </select>
        </div>
      </div>

      {loading ? (
        <p className="text-gray-400">Memuat data...</p>
      ) : (
        <div className="bg-gray-800 shadow overflow-x-auto rounded-lg border border-gray-700">
          <table className="min-w-full divide-y divide-gray-700">
            <thead className="bg-gray-700">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">Nama / NIP</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">L/P</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">No HP</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">Akun</th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-300 uppercase tracking-wider">Aksi</th>
              </tr>
            </thead>
            <tbody className="bg-gray-800 divide-y divide-gray-700">
              {filteredData.map((guru) => (
                <tr key={guru.id}>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="text-sm font-medium text-white">{guru.nama}</div>
                    <div className="text-sm text-gray-400">{guru.nip || '-'}</div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">{guru.jenis_kelamin}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">{guru.no_hp}</td>
                  <td className="px-6 py-4 whitespace-nowrap">
                     <div className="text-sm text-white">{guru.username}</div>
                     <span className={`text-xs inline-flex px-2 py-1 rounded-full ${guru.peran === 'ADMIN' ? 'bg-purple-900 text-purple-200' : 'bg-green-900 text-green-200'}`}>
                        {guru.peran}
                     </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                    <button onClick={() => openModal(guru)} className="text-indigo-400 hover:text-indigo-300 mr-4">Edit</button>
                    <button onClick={() => handleDeleteClick(guru.id)} className="text-red-400 hover:text-red-300">Hapus</button>
                  </td>
                </tr>
              ))}
              {filteredData.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-6 py-4 text-center text-gray-500">
                    Tidak ada data guru yang cocok.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      )}

      {/* Modal Form */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50 p-4">
          <div className="bg-gray-800 rounded-lg shadow-lg w-full max-w-lg p-6 max-h-[90vh] overflow-y-auto border border-gray-700">
            <h3 className="text-lg font-bold mb-4 text-white">{isEditing ? 'Edit Guru' : 'Tambah Guru'}</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-300">NIP</label>
                  <input
                    type="text"
                    value={formData.nip || ''}
                    onChange={(e) => setFormData({ ...formData, nip: e.target.value })}
                    className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm focus:ring-primary focus:border-primary text-white"
                  />
                </div>
                <div>
                   <label className="block text-sm font-medium text-gray-300">Peran</label>
                   <select
                      value={formData.peran || 'GURU_WALI'}
                      onChange={(e) => setFormData({ ...formData, peran: e.target.value })}
                      className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 text-white"
                   >
                     <option value="GURU_WALI">Guru Wali</option>
                     <option value="ADMIN">Admin</option>
                     <option value="GURU_PENGAJAR">Guru Pengajar</option>
                   </select>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-300">Nama Lengkap *</label>
                <input
                  type="text"
                  required
                  value={formData.nama || ''}
                  onChange={(e) => setFormData({ ...formData, nama: e.target.value })}
                  className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm focus:ring-primary focus:border-primary text-white"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-300">Jenis Kelamin</label>
                  <select
                    value={formData.jenis_kelamin || 'L'}
                    onChange={(e) => setFormData({ ...formData, jenis_kelamin: e.target.value as 'L' | 'P' })}
                    className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm text-white"
                  >
                    <option value="L">Laki-laki</option>
                    <option value="P">Perempuan</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-300">No HP</label>
                  <input
                    type="text"
                    value={formData.no_hp || ''}
                    onChange={(e) => setFormData({ ...formData, no_hp: e.target.value })}
                    className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm text-white"
                  />
                </div>
              </div>

              <div className="border-t border-gray-700 pt-4 mt-4">
                <p className="text-xs text-gray-400 mb-2">Informasi Login</p>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-300">Username *</label>
                    <input
                      type="text"
                      required
                      value={formData.username || ''}
                      onChange={(e) => setFormData({ ...formData, username: e.target.value })}
                      className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm text-white"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-300">Password *</label>
                    <input
                      type="text"
                      required={!isEditing}
                      value={formData.password || ''}
                      onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                      placeholder={isEditing ? 'Isi untuk ubah password' : ''}
                      className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm text-white placeholder-gray-400"
                    />
                  </div>
                </div>
              </div>

              <div className="flex justify-end space-x-3 pt-4">
                <button
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="px-4 py-2 bg-gray-600 text-gray-200 rounded hover:bg-gray-500"
                >
                  Batal
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-primary text-white rounded hover:bg-secondary"
                >
                  Simpan
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../supabaseClient';
import { Guru, Siswa, Kelas } from '../types';

interface CrudAnggotaGurwalProps {
  showToast: (msg: string, type: 'success' | 'error') => void;
}

export const CrudAnggotaGurwal: React.FC<CrudAnggotaGurwalProps> = ({ showToast }) => {
  const [guruWaliList, setGuruWaliList] = useState<Guru[]>([]);
  const [siswaList, setSiswaList] = useState<Siswa[]>([]);
  const [kelasOptions, setKelasOptions] = useState<Kelas[]>([]);

  const [selectedGuru, setSelectedGuru] = useState<string>('');
  const [assignedSiswaIds, setAssignedSiswaIds] = useState<Set<string>>(new Set());

  // Filters
  const [filterKelas, setFilterKelas] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(false);

  // 1. Initial Load: Gurus & Kelas
  useEffect(() => {
    const fetchInitial = async () => {
      const { data: gurus } = await supabase.from('guru').select('*').eq('peran', 'GURU_WALI').order('nama');
      const { data: kelas } = await supabase.from('kelas').select('*').order('nama');
      const { data: siswa } = await supabase.from('siswa').select('*, kelas(nama)').order('nama');

      if (gurus) setGuruWaliList(gurus);
      if (kelas) setKelasOptions(kelas);
      // @ts-ignore
      if (siswa) setSiswaList(siswa);
    };
    fetchInitial();
  }, []);

  // 2. Load Bimbingan when Guru Selected
  useEffect(() => {
    if (selectedGuru) {
      fetchBimbingan();
    } else {
      setAssignedSiswaIds(new Set());
    }
     // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedGuru]);

  const fetchBimbingan = async () => {
    if (!selectedGuru) return;
    setLoading(true);
    const { data } = await supabase.from('bimbingan').select('id_siswa').eq('id_guru', selectedGuru);
    if (data) {
      setAssignedSiswaIds(new Set(data.map(item => item.id_siswa)));
    }
    setLoading(false);
  };

  const handleToggleSiswa = async (id_siswa: string, isAssigned: boolean) => {
    if (!selectedGuru) {
      showToast('Pilih Guru Wali terlebih dahulu', 'error');
      return;
    }

    try {
      if (isAssigned) {
        // Remove
        const { error } = await supabase
          .from('bimbingan')
          .delete()
          .eq('id_guru', selectedGuru)
          .eq('id_siswa', id_siswa);
        if (error) throw error;
      } else {
        // Add
        const { error } = await supabase
          .from('bimbingan')
          .insert([{ id_guru: selectedGuru, id_siswa: id_siswa }]);
        if (error) throw error;
      }

      // Optimistic update
      const newSet = new Set(assignedSiswaIds);
      if (isAssigned) newSet.delete(id_siswa);
      else newSet.add(id_siswa);
      setAssignedSiswaIds(newSet);

      // We don't necessarily need to fetchBimbingan here if optimistic update works, 
      // but strictly following sync logic is safer.
      // fetchBimbingan(); 
    } catch (e) {
      showToast('Gagal mengubah data', 'error');
      fetchBimbingan(); // Revert on error
    }
  };

  const filteredSiswa = siswaList
    .filter(s => {
      const matchSearch = s.nama.toLowerCase().includes(searchTerm.toLowerCase()) || s.nisn.includes(searchTerm);
      const matchKelas = filterKelas === '' || s.id_kelas === filterKelas;
      return matchSearch && matchKelas;
    })
    .sort((a, b) => {
      const aAssigned = assignedSiswaIds.has(a.id);
      const bAssigned = assignedSiswaIds.has(b.id);

      // Sort priority 1: Assigned (Checked) items go to top
      if (aAssigned && !bAssigned) return -1;
      if (!aAssigned && bAssigned) return 1;

      // Sort priority 2: Alphabetical name
      return a.nama.localeCompare(b.nama);
    });

  return (
    <div>
      <h2 className="text-2xl font-bold text-white mb-6">Manajemen Anggota GurWal</h2>

      {/* Main Filter Section */}
      <div className="bg-gray-800 p-6 rounded-lg border border-gray-700 mb-6">
        <label className="block text-sm font-medium text-gray-300 mb-2">Pilih Guru Wali</label>
        <select
          value={selectedGuru}
          onChange={(e) => setSelectedGuru(e.target.value)}
          className="w-full md:w-1/2 bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white focus:outline-none focus:border-primary"
        >
          <option value="">-- Pilih Guru Wali --</option>
          {guruWaliList.map(g => (
            <option key={g.id} value={g.id}>{g.nama} - {g.nip || 'No NIP'}</option>
          ))}
        </select>
        {!selectedGuru && <p className="text-yellow-500 text-sm mt-2">Silakan pilih guru wali untuk mulai mengelola siswa binaan.</p>}
      </div>

      {/* Siswa List Section */}
      {selectedGuru && (
        <>
          <div className="flex flex-col md:flex-row gap-4 mb-4">
            <div className="flex-1">
              <input
                type="text"
                placeholder="Cari Siswa / NISN..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white placeholder-gray-400"
              />
            </div>
            <div className="w-full md:w-64">
              <select
                value={filterKelas}
                onChange={(e) => setFilterKelas(e.target.value)}
                className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white"
              >
                <option value="">Semua Kelas</option>
                {kelasOptions.map(k => <option key={k.id} value={k.id}>{k.nama}</option>)}
              </select>
            </div>
          </div>

          <div className="bg-gray-800 shadow overflow-hidden rounded-lg border border-gray-700">
            {loading ? <p className="p-4 text-gray-400">Memuat data bimbingan...</p> : (
              <table className="min-w-full divide-y divide-gray-700">
                <thead className="bg-gray-700">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase w-10">Pilih</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Nama Siswa</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Kelas</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Status</th>
                  </tr>
                </thead>
                <tbody className="bg-gray-800 divide-y divide-gray-700">
                  {filteredSiswa.map(siswa => {
                    const isAssigned = assignedSiswaIds.has(siswa.id);
                    return (
                      <tr 
                        key={siswa.id} 
                        className={`transition-all duration-300 ${isAssigned 
                            ? 'bg-green-900 text-white border-l-4 border-green-500' 
                            : 'hover:bg-gray-700 border-l-4 border-transparent'
                        }`}
                      >
                        <td className="px-6 py-4 whitespace-nowrap">
                          <input
                            type="checkbox"
                            checked={isAssigned}
                            onChange={() => handleToggleSiswa(siswa.id, isAssigned)}
                            className="w-5 h-5 text-green-500 border-gray-300 rounded focus:ring-green-500 bg-gray-700"
                          />
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap font-medium">
                          {siswa.nama}
                          <div className={`text-xs ${isAssigned ? 'text-green-200' : 'text-gray-400'}`}>{siswa.nisn}</div>
                        </td>
                        <td className={`px-6 py-4 whitespace-nowrap ${isAssigned ? 'text-green-100' : 'text-gray-300'}`}>
                            {siswa.kelas?.nama || '-'}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          {isAssigned ? (
                            <span className="bg-green-700 text-white text-xs px-2 py-1 rounded-full border border-green-500 font-bold shadow-sm">
                                ✓ Terpilih
                            </span>
                          ) : (
                            <span className="text-gray-500 text-xs">-</span>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                  {filteredSiswa.length === 0 && (
                    <tr><td colSpan={4} className="p-6 text-center text-gray-500">Tidak ada siswa ditemukan.</td></tr>
                  )}
                </tbody>
              </table>
            )}
          </div>
        </>
      )}
    </div>
  );
};

import React, { useEffect, useState, useRef } from 'react';
import { supabase } from '../supabaseClient';
import { Guru } from '../types';
import Papa from 'papaparse';
import { ConfirmDialog } from './ConfirmDialog';

interface CrudGuruProps {
  showToast: (msg: string, type: 'success' | 'error', duration?: number, position?: 'top-right' | 'center') => void;
}

export const CrudGuru: React.FC<CrudGuruProps> = ({ showToast }) => {
  const [data, setData] = useState<Guru[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Guru>>({});
  const [isEditing, setIsEditing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Import State
  const [isImporting, setIsImporting] = useState(false);
  const [importProgress, setImportProgress] = useState(0);
  const [showPreview, setShowPreview] = useState(false);
  const [previewData, setPreviewData] = useState<any[]>([]);

  // Filter States
  const [searchTerm, setSearchTerm] = useState('');
  const [filterPeran, setFilterPeran] = useState('');

  // Delete Confirmation State
  const [deleteId, setDeleteId] = useState<string | null>(null);

  const fetchData = async () => {
    try {
      const { data: guruData, error } = await supabase
        .from('guru')
        .select('*')
        .order('nama', { ascending: true });

      if (error) throw error;
      setData(guruData || []);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();

    // Realtime subscription
    const channel = supabase
      .channel('guru_changes')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'guru' }, () => {
        fetchData();
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
     // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleDeleteClick = (id: string) => {
    setDeleteId(id);
  };

  const confirmDelete = async () => {
    if (!deleteId) return;
    try {
      const { error } = await supabase.from('guru').delete().eq('id', deleteId);
      if (error) throw error;
      showToast('Data guru berhasil dihapus', 'success');
      fetchData(); // Instant update
    } catch (error) {
      showToast('Gagal menghapus data', 'error');
    } finally {
      setDeleteId(null);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validasi Field Wajib
    if (!formData.nip || !formData.nama || !formData.username || !formData.password || !formData.peran) {
        showToast('Mohon lengkapi semua data wajib: NIP, Nama, Username, Password, dan Peran.', 'error');
        return;
    }

    try {
      const payload = {
        nip: formData.nip,
        nama: formData.nama,
        jenis_kelamin: formData.jenis_kelamin || 'L',
        no_hp: formData.no_hp,
        username: formData.username,
        password: formData.password, 
        peran: formData.peran
      };

      if (isEditing && formData.id) {
        // Update
        const { error } = await supabase
          .from('guru')
          .update(payload)
          .eq('id', formData.id);
        if (error) throw error;
        showToast('Data Guru berhasil diperbarui', 'success');
      } else {
        // Create / Upsert
        // Menggunakan upsert agar aman jika ada duplikasi ID (jarang terjadi di insert biasa)
        const { error } = await supabase
          .from('guru')
          .upsert([payload], { onConflict: 'username' }); 

        if (error) throw error;
        showToast('Guru berhasil ditambahkan', 'success');
      }
      setIsModalOpen(false);
      setFormData({});
      fetchData(); // Instant update
    } catch (error: any) {
        const msg = error.code === '23505' ? 'Username sudah digunakan, silakan ganti.' : 'Gagal menyimpan data';
        showToast(msg, 'error');
    }
  };

  const openModal = (guru?: Guru) => {
    if (guru) {
      setIsEditing(true);
      setFormData(guru);
    } else {
      setIsEditing(false);
      // Default Value: GURU_WALI (sesuai konteks aplikasi GurWal)
      setFormData({ peran: 'GURU_WALI', jenis_kelamin: 'L', password: '' });
    }
    setIsModalOpen(true);
  };

  const handleExport = () => {
    if (data.length === 0) {
      showToast('Tidak ada data untuk diekspor', 'error');
      return;
    }

    const exportData = data.map(guru => ({
      'NIP': guru.nip ? `'${guru.nip}` : '-', 
      'Nama Lengkap': guru.nama,
      'Username': guru.username,
      'Password': guru.password || '',
      'Peran': guru.peran,
      'Jenis Kelamin': guru.jenis_kelamin,
      'No HP': guru.no_hp ? `'${guru.no_hp}` : '-'
    }));

    const csv = Papa.unparse(exportData);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');

    const timestamp = new Date().toISOString().split('T')[0];
    link.href = url;
    link.setAttribute('download', `data_guru_gurwal_${timestamp}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleDownloadTemplate = () => {
    const templateData = [
      {
        nip: '198001012005011001',
        nama: 'Contoh Guru Wali',
        jenis_kelamin: 'L',
        no_hp: '081234567890',
        username: 'guruwali01',
        password: 'password123',
        peran: 'GURU_WALI'
      },
      {
        nip: '198502022010012002',
        nama: 'Contoh Guru Pengajar',
        jenis_kelamin: 'P',
        no_hp: '089876543210',
        username: 'pengajar01',
        password: 'password123',
        peran: 'GURU_PENGAJAR'
      }
    ];

    const csv = Papa.unparse(templateData);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');

    link.href = url;
    link.setAttribute('download', 'template_import_guru.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Step 1: Parse and Validate
  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: async (results) => {
        const errorMessages: string[] = [];

        const parsedData = results.data.map((row: any, index: number) => {
            const rowNum = index + 2;

            // Sanitize
            const nama = row.nama ? String(row.nama).trim() : '';
            const username = row.username ? String(row.username).trim() : '';
            const nip = row.nip ? String(row.nip).replace(/['"]/g, '').trim() : null;
            const no_hp = row.no_hp ? String(row.no_hp).replace(/['"]/g, '').trim() : null;
            const jenis_kelamin = row.jenis_kelamin ? String(row.jenis_kelamin).trim().toUpperCase() : 'L';
            const peran = row.peran ? String(row.peran).trim() : 'GURU_WALI';
            const password = row.password ? String(row.password).trim() : '123456';

            // Validation
            if (!nama) errorMessages.push(`Baris ${rowNum}: Nama kosong.`);
            if (!username) errorMessages.push(`Baris ${rowNum}: Username kosong.`);

            return {
              nip: nip === '' ? null : nip,
              nama,
              jenis_kelamin: jenis_kelamin === 'P' ? 'P' : 'L',
              no_hp: no_hp === '' ? null : no_hp,
              username,
              password, 
              peran
            };
        }).filter((row: any) => row.nama !== '');

        if (errorMessages.length > 0) {
            const maxErrors = 5;
            const displayErrors = errorMessages.slice(0, maxErrors).join('\n');
            const suffix = errorMessages.length > maxErrors ? `\n...dan ${errorMessages.length - maxErrors} kesalahan lainnya.` : '';

            showToast(
                `Gagal Membaca CSV. Perbaiki data berikut:\n${displayErrors}${suffix}`, 
                'error', 
                10000, 
                'center'
            );

            if (fileInputRef.current) fileInputRef.current.value = '';
            return;
        }

        if (parsedData.length === 0) {
            showToast('File CSV kosong atau format salah', 'error');
        } else {
            setPreviewData(parsedData);
            setShowPreview(true);
        }

        if (fileInputRef.current) fileInputRef.current.value = '';
      },
      error: (error) => {
        showToast('Gagal membaca file CSV: ' + error.message, 'error');
      }
    });
  };

  // Step 2: Save to DB
  const handleSaveImport = async () => {
    setIsImporting(true);
    setImportProgress(0);
    setShowPreview(false);

    try {
        const total = previewData.length;
        const BATCH_SIZE = 50;

        for (let i = 0; i < total; i += BATCH_SIZE) {
             const batch = previewData.slice(i, i + BATCH_SIZE);
             const { error } = await supabase.from('guru').upsert(batch, { onConflict: 'username' });

             if (error) throw error;
             const currentProgress = Math.min(Math.round(((i + batch.length) / total) * 100), 100);
             setImportProgress(currentProgress);
        }

        showToast(`Berhasil mengimport ${total} data guru`, 'success');
        setPreviewData([]);
        fetchData();
    } catch (error: any) {
        showToast('Gagal menyimpan data ke database: ' + (error.message || 'Unknown'), 'error', 10000, 'center');
    } finally {
        setIsImporting(false);
        setImportProgress(0);
    }
  };

  // Filter Logic
  const filteredData = data.filter(guru => {
    const matchesSearch = 
      guru.nama.toLowerCase().includes(searchTerm.toLowerCase()) || 
      (guru.nip && guru.nip.includes(searchTerm)) ||
      guru.username.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesRole = filterPeran === '' || guru.peran === filterPeran;

    return matchesSearch && matchesRole;
  });

  return (
    <div>
      <ConfirmDialog 
        isOpen={!!deleteId}
        message="Yakin ingin menghapus data guru ini?"
        onConfirm={confirmDelete}
        onCancel={() => setDeleteId(null)}
      />

      <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
        <h2 className="text-2xl font-bold text-white">Manajemen Guru</h2>
        <div className="flex flex-wrap gap-2">
            <button
              onClick={handleExport}
              className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 transition flex items-center gap-2"
            >
              📥 Ekspor Data
            </button>
            <button
              onClick={handleDownloadTemplate}
              className="bg-gray-600 text-white px-4 py-2 rounded hover:bg-gray-500 transition flex items-center gap-2"
            >
              📥 Template
            </button>
            <input 
              type="file" 
              accept=".csv" 
              ref={fileInputRef} 
              onChange={handleFileUpload} 
              className="hidden" 
            />
            <button
              onClick={() => fileInputRef.current?.click()}
              className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700 transition"
            >
              📂 Import CSV
            </button>
            <button
              onClick={() => openModal()}
              className="bg-primary text-white px-4 py-2 rounded hover:bg-secondary transition"
            >
              + Tambah Guru
            </button>
        </div>
      </div>

      {/* Import Progress Overlay */}
      {isImporting && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black bg-opacity-80">
          <div className="bg-gray-800 p-6 rounded-lg border border-gray-700 w-80 md:w-96 text-center">
            <h3 className="text-white font-bold mb-4 text-lg">Mengimport Data...</h3>
            <div className="w-full bg-gray-700 rounded-full h-4 mb-2 overflow-hidden">
               <div 
                 className="bg-green-500 h-4 rounded-full transition-all duration-300" 
                 style={{ width: `${importProgress}%` }}
               ></div>
            </div>
            <p className="text-gray-300 font-medium">{importProgress}%</p>
            <p className="text-gray-500 text-sm mt-1">Mohon jangan tutup halaman ini.</p>
          </div>
        </div>
      )}

      {/* Preview Modal */}
      {showPreview && (
        <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50 p-4">
            <div className="bg-gray-800 rounded-lg shadow-lg w-full max-w-5xl p-6 border border-gray-700 max-h-[90vh] flex flex-col">
                <h3 className="text-xl font-bold mb-4 text-white">Preview Data Import ({previewData.length} Guru)</h3>
                <div className="flex-1 overflow-auto border border-gray-700 rounded mb-4">
                    <table className="min-w-full divide-y divide-gray-700">
                        <thead className="bg-gray-700 sticky top-0">
                            <tr>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">NIP</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">Nama Lengkap</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">Username</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">Password</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">Peran</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">L/P</th>
                            </tr>
                        </thead>
                        <tbody className="bg-gray-800 divide-y divide-gray-700">
                            {previewData.slice(0, 100).map((row, idx) => (
                                <tr key={idx} className="hover:bg-gray-700">
                                    <td className="px-4 py-2 text-sm text-gray-300">{row.nip || '-'}</td>
                                    <td className="px-4 py-2 text-sm text-white font-medium">{row.nama}</td>
                                    <td className="px-4 py-2 text-sm text-blue-300">{row.username}</td>
                                    <td className="px-4 py-2 text-sm text-gray-400">{row.password}</td>
                                    <td className="px-4 py-2 text-sm text-gray-300">{row.peran}</td>
                                    <td className="px-4 py-2 text-sm text-gray-300">{row.jenis_kelamin}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                    {previewData.length > 100 && (
                        <div className="p-2 text-center text-gray-500 text-sm bg-gray-700">
                            ... dan {previewData.length - 100} baris lainnya.
                        </div>
                    )}
                </div>
                <div className="flex justify-end space-x-3">
                    <button 
                        onClick={() => { setShowPreview(false); setPreviewData([]); }}
                        className="px-4 py-2 bg-gray-600 text-white rounded hover:bg-gray-500"
                    >
                        Batal
                    </button>
                    <button 
                        onClick={handleSaveImport}
                        className="px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700 font-bold"
                    >
                        📥 Simpan ke Database
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Filter Bar */}
      <div className="flex flex-col md:flex-row gap-4 mb-6 bg-gray-800 p-4 rounded-lg border border-gray-700">
        <div className="flex-1">
          <input
            type="text"
            placeholder="Cari Nama / NIP / Username..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white placeholder-gray-400 focus:outline-none focus:border-primary"
          />
        </div>
        <div className="w-full md:w-64">
           <select
             value={filterPeran}
             onChange={(e) => setFilterPeran(e.target.value)}
             className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white focus:outline-none focus:border-primary"
           >
             <option value="">Semua Peran</option>
             <option value="ADMIN">Admin</option>
             <option value="GURU_WALI">Guru Wali</option>
             <option value="GURU_PENGAJAR">Guru Pengajar</option>
           </select>
        </div>
      </div>

      {loading ? (
        <p className="text-gray-400">Memuat data...</p>
      ) : (
        <div className="bg-gray-800 shadow overflow-x-auto rounded-lg border border-gray-700">
          <table className="min-w-full divide-y divide-gray-700">
            <thead className="bg-gray-700">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">Nama / NIP</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">L/P</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">No HP</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">Akun</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">Peran</th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-300 uppercase tracking-wider">Aksi</th>
              </tr>
            </thead>
            <tbody className="bg-gray-800 divide-y divide-gray-700">
              {filteredData.map((guru) => (
                <tr key={guru.id}>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="text-sm font-medium text-white">{guru.nama}</div>
                    <div className="text-sm text-gray-400">{guru.nip || '-'}</div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">{guru.jenis_kelamin}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">{guru.no_hp}</td>
                  <td className="px-6 py-4 whitespace-nowrap">
                     <div className="text-sm text-white">{guru.username}</div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                     <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${
                        guru.peran === 'ADMIN' ? 'bg-blue-900 text-blue-200' : 'bg-green-900 text-green-200'
                     }`}>
                        {guru.peran === 'ADMIN' ? 'ADMIN' : (guru.peran === 'GURU_WALI' ? 'GURU WALI' : 'GURU PENGAJAR')}
                     </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                    <button onClick={() => openModal(guru)} className="text-indigo-400 hover:text-indigo-300 mr-4">Edit</button>
                    <button onClick={() => handleDeleteClick(guru.id)} className="text-red-400 hover:text-red-300">Hapus</button>
                  </td>
                </tr>
              ))}
              {filteredData.length === 0 && (
                <tr>
                  <td colSpan={6} className="px-6 py-4 text-center text-gray-500">
                    Tidak ada data guru yang cocok.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      )}

      {/* Modal Form */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50 p-4">
          <div className="bg-gray-800 rounded-lg shadow-lg w-full max-w-lg p-6 max-h-[90vh] overflow-y-auto border border-gray-700">
            <h3 className="text-lg font-bold mb-4 text-white">{isEditing ? 'Edit Guru' : 'Tambah Guru'}</h3>
            <form onSubmit={handleSubmit} className="space-y-4">

              {/* Field Peran */}
              <div>
                   <label className="block text-sm font-medium text-gray-300">Peran *</label>
                   <select
                      value={formData.peran || 'GURU_WALI'}
                      onChange={(e) => setFormData({ ...formData, peran: e.target.value })}
                      className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 text-white focus:ring-primary focus:border-primary"
                   >
                     <option value="GURU_WALI">Guru Wali (Default)</option>
                     <option value="ADMIN">Admin</option>
                     <option value="GURU_PENGAJAR">Guru Pengajar</option>
                   </select>
                   <p className="text-xs text-gray-500 mt-1">Pilih "Guru Wali" untuk wali kelas, atau "Guru Pengajar" untuk guru mapel.</p>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-300">NIP / NUPTK *</label>
                  <input
                    type="text"
                    required
                    value={formData.nip || ''}
                    onChange={(e) => setFormData({ ...formData, nip: e.target.value })}
                    className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm focus:ring-primary focus:border-primary text-white"
                  />
                </div>
                <div>
                   <label className="block text-sm font-medium text-gray-300">Jenis Kelamin</label>
                   <select
                      value={formData.jenis_kelamin || 'L'}
                      onChange={(e) => setFormData({ ...formData, jenis_kelamin: e.target.value as 'L' | 'P' })}
                      className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 text-white"
                   >
                     <option value="L">Laki-laki</option>
                     <option value="P">Perempuan</option>
                   </select>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-300">Nama Lengkap *</label>
                <input
                  type="text"
                  required
                  value={formData.nama || ''}
                  onChange={(e) => setFormData({ ...formData, nama: e.target.value })}
                  className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm focus:ring-primary focus:border-primary text-white"
                />
              </div>

              <div>
                  <label className="block text-sm font-medium text-gray-300">No HP</label>
                  <input
                    type="text"
                    value={formData.no_hp || ''}
                    onChange={(e) => setFormData({ ...formData, no_hp: e.target.value })}
                    className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm text-white"
                  />
              </div>

              <div className="border-t border-gray-700 pt-4 mt-4">
                <p className="text-xs text-gray-400 mb-2">Informasi Akun Login</p>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-300">Username *</label>
                    <input
                      type="text"
                      required
                      value={formData.username || ''}
                      onChange={(e) => setFormData({ ...formData, username: e.target.value })}
                      className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm text-white"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-300">Password *</label>
                    <input
                      type="text"
                      required={!isEditing}
                      value={formData.password || ''}
                      onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                      placeholder={isEditing ? 'Biarkan kosong jika tetap' : ''}
                      className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 shadow-sm text-white placeholder-gray-400"
                    />
                  </div>
                </div>
              </div>

              <div className="flex justify-end space-x-3 pt-4">
                <button
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="px-4 py-2 bg-gray-600 text-gray-200 rounded hover:bg-gray-500"
                >
                  Batal
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-primary text-white rounded hover:bg-secondary"
                >
                  Simpan
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useRef } from 'react';
import { supabase } from '../supabaseClient';
import { Guru } from '../types';
import Papa from 'papaparse';
import { ConfirmDialog } from './ConfirmDialog';

interface CrudGuruProps {
  showToast: (msg: string, type: 'success' | 'error', duration?: number, position?: 'top-right' | 'center') => void;
}

export const CrudGuru: React.FC<CrudGuruProps> = ({ showToast }) => {
  const [data, setData] = useState<Guru[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Guru>>({});
  const [isEditing, setIsEditing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Import State
  const [isImporting, setIsImporting] = useState(false);
  const [importProgress, setImportProgress] = useState(0);
  const [showPreview, setShowPreview] = useState(false);
  const [previewData, setPreviewData] = useState<any[]>([]);

  // Filter States
  const [searchTerm, setSearchTerm] = useState('');
  const [filterPeran, setFilterPeran] = useState('');

  // Delete Confirmation State
  const [deleteId, setDeleteId] = useState<string | null>(null);

  const fetchData = async () => {
    try {
      const { data: guruData, error } = await supabase
        .from('guru')
        .select('*')
        .order('nama', { ascending: true });

      if (error) throw error;
      setData(guruData || []);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();

    // Realtime subscription
    const channel = supabase
      .channel('guru_changes')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'guru' }, () => {
        fetchData();
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
     // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleDeleteClick = (id: string) => {
    setDeleteId(id);
  };

  const confirmDelete = async () => {
    if (!deleteId) return;
    try {
      const { error } = await supabase.from('guru').delete().eq('id', deleteId);
      if (error) throw error;
      showToast('Data guru berhasil dihapus', 'success');
      fetchData(); // Instant update
    } catch (error) {
      showToast('Gagal menghapus data', 'error');
    } finally {
      setDeleteId(null);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validasi Field Wajib
    if (!formData.nip || !formData.nama || !formData.username || !formData.password || !formData.peran) {
        showToast('Mohon lengkapi semua data wajib: NIP, Nama, Username, Password, dan Peran.', 'error');
        return;
    }

    try {
      const payload = {
        nip: formData.nip,
        nama: formData.nama,
        jenis_kelamin: formData.jenis_kelamin || 'L',
        no_hp: formData.no_hp,
        username: formData.username,
        password: formData.password, 
        peran: formData.peran
      };

      if (isEditing && formData.id) {
        // Update
        const { error } = await supabase
          .from('guru')
          .update(payload)
          .eq('id', formData.id);
        if (error) throw error;
        showToast('Data Guru berhasil diperbarui', 'success');
      } else {
        // Create / Upsert
        const { error } = await supabase
          .from('guru')
          .upsert([payload], { onConflict: 'username' }); 

        if (error) throw error;
        showToast('Guru berhasil ditambahkan', 'success');
      }
      setIsModalOpen(false);
      setFormData({});
      fetchData(); // Instant update
    } catch (error: any) {
        const msg = error.code === '23505' ? 'Username sudah digunakan, silakan ganti.' : 'Gagal menyimpan data';
        showToast(msg, 'error');
    }
  };

  const openModal = (guru?: Guru) => {
    if (guru) {
      setIsEditing(true);
      setFormData(guru);
    } else {
      setIsEditing(false);
      // Default Value: GURU
      setFormData({ peran: 'GURU', jenis_kelamin: 'L', password: '' });
    }
    setIsModalOpen(true);
  };

  const handleExport = () => {
    if (data.length === 0) {
      showToast('Tidak ada data untuk diekspor', 'error');
      return;
    }

    const exportData = data.map(guru => ({
      'NIP': guru.nip ? `'${guru.nip}` : '-', 
      'Nama Lengkap': guru.nama,
      'Username': guru.username,
      'Password': guru.password || '',
      'Peran': guru.peran,
      'Jenis Kelamin': guru.jenis_kelamin,
      'No HP': guru.no_hp ? `'${guru.no_hp}` : '-'
    }));

    const csv = Papa.unparse(exportData);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');

    const timestamp = new Date().toISOString().split('T')[0];
    link.href = url;
    link.setAttribute('download', `data_guru_gurwal_${timestamp}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleDownloadTemplate = () => {
    const templateData = [
      {
        nip: '198001012005011001',
        nama: 'Contoh Guru',
        jenis_kelamin: 'L',
        no_hp: '081234567890',
        username: 'guru01',
        password: 'password123',
        peran: 'GURU'
      },
      {
        nip: '198502022010012002',
        nama: 'Contoh Admin',
        jenis_kelamin: 'P',
        no_hp: '089876543210',
        username: 'admin01',
        password: 'password123',
        peran: 'ADMIN'
      }
    ];

    const csv = Papa.unparse(templateData);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');

    link.href = url;
    link.setAttribute('download', 'template_import_guru.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Step 1: Parse and Validate
  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: async (results) => {
        const errorMessages: string[] = [];

        const parsedData = results.data.map((row: any, index: number) => {
            const rowNum = index + 2;

            // Sanitize
            const nama = row.nama ? String(row.nama).trim() : '';
            const username = row.username ? String(row.username).trim() : '';
            const nip = row.nip ? String(row.nip).replace(/['"]/g, '').trim() : null;
            const no_hp = row.no_hp ? String(row.no_hp).replace(/['"]/g, '').trim() : null;
            const jenis_kelamin = row.jenis_kelamin ? String(row.jenis_kelamin).trim().toUpperCase() : 'L';
            const peranRaw = row.peran ? String(row.peran).trim().toUpperCase() : 'GURU';
            const peran = (peranRaw === 'ADMIN') ? 'ADMIN' : 'GURU'; // Default to GURU if unknown
            const password = row.password ? String(row.password).trim() : '123456';

            // Validation
            if (!nama) errorMessages.push(`Baris ${rowNum}: Nama kosong.`);
            if (!username) errorMessages.push(`Baris ${rowNum}: Username kosong.`);

            return {
              nip: nip === '' ? null : nip,
              nama,
              jenis_kelamin: jenis_kelamin === 'P' ? 'P' : 'L',
              no_hp: no_hp === '' ? null : no_hp,
              username,
              password, 
              peran
            };
        }).filter((row: any) => row.nama !== '');

        if (errorMessages.length > 0) {
            const maxErrors = 5;
            const displayErrors = errorMessages.slice(0, maxErrors).join('\n');
            const suffix = errorMessages.length > maxErrors ? `\n...dan ${errorMessages.length - maxErrors} kesalahan lainnya.` : '';

            showToast(
                `Gagal Membaca CSV. Perbaiki data berikut:\n${displayErrors}${suffix}`, 
                'error', 
                10000, 
                'center'
            );

            if (fileInputRef.current) fileInputRef.current.value = '';
            return;
        }

        if (parsedData.length === 0) {
            showToast('File CSV kosong atau format salah', 'error');
        } else {
            setPreviewData(parsedData);
            setShowPreview(true);
        }

        if (fileInputRef.current) fileInputRef.current.value = '';
      },
      error: (error) => {
        showToast('Gagal membaca file CSV: ' + error.message, 'error');
      }
    });
  };

  // Step 2: Save to DB
  const handleSaveImport = async () => {
    setIsImporting(true);
    setImportProgress(0);
    setShowPreview(false);

    try {
        const total = previewData.length;
        const BATCH_SIZE = 50;

        for (let i = 0; i < total; i += BATCH_SIZE) {
             const batch = previewData.slice(i, i + BATCH_SIZE);
             const { error } = await supabase.from('guru').upsert(batch, { onConflict: 'username' });

             if (error) throw error;
             const currentProgress = Math.min(Math.round(((i + batch.length) / total) * 100), 100);
             setImportProgress(currentProgress);
        }

        showToast(`Berhasil mengimport ${total} data guru`, 'success');
        setPreviewData([]);
        fetchData();
    } catch (error: any) {
        showToast('Gagal menyimpan data ke database: ' + (error.message || 'Unknown'), 'error', 10000, 'center');
    } finally {
        setIsImporting(false);
        setImportProgress(0);
    }
  };

  // Filter Logic
  const filteredData = data.filter(guru => {
    const matchesSearch = 
      guru.nama.toLowerCase().includes(searchTerm.toLowerCase()) || 
      (guru.nip && guru.nip.includes(searchTerm)) ||
      guru.username.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesRole = filterPeran === '' || guru.peran === filterPeran;

    return matchesSearch && matchesRole;
  });

  return (
    <div>
      <ConfirmDialog 
        isOpen={!!deleteId}
        message="Yakin ingin menghapus data guru ini?"
        onConfirm={confirmDelete}
        onCancel={() => setDeleteId(null)}
      />

      <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
        <h2 className="text-2xl font-bold text-white">Manajemen Guru</h2>
        <div className="flex flex-wrap gap-2">
            <button
              onClick={handleExport}
              className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 transition flex items-center gap-2"
            >
              📥 Ekspor Data
            </button>
            <button
              onClick={handleDownloadTemplate}
              className="bg-gray-600 text-white px-4 py-2 rounded hover:bg-gray-500 transition flex items-center gap-2"
            >
              📥 Template
            </button>
            <input 
              type="file" 
              accept=".csv" 
              ref={fileInputRef} 
              onChange={handleFileUpload} 
              className="hidden" 
            />
            <button
              onClick={() => fileInputRef.current?.click()}
              className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700 transition"
            >
              📂 Import CSV
            </button>
            <button
              onClick={() => openModal()}
              className="bg-primary text-white px-4 py-2 rounded hover:bg-secondary transition"
            >
              + Tambah Guru
            </button>
        </div>
      </div>

      {/* Import Progress Overlay */}
      {isImporting && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black bg-opacity-80">
          <div className="bg-gray-800 p-6 rounded-lg border border-gray-700 w-80 md:w-96 text-center">
            <h3 className="text-white font-bold mb-4 text-lg">Mengimport Data...</h3>
            <div className="w-full bg-gray-700 rounded-full h-4 mb-2 overflow-hidden">
               <div 
                 className="bg-green-500 h-4 rounded-full transition-all duration-300" 
                 style={{ width: `${importProgress}%` }}
               ></div>
            </div>
            <p className="text-gray-300 font-medium">{importProgress}%</p>
            <p className="text-gray-500 text-sm mt-1">Mohon jangan tutup halaman ini.</p>
          </div>
        </div>
      )}

      {/* Preview Modal */}
      {showPreview && (
        <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50 p-4">
            <div className="bg-gray-800 rounded-lg shadow-lg w-full max-w-5xl p-6 border border-gray-700 max-h-[90vh] flex flex-col">
                <h3 className="text-xl font-bold mb-4 text-white">Preview Data Import ({previewData.length} Guru)</h3>
                <div className="flex-1 overflow-auto border border-gray-700 rounded mb-4">
                    <table className="min-w-full divide-y divide-gray-700">
                        <thead className="bg-gray-700 sticky top-0">
                            <tr>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">NIP</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">Nama Lengkap</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">Username</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">Password</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">Peran</th>
                                <th className="px-4 py-2 text-left text-xs font-medium text-gray-300">L/P</th>
                            </tr>
                        </thead>
                        <tbody className="bg-gray-800 divide-y divide-gray-700">
                            {previewData.slice(0, 100).map((row, idx) => (
                                <tr key={idx} className="hover:bg-gray-700">
                                    <td className="px-4 py-2 text-sm text-gray-300">{row.nip || '-'}</td>
                                    <td className="px-4 py-2 text-sm text-white font-medium">{row.nama}</td>
                                    <td className="px-4 py-2 text-sm text-blue-300">{row.username}</td>
                                    <td className="px-4 py-2 text-sm text-gray-400">{row.password}</td>
                                    <td className="px-4 py-2 text-sm text-gray-300">{row.peran}</td>
                                    <td className="px-4 py-2 text-sm text-gray-300">{row.jenis_kelamin}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                    {previewData.length > 100 && (
                        <div className="p-2 text-center text-gray-500 text-sm bg-gray-700">
                            ... dan {previewData.length - 100} baris lainnya.
                        </div>
                    )}
                </div>
                <div className="flex justify-end space-x-3">
                    <button 
                        onClick={() => { setShowPreview(false); setPreviewData([]); }}
                        className="px-4 py-2 bg-gray-600 text-white rounded hover:bg-gray-500"
                    >
                        Batal
                    </button>
                    <button 
                        onClick={handleSaveImport}
                        className="px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700 font-bold"
                    >
                        📥 Simpan ke Database
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Filter Bar */}
      <div className="flex flex-col md:flex-row gap-4 mb-6 bg-gray-800 p-4 rounded-lg border border-gray-700">
        <div className="flex-1">
          <input
            type="text"
            placeholder="Cari Nama / NIP / Username..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white placeholder-gray-400 focus:outline-none focus:border-primary"
          />
        </div>
        <div className="w-full md:w-64">
           <select
             value={filterPeran}
             onChange={(e) => setFilterPeran(e.target.value)}
             className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white focus:outline-none focus:border-primary"
           >
             <option value="">Semua Peran</option>
             <option value="ADMIN">Admin</option>
             <option value="GURU">Guru</option>
           </select>
        </div>
      </div>

      {loading ? (
        <p className="text-gray-400">Memuat data...</p>
      ) : (
        <div className="bg-gray-800 shadow overflow-x-auto rounded-lg border border-gray-700">
          <table className="min-w-full divide-y divide-gray-700">
            <thead className="bg-gray-700">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">Nama / NIP</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">L/P</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">No HP</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">Akun</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase tracking-wider">Peran</th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-300 uppercase tracking-wider">Aksi</th>
              </tr>
            </thead>
            <tbody className="bg-gray-800 divide-y divide-gray-700">
              {filteredData.map((guru) => (
                <tr key={guru.id}>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="text-sm font-medium text-white">{guru.nama}</div>
                    <div className="text-sm text-gray-400">{guru.nip || '-'}</div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">{guru.jenis_kelamin}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">{guru.no_hp}</td>
                  <td className="px-6 py-4 whitespace-nowrap">
                     <div className="text-sm text-white">{guru.username}</div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                     <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${
                        guru.peran === 'ADMIN' ? 'bg-blue-900 text-blue-200' : 'bg-green-900 text-green-200'
                     }`}>
                        {guru.peran}
                     </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                    <button onClick={() => openModal(guru)} className="text-indigo-400 hover:text-indigo-300 mr-4">Edit</button>
                    <button onClick={() => handleDeleteClick(guru.id)} className="text-red-400 hover:text-red-300">Hapus</button>
                  </td>
                </tr>
              ))}
              {filteredData.length === 0 && (
                <tr>
                  <td colSpan={6} className="px-6 py-4 text-center text-gray-500">
                    Tidak ada data guru yang cocok.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      )}

      {/* Modal Form */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50 p-4">
          <div className="bg-gray-800 rounded-lg shadow-lg w-full max-w-lg p-6 max-h-[90vh] overflow-y-auto border border-gray-700">
            <h3 className="text-lg font-bold mb-4 text-white">{isEditing ? 'Edit Guru' : 'Tambah Guru'}</h3>
            <form onSubmit={handleSubmit} className="space-y-4">

              {/* Field Peran */}
              <div>
                   <label className="block text-sm font-medium text-gray-300">Peran *</label>
                   <select
                      value={formData.peran || 'GURU'}
                      onChange={(e) => setFormData({ ...formData, peran: e.target.value })}
                      className="mt-1 block w-full bg-gray-700 border border-gray-600 rounded-md p-2 text-white focus:ring-primary focus:border-primary"
