import React, { useEffect, useState } from 'react';
import { supabase } from '../../supabaseClient';
import { Guru, Bimbingan, Kehadiran } from '../../types';

interface Props {
  currentUser: Guru;
  showToast: (msg: string, type: 'success' | 'error') => void;
}

export const KehadiranBinaan: React.FC<Props> = ({ currentUser, showToast }) => {
  const [siswaList, setSiswaList] = useState<Bimbingan[]>([]);
  const [kehadiranList, setKehadiranList] = useState<Kehadiran[]>([]);
  const [tanggal, setTanggal] = useState(new Date().toISOString().split('T')[0]);
  const [loading, setLoading] = useState(true);

  // Load students
  useEffect(() => {
    const fetchSiswa = async () => {
      const { data, error } = await supabase
        .from('bimbingan')
        .select('*, siswa(id, nama, nisn, kelas(nama))')
        .eq('id_guru', currentUser.id)
        .order('created_at', { ascending: true });

      if (!error && data) {
         // @ts-ignore
         setSiswaList(data);
      }
    };
    fetchSiswa();
  }, [currentUser.id]);

  // Load attendance for selected date
  const fetchKehadiran = async () => {
    setLoading(true);
    const { data, error } = await supabase
      .from('kehadiran')
      .select('*')
      .eq('id_guru', currentUser.id)
      .eq('tanggal', tanggal);

    if (!error && data) {
      setKehadiranList(data as Kehadiran[]);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchKehadiran();
    // Realtime subscription
    const channel = supabase
      .channel('kehadiran_realtime')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'kehadiran', filter: `tanggal=eq.${tanggal}` }, () => {
          fetchKehadiran();
      })
      .subscribe();

    return () => { supabase.removeChannel(channel); };
     // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tanggal, currentUser.id]);

  const handleStatusChange = async (id_siswa: string, status: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA') => {
    const existing = kehadiranList.find(k => k.id_siswa === id_siswa);
    try {
      if (existing) {
        const { error } = await supabase.from('kehadiran').update({ status }).eq('id', existing.id);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('kehadiran').insert([{ id_guru: currentUser.id, id_siswa, tanggal, status }]);
        if (error) throw error;
      }
      showToast('Status disimpan', 'success');
      fetchKehadiran();
    } catch (e) {
      showToast('Gagal menyimpan status', 'error');
    }
  };

  return (
    <div>
      <h2 className="text-2xl font-bold text-white mb-6">Input Kehadiran Binaan</h2>

      <div className="mb-6 bg-gray-800 p-4 rounded-lg border border-gray-700 flex items-center gap-4">
        <label className="text-gray-300 font-medium">Pilih Tanggal:</label>
        <input 
          type="date" 
          value={tanggal}
          onChange={(e) => setTanggal(e.target.value)}
          className="bg-gray-700 border border-gray-600 text-white rounded px-3 py-2 focus:outline-none focus:border-primary"
        />
      </div>

      <div className="bg-gray-800 shadow overflow-hidden rounded-lg border border-gray-700">
        <table className="min-w-full divide-y divide-gray-700">
          <thead className="bg-gray-700">
            <tr>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Nama Siswa</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Kelas</th>
              <th className="px-6 py-3 text-center text-xs font-medium text-gray-300 uppercase">Status Kehadiran</th>
            </tr>
          </thead>
          <tbody className="bg-gray-800 divide-y divide-gray-700">
            {siswaList.map((item) => {
               const currentStatus = kehadiranList.find(k => k.id_siswa === item.id_siswa)?.status;
               return (
                <tr key={item.id}>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-white font-medium">{item.siswa?.nama}</td>
                  {/* @ts-ignore */}
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-400">{item.siswa?.kelas?.nama}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-center">
                    <div className="flex justify-center gap-2">
                       {(['HADIR', 'SAKIT', 'IZIN', 'ALPHA'] as const).map(status => (
                         <button
                           key={status}
                           onClick={() => handleStatusChange(item.id_siswa, status)}
                           className={`px-3 py-1 rounded text-xs font-bold transition-all ${
                             currentStatus === status 
                               ? status === 'HADIR' ? 'bg-green-600 text-white' 
                                 : status === 'SAKIT' ? 'bg-yellow-600 text-white'
                                 : status === 'IZIN' ? 'bg-blue-600 text-white'
                                 : 'bg-red-600 text-white'
                               : 'bg-gray-700 text-gray-400 hover:bg-gray-600'
                           }`}
                         >
                           {status}
                         </button>
                       ))}
                    </div>
                  </td>
                </tr>
               );
            })}
            {siswaList.length === 0 && (
               <tr><td colSpan={3} className="p-6 text-center text-gray-500">Tidak ada siswa binaan.</td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../supabaseClient';
import { Guru, Bimbingan, Pelanggaran } from '../../types';
import { ConfirmDialog } from '../ConfirmDialog';

interface Props {
  currentUser: Guru;
  showToast: (msg: string, type: 'success' | 'error') => void;
}

export const PelanggaranBinaan: React.FC<Props> = ({ currentUser, showToast }) => {
  const [siswaList, setSiswaList] = useState<Bimbingan[]>([]);
  const [data, setData] = useState<Pelanggaran[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Pelanggaran>>({});
  const [deleteId, setDeleteId] = useState<string | null>(null);

  const fetchData = async () => {
    const { data: pelData, error } = await supabase
      .from('pelanggaran')
      .select('*, siswa(nama, kelas(nama))')
      .eq('id_guru', currentUser.id)
      .order('tanggal', { ascending: false });

    if (!error && pelData) {
        // @ts-ignore
        setData(pelData);
    }
  };

  useEffect(() => {
    const fetchSiswa = async () => {
        const { data } = await supabase.from('bimbingan').select('*, siswa(id, nama)').eq('id_guru', currentUser.id);
        // @ts-ignore
        if (data) setSiswaList(data);
    };
    fetchSiswa();
    fetchData();

    const channel = supabase
      .channel('pelanggaran_change')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'pelanggaran', filter: `id_guru=eq.${currentUser.id}` }, () => fetchData())
      .subscribe();
    return () => { supabase.removeChannel(channel); };
     // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentUser.id]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
        const { error } = await supabase.from('pelanggaran').insert([{
            id_guru: currentUser.id,
            id_siswa: formData.id_siswa,
            deskripsi: formData.deskripsi,
            tindakan: formData.tindakan,
            tanggal: formData.tanggal || new Date().toISOString().split('T')[0]
        }]);
        if (error) throw error;
        showToast('Pelanggaran dicatat', 'success');
        setIsModalOpen(false);
        setFormData({});
        fetchData();
    } catch (e) {
        showToast('Gagal menyimpan', 'error');
    }
  };

  const confirmDelete = async () => {
    if (!deleteId) return;
    const { error } = await supabase.from('pelanggaran').delete().eq('id', deleteId);
    if(error) showToast("Gagal hapus", "error");
    else {
      showToast("Terhapus", "success");
      fetchData();
    }
    setDeleteId(null);
  }

  return (
    <div>
      <ConfirmDialog isOpen={!!deleteId} message="Hapus data pelanggaran ini?" onConfirm={confirmDelete} onCancel={() => setDeleteId(null)} />
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-white">Catatan Pelanggaran (Binaan)</h2>
        <button onClick={() => setIsModalOpen(true)} className="bg-red-600 text-white px-4 py-2 rounded hover:bg-red-700 transition">+ Catat Pelanggaran</button>
      </div>

      <div className="bg-gray-800 shadow overflow-hidden rounded-lg border border-gray-700">
        <table className="min-w-full divide-y divide-gray-700">
          <thead className="bg-gray-700">
            <tr>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Tanggal</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Siswa</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Deskripsi</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Tindakan</th>
              <th className="px-6 py-3 text-right text-xs font-medium text-gray-300 uppercase">Aksi</th>
            </tr>
          </thead>
          <tbody className="bg-gray-800 divide-y divide-gray-700">
             {data.map(item => (
                 <tr key={item.id}>
                     <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-300">{item.tanggal}</td>
                     <td className="px-6 py-4 whitespace-nowrap text-sm font-bold text-white">{item.siswa?.nama}</td>
                     <td className="px-6 py-4 text-sm text-gray-300">{item.deskripsi}</td>
                     <td className="px-6 py-4 text-sm text-gray-300">{item.tindakan || '-'}</td>
                     <td className="px-6 py-4 text-right">
                         <button onClick={() => setDeleteId(item.id)} className="text-red-400 hover:text-red-300 text-sm">Hapus</button>
                     </td>
                 </tr>
             ))}
             {data.length === 0 && <tr><td colSpan={5} className="p-6 text-center text-gray-500">Belum ada data pelanggaran.</td></tr>}
          </tbody>
        </table>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50 p-4">
          <div className="bg-gray-800 rounded-lg shadow-lg w-full max-w-md p-6 border border-gray-700">
             <h3 className="text-lg font-bold mb-4 text-white">Input Pelanggaran</h3>
             <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                    <label className="block text-sm font-medium text-gray-300">Siswa</label>
                    <select required className="mt-1 w-full bg-gray-700 border border-gray-600 rounded p-2 text-white" onChange={e => setFormData({...formData, id_siswa: e.target.value})}>
                        <option value="">-- Pilih Siswa --</option>
                        {siswaList.map(s => <option key={s.id_siswa} value={s.id_siswa}>{s.siswa?.nama}</option>)}
                    </select>
                </div>
                <div>
                    <label className="block text-sm font-medium text-gray-300">Tanggal</label>
                    <input type="date" required className="mt-1 w-full bg-gray-700 border border-gray-600 rounded p-2 text-white" onChange={e => setFormData({...formData, tanggal: e.target.value})} />
                </div>
                <div>
                    <label className="block text-sm font-medium text-gray-300">Deskripsi</label>
                    <textarea required className="mt-1 w-full bg-gray-700 border border-gray-600 rounded p-2 text-white" rows={3} onChange={e => setFormData({...formData, deskripsi: e.target.value})}></textarea>
                </div>
                <div>
                    <label className="block text-sm font-medium text-gray-300">Tindakan</label>
                    <input type="text" className="mt-1 w-full bg-gray-700 border border-gray-600 rounded p-2 text-white" onChange={e => setFormData({...formData, tindakan: e.target.value})} />
                </div>
                <div className="flex justify-end space-x-3 pt-4">
                    <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 bg-gray-600 text-gray-200 rounded">Batal</button>
                    <button type="submit" className="px-4 py-2 bg-primary text-white rounded">Simpan</button>
                </div>
             </form>
          </div>
        </div>
      )}
    </div>
  );
};

