import React, { useEffect, useState, useRef } from 'react';
import { supabase } from '../supabaseClient';
import { Sekolah } from '../types';

interface CrudSekolahProps {
  showToast: (msg: string, type: 'success' | 'error', duration?: number, position?: 'top-right' | 'center') => void;
}

export const CrudSekolah: React.FC<CrudSekolahProps> = ({ showToast }) => {
  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Sekolah>>({
    nama_sekolah: '',
    npsn: '',
    alamat: '',
    email: '',
    no_telp: '',
    logo_url: ''
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      // Ambil single row. Karena tabel sekolah hanya untuk 1 entitas.
      const { data, error } = await supabase
        .from('sekolah')
        .select('*')
        .limit(1)
        .single();

      if (data) {
        setFormData(data);
      } else if (error && error.code !== 'PGRST116') { // PGRST116 = JSON object requested, multiple (or no) rows returned
         console.error(error);
      }
    } catch (error) {
      console.error('Error fetching data sekolah:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleLogoUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    try {
      setUploading(true);
      if (!event.target.files || event.target.files.length === 0) {
        throw new Error('Pilih gambar terlebih dahulu.');
      }

      const file = event.target.files[0];
      const fileExt = file.name.split('.').pop();
      const fileName = `logo-${Date.now()}.${fileExt}`;
      const filePath = `${fileName}`;

      // Upload ke bucket 'logo-sekolah'
      const { error: uploadError } = await supabase.storage
        .from('logo-sekolah')
        .upload(filePath, file);

      if (uploadError) {
        throw uploadError;
      }

      // Dapatkan Public URL
      const { data } = supabase.storage
        .from('logo-sekolah')
        .getPublicUrl(filePath);

      if (data) {
         setFormData(prev => ({ ...prev, logo_url: data.publicUrl }));
         showToast('Logo berhasil diunggah', 'success');
      }

    } catch (error: any) {
      showToast('Gagal mengunggah logo: ' + error.message, 'error');
    } finally {
      setUploading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const payload = {
        ...formData,
        // Jika ID belum ada, biarkan Supabase auto-increment atau kita handle logic single row
        // Namun cara paling aman untuk "Single Row Config" adalah upsert dengan ID fix (misal 1) jika tabel kosong, 
        // atau update jika ID sudah ada.
        id: formData.id || 1, 
      };

      const { error } = await supabase
        .from('sekolah')
        .upsert(payload, { onConflict: 'id' });

      if (error) throw error;

      showToast('Data sekolah berhasil disimpan', 'success');
      fetchData(); // Refresh to ensure ID and everything is synced
    } catch (error: any) {
      showToast('Gagal menyimpan data: ' + error.message, 'error');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto">
      <h2 className="text-3xl font-bold text-white mb-2">Pengaturan Sekolah</h2>
      <p className="text-gray-400 mb-8">Kelola identitas instansi, kontak, dan logo sekolah yang akan tampil di aplikasi.</p>

      <div className="bg-gray-800 rounded-lg shadow-lg border border-gray-700 p-8">
        <form onSubmit={handleSubmit} className="space-y-6">

          {/* Logo Section */}
          <div className="flex flex-col md:flex-row gap-8 items-start mb-8 border-b border-gray-700 pb-8">
            <div className="w-full md:w-1/3 flex flex-col items-center">
                <label className="block text-sm font-medium text-gray-300 mb-3">Logo Sekolah</label>
                <div className="relative w-40 h-40 bg-gray-700 border-2 border-dashed border-gray-500 rounded-lg flex items-center justify-center overflow-hidden mb-4 group hover:border-primary transition-colors">
                    {formData.logo_url ? (
                        <img src={formData.logo_url} alt="Logo Sekolah" className="w-full h-full object-contain p-2" />
                    ) : (
                        <div className="text-center p-4">
                             <span className="text-4xl block mb-2">🏫</span>
                             <span className="text-xs text-gray-400">Belum ada logo</span>
                        </div>
                    )}
                    {/* Overlay Upload Trigger */}
                    <div 
                        className="absolute inset-0 bg-black/60 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer"
                        onClick={() => fileInputRef.current?.click()}
                    >
                         <span className="text-white text-sm font-medium">Ubah Logo</span>
                    </div>
                </div>

                <input 
                    type="file" 
                    ref={fileInputRef}
                    accept="image/*"
                    onChange={handleLogoUpload}
                    className="hidden"
                />

                <button
                    type="button"
                    disabled={uploading}
                    onClick={() => fileInputRef.current?.click()}
                    className="text-sm bg-gray-700 hover:bg-gray-600 text-white py-2 px-4 rounded border border-gray-600 transition"
                >
                    {uploading ? 'Mengunggah...' : 'Pilih File Gambar'}
                </button>
                <p className="text-xs text-gray-500 mt-2 text-center">Format: PNG, JPG (Maks. 2MB)</p>
            </div>

            <div className="w-full md:w-2/3 space-y-4">
                 {/* Identitas Utama */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-300 mb-1">Nama Sekolah <span className="text-red-500">*</span></label>
                        <input
                            type="text"
                            name="nama_sekolah"
                            required
                            value={formData.nama_sekolah || ''}
                            onChange={handleInputChange}
                            placeholder="Contoh: SMKN 9 BULUKUMBA"
                            className="w-full bg-gray-700 border border-gray-600 rounded p-2.5 text-white focus:ring-primary focus:border-primary"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-300 mb-1">NPSN</label>
                        <input
                            type="text"
                            name="npsn"
                            value={formData.npsn || ''}
                            onChange={handleInputChange}
                            placeholder="Nomor Pokok Sekolah Nasional"
                            className="w-full bg-gray-700 border border-gray-600 rounded p-2.5 text-white focus:ring-primary focus:border-primary"
                        />
                    </div>
                </div>

                {/* Kontak */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-300 mb-1">Email Sekolah</label>
                        <input
                            type="email"
                            name="email"
                            value={formData.email || ''}
                            onChange={handleInputChange}
                            placeholder="admin@sekolah.sch.id"
                            className="w-full bg-gray-700 border border-gray-600 rounded p-2.5 text-white focus:ring-primary focus:border-primary"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-300 mb-1">Nomor Telepon</label>
                        <input
                            type="text"
                            name="no_telp"
                            value={formData.no_telp || ''}
                            onChange={handleInputChange}
                            placeholder="021-xxxxxxx"
                            className="w-full bg-gray-700 border border-gray-600 rounded p-2.5 text-white focus:ring-primary focus:border-primary"
                        />
                    </div>
                </div>

                {/* Alamat */}
                <div>
                    <label className="block text-sm font-medium text-gray-300 mb-1">Alamat Lengkap</label>
                    <textarea
                        name="alamat"
                        rows={3}
                        value={formData.alamat || ''}
                        onChange={handleInputChange}
                        placeholder="Jalan, Kelurahan, Kecamatan, Kota/Kabupaten..."
                        className="w-full bg-gray-700 border border-gray-600 rounded p-2.5 text-white focus:ring-primary focus:border-primary"
                    />
                </div>
            </div>
          </div>

          <div className="flex justify-end pt-2">
            <button
                type="submit"
                disabled={loading || uploading}
                className="bg-green-600 hover:bg-green-700 text-white font-semibold py-3 px-8 rounded-lg shadow-lg flex items-center gap-2 transition disabled:opacity-50 disabled:cursor-not-allowed"
            >
                {loading ? (
                    <>
                        <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                        Menyimpan...
                    </>
                ) : (
                    <>
                        <span>💾</span> Simpan Perubahan
                    </>
                )}
            </button>
          </div>

        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Login } from './components/Login';
// Admin Components
import { AdminDashboard } from './components/AdminDashboard';
import { CrudGuru } from './components/CrudGuru';
import { CrudSiswa } from './components/CrudSiswa';
import { CrudKelas } from './components/CrudKelas';
import { CrudMapel } from './components/CrudMapel';
import { CrudAnggotaGurwal } from './components/CrudAnggotaGurwal';
import { CrudDataPengajar } from './components/CrudDataPengajar';
import { CrudSekolah } from './components/CrudSekolah';

// Unified Guru Components
import { GuruDashboard } from './components/GuruDashboard';
// Binaan
import { DaftarBinaan } from './components/GuruBinaan/DaftarBinaan';
import { KehadiranBinaan } from './components/GuruBinaan/KehadiranBinaan';
import { PelanggaranBinaan } from './components/GuruBinaan/PelanggaranBinaan';
import { PrestasiBinaan } from './components/GuruBinaan/PrestasiBinaan';
import { LaporanBinaan } from './components/GuruBinaan/LaporanBinaan';
// Pengajar
import { DaftarKelasAjar } from './components/GuruPengajar/DaftarKelasAjar';
import { InputNilai } from './components/GuruPengajar/InputNilai';
import { RekapNilai } from './components/GuruPengajar/RekapNilai';

import { Toast } from './components/Toast';
import { Guru, ViewState } from './types';

interface ToastState {
  message: string;
  type: 'success' | 'error';
  duration?: number;
  position?: 'top-right' | 'center';
}

function App() {
  const [session, setSession] = useState<Guru | null>(null);
  const [currentView, setCurrentView] = useState<ViewState>('DASHBOARD');
  const [toast, setToast] = useState<ToastState | null>(null);

  useEffect(() => {
    // Check localStorage for persisted session
    const storedUser = localStorage.getItem('gurwal_admin_user');
    const storedView = localStorage.getItem('gurwal_current_view') as ViewState;

    if (storedUser) {
      try {
        const user = JSON.parse(storedUser);
        setSession(user);

        if (storedView) {
          setCurrentView(storedView);
        } else {
          // Default views
          if (user.peran === 'ADMIN') setCurrentView('DASHBOARD');
          else setCurrentView('GURU_DASHBOARD');
        }
      } catch (e) {
        localStorage.removeItem('gurwal_admin_user');
        localStorage.removeItem('gurwal_current_view');
      }
    }
  }, []);

  const handleLoginSuccess = (user: Guru) => {
    setSession(user);
    localStorage.setItem('gurwal_admin_user', JSON.stringify(user));

    let defaultView: ViewState = 'DASHBOARD';
    if (user.peran !== 'ADMIN') defaultView = 'GURU_DASHBOARD';

    setCurrentView(defaultView);
    localStorage.setItem('gurwal_current_view', defaultView);
  };

  const handleLogout = () => {
    setSession(null);
    localStorage.removeItem('gurwal_admin_user');
    localStorage.removeItem('gurwal_current_view');
    showToast('Anda telah keluar', 'success');
  };

  const handleChangeView = (view: ViewState) => {
    setCurrentView(view);
    localStorage.setItem('gurwal_current_view', view);
  };

  const showToast = (
    message: string, 
    type: 'success' | 'error', 
    duration: number = 3000, 
    position: 'top-right' | 'center' = 'top-right'
  ) => {
    setToast({ message, type, duration, position });
  };

  // Render Logic
  if (!session) {
    return (
      <>
        <Login onLoginSuccess={handleLoginSuccess} showToast={showToast} />
        {toast && (
          <Toast
            message={toast.message}
            type={toast.type}
            duration={toast.duration}
            position={toast.position}
            onClose={() => setToast(null)}
          />
        )}
      </>
    );
  }

  const renderContent = () => {
    switch (currentView) {
      // ADMIN
      case 'GURU': return <CrudGuru showToast={showToast} />;
      case 'SISWA': return <CrudSiswa showToast={showToast} />;
      case 'KELAS': return <CrudKelas showToast={showToast} />;
      case 'MAPEL': return <CrudMapel showToast={showToast} />;
      case 'ANGGOTA_GURWAL': return <CrudAnggotaGurwal showToast={showToast} />;
      case 'DATA_PENGAJAR': return <CrudDataPengajar showToast={showToast} />;
      case 'PENGATURAN_SEKOLAH': return <CrudSekolah showToast={showToast} />;
      case 'DASHBOARD': return <AdminDashboard />;

      // UNIFIED GURU
      case 'GURU_DASHBOARD': return <GuruDashboard currentUser={session} />;

      // BINAAN (WALI)
      case 'GURU_BINAAN_LIST': return <DaftarBinaan currentUser={session} showToast={showToast} />;
      case 'GURU_BINAAN_KEHADIRAN': return <KehadiranBinaan currentUser={session} showToast={showToast} />;
      case 'GURU_BINAAN_PELANGGARAN': return <PelanggaranBinaan currentUser={session} showToast={showToast} />;
      case 'GURU_BINAAN_PRESTASI': return <PrestasiBinaan currentUser={session} showToast={showToast} />;
      case 'GURU_BINAAN_LAPORAN': return <LaporanBinaan currentUser={session} />;

      // PENGAJAR
      case 'GURU_PENGAJAR_JADWAL': return <DaftarKelasAjar currentUser={session} />;
      case 'GURU_PENGAJAR_NILAI': return <InputNilai currentUser={session} showToast={showToast} />;
      case 'GURU_PENGAJAR_REKAP': return <RekapNilai currentUser={session} />;

      default:
        return <div className="p-6 text-white">Halaman tidak ditemukan</div>;
    }
  };

  return (
    <Layout
      currentUser={session}
      currentView={currentView}
      onChangeView={handleChangeView}
      onLogout={handleLogout}
    >
      {renderContent()}
      {toast && (
        <Toast
          message={toast.message}
          type={toast.type}
          duration={toast.duration}
          position={toast.position}
          onClose={() => setToast(null)}
        />
      )}
    </Layout>
  );
}

export default App;

import { createClient } from '@supabase/supabase-js';

