import React, { useEffect, useState, useRef } from 'react';
import { supabase } from '../supabaseClient';
import { Sekolah } from '../types';

interface CrudSekolahProps {
  showToast: (msg: string, type: 'success' | 'error', duration?: number, position?: 'top-right' | 'center') => void;
}

export const CrudSekolah: React.FC<CrudSekolahProps> = ({ showToast }) => {
  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Sekolah>>({
    nama_sekolah: '',
    npsn: '',
    alamat: '',
    email: '',
    no_telp: '',
    logo_url: ''
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      // Menggunakan limit(1) alih-alih single() untuk menghindari error PGRST116 jika kosong
      const { data, error } = await supabase
        .from('sekolah')
        .select('*')
        .limit(1);

      if (error) throw error;

      if (data && data.length > 0) {
        setFormData(data[0]);
      }
    } catch (error: any) {
      console.error('Error fetching data sekolah:', error);
      // showToast('Gagal memuat data sekolah', 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleLogoUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    try {
      setUploading(true);
      const file = event.target.files?.[0];
      if (!file) return;

      const fileExt = file.name.split('.').pop();
      const fileName = `logo-${Date.now()}.${fileExt}`;
      const filePath = `${fileName}`;

      // Upload ke bucket 'logo-sekolah'
      const { error: uploadError } = await supabase.storage
        .from('logo-sekolah')
        .upload(filePath, file);

      if (uploadError) throw uploadError;

      // Dapatkan Public URL
      const { data } = supabase.storage
        .from('logo-sekolah')
        .getPublicUrl(filePath);

      if (data) {
         setFormData(prev => ({ ...prev, logo_url: data.publicUrl }));
         showToast('Logo berhasil diunggah. Klik Simpan untuk menerapkan.', 'success');
      }

    } catch (error: any) {
      showToast('Gagal mengunggah logo: ' + error.message, 'error');
    } finally {
      setUploading(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const payload = {
        ...formData,
        // Pastikan ID selalu 1 untuk single row logic
        id: formData.id || 1, 
      };

      const { error } = await supabase
        .from('sekolah')
        .upsert(payload, { onConflict: 'id' });

      if (error) throw error;

      showToast('Data sekolah berhasil disimpan', 'success');
      fetchData(); 
    } catch (error: any) {
      showToast('Gagal menyimpan data: ' + error.message, 'error');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto">
      <h2 className="text-3xl font-bold text-white mb-2">Pengaturan Sekolah</h2>
      <p className="text-gray-400 mb-8">Kelola identitas instansi, kontak, dan logo sekolah yang akan tampil di aplikasi.</p>

      <div className="bg-gray-800 rounded-lg shadow-lg border border-gray-700 p-8">
        <form onSubmit={handleSubmit} className="space-y-6">

          {/* Logo Section */}
          <div className="flex flex-col md:flex-row gap-8 items-start mb-8 border-b border-gray-700 pb-8">
            <div className="w-full md:w-1/3 flex flex-col items-center">
                <label className="block text-sm font-medium text-gray-300 mb-3">Logo Sekolah</label>
                <div className="relative w-40 h-40 bg-gray-700 border-2 border-dashed border-gray-500 rounded-lg flex items-center justify-center overflow-hidden mb-4 group hover:border-primary transition-colors">
                    {formData.logo_url ? (
                        <img src={formData.logo_url} alt="Logo Sekolah" className="w-full h-full object-contain p-2" />
                    ) : (
                        <div className="text-center p-4">
                             <span className="text-4xl block mb-2">🏫</span>
                             <span className="text-xs text-gray-400">Belum ada logo</span>
                        </div>
                    )}
                    {/* Overlay Upload Trigger */}
                    <div 
                        className="absolute inset-0 bg-black/60 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer"
                        onClick={() => fileInputRef.current?.click()}
                    >
                         <span className="text-white text-sm font-medium">Ubah Logo</span>
                    </div>
                </div>

                <input 
                    type="file" 
                    ref={fileInputRef}
                    accept="image/*"
                    onChange={handleLogoUpload}
                    className="hidden"
                />

                <button
                    type="button"
                    disabled={uploading}
                    onClick={() => fileInputRef.current?.click()}
                    className="text-sm bg-gray-700 hover:bg-gray-600 text-white py-2 px-4 rounded border border-gray-600 transition"
                >
                    {uploading ? 'Mengunggah...' : 'Pilih File Gambar'}
                </button>
                <p className="text-xs text-gray-500 mt-2 text-center">Format: PNG, JPG (Maks. 2MB)</p>
            </div>

            <div className="w-full md:w-2/3 space-y-4">
                 {/* Identitas Utama */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-300 mb-1">Nama Sekolah <span className="text-red-500">*</span></label>
                        <input
                            type="text"
                            name="nama_sekolah"
                            required
                            value={formData.nama_sekolah || ''}
                            onChange={handleInputChange}
                            placeholder="Contoh: SMKN 9 BULUKUMBA"
                            className="w-full bg-gray-700 border border-gray-600 rounded p-2.5 text-white focus:ring-primary focus:border-primary"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-300 mb-1">NPSN</label>
                        <input
                            type="text"
                            name="npsn"
                            value={formData.npsn || ''}
                            onChange={handleInputChange}
                            placeholder="Nomor Pokok Sekolah Nasional"
                            className="w-full bg-gray-700 border border-gray-600 rounded p-2.5 text-white focus:ring-primary focus:border-primary"
                        />
                    </div>
                </div>

                {/* Kontak */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-300 mb-1">Email Sekolah</label>
                        <input
                            type="email"
                            name="email"
                            value={formData.email || ''}
                            onChange={handleInputChange}
                            placeholder="admin@sekolah.sch.id"
                            className="w-full bg-gray-700 border border-gray-600 rounded p-2.5 text-white focus:ring-primary focus:border-primary"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-300 mb-1">Nomor Telepon</label>
                        <input
                            type="text"
                            name="no_telp"
                            value={formData.no_telp || ''}
                            onChange={handleInputChange}
                            placeholder="021-xxxxxxx"
                            className="w-full bg-gray-700 border border-gray-600 rounded p-2.5 text-white focus:ring-primary focus:border-primary"
                        />
                    </div>
                </div>

                {/* Alamat */}
                <div>
                    <label className="block text-sm font-medium text-gray-300 mb-1">Alamat Lengkap</label>
                    <textarea
                        name="alamat"
                        rows={3}
                        value={formData.alamat || ''}
                        onChange={handleInputChange}
                        placeholder="Jalan, Kelurahan, Kecamatan, Kota/Kabupaten..."
                        className="w-full bg-gray-700 border border-gray-600 rounded p-2.5 text-white focus:ring-primary focus:border-primary"
                    />
                </div>
            </div>
          </div>

          <div className="flex justify-end pt-2">
            <button
                type="submit"
                disabled={loading || uploading}
                className="bg-green-600 hover:bg-green-700 text-white font-semibold py-3 px-8 rounded-lg shadow-lg flex items-center gap-2 transition disabled:opacity-50 disabled:cursor-not-allowed"
            >
                {loading ? (
                    <>
                        <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                        Menyimpan...
                    </>
                ) : (
                    <>
                        <span>💾</span> Simpan Perubahan
                    </>
                )}
            </button>
          </div>

        </form>
      </div>
    </div>
  );
};

