import React, { useEffect, useState, useRef } from 'react';
import { supabase, supabaseUrl } from '../supabaseClient';
import { Sekolah } from '../types';

interface CrudSekolahProps {
  showToast: (msg: string, type: 'success' | 'error', duration?: number, position?: 'top-right' | 'center') => void;
}

export const CrudSekolah: React.FC<CrudSekolahProps> = ({ showToast }) => {
  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Sekolah>>({
    nama_sekolah: '',
    npsn: '',
    alamat: '',
    email: '',
    no_telp: '',
    logo_url: ''
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('sekolah')
        .select('*')
        .limit(1);

      if (error) throw error;

      if (data && data.length > 0) {
        setFormData(data[0]);
      }
    } catch (error: any) {
      console.error('Error fetching data sekolah:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    try {
      setUploading(true);
      const fileExt = file.name.split('.').pop();
      const filePath = `logo-${Date.now()}.${fileExt}`;

      // Upload ke bucket 'logo-sekolah'
      const { error: uploadError } = await supabase.storage
        .from('logo-sekolah')
        .upload(filePath, file);

      if (uploadError) throw uploadError;

      // Construct Public URL Manual
      const logoUrl = `${supabaseUrl}/storage/v1/object/public/logo-sekolah/${filePath}`;

      // Update state for preview
      setFormData(prev => ({ ...prev, logo_url: logoUrl }));

      // Upsert immediately to DB
      const payload: any = { logo_url: logoUrl };
      // Ensure we target the correct row (ID 1 default)
      if (formData.id) payload.id = formData.id;
      else payload.id = 1;

      // Merge with current data to avoid overwriting other fields with null if they exist
      const fullPayload = { ...formData, ...payload };
      if (!fullPayload.nama_sekolah) fullPayload.nama_sekolah = 'Sekolah Baru'; // Fallback

      const { error: dbError } = await supabase
        .from('sekolah')
        .upsert(fullPayload, { onConflict: 'id' });

      if (dbError) throw dbError;

      showToast('Logo berhasil diperbarui!', 'success');

    } catch (error: any) {
      console.error('Upload error:', error);
      showToast('Gagal mengunggah logo: ' + error.message, 'error');
    } finally {
      setUploading(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const payload = {
        ...formData,
        id: formData.id || 1, 
      };

      const { error } = await supabase
        .from('sekolah')
        .upsert(payload, { onConflict: 'id' });

      if (error) throw error;

      showToast('Data sekolah berhasil disimpan', 'success');
      fetchData(); 
    } catch (error: any) {
      showToast('Gagal menyimpan data: ' + error.message, 'error');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto">
      <h2 className="text-3xl font-bold text-white mb-2">Pengaturan Sekolah</h2>
      <p className="text-gray-400 mb-8">Kelola identitas instansi, kontak, dan logo sekolah yang akan tampil di aplikasi.</p>

      <div className="bg-gray-800 rounded-lg shadow-lg border border-gray-700 p-8">
        <form onSubmit={handleSubmit} className="space-y-6">

          {/* Logo Section */}
          <div className="flex flex-col md:flex-row gap-8 items-start mb-8 border-b border-gray-700 pb-8">
            <div className="w-full md:w-1/3 flex flex-col items-center">
                <label className="block text-sm font-medium text-gray-300 mb-3">Logo Sekolah</label>
                <div className="relative w-40 h-40 bg-gray-700 border-2 border-dashed border-gray-500 rounded-lg flex items-center justify-center overflow-hidden mb-4 group hover:border-primary transition-colors">
                    {formData.logo_url ? (
                        <img src={formData.logo_url} alt="Logo Sekolah" className="w-full h-full object-contain p-2" />
                    ) : (
                        <div className="text-center p-4">
                             <span className="text-4xl block mb-2">🏫</span>
                             <span className="text-xs text-gray-400">Belum ada logo</span>
                        </div>
                    )}
                    {/* Overlay Upload Trigger */}
                    <div 
                        className="absolute inset-0 bg-black/60 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer"
                        onClick={() => fileInputRef.current?.click()}
                    >
                         <span className="text-white text-sm font-medium">Ubah Logo</span>
                    </div>
                </div>

                <input 
                    type="file" 
                    ref={fileInputRef}
                    accept="image/*"
                    onChange={handleUpload}
                    className="hidden"
                />

                <button
                    type="button"
                    disabled={uploading}
                    onClick={() => fileInputRef.current?.click()}
                    className="text-sm bg-gray-700 hover:bg-gray-600 text-white py-2 px-4 rounded border border-gray-600 transition"
                >
                    {uploading ? 'Mengunggah...' : 'Pilih File Gambar'}
                </button>
                <p className="text-xs text-gray-500 mt-2 text-center">Format: PNG, JPG (Maks. 2MB)</p>
            </div>

            <div className="w-full md:w-2/3 space-y-4">
                 {/* Identitas Utama */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-300 mb-1">Nama Sekolah <span className="text-red-500">*</span></label>
                        <input
                            type="text"
