import { useState, useEffect } from 'react';
import { supabase } from '../supabaseClient';

export default function CrudSekolah() {
  const [sekolah, setSekolah] = useState({
    nama: '',
    npsn: '',
    alamat: '',
    email: '',
    telp: '',
    logo_url: ''
  });
  const [preview, setPreview] = useState('');

  // Ambil data sekolah saat load halaman
  useEffect(() => {
    fetchSekolah();
  }, []);

  async function fetchSekolah() {
    const { data, error } = await supabase
      .from('sekolah')
      .select('*')
      .limit(1)
      .single();

    if (error) console.error('Gagal ambil data sekolah:', error.message);
    else setSekolah(data || {});
  }

  async function handleUpload(e) {
    const file = e.target.files?.[0];
    if (!file) return alert('Pilih file logo terlebih dahulu.');

    // tampilkan preview lokal
    setPreview(URL.createObjectURL(file));

    // upload ke bucket logo-sekolah
    const fileExt = file.name.split('.').pop();
    const filePath = `logo-${Date.now()}.${fileExt}`;

    const { data, error } = await supabase.storage
      .from('logo-sekolah')
      .upload(filePath, file);

    if (error) {
      console.error('Upload gagal:', error.message);
      alert('Gagal upload logo.');
      return;
    }

    const logoUrl = `${supabase.storageUrl}/object/public/logo-sekolah/${filePath}`;

    // update ke tabel sekolah
    const { error: dbError } = await supabase
      .from('sekolah')
      .upsert([{ id: sekolah.id || '00000000-0000-0000-0000-000000000001', logo_url: logoUrl }]);

    if (dbError) {
      console.error('Gagal update logo sekolah:', dbError.message);
    } else {
      alert('Logo sekolah berhasil diperbarui!');
      setSekolah((prev) => ({ ...prev, logo_url: logoUrl }));
    }
  }

  return (
    <div className="p-4 max-w-xl mx-auto">
      <h2 className="text-xl font-semibold mb-4">Pengaturan Sekolah</h2>

