        {preview ? (
          <img src={preview} alt="Preview Logo" className="w-32 h-32 object-contain border rounded mb-2" />
        ) : sekolah.logo_url ? (
          <img src={sekolah.logo_url} alt="Logo Sekolah" className="w-32 h-32 object-contain border rounded mb-2" />
        ) : (
