import { useState, useEffect } from "react";
import { supabase } from "../supabaseClient";
import Toast from "./Toast";

export default function CrudSekolah() {
  const [sekolah, setSekolah] = useState({
    id: "",
    nama: "",
    npsn: "",
    alamat: "",
    email: "",
    no_telp: "",
    logo_url: "",
  });

  const [loading, setLoading] = useState(false);
  const [toast, setToast] = useState({ message: "", type: "" });

  // ✅ Ambil data sekolah saat halaman dibuka
  useEffect(() => {
    async function fetchSekolah() {
      const { data, error } = await supabase
        .from("sekolah")
        .select("*")
        .limit(1)
        .maybeSingle();

      if (error) {
        console.error("Gagal mengambil data sekolah:", error.message);
      } else if (data) {
        setSekolah(data);
      }
    }
    fetchSekolah();
  }, []);

  // ✅ Simpan / update data sekolah
  async function handleSave() {
    setLoading(true);

    const dataToSave = {
      id: sekolah.id || "00000000-0000-0000-0000-000000000001", // agar hanya 1 record
      nama: sekolah.nama || "",
      npsn: sekolah.npsn || "",
      alamat: sekolah.alamat || "",
      email: sekolah.email || "",
      no_telp: sekolah.no_telp || "",
      logo_url: sekolah.logo_url || "",
    };

    const { error } = await supabase
      .from("sekolah")
      .upsert([dataToSave], { onConflict: "id" });

    setLoading(false);

    if (error) {
      console.error("Gagal menyimpan data sekolah:", error);
      setToast({ message: "❌ Gagal menyimpan data sekolah!", type: "error" });
    } else {
      setToast({ message: "✅ Data sekolah berhasil disimpan!", type: "success" });
    }
  }

  function handleChange(e) {
    const { name, value } = e.target;
    setSekolah((prev) => ({ ...prev, [name]: value }));
  }

  return (
    <div className="p-4">
      <h2 className="text-2xl font-semibold mb-4">🏫 Pengaturan Identitas Sekolah</h2>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div>
          <label className="block font-medium">Nama Sekolah</label>
          <input
            type="text"
            name="nama"
            value={sekolah.nama}
            onChange={handleChange}
            className="w-full border rounded p-2"
          />
        </div>

        <div>
          <label className="block font-medium">NPSN</label>
          <input
            type="text"
            name="npsn"
            value={sekolah.npsn}
            onChange={handleChange}
            className="w-full border rounded p-2"
          />
        </div>

        <div>
          <label className="block font-medium">Alamat</label>
          <textarea
            name="alamat"
            value={sekolah.alamat}
            onChange={handleChange}
            className="w-full border rounded p-2"
          />
        </div>

        <div>
          <label className="block font-medium">Email</label>
          <input
            type="email"
            name="email"
            value={sekolah.email}
            onChange={handleChange}
            className="w-full border rounded p-2"
          />
        </div>

        <div>
          <label className="block font-medium">Nomor Telepon</label>
          <input
            type="text"
            name="no_telp"
            value={sekolah.no_telp}
            onChange={handleChange}
            className="w-full border rounded p-2"
          />
        </div>

        <div>
          <label className="block font-medium">URL Logo Sekolah</label>
          <input
            type="text"
            name="logo_url"
            value={sekolah.logo_url}
            onChange={handleChange}
            className="w-full border rounded p-2"
            placeholder="https://example.com/logo.png"
          />
        </div>
      </div>

      {sekolah.logo_url && (
        <div className="mt-4">
          <p className="font-medium mb-1">Pratinjau Logo:</p>
          <img
            src={sekolah.logo_url}
            alt="Logo Sekolah"
            className="w-32 h-32 object-contain border rounded"
          />
        </div>
      )}

      <button
        onClick={handleSave}
        disabled={loading}
        className="mt-6 bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
      >
        {loading ? "Menyimpan..." : "Simpan Data"}
      </button>

      {toast.message && (
        <Toast message={toast.message} type={toast.type} onClose={() => setToast({ message: "", type: "" })} />
      )}
    </div>
  );
}

