// src/hooks/useSekolah.ts
import { useEffect, useState } from "react";
import { supabase } from "../supabaseClient";

export function useSekolah() {
  const [sekolah, setSekolah] = useState<{ nama?: string; logo_url?: string }>({});

  useEffect(() => {
    async function fetchSekolah() {
      const { data, error } = await supabase
        .from("sekolah")
        .select("nama, logo_url")
        .limit(1)
        .maybeSingle();

      if (!error && data) setSekolah(data);
    }
    fetchSekolah();
  }, []);

  return sekolah;
}

