    try {
      // Corrected Join Syntax: Use table names for relations
      const { data: pengajaran, error } = await supabase
        .from('pengajaran')
        .select(`
          *,
          guru (nama, nip),
          mapel (nama, kode),
          kelas (nama)
        `)
        .order('id', { ascending: false });

