export const KehadiranBinaan: React.FC<Props> = ({ currentUser, showToast }) => {
  const [siswaList, setSiswaList] = useState<Bimbingan[]>([]);
  const [kehadiranList, setKehadiranList] = useState<Kehadiran[]>([]);
  const [tanggal, setTanggal] = useState(new Date().toISOString().split('T')[0]);
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);

  // State untuk menangani mode edit per baris siswa
  // Key: id_siswa, Value: boolean (sedang edit atau tidak)
  const [editingRows, setEditingRows] = useState<Record<string, boolean>>({});

  // State untuk menangani nilai input form per baris siswa
  // Key: id_siswa, Value: Object input
  const [formValues, setFormValues] = useState<Record<string, RowInput>>({});

  // Delete Confirmation
  const [deleteId, setDeleteId] = useState<string | null>(null);

  // 1. Fetch Daftar Siswa Binaan
  useEffect(() => {
    const fetchSiswa = async () => {
      const { data, error } = await supabase
        .from('bimbingan')
        .select('*, siswa(id, nama, nisn, kelas(nama))')
        .eq('id_guru', currentUser.id)
        .order('created_at', { ascending: true });

      if (!error && data) {
         // @ts-ignore
         setSiswaList(data);
         // Inisialisasi form values default untuk setiap siswa
         const initialForms: Record<string, RowInput> = {};
         data.forEach((item: any) => {
             initialForms[item.id_siswa] = { status: 'HADIR', catatan: '' };
         });
         setFormValues(initialForms);
      }
    };
    fetchSiswa();
  }, [currentUser.id]);

  // 2. Fetch Data Kehadiran Berdasarkan Tanggal
  const fetchKehadiran = async () => {
    setLoading(true);
    const { data, error } = await supabase
      .from('kehadiran')
      .select('*')
      .eq('id_guru', currentUser.id)
      .eq('tanggal', tanggal);

    if (!error && data) {
      setKehadiranList(data as Kehadiran[]);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchKehadiran();
    // Reset editing rows saat tanggal berubah
    setEditingRows({});
     // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tanggal, currentUser.id]);


  // --- HANDLERS ---

  // Mengubah nilai input form lokal
  const handleInputChange = (id_siswa: string, field: keyof RowInput, value: string) => {
    setFormValues(prev => ({
        ...prev,
        [id_siswa]: {
            ...prev[id_siswa],
            [field]: value
        }
    }));
  };

  // Simpan Baru (INSERT)
  const handleSave = async (id_siswa: string) => {
    const input = formValues[id_siswa];
    setProcessingId(id_siswa);

    try {
        const { error } = await supabase.from('kehadiran').insert([{
            id_guru: currentUser.id,
            id_siswa: id_siswa,
            tanggal: tanggal,
            status: input.status,
            catatan: input.catatan
        }]);

        if (error) throw error;
        showToast('✅ Kehadiran berhasil disimpan', 'success');
        await fetchKehadiran();
    } catch (e) {
        showToast('❌ Gagal menyimpan kehadiran', 'error');
    } finally {
        setProcessingId(null);
    }
  };

  // Masuk Mode Edit
  const handleEditClick = (attendance: Kehadiran) => {
    // Set form value sesuai data yang ada di database agar siap diedit
    setFormValues(prev => ({
        ...prev,
        [attendance.id_siswa]: {
            status: attendance.status,
            catatan: attendance.catatan || ''
        }
    }));
    // Aktifkan mode edit untuk siswa ini
    setEditingRows(prev => ({ ...prev, [attendance.id_siswa]: true }));
  };

  // Batal Edit
  const handleCancelEdit = (id_siswa: string) => {
    setEditingRows(prev => ({ ...prev, [id_siswa]: false }));
  };

  // Simpan Perubahan (UPDATE)
  const handleUpdate = async (attendanceId: string, id_siswa: string) => {
    const input = formValues[id_siswa];
    setProcessingId(id_siswa);

    try {
        const { error } = await supabase
            .from('kehadiran')
            .update({
                status: input.status,
                catatan: input.catatan
            })
            .eq('id', attendanceId);

        if (error) throw error;

        showToast('✅ Kehadiran berhasil diperbarui', 'success');
        setEditingRows(prev => ({ ...prev, [id_siswa]: false }));
        await fetchKehadiran();
    } catch (e) {
        showToast('❌ Gagal memperbarui data', 'error');
    } finally {
        setProcessingId(null);
    }
  };

  // Hapus (DELETE)
  const confirmDelete = async () => {
    if (!deleteId) return;
    try {
        const { error } = await supabase.from('kehadiran').delete().eq('id', deleteId);
        if (error) throw error;
        showToast('✅ Data kehadiran dihapus', 'success');
        await fetchKehadiran();
    } catch (e) {
        showToast('❌ Gagal menghapus data', 'error');
    } finally {
        setDeleteId(null);
    }
  };


  // --- RENDER HELPERS ---

  const getStatusBadge = (status: string) => {
    switch (status) {
        case 'HADIR': return <span className="px-2 py-1 rounded bg-green-900 text-green-200 text-xs font-bold border border-green-700">HADIR</span>;
        case 'SAKIT': return <span className="px-2 py-1 rounded bg-yellow-900 text-yellow-200 text-xs font-bold border border-yellow-700">SAKIT</span>;
        case 'IZIN': return <span className="px-2 py-1 rounded bg-blue-900 text-blue-200 text-xs font-bold border border-blue-700">IZIN</span>;
        case 'ALPHA': return <span className="px-2 py-1 rounded bg-red-900 text-red-200 text-xs font-bold border border-red-700">ALPHA</span>;
        default: return null;
    }
  };

  return (
    <div>
      <ConfirmDialog 
        isOpen={!!deleteId} 
        message="Apakah Anda yakin ingin menghapus data kehadiran siswa ini?" 
        onConfirm={confirmDelete} 
        onCancel={() => setDeleteId(null)} 
      />

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-white">Input Kehadiran Binaan</h2>
      </div>

      {/* Date Picker */}
      <div className="mb-6 bg-gray-800 p-4 rounded-lg border border-gray-700 flex flex-col md:flex-row md:items-center gap-4 shadow-lg">
        <div className="flex-1">
             <label className="text-gray-400 text-sm font-medium mb-1 block">Pilih Tanggal Absensi:</label>
             <input 
                type="date" 
                value={tanggal}
                onChange={(e) => setTanggal(e.target.value)}
                className="bg-gray-700 border border-gray-600 text-white rounded px-4 py-2 focus:outline-none focus:border-primary w-full md:w-auto"
             />
        </div>
        <div className="text-sm text-gray-400 italic">
            {loading ? 'Sedang memuat data...' : `Menampilkan data untuk tanggal: ${tanggal}`}
        </div>
      </div>

      <div className="bg-gray-800 shadow overflow-hidden rounded-lg border border-gray-700">
        <div className="overflow-x-auto">
        <table className="min-w-full divide-y divide-gray-700">
          <thead className="bg-gray-700">
            <tr>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase w-1/4">Siswa</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase w-1/6">Status</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase w-1/3">Catatan</th>
              <th className="px-6 py-3 text-right text-xs font-medium text-gray-300 uppercase w-1/4">Aksi</th>
            </tr>
          </thead>
          <tbody className="bg-gray-800 divide-y divide-gray-700">
            {siswaList.map((item) => {
               // Cari data kehadiran yang sudah tersimpan untuk siswa ini
               const existingData = kehadiranList.find(k => k.id_siswa === item.id_siswa);
               const isEditing = editingRows[item.id_siswa];
               const isProcessing = processingId === item.id_siswa;
               const form = formValues[item.id_siswa] || { status: 'HADIR', catatan: '' };

               return (
                <tr key={item.id} className="hover:bg-gray-750 transition-colors">
                  {/* KOLOM NAMA */}
                  <td className="px-6 py-4 whitespace-nowrap">
                      <div className="text-sm font-bold text-white">{item.siswa?.nama}</div>
                      {/* @ts-ignore */}
                      <div className="text-xs text-gray-400">{item.siswa?.kelas?.nama || '-'}</div>
                  </td>

                  {/* KOLOM STATUS & CATATAN (Tergantung Mode) */}

                  {existingData && !isEditing ? (
                      // MODE BACA (READ ONLY)
                      <>
                        <td className="px-6 py-4 whitespace-nowrap">
                            {getStatusBadge(existingData.status)}
                        </td>
                        <td className="px-6 py-4">
                            <span className="text-sm text-gray-300 italic">
                                {existingData.catatan ? `"${existingData.catatan}"` : '-'}
                            </span>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                            <div className="flex justify-end gap-2">
                                <button 
                                    onClick={() => handleEditClick(existingData)}
                                    className="bg-yellow-600 hover:bg-yellow-700 text-white px-3 py-1 rounded text-xs transition"
                                >
                                    ✏️ Edit
                                </button>
                                <button 
                                    onClick={() => setDeleteId(existingData.id)}
                                    className="bg-red-600 hover:bg-red-700 text-white px-3 py-1 rounded text-xs transition"
                                >
                                    🗑️ Hapus
                                </button>
                            </div>
                        </td>
                      </>
                  ) : (
                      // MODE INPUT / EDIT
                      <>
                        <td className="px-6 py-4 whitespace-nowrap">
                            <select
                                value={form.status}
                                onChange={(e) => handleInputChange(item.id_siswa, 'status', e.target.value)}
                                disabled={isProcessing}
                                className={`bg-gray-700 border border-gray-600 text-white text-sm rounded px-2 py-1 w-full focus:ring-primary focus:border-primary ${
                                    form.status === 'HADIR' ? 'text-green-400' : 
                                    form.status === 'SAKIT' ? 'text-yellow-400' :
                                    form.status === 'IZIN' ? 'text-blue-400' : 'text-red-400'
                                }`}
                            >
                                <option value="HADIR">HADIR</option>
                                <option value="SAKIT">SAKIT</option>
                                <option value="IZIN">IZIN</option>
                                <option value="ALPHA">ALPHA</option>
                            </select>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                            <input
                                type="text"
                                value={form.catatan}
                                onChange={(e) => handleInputChange(item.id_siswa, 'catatan', e.target.value)}
                                placeholder="Keterangan (opsional)..."
                                disabled={isProcessing}
                                className="bg-gray-700 border border-gray-600 text-white text-sm rounded px-3 py-1 w-full focus:ring-primary focus:border-primary placeholder-gray-500"
                            />
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                            {existingData ? (
                                // Tombol Aksi saat Edit
                                <div className="flex justify-end gap-2">
                                    <button
                                        onClick={() => handleCancelEdit(item.id_siswa)}
                                        disabled={isProcessing}
                                        className="bg-gray-600 hover:bg-gray-500 text-white px-3 py-1 rounded text-xs transition"
                                    >
                                        Batal
                                    </button>
                                    <button
                                        onClick={() => handleUpdate(existingData.id, item.id_siswa)}
                                        disabled={isProcessing}
                                        className="bg-green-600 hover:bg-green-700 text-white px-3 py-1 rounded text-xs transition flex items-center gap-1"
                                    >
                                        {isProcessing ? '...' : '💾 Update'}
                                    </button>
                                </div>
                            ) : (
                                // Tombol Aksi saat Baru
                                <button
                                    onClick={() => handleSave(item.id_siswa)}
                                    disabled={isProcessing}
                                    className="bg-primary hover:bg-secondary text-white px-4 py-1.5 rounded text-xs transition font-bold shadow-md"
                                >
                                    {isProcessing ? 'Menyimpan...' : '💾 Simpan'}
                                </button>
                            )}
                        </td>
                      </>
                  )}
                </tr>
               );
            })}
            {siswaList.length === 0 && (
               <tr><td colSpan={4} className="p-10 text-center text-gray-500 italic">Belum ada siswa binaan yang ditugaskan kepada Anda.</td></tr>
            )}
          </tbody>
        </table>
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../supabaseClient';
import { Guru, Bimbingan, Kehadiran } from '../../types';
import { ConfirmDialog } from '../ConfirmDialog';

interface Props {
  currentUser: Guru;
  showToast: (msg: string, type: 'success' | 'error') => void;
}

// Tipe untuk state lokal form
interface AttendanceFormState {
  [id_siswa: string]: {
    id?: string; // ID kehadiran jika sudah ada (untuk update)
    status: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA';
    catatan: string;
  };
}

export const KehadiranBinaan: React.FC<Props> = ({ currentUser, showToast }) => {
  const [siswaList, setSiswaList] = useState<Bimbingan[]>([]);
  const [tanggal, setTanggal] = useState(new Date().toISOString().split('T')[0]);
  const [loading, setLoading] = useState(true);
  const [processing, setProcessing] = useState(false);

  // State Form Data
  const [formData, setFormData] = useState<AttendanceFormState>({});

  // State Mode: apakah data sudah tersimpan di DB?
  const [isDataSaved, setIsDataSaved] = useState(false);
  // State Mode: apakah user sedang mengklik tombol Edit?
  const [isEditing, setIsEditing] = useState(false);

  // Delete Confirmation
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  // 1. Fetch Daftar Siswa Binaan (Sekali saja saat mount)
  useEffect(() => {
    const fetchSiswa = async () => {
      const { data, error } = await supabase
        .from('bimbingan')
        .select('*, siswa(id, nama, nisn, jenis_kelamin, kelas(nama))')
        .eq('id_guru', currentUser.id)
        .order('created_at', { ascending: true });

      if (!error && data) {
         // @ts-ignore
         setSiswaList(data);
      }
    };
    fetchSiswa();
  }, [currentUser.id]);

  // 2. Fetch Data Kehadiran ketika Tanggal atau Siswa berubah
  useEffect(() => {
    if (siswaList.length > 0) {
        fetchKehadiran();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tanggal, siswaList]);

  const fetchKehadiran = async () => {
    setLoading(true);
    setIsEditing(false); // Reset edit mode saat ganti tanggal

    try {
        const { data } = await supabase
        .from('kehadiran')
        .select('*')
        .eq('id_guru', currentUser.id)
        .eq('tanggal', tanggal);

        const currentData = data as Kehadiran[] || [];
        const newFormState: AttendanceFormState = {};
        const hasData = currentData.length > 0;

        setIsDataSaved(hasData);

        // Mapping data siswa ke form state
        siswaList.forEach(item => {
            const record = currentData.find(k => k.id_siswa === item.id_siswa);
            if (record) {
                // Jika data ada di DB
                newFormState[item.id_siswa] = {
                    id: record.id,
                    status: record.status,
                    catatan: record.catatan || ''
                };
            } else {
                // Default value jika data belum ada
                newFormState[item.id_siswa] = {
                    status: 'HADIR',
                    catatan: ''
                };
            }
        });

        setFormData(newFormState);

    } catch (error) {
        console.error(error);
    } finally {
        setLoading(false);
    }
  };

  // --- Handlers ---

  const handleRadioChange = (id_siswa: string, value: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA') => {
    setFormData(prev => ({
        ...prev,
        [id_siswa]: { ...prev[id_siswa], status: value }
    }));
  };

  const handleCatatanChange = (id_siswa: string, value: string) => {
    setFormData(prev => ({
        ...prev,
        [id_siswa]: { ...prev[id_siswa], catatan: value }
    }));
  };

  const handleSaveOrUpdate = async () => {
    setProcessing(true);
    try {
        // Siapkan payload untuk upsert
        const payload = siswaList.map(item => {
            const form = formData[item.id_siswa];
            return {
                id: form.id, // Jika ada ID, maka update. Jika undefined, maka insert (handle by DB/Supabase logic usually needs clear ID or omit it)
                // Note: Untuk upsert Supabase agar Insert baru bekerja, jangan kirim 'id' jika undefined.
                // Kita akan filter properti di bawah.
                id_guru: currentUser.id,
                id_siswa: item.id_siswa,
                tanggal: tanggal,
                status: form.status,
                catatan: form.catatan
            };
        });

        // Bersihkan payload (hapus properti id jika undefined agar jadi INSERT)
        const cleanPayload = payload.map(p => {
            if (!p.id) {
                const { id, ...rest } = p;
                return rest;
            }
            return p;
        });

        const { error } = await supabase.from('kehadiran').upsert(cleanPayload);

        if (error) throw error;

        showToast(isDataSaved ? '✅ Data berhasil diperbarui' : '✅ Data berhasil disimpan', 'success');
        await fetchKehadiran(); // Refresh data & mode

    } catch (error) {
        showToast('❌ Gagal menyimpan data', 'error');
        console.error(error);
    } finally {
        setProcessing(false);
    }
  };

  const handleDelete = async () => {
    setProcessing(true);
    try {
        const { error } = await supabase
            .from('kehadiran')
            .delete()
            .eq('id_guru', currentUser.id)
            .eq('tanggal', tanggal);

        if (error) throw error;

        showToast('✅ Data kehadiran tanggal ini dihapus', 'success');
        setShowDeleteConfirm(false);
        await fetchKehadiran(); // Reset ke mode input baru
    } catch (error) {
        showToast('❌ Gagal menghapus data', 'error');
    } finally {
        setProcessing(false);
    }
  };

  // Helper UI Radio
  const RadioOption = ({ id_siswa, val, label, colorClass }: any) => {
      const isChecked = formData[id_siswa]?.status === val;
      // Jika mode VIEW (Saved & Not Editing) -> Disabled
      const isDisabled = isDataSaved && !isEditing;

      return (
          <label className={`
            cursor-pointer flex flex-col items-center justify-center w-10 h-10 rounded-lg border-2 transition-all
            ${isChecked 
                ? `${colorClass} border-transparent text-white shadow-md transform scale-105` 
                : 'border-gray-600 text-gray-400 hover:bg-gray-700'}
            ${isDisabled ? 'opacity-60 cursor-not-allowed' : ''}
          `}>
              <input 
                type="radio" 
                name={`status-${id_siswa}`} 
                value={val}
                checked={isChecked}
                onChange={() => !isDisabled && handleRadioChange(id_siswa, val)}
                className="hidden"
                disabled={isDisabled}
              />
              <span className="font-bold text-sm">{label}</span>
          </label>
      );
  };

  return (
    <div>
      <ConfirmDialog 
        isOpen={showDeleteConfirm} 
        message={`Apakah Anda yakin ingin menghapus seluruh data kehadiran pada tanggal ${tanggal}?`} 
        onConfirm={handleDelete} 
        onCancel={() => setShowDeleteConfirm(false)} 
      />

      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-white">Input Kehadiran Binaan</h2>
      </div>

      {/* Date Picker & Summary */}
      <div className="mb-6 bg-gray-800 p-4 rounded-lg border border-gray-700 shadow-lg sticky top-0 z-20">
        <div className="flex flex-col md:flex-row justify-between items-center gap-4">
            <div className="flex items-center gap-4 w-full md:w-auto">
                <label className="text-gray-300 font-medium whitespace-nowrap">Tanggal:</label>
                <input 
                    type="date" 
                    value={tanggal}
                    onChange={(e) => setTanggal(e.target.value)}
                    className="bg-gray-700 border border-gray-600 text-white rounded px-4 py-2 focus:outline-none focus:border-primary w-full md:w-auto"
                />
            </div>

            <div className="flex gap-2">
                {isDataSaved && !isEditing ? (
                    // MODE VIEW: Tombol Edit & Hapus
                    <>
                        <button 
                            onClick={() => setIsEditing(true)}
                            className="bg-yellow-600 hover:bg-yellow-700 text-white px-5 py-2 rounded font-medium transition shadow-lg flex items-center gap-2"
                        >
                            ✏️ Edit Data
                        </button>
                        <button 
                            onClick={() => setShowDeleteConfirm(true)}
                            className="bg-red-600 hover:bg-red-700 text-white px-5 py-2 rounded font-medium transition shadow-lg flex items-center gap-2"
                        >
                            🗑️ Hapus Data
                        </button>
                    </>
                ) : (
                    // MODE INPUT / EDITING
                    <>
                        {isEditing && (
                            <button 
                                onClick={() => { setIsEditing(false); fetchKehadiran(); }} // Batal = Reset fetch
                                className="bg-gray-600 hover:bg-gray-500 text-white px-5 py-2 rounded font-medium transition"
                                disabled={processing}
                            >
                                Batal
                            </button>
                        )}
                        <button 
                            onClick={handleSaveOrUpdate}
                            disabled={processing || siswaList.length === 0}
                            className={`${isEditing ? 'bg-green-600 hover:bg-green-700' : 'bg-primary hover:bg-secondary'} text-white px-6 py-2 rounded font-bold transition shadow-lg flex items-center gap-2 disabled:opacity-50`}
                        >
                            {processing ? 'Menyimpan...' : (isEditing ? '💾 Simpan Perubahan' : '💾 Simpan Absensi')}
                        </button>
                    </>
                )}
            </div>
        </div>
      </div>

      <div className="bg-gray-800 shadow overflow-hidden rounded-lg border border-gray-700">
        {loading ? (
             <div className="p-10 text-center text-gray-400">Memuat data kehadiran...</div>
        ) : (
            <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-700">
            <thead className="bg-gray-700">
                <tr>
                <th className="px-6 py-3 text-center text-xs font-medium text-gray-300 uppercase w-10">No</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Nama Siswa</th>
                <th className="px-6 py-3 text-center text-xs font-medium text-gray-300 uppercase w-20">L/P</th>
                <th className="px-6 py-3 text-center text-xs font-medium text-gray-300 uppercase">Status Kehadiran</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Catatan</th>
                </tr>
            </thead>
            <tbody className="bg-gray-800 divide-y divide-gray-700">
                {siswaList.map((item, index) => {
                    const isDisabled = isDataSaved && !isEditing;

                    return (
                        <tr key={item.id} className="hover:bg-gray-750 transition-colors">
                            <td className="px-6 py-4 text-center text-gray-500 text-sm">
                                {index + 1}
                            </td>
                            <td className="px-6 py-4 whitespace-nowrap">
                                <div className="text-sm font-bold text-white">{item.siswa?.nama}</div>
                                <div className="text-xs text-gray-400">{item.siswa?.nisn}</div>
                            </td>
                            <td className="px-6 py-4 text-center whitespace-nowrap text-sm text-gray-300">
                                {item.siswa?.jenis_kelamin || '-'}
                            </td>

