      </div>

    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Login } from './components/Login';
// Admin Components
import { AdminDashboard } from './components/AdminDashboard';
import { CrudGuru } from './components/CrudGuru';
import { CrudSiswa } from './components/CrudSiswa';
import { CrudKelas } from './components/CrudKelas';
import { CrudMapel } from './components/CrudMapel';
import { CrudAnggotaGurwal } from './components/CrudAnggotaGurwal';
import { CrudDataPengajar } from './components/CrudDataPengajar';
import { CrudSekolah } from './components/CrudSekolah';

// Unified Guru Components
import { GuruDashboard } from './components/GuruDashboard';
// Binaan
import { DaftarBinaan } from './components/GuruBinaan/DaftarBinaan';
import { KehadiranBinaan } from './components/GuruBinaan/KehadiranBinaan';
import { ImportKehadiranTemplate } from './components/GuruBinaan/ImportKehadiranTemplate';
import { PelanggaranBinaan } from './components/GuruBinaan/PelanggaranBinaan';
import { PrestasiBinaan } from './components/GuruBinaan/PrestasiBinaan';
import { LaporanBinaan } from './components/GuruBinaan/LaporanBinaan';
// Pengajar
import { DaftarKelasAjar } from './components/GuruPengajar/DaftarKelasAjar';
import { InputNilai } from './components/GuruPengajar/InputNilai';
import { RekapNilai } from './components/GuruPengajar/RekapNilai';

import { Toast } from './components/Toast';
import { Guru, ViewState } from './types';

interface ToastState {
  message: string;
  type: 'success' | 'error';
  duration?: number;
  position?: 'top-right' | 'center';
}

function App() {
  const [session, setSession] = useState<Guru | null>(null);
  const [currentView, setCurrentView] = useState<ViewState>('DASHBOARD');
  const [toast, setToast] = useState<ToastState | null>(null);

  useEffect(() => {
    // Check localStorage for persisted session
    const storedUser = localStorage.getItem('gurwal_admin_user');
    const storedView = localStorage.getItem('gurwal_current_view') as ViewState;

    if (storedUser) {
      try {
        const user = JSON.parse(storedUser);
        setSession(user);

        if (storedView) {
          setCurrentView(storedView);
        } else {
          // Default views
          if (user.peran === 'ADMIN') setCurrentView('DASHBOARD');
          else setCurrentView('GURU_DASHBOARD');
        }
      } catch (e) {
        localStorage.removeItem('gurwal_admin_user');
        localStorage.removeItem('gurwal_current_view');
      }
    }
  }, []);

  const handleLoginSuccess = (user: Guru) => {
    setSession(user);
    localStorage.setItem('gurwal_admin_user', JSON.stringify(user));

    let defaultView: ViewState = 'DASHBOARD';
    if (user.peran !== 'ADMIN') defaultView = 'GURU_DASHBOARD';

    setCurrentView(defaultView);
    localStorage.setItem('gurwal_current_view', defaultView);
  };

  const handleLogout = () => {
    setSession(null);
    localStorage.removeItem('gurwal_admin_user');
    localStorage.removeItem('gurwal_current_view');
    showToast('Anda telah keluar', 'success');
  };

  const handleChangeView = (view: ViewState) => {
    setCurrentView(view);
    localStorage.setItem('gurwal_current_view', view);
  };

  const showToast = (
    message: string, 
    type: 'success' | 'error', 
    duration: number = 3000, 
    position: 'top-right' | 'center' = 'top-right'
  ) => {
    setToast({ message, type, duration, position });
  };

  // Render Logic
  if (!session) {
    return (
      <>
        <Login onLoginSuccess={handleLoginSuccess} showToast={showToast} />
        {toast && (
          <Toast
            message={toast.message}
            type={toast.type}
            duration={toast.duration}
            position={toast.position}
            onClose={() => setToast(null)}
          />
        )}
      </>
    );
  }

  const renderContent = () => {
    switch (currentView) {
      // ADMIN
      case 'GURU': return <CrudGuru showToast={showToast} />;
      case 'SISWA': return <CrudSiswa showToast={showToast} />;
      case 'KELAS': return <CrudKelas showToast={showToast} />;
      case 'MAPEL': return <CrudMapel showToast={showToast} />;
      case 'ANGGOTA_GURWAL': return <CrudAnggotaGurwal showToast={showToast} />;
      case 'DATA_PENGAJAR': return <CrudDataPengajar showToast={showToast} />;
      case 'PENGATURAN_SEKOLAH': return <CrudSekolah showToast={showToast} />;
      case 'DASHBOARD': return <AdminDashboard />;

      // UNIFIED GURU
      case 'GURU_DASHBOARD': return <GuruDashboard currentUser={session} />;

      // BINAAN (WALI)
      case 'GURU_BINAAN_LIST': return <DaftarBinaan currentUser={session} showToast={showToast} />;
      case 'GURU_BINAAN_KEHADIRAN': return <KehadiranBinaan currentUser={session} showToast={showToast} />;
      case 'GURU_IMPORT_KEHADIRAN': return <ImportKehadiranTemplate currentUser={session} showToast={showToast} />;
      case 'GURU_BINAAN_PELANGGARAN': return <PelanggaranBinaan currentUser={session} showToast={showToast} />;
      case 'GURU_BINAAN_PRESTASI': return <PrestasiBinaan currentUser={session} showToast={showToast} />;
      case 'GURU_BINAAN_LAPORAN': return <LaporanBinaan currentUser={session} />;

      // PENGAJAR
      case 'GURU_PENGAJAR_JADWAL': return <DaftarKelasAjar currentUser={session} />;
      case 'GURU_PENGAJAR_NILAI': return <InputNilai currentUser={session} showToast={showToast} />;
      case 'GURU_PENGAJAR_REKAP': return <RekapNilai currentUser={session} />;

      default:
        return <div className="p-6 text-white">Halaman tidak ditemukan</div>;
    }
  };

  return (
    <Layout
      currentUser={session}
      currentView={currentView}
      onChangeView={handleChangeView}
      onLogout={handleLogout}
    >
      {renderContent()}
      {toast && (
        <Toast
          message={toast.message}
          type={toast.type}
          duration={toast.duration}
          position={toast.position}
          onClose={() => setToast(null)}
        />
      )}
    </Layout>
  );
}

export default App;

import React, { useState, useRef } from 'react';
import { supabase } from '../../supabaseClient';
import { Guru } from '../../types';
import * as XLSX from 'xlsx';

interface Props {
  currentUser: Guru;
  showToast: (msg: string, type: 'success' | 'error') => void;
}

export const ImportKehadiranTemplate: React.FC<Props> = ({ currentUser, showToast }) => {
  const [selectedDates, setSelectedDates] = useState<string[]>([]);
  const [dateInput, setDateInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [importProgress, setImportProgress] = useState(0); // State untuk progress bar
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Fungsi Tambah Tanggal ke List
  const handleAddDate = () => {
    if (!dateInput) return;
    if (selectedDates.includes(dateInput)) {
      showToast('Tanggal sudah ada dalam daftar', 'error');
      return;
    }
    // Sort dates chronologically
    const newDates = [...selectedDates, dateInput].sort();
    setSelectedDates(newDates);
    setDateInput('');
  };

  // Fungsi Hapus Tanggal
  const handleRemoveDate = (dateToRemove: string) => {
    setSelectedDates(selectedDates.filter(d => d !== dateToRemove));
  };

  // 1. Generate & Download Template
  const handleGenerateTemplate = async () => {
    if (selectedDates.length === 0) {
      showToast('Pilih minimal satu tanggal terlebih dahulu', 'error');
      return;
    }

    setLoading(true);
    try {
      // Ambil siswa binaan
      const { data: siswaData, error } = await supabase
        .from('bimbingan')
        .select('*, siswa(id, nama, nisn, kelas(nama))')
        .eq('id_guru', currentUser.id)
        .order('created_at', { ascending: true });

      if (error) throw error;

      if (!siswaData || siswaData.length === 0) {
        showToast('Anda belum memiliki siswa binaan', 'error');
        setLoading(false);
        return;
      }

      // Format Data untuk Excel
      const rows = siswaData.map((item, index) => {
        const row: any = {
          NO: index + 1,
          NISN: item.siswa?.nisn || '', // Hidden identifier for matching
          NAMA: item.siswa?.nama || '',
          KELAS: item.siswa?.kelas?.nama || '',
        };
        // Tambahkan kolom tanggal kosong
        selectedDates.forEach(date => {
          row[date] = ''; // Kolom kosong untuk diisi Guru
        });
        return row;
      });

      // Buat Worksheet
      const ws = XLSX.utils.json_to_sheet(rows);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Kehadiran");

      // Download File
      const filename = `Template_Kehadiran_${new Date().toISOString().split('T')[0]}.xlsx`;
      XLSX.writeFile(wb, filename);

      showToast('Template berhasil dibuat!', 'success');
    } catch (err: any) {
      console.error(err);
      showToast('Gagal membuat template: ' + err.message, 'error');
    } finally {
      setLoading(false);
    }
  };

  // 2. Upload & Process Excel
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setImportProgress(0); // Reset progress
    const reader = new FileReader();

    reader.onload = async (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsName = wb.SheetNames[0];
        const ws = wb.Sheets[wsName];

        // Convert to JSON
        const data = XLSX.utils.sheet_to_json(ws);

        if (data.length === 0) {
          showToast('File Excel kosong', 'error');
          setLoading(false);
          return;
        }

        let processedCount = 0;
        let errorCount = 0;
        const totalRows = data.length;

        // Iterate setiap baris (Siswa)
        // Gunakan for loop biasa agar bisa update progress per iterasi
        for (let i = 0; i < totalRows; i++) {
          const row: any = data[i];
          const nisn = row['NISN'] ? String(row['NISN']).trim() : '';
          const nama = row['NAMA'] ? String(row['NAMA']).trim() : '';

          if (!nisn && !nama) {
             // Update progress meskipun skip
             const currentProgress = Math.round(((i + 1) / totalRows) * 100);
             setImportProgress(currentProgress);
             continue; 
          }

          // Cari ID Siswa di DB berdasarkan NISN (prioritas) atau Nama
          let studentId = '';

          // Strategy: Match with current student list in memory or fetch individually
          // Fetch id based on NISN from DB to ensure validity
          const { data: foundSiswa } = await supabase
             .from('siswa')
             .select('id')
             .eq('nisn', nisn)
             .maybeSingle();

          if (foundSiswa) {
            studentId = foundSiswa.id;
          } else {
            // Fallback match by Name if NISN failed/missing (less accurate)
            const { data: foundSiswaByName } = await supabase
                .from('siswa')
                .select('id')
                .ilike('nama', nama)
                .maybeSingle();
            if (foundSiswaByName) studentId = foundSiswaByName.id;
          }

          if (!studentId) {
            console.warn(`Siswa tidak ditemukan: ${nama} (${nisn})`);
            errorCount++;
          } else {
            // Iterate Keys in Row to find Dates
            const keys = Object.keys(row);
            // Regex simple YYYY-MM-DD or similar
            const dateRegex = /^\d{4}-\d{2}-\d{2}$/; 

            for (const key of keys) {
               // Cek apakah key adalah tanggal yang valid
               if (dateRegex.test(key)) {
                  const rawStatus = row[key] ? String(row[key]).trim().toUpperCase() : '';
                  let statusDb: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA' | null = null;

                  // Map Singkatan ke Full Status
                  if (['H', 'HADIR'].includes(rawStatus)) statusDb = 'HADIR';
                  else if (['S', 'SAKIT'].includes(rawStatus)) statusDb = 'SAKIT';
                  else if (['I', 'IZIN'].includes(rawStatus)) statusDb = 'IZIN';
                  else if (['A', 'ALPHA', 'ALPA'].includes(rawStatus)) statusDb = 'ALPHA';

                  if (statusDb) {
                      // Cek apakah data sudah ada
                      const { data: existing } = await supabase
                          .from('kehadiran')
                          .select('id')
                          .eq('id_guru', currentUser.id)
                          .eq('id_siswa', studentId)
                          .eq('tanggal', key)
                          .maybeSingle();

                      if (existing) {
                          // Update
                          await supabase.from('kehadiran').update({ status: statusDb }).eq('id', existing.id);
                      } else {
                          // Insert
                          await supabase.from('kehadiran').insert([{
                              id_guru: currentUser.id,
                              id_siswa: studentId,
                              tanggal: key,
                              status: statusDb
                          }]);
                      }
                  }
               }
            }
            processedCount++;
          }

          // Update Progress UI
          const currentProgress = Math.round(((i + 1) / totalRows) * 100);
          setImportProgress(currentProgress);
        }

        showToast(`Import selesai. ${processedCount} siswa diproses.`, 'success');
        if (errorCount > 0) {
            setTimeout(() => showToast(`${errorCount} siswa tidak ditemukan di database.`, 'error'), 2000);
        }

      } catch (err: any) {
        console.error(err);
        showToast('Gagal memproses file: ' + err.message, 'error');
      } finally {
        setLoading(false);
        setImportProgress(0);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };

    reader.readAsBinaryString(file);
  };

  return (
    <div className="max-w-4xl mx-auto p-4">
      <h2 className="text-3xl font-bold text-white mb-2">Import Kehadiran (Custom)</h2>
      <p className="text-gray-400 mb-8">
        Fitur ini memungkinkan Anda mengisi absensi untuk beberapa tanggal sekaligus menggunakan Excel.
      </p>

      {/* STEP 1: PILIH TANGGAL */}
      <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-lg mb-6">
        <h3 className="text-lg font-semibold text-blue-400 mb-4">1. Pilih Tanggal & Buat Template</h3>

        <div className="flex flex-col md:flex-row gap-4 items-end md:items-center mb-6">
            <div className="w-full md:w-auto">
                <label className="block text-sm text-gray-400 mb-1">Tambah Tanggal</label>
                <input 
                    type="date" 
                    value={dateInput}
                    onChange={(e) => setDateInput(e.target.value)}
                    className="bg-gray-700 border border-gray-600 text-white rounded px-4 py-2 focus:outline-none focus:border-primary w-full"
                />
            </div>
            <button 
                onClick={handleAddDate}
                className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded font-medium transition flex items-center gap-2"
            >
                + Tambah
            </button>
        </div>

        {/* Selected Dates Chips */}
        {selectedDates.length > 0 && (
            <div className="flex flex-wrap gap-2 mb-6 bg-gray-900/50 p-4 rounded-lg border border-gray-700">
                {selectedDates.map(date => (
                    <div key={date} className="bg-gray-700 text-white px-3 py-1 rounded-full text-sm flex items-center gap-2 border border-gray-600">
                        <span>🗓️ {date}</span>
                        <button 
                            onClick={() => handleRemoveDate(date)}
                            className="text-red-400 hover:text-red-300 font-bold px-1"
                        >
                            &times;
                        </button>
                    </div>
                ))}
            </div>
        )}

        <button 
            onClick={handleGenerateTemplate}
            disabled={loading || selectedDates.length === 0}
            className="w-full md:w-auto bg-green-600 hover:bg-green-700 text-white px-6 py-3 rounded-lg font-bold transition shadow-lg flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
        >
            {loading ? 'Memproses...' : '📥 Buat & Download Template'}
        </button>
      </div>

      {/* STEP 2: UPLOAD */}
      <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-lg">
        <h3 className="text-lg font-semibold text-green-400 mb-4">2. Upload & Import Data</h3>
        <p className="text-sm text-gray-400 mb-4">
            Isi file Excel yang telah diunduh. Gunakan kode: <strong>H</strong> (Hadir), <strong>S</strong> (Sakit), <strong>I</strong> (Izin), <strong>A</strong> (Alpha).
        </p>

        <div className="flex flex-col items-center justify-center border-2 border-dashed border-gray-600 rounded-lg p-10 bg-gray-700/30 hover:bg-gray-700/50 transition">
            <input 
                type="file" 
                accept=".xlsx, .xls"
                ref={fileInputRef}
                onChange={handleFileUpload}
                disabled={loading}
                className="hidden" 
                id="file-upload"
            />
            <label htmlFor="file-upload" className="cursor-pointer flex flex-col items-center">
                <span className="text-4xl mb-2">📂</span>
                <span className="text-white font-medium mb-1">Klik untuk Upload Excel</span>
                <span className="text-xs text-gray-500">Format .xlsx atau .xls</span>
            </label>
        </div>
      </div>

      {/* PROGRESS OVERLAY */}
      {loading && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-80">
          <div className="bg-gray-800 p-6 rounded-lg border border-gray-700 w-80 md:w-96 text-center">
            <h3 className="text-white font-bold mb-4 text-lg">Mengimport Data...</h3>
            <div className="w-full bg-gray-700 rounded-full h-4 mb-2 overflow-hidden">
               <div 
                 className="bg-green-500 h-4 rounded-full transition-all duration-300" 
                 style={{ width: `${importProgress}%` }}
               ></div>
            </div>
            <p className="text-gray-300 font-medium">{importProgress}%</p>
            <p className="text-gray-500 text-sm mt-1">Mohon tunggu sebentar...</p>
          </div>
        </div>
      )}

    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../supabaseClient';
import { Guru, Siswa, Kelas } from '../types';
import { ConfirmDialog } from './ConfirmDialog';

interface CrudAnggotaGurwalProps {
  showToast: (msg: string, type: 'success' | 'error', duration?: number, position?: 'top-right' | 'center') => void;
}

export const CrudAnggotaGurwal: React.FC<CrudAnggotaGurwalProps> = ({ showToast }) => {
  const [guruWaliList, setGuruWaliList] = useState<Guru[]>([]);
  const [siswaList, setSiswaList] = useState<Siswa[]>([]);
  const [kelasOptions, setKelasOptions] = useState<Kelas[]>([]);

  const [selectedGuru, setSelectedGuru] = useState<string>('');
  const [assignedSiswaIds, setAssignedSiswaIds] = useState<Set<string>>(new Set());

  // State untuk menyimpan pemetaan global: StudentID -> GuruID
  // Digunakan untuk validasi agar tidak ada siswa yang double guru wali
  const [allAssignments, setAllAssignments] = useState<Map<string, string>>(new Map());

  // Confirmation State for Removal
  const [pendingRemoval, setPendingRemoval] = useState<{ id: string; nama: string } | null>(null);

  // Filters
  const [filterKelas, setFilterKelas] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(false);

  // 1. Initial Load: Gurus & Kelas & All Assignments
  useEffect(() => {
    const fetchInitial = async () => {
      // Mengambil data guru dengan peran 'GURU' 
      const { data: gurus } = await supabase
        .from('guru')
        .select('*')
        .eq('peran', 'GURU') 
        .order('nama');

      const { data: kelas } = await supabase.from('kelas').select('*').order('nama');
      const { data: siswa } = await supabase.from('siswa').select('*, kelas(nama)').order('nama');

      if (gurus) setGuruWaliList(gurus);
      if (kelas) setKelasOptions(kelas);
      // @ts-ignore
      if (siswa) setSiswaList(siswa);

      fetchGlobalAssignments();
    };
    fetchInitial();
  }, []);

  // Fetch seluruh data bimbingan untuk validasi
  const fetchGlobalAssignments = async () => {
      const { data } = await supabase.from('bimbingan').select('id_siswa, id_guru');
      if (data) {
          const map = new Map<string, string>();
          data.forEach(item => map.set(item.id_siswa, item.id_guru));
          setAllAssignments(map);
      }
  };

  // 2. Load Bimbingan when Guru Selected
  useEffect(() => {
    if (selectedGuru) {
      fetchBimbingan();
    } else {
      setAssignedSiswaIds(new Set());
    }
     // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedGuru]);

  const fetchBimbingan = async () => {
    if (!selectedGuru) return;
    setLoading(true);
    const { data } = await supabase.from('bimbingan').select('id_siswa').eq('id_guru', selectedGuru);
    if (data) {
      setAssignedSiswaIds(new Set(data.map(item => item.id_siswa)));
    }
    setLoading(false);
  };

  // Logic to execute DB changes
  const executeToggle = async (id_siswa: string, nama_siswa: string, isAssigned: boolean) => {
    try {
      if (isAssigned) {
        // Remove assignment
        const { error } = await supabase
          .from('bimbingan')
          .delete()
          .eq('id_guru', selectedGuru)
          .eq('id_siswa', id_siswa);
        if (error) throw error;

        showToast(`Berhasil menghapus ${nama_siswa} dari binaan`, 'success');
      } else {
        // Add assignment
        const { error } = await supabase
          .from('bimbingan')
          .insert([{ id_guru: selectedGuru, id_siswa: id_siswa }]);
        if (error) throw error;

        // Tambahkan Toast Sukses TEPAT DI TENGAH dengan NAMA SISWA
        showToast(`Berhasil menambahkan ${nama_siswa} ke binaan`, 'success', 2000, 'center');
        setSearchTerm(''); 
      }

      // Optimistic update for UI responsiveness
      const newSet = new Set(assignedSiswaIds);
      if (isAssigned) newSet.delete(id_siswa);
      else newSet.add(id_siswa);
      setAssignedSiswaIds(newSet);

      // Refresh global map untuk validasi terbaru
      fetchGlobalAssignments();

    } catch (e) {
      showToast('Gagal mengubah data', 'error');
      fetchBimbingan(); // Revert on error
    }
  };

  // Handler triggered by checkbox click
  const handleToggleClick = (siswa: Siswa, isAssigned: boolean) => {
    if (!selectedGuru) {
      showToast('Pilih Guru Wali terlebih dahulu', 'error');
      return;
    }

    // VALIDASI: Cek apakah siswa sudah punya guru wali LAIN
    // Ambil Guru ID pemilik siswa ini dari map global
    const existingGuruId = allAssignments.get(siswa.id);

    // Jika ada pemilik, DAN pemiliknya BUKAN guru yang sedang dipilih
    if (existingGuruId && existingGuruId !== selectedGuru) {
        showToast("⚠️ Siswa ini sudah memiliki guru wali lain!", "error", 4000, "center");
        return; // Batalkan aksi
    }

    if (isAssigned) {
      // Jika sudah assigned (dicentang) dan diklik -> berarti ingin menghapus (uncheck)
      // Tampilkan Konfirmasi
      setPendingRemoval({ id: siswa.id, nama: siswa.nama });
    } else {
      // Jika belum assigned -> berarti ingin menambah
      // Langsung eksekusi dengan NAMA
      executeToggle(siswa.id, siswa.nama, false);
    }
  };

  const handleConfirmRemoval = () => {
    if (pendingRemoval) {
      executeToggle(pendingRemoval.id, pendingRemoval.nama, true); // true indicates "currently assigned", so logic will delete
      setPendingRemoval(null);
    }
  };

  const filteredSiswa = siswaList
    .filter(s => {
      // 1. Filter Pencarian & Kelas
      const matchSearch = s.nama.toLowerCase().includes(searchTerm.toLowerCase()) || s.nisn.includes(searchTerm);
      const matchKelas = filterKelas === '' || s.id_kelas === filterKelas;

      // 2. Filter Status Binaan (Requirement: Hanya tampil siswa yang belum dibimbing)
      // Tampilkan jika:
      // a. Belum punya guru wali sama sekali (!allAssignments.has(s.id))
      // b. ATAU Sudah dibimbing oleh guru yang SEDANG dipilih (agar bisa di-uncheck)
      const ownerGuruId = allAssignments.get(s.id);
      const isAvailableOrMine = !ownerGuruId || ownerGuruId === selectedGuru;

      return matchSearch && matchKelas && isAvailableOrMine;
    })
    .sort((a, b) => {
      const aAssigned = assignedSiswaIds.has(a.id);
      const bAssigned = assignedSiswaIds.has(b.id);

      // Sort priority 1: Assigned (Checked) items go to top
      if (aAssigned && !bAssigned) return -1;
      if (!aAssigned && bAssigned) return 1;

      // Sort priority 2: Alphabetical name
      return a.nama.localeCompare(b.nama);
    });

  return (
    <div>
      {/* Dialog Konfirmasi Hapus Anggota */}
      <ConfirmDialog 
        isOpen={!!pendingRemoval}
        message={`Apakah Anda yakin menghapus anggota ${pendingRemoval?.nama}?`}
        onConfirm={handleConfirmRemoval}
        onCancel={() => setPendingRemoval(null)}
      />

      <h2 className="text-2xl font-bold text-white mb-6">Manajemen Anggota GurWal</h2>
      <p className="text-gray-400 mb-4">
        Tetapkan siswa binaan kepada guru. <br/>
        <span className="text-sm text-yellow-500 italic">Catatan: Siswa yang sudah memiliki Guru Wali lain tidak akan ditampilkan di daftar ini.</span>
      </p>

      {/* Main Filter Section */}
      <div className="bg-gray-800 p-6 rounded-lg border border-gray-700 mb-6">
        <label className="block text-sm font-medium text-gray-300 mb-2">Pilih Guru (Calon Guru Wali)</label>
        <div className="flex flex-col md:flex-row gap-4 items-center">
            <select
            value={selectedGuru}
            onChange={(e) => setSelectedGuru(e.target.value)}
            className="w-full md:w-1/2 bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white focus:outline-none focus:border-primary"
            >
            <option value="">-- Pilih Guru --</option>
            {guruWaliList.map(g => (
                <option key={g.id} value={g.id}>{g.nama} - {g.nip || 'No NIP'}</option>
            ))}
            </select>
            {selectedGuru && (
                 <span className="text-sm text-green-400 bg-green-900/30 px-3 py-1 rounded-full border border-green-800 font-medium">
                    ✅ Guru Terpilih
                 </span>
            )}
        </div>
        {!selectedGuru && <p className="text-yellow-500 text-sm mt-2">Silakan pilih guru terlebih dahulu untuk mengelola siswa binaannya.</p>}
      </div>

      {/* Siswa List Section */}
      {selectedGuru && (
        <>
          <div className="flex flex-col md:flex-row gap-4 mb-4">
            <div className="flex-1">
              <input
                type="text"
                placeholder="Cari Siswa / NISN..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white placeholder-gray-400"
              />
            </div>
            <div className="w-full md:w-64">
              <select
                value={filterKelas}
                onChange={(e) => setFilterKelas(e.target.value)}
                className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white"
              >
                <option value="">Semua Kelas</option>
                {kelasOptions.map(k => <option key={k.id} value={k.id}>{k.nama}</option>)}
              </select>
            </div>
          </div>

          <div className="bg-gray-800 shadow overflow-hidden rounded-lg border border-gray-700">
            {loading ? <p className="p-4 text-gray-400">Memuat data bimbingan...</p> : (
              <table className="min-w-full divide-y divide-gray-700">
                <thead className="bg-gray-700">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase w-10">Pilih</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Nama Siswa</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Kelas</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Status</th>
                  </tr>
                </thead>
                <tbody className="bg-gray-800 divide-y divide-gray-700">
                  {filteredSiswa.map(siswa => {
                    const isAssigned = assignedSiswaIds.has(siswa.id);
                    return (
                      <tr 
                        key={siswa.id} 
                        className={`transition-all duration-300 ${isAssigned 
                            ? 'bg-green-500/10 shadow-[0_0_15px_rgba(34,197,94,0.15)] border-l-4 border-green-500' // EFEK LAMPU HIJAU
                            : 'hover:bg-gray-700 border-l-4 border-transparent'
                        }`}
                      >
                        <td className="px-6 py-4 whitespace-nowrap">
                          <input
                            type="checkbox"
                            checked={isAssigned}
                            onChange={() => handleToggleClick(siswa, isAssigned)}
                            className="w-5 h-5 text-green-500 border-gray-300 rounded focus:ring-green-500 bg-gray-700 cursor-pointer accent-green-600"
                          />
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                            <div className={`font-medium ${isAssigned ? 'text-green-400 drop-shadow-[0_0_2px_rgba(74,222,128,0.5)]' : 'text-white'}`}>
                              {siswa.nama}
                            </div>
                            <div className="text-xs text-gray-500">{siswa.nisn}</div>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-gray-300">
                            {siswa.kelas?.nama || '-'}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          {isAssigned ? (
                            <span className="bg-green-900 text-green-200 text-xs px-2 py-1 rounded-full font-bold border border-green-700 shadow-[0_0_5px_rgba(34,197,94,0.4)]">
                                ✓ Binaan Anda
                            </span>
                          ) : (
                            <span className="text-gray-500 text-xs">-</span>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                  {filteredSiswa.length === 0 && (
                    <tr><td colSpan={4} className="p-6 text-center text-gray-500">
                        {searchTerm ? 'Siswa tidak ditemukan.' : 'Semua siswa di kelas ini sudah memiliki Guru Wali.'}
                    </td></tr>
                  )}
                </tbody>
              </table>
            )}
          </div>
        </>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../supabaseClient';
import { Guru, Siswa, Kelas } from '../types';
import { ConfirmDialog } from './ConfirmDialog';

interface CrudAnggotaGurwalProps {
  showToast: (msg: string, type: 'success' | 'error', duration?: number, position?: 'top-right' | 'center') => void;
}

export const CrudAnggotaGurwal: React.FC<CrudAnggotaGurwalProps> = ({ showToast }) => {
  const [guruWaliList, setGuruWaliList] = useState<Guru[]>([]);
  const [siswaList, setSiswaList] = useState<Siswa[]>([]);
  const [kelasOptions, setKelasOptions] = useState<Kelas[]>([]);

  const [selectedGuru, setSelectedGuru] = useState<string>('');
  const [assignedSiswaIds, setAssignedSiswaIds] = useState<Set<string>>(new Set());

  // State untuk menyimpan pemetaan global: StudentID -> GuruID
  const [allAssignments, setAllAssignments] = useState<Map<string, string>>(new Map());

  // Confirmation State for Removal
  const [pendingRemoval, setPendingRemoval] = useState<{ id: string; nama: string } | null>(null);

  // Filters
  const [filterKelas, setFilterKelas] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(false);

  // 1. Initial Load: Gurus & Kelas & All Assignments
  useEffect(() => {
    const fetchInitial = async () => {
      // Mengambil data guru dengan peran 'GURU' 
      const { data: gurus } = await supabase
        .from('guru')
        .select('*')
        .eq('peran', 'GURU') 
        .order('nama');

      const { data: kelas } = await supabase.from('kelas').select('*').order('nama');
      const { data: siswa } = await supabase.from('siswa').select('*, kelas(nama)').order('nama');

      if (gurus) setGuruWaliList(gurus);
      if (kelas) setKelasOptions(kelas);
      // @ts-ignore
      if (siswa) setSiswaList(siswa);

      fetchGlobalAssignments();
    };
    fetchInitial();
  }, []);

  // Fetch seluruh data bimbingan untuk validasi global
  const fetchGlobalAssignments = async () => {
      const { data } = await supabase.from('bimbingan').select('id_siswa, id_guru');
      if (data) {
          const map = new Map<string, string>();
          data.forEach(item => map.set(item.id_siswa, item.id_guru));
          setAllAssignments(map);
      }
  };

  // 2. Load Bimbingan when Guru Selected
  useEffect(() => {
    if (selectedGuru) {
      fetchBimbingan();
    } else {
      setAssignedSiswaIds(new Set());
    }
     // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedGuru]);

  const fetchBimbingan = async () => {
    if (!selectedGuru) return;
    setLoading(true);
    const { data } = await supabase.from('bimbingan').select('id_siswa').eq('id_guru', selectedGuru);
    if (data) {
      setAssignedSiswaIds(new Set(data.map(item => item.id_siswa)));
    }
    setLoading(false);
  };

  // Logic to execute DB changes
  const executeToggle = async (id_siswa: string, nama_siswa: string, isAssigned: boolean) => {
    try {
      if (isAssigned) {
        // Remove assignment
        const { error } = await supabase
          .from('bimbingan')
          .delete()
          .eq('id_guru', selectedGuru)
          .eq('id_siswa', id_siswa);
        if (error) throw error;

        showToast(`Berhasil menghapus ${nama_siswa} dari binaan`, 'success');
      } else {
        // Add assignment
        const { error } = await supabase
          .from('bimbingan')
          .insert([{ id_guru: selectedGuru, id_siswa: id_siswa }]);
        if (error) throw error;

        // Tambahkan Toast Sukses
        showToast(`Berhasil menambahkan ${nama_siswa} ke binaan`, 'success', 2000, 'center');
        setSearchTerm(''); 
      }

      // Optimistic update for UI responsiveness
      const newSet = new Set(assignedSiswaIds);
      if (isAssigned) newSet.delete(id_siswa);
      else newSet.add(id_siswa);
      setAssignedSiswaIds(newSet);

      // Refresh global map untuk validasi terbaru
      fetchGlobalAssignments();

    } catch (e) {
      showToast('Gagal mengubah data', 'error');
      fetchBimbingan(); // Revert on error
    }
  };

  // Handler triggered by checkbox click
  const handleToggleClick = (siswa: Siswa, isAssigned: boolean) => {
    if (!selectedGuru) {
      showToast('Pilih Guru Wali terlebih dahulu', 'error');
      return;
    }

    // VALIDASI: Cek apakah siswa sudah punya guru wali LAIN
    const existingGuruId = allAssignments.get(siswa.id);

    // Jika ada pemilik, DAN pemiliknya BUKAN guru yang sedang dipilih
    if (existingGuruId && existingGuruId !== selectedGuru) {
        showToast("⚠️ Siswa ini sudah memiliki guru wali lain!", "error", 4000, "center");
        return; // Batalkan aksi
    }

    if (isAssigned) {
      // Uncheck / Hapus
      setPendingRemoval({ id: siswa.id, nama: siswa.nama });
    } else {
      // Check / Tambah
      executeToggle(siswa.id, siswa.nama, false);
    }
  };

  const handleConfirmRemoval = () => {
    if (pendingRemoval) {
      executeToggle(pendingRemoval.id, pendingRemoval.nama, true);
      setPendingRemoval(null);
    }
  };

  const filteredSiswa = siswaList
    .filter(s => {
      // Filter Pencarian & Kelas
      const matchSearch = s.nama.toLowerCase().includes(searchTerm.toLowerCase()) || s.nisn.includes(searchTerm);
      const matchKelas = filterKelas === '' || s.id_kelas === filterKelas;
      return matchSearch && matchKelas;
    })
    .sort((a, b) => {
      // Sorting:
      // 1. Yang sudah dipilih guru ini (Assigned) paling atas
      // 2. Yang available (belum punya guru) di tengah
      // 3. Yang Locked (punya guru lain) paling bawah (opsional, tapi lebih rapi)

      const aAssigned = assignedSiswaIds.has(a.id);
      const bAssigned = assignedSiswaIds.has(b.id);

      const aLocked = allAssignments.has(a.id) && allAssignments.get(a.id) !== selectedGuru;
      const bLocked = allAssignments.has(b.id) && allAssignments.get(b.id) !== selectedGuru;

      if (aAssigned && !bAssigned) return -1;
      if (!aAssigned && bAssigned) return 1;

      if (!aLocked && bLocked) return -1;
      if (aLocked && !bLocked) return 1;

      return a.nama.localeCompare(b.nama);
    });

  // Helper untuk mendapatkan nama guru berdasarkan ID
  const getGuruName = (guruId: string) => {
      const guru = guruWaliList.find(g => g.id === guruId);
      return guru ? guru.nama : 'Guru Lain';
  };

  return (
    <div>
      {/* Dialog Konfirmasi Hapus Anggota */}
      <ConfirmDialog 
        isOpen={!!pendingRemoval}
        message={`Apakah Anda yakin menghapus anggota ${pendingRemoval?.nama}?`}
        onConfirm={handleConfirmRemoval}
        onCancel={() => setPendingRemoval(null)}
      />

      <h2 className="text-2xl font-bold text-white mb-6">Manajemen Anggota GurWal</h2>
      <p className="text-gray-400 mb-4">
        Tetapkan siswa binaan kepada guru.
      </p>

      {/* Main Filter Section */}
      <div className="bg-gray-800 p-6 rounded-lg border border-gray-700 mb-6">
        <label className="block text-sm font-medium text-gray-300 mb-2">Pilih Guru (Calon Guru Wali)</label>
        <div className="flex flex-col md:flex-row gap-4 items-center">
            <select
            value={selectedGuru}
            onChange={(e) => setSelectedGuru(e.target.value)}
            className="w-full md:w-1/2 bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white focus:outline-none focus:border-primary"
            >
            <option value="">-- Pilih Guru --</option>
            {guruWaliList.map(g => (
                <option key={g.id} value={g.id}>{g.nama} - {g.nip || 'No NIP'}</option>
            ))}
            </select>
            {selectedGuru && (
                 <span className="text-sm text-green-400 bg-green-900/30 px-3 py-1 rounded-full border border-green-800 font-medium">
                    ✅ Guru Terpilih
                 </span>
            )}
        </div>
        {!selectedGuru && <p className="text-yellow-500 text-sm mt-2">Silakan pilih guru terlebih dahulu untuk mengelola siswa binaannya.</p>}
      </div>

      {/* Siswa List Section */}
      {selectedGuru && (
        <>
          <div className="flex flex-col md:flex-row gap-4 mb-4">
            <div className="flex-1">
              <input
                type="text"
                placeholder="Cari Siswa / NISN..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white placeholder-gray-400"
              />
            </div>
            <div className="w-full md:w-64">
              <select
                value={filterKelas}
                onChange={(e) => setFilterKelas(e.target.value)}
                className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white"
              >
                <option value="">Semua Kelas</option>
                {kelasOptions.map(k => <option key={k.id} value={k.id}>{k.nama}</option>)}
              </select>
            </div>
          </div>

          <div className="bg-gray-800 shadow overflow-hidden rounded-lg border border-gray-700">
            {loading ? <p className="p-4 text-gray-400">Memuat data bimbingan...</p> : (
              <table className="min-w-full divide-y divide-gray-700">
                <thead className="bg-gray-700">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase w-10">Pilih</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Nama Siswa</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Kelas</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Status</th>
                  </tr>
                </thead>
                <tbody className="bg-gray-800 divide-y divide-gray-700">
                  {filteredSiswa.map(siswa => {
                    const isAssignedToMe = assignedSiswaIds.has(siswa.id);
                    const ownerGuruId = allAssignments.get(siswa.id);
                    // Locked jika punya guru wali TAPI bukan guru yang sedang dipilih
                    const isLocked = ownerGuruId && ownerGuruId !== selectedGuru;
                    const ownerName = isLocked ? getGuruName(ownerGuruId) : '';

                    return (
                      <tr 
                        key={siswa.id} 
                        className={`transition-all duration-300 ${
                            isAssignedToMe 
                                ? 'bg-green-500/10 shadow-[0_0_15px_rgba(34,197,94,0.15)] border-l-4 border-green-500' // Binaan Sendiri
                                : isLocked 
                                    ? 'bg-gray-900 opacity-60' // Terkunci (Punya Orang Lain)
                                    : 'hover:bg-gray-700 border-l-4 border-transparent' // Available
                        }`}
                      >
                        <td className="px-6 py-4 whitespace-nowrap">
                          <input
                            type="checkbox"
                            checked={isAssignedToMe}
                            onChange={() => handleToggleClick(siswa, isAssignedToMe)}
                            disabled={!!isLocked}
                            className={`w-5 h-5 rounded focus:ring-offset-0 ${
                                isLocked 
                                ? 'cursor-not-allowed bg-gray-600 text-gray-500' 
                                : 'cursor-pointer text-green-500 focus:ring-green-500 bg-gray-700 accent-green-600'
                            }`}
                          />
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                            <div className={`font-medium ${
                                isAssignedToMe ? 'text-green-400' : isLocked ? 'text-gray-400' : 'text-white'
                            }`}>
                              {siswa.nama}
                            </div>
                            <div className="text-xs text-gray-500">{siswa.nisn}</div>

                            {/* Keterangan Terkunci */}
                            {isLocked && (
                                <div className="text-xs text-red-400 mt-1 font-semibold flex items-center gap-1">
                                    <span>⛔ Binaan: {ownerName}</span>
                                </div>
                            )}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-gray-300">
                            {siswa.kelas?.nama || '-'}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          {isAssignedToMe ? (
                            <span className="bg-green-900 text-green-200 text-xs px-2 py-1 rounded-full font-bold border border-green-700 shadow-[0_0_5px_rgba(34,197,94,0.4)]">
                                ✓ Binaan Anda
                            </span>
                          ) : isLocked ? (
                            <span className="bg-gray-700 text-gray-400 text-xs px-2 py-1 rounded-full font-bold border border-gray-600">
                                🔒 Terkunci
                            </span>
                          ) : (
                            <span className="text-gray-500 text-xs">-</span>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                  {filteredSiswa.length === 0 && (
                    <tr><td colSpan={4} className="p-6 text-center text-gray-500">
                        Siswa tidak ditemukan.
                    </td></tr>
                  )}
                </tbody>
              </table>
            )}
          </div>
        </>
      )}
    </div>
  );
};

import React, { useEffect, useState, useRef } from 'react';
