  const [siswaList, setSiswaList] = useState<Siswa[]>([]);
  const [kelasOptions, setKelasOptions] = useState<Kelas[]>([]);

  const [selectedGuru, setSelectedGuru] = useState<string>('');
  const [assignedSiswaIds, setAssignedSiswaIds] = useState<Set<string>>(new Set());

  // State untuk Custom Dropdown Guru
  const [isGuruDropdownOpen, setIsGuruDropdownOpen] = useState(false);
  const [guruSearchTerm, setGuruSearchTerm] = useState('');

  // State untuk menyimpan pemetaan global: StudentID -> GuruID
  const [allAssignments, setAllAssignments] = useState<Map<string, string>>(new Map());

  // Confirmation State for Removal
  const [pendingRemoval, setPendingRemoval] = useState<{ id: string; nama: string } | null>(null);

  // Filters
  const [filterKelas, setFilterKelas] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(false);

  // 1. Initial Load: Gurus & Kelas & All Assignments
  useEffect(() => {
    const fetchInitial = async () => {
      // Mengambil data guru dengan peran 'GURU' 
      const { data: gurus } = await supabase
        .from('guru')
        .select('*')
        .eq('peran', 'GURU') 
        .order('nama');

      const { data: kelas } = await supabase.from('kelas').select('*').order('nama');
      const { data: siswa } = await supabase.from('siswa').select('*, kelas(nama)').order('nama');

      if (gurus) setGuruWaliList(gurus);
      if (kelas) setKelasOptions(kelas);
      // @ts-ignore
      if (siswa) setSiswaList(siswa);

      fetchGlobalAssignments();
    };
    fetchInitial();
  }, []);

  // Fetch seluruh data bimbingan untuk validasi global
  const fetchGlobalAssignments = async () => {
      const { data } = await supabase.from('bimbingan').select('id_siswa, id_guru');
      if (data) {
          const map = new Map<string, string>();
          data.forEach(item => map.set(item.id_siswa, item.id_guru));
          setAllAssignments(map);
      }
  };

  // 2. Load Bimbingan when Guru Selected
  useEffect(() => {
    if (selectedGuru) {
      fetchBimbingan();
    } else {
      setAssignedSiswaIds(new Set());
    }
     // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedGuru]);

  const fetchBimbingan = async () => {
    if (!selectedGuru) return;
    setLoading(true);
    const { data } = await supabase.from('bimbingan').select('id_siswa').eq('id_guru', selectedGuru);
    if (data) {
      setAssignedSiswaIds(new Set(data.map(item => item.id_siswa)));
    }
    setLoading(false);
  };

  // Logic to execute DB changes
  const executeToggle = async (id_siswa: string, nama_siswa: string, isAssigned: boolean) => {
    try {
      if (isAssigned) {
        // Remove assignment
        const { error } = await supabase
          .from('bimbingan')
          .delete()
          .eq('id_guru', selectedGuru)
          .eq('id_siswa', id_siswa);
        if (error) throw error;

        showToast(`Berhasil menghapus ${nama_siswa} dari binaan`, 'success');
      } else {
        // Add assignment
        const { error } = await supabase
          .from('bimbingan')
          .insert([{ id_guru: selectedGuru, id_siswa: id_siswa }]);
        if (error) throw error;

        // Tambahkan Toast Sukses
        showToast(`Berhasil menambahkan ${nama_siswa} ke binaan`, 'success', 2000, 'center');
        setSearchTerm(''); 
      }

      // Optimistic update for UI responsiveness
      const newSet = new Set(assignedSiswaIds);
      if (isAssigned) newSet.delete(id_siswa);
      else newSet.add(id_siswa);
      setAssignedSiswaIds(newSet);

      // Refresh global map untuk validasi terbaru
      fetchGlobalAssignments();

    } catch (e) {
      showToast('Gagal mengubah data', 'error');
      fetchBimbingan(); // Revert on error
    }
  };

  // Handler triggered by checkbox click
  const handleToggleClick = (siswa: Siswa, isAssigned: boolean) => {
    if (!selectedGuru) {
      showToast('Pilih Guru Wali terlebih dahulu', 'error');
      return;
    }

    // VALIDASI: Cek apakah siswa sudah punya guru wali LAIN
    const existingGuruId = allAssignments.get(siswa.id);

    // Jika ada pemilik, DAN pemiliknya BUKAN guru yang sedang dipilih
    if (existingGuruId && existingGuruId !== selectedGuru) {
        showToast("⚠️ Siswa ini sudah memiliki guru wali lain!", "error", 4000, "center");
        return; // Batalkan aksi
    }

    if (isAssigned) {
      // Uncheck / Hapus
      setPendingRemoval({ id: siswa.id, nama: siswa.nama });
    } else {
      // Check / Tambah
      executeToggle(siswa.id, siswa.nama, false);
    }
  };

  const handleConfirmRemoval = () => {
    if (pendingRemoval) {
      executeToggle(pendingRemoval.id, pendingRemoval.nama, true);
      setPendingRemoval(null);
    }
  };

  const filteredSiswa = siswaList
    .filter(s => {
      // Filter Pencarian & Kelas
      const matchSearch = s.nama.toLowerCase().includes(searchTerm.toLowerCase()) || s.nisn.includes(searchTerm);
      const matchKelas = filterKelas === '' || s.id_kelas === filterKelas;
      return matchSearch && matchKelas;
    })
    .sort((a, b) => {
      const aAssigned = assignedSiswaIds.has(a.id);
      const bAssigned = assignedSiswaIds.has(b.id);

      const aLocked = allAssignments.has(a.id) && allAssignments.get(a.id) !== selectedGuru;
      const bLocked = allAssignments.has(b.id) && allAssignments.get(b.id) !== selectedGuru;

      if (aAssigned && !bAssigned) return -1;
      if (!aAssigned && bAssigned) return 1;

      if (!aLocked && bLocked) return -1;
      if (aLocked && !bLocked) return 1;

      return a.nama.localeCompare(b.nama);
    });

  // Helper untuk mendapatkan nama guru berdasarkan ID
  const getGuruName = (guruId: string) => {
      const guru = guruWaliList.find(g => g.id === guruId);
      return guru ? guru.nama : 'Guru Lain';
  };

  // --- LOGIC CUSTOM SEARCH DROPDOWN ---
  const filteredGuruList = guruWaliList.filter(g => 
    g.nama.toLowerCase().includes(guruSearchTerm.toLowerCase()) || 
    (g.nip && g.nip.includes(guruSearchTerm))
  );

  const selectedGuruObj = guruWaliList.find(g => g.id === selectedGuru);
  const selectedGuruLabel = selectedGuruObj 
    ? `${selectedGuruObj.nama} - ${selectedGuruObj.nip || 'No NIP'}`
    : '-- Pilih Guru --';

  return (
    <div>
      {/* Dialog Konfirmasi Hapus Anggota */}
      <ConfirmDialog 
        isOpen={!!pendingRemoval}
        message={`Apakah Anda yakin menghapus anggota ${pendingRemoval?.nama}?`}
        onConfirm={handleConfirmRemoval}
        onCancel={() => setPendingRemoval(null)}
      />

      <h2 className="text-2xl font-bold text-white mb-6">Manajemen Anggota GurWal</h2>
      <p className="text-gray-400 mb-4">
        Tetapkan siswa binaan kepada guru.
      </p>

      {/* Main Filter Section */}
      <div className="bg-gray-800 p-6 rounded-lg border border-gray-700 mb-6 relative">
        <label className="block text-sm font-medium text-gray-300 mb-2">Pilih Guru (Calon Guru Wali)</label>

        <div className="flex flex-col md:flex-row gap-4 items-center">
            {/* Custom Searchable Select */}
            <div className="w-full md:w-1/2 relative">
                {/* Trigger Button */}
                <button 
                  onClick={() => setIsGuruDropdownOpen(!isGuruDropdownOpen)}
                  className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white text-left flex justify-between items-center focus:outline-none focus:border-primary"
                >
                    <span className={!selectedGuru ? 'text-gray-400' : 'text-white font-medium'}>
                        {selectedGuruLabel}
                    </span>
                    <span className="text-gray-400 text-xs">▼</span>
                </button>

                {/* Dropdown Content */}
                {isGuruDropdownOpen && (
                    <>
                        {/* Backdrop to close on click outside */}
                        <div 
                           className="fixed inset-0 z-10 cursor-default" 
                           onClick={() => setIsGuruDropdownOpen(false)}
                        ></div>

                        <div className="absolute z-20 w-full bg-gray-700 border border-gray-500 mt-1 rounded shadow-2xl max-h-60 overflow-y-auto overflow-x-hidden">
                             {/* Search Input Sticky Header */}
                             <div className="p-2 sticky top-0 bg-gray-700 border-b border-gray-600">
                                <input
                                    type="text"
                                    placeholder="Cari nama atau NIP..."
                                    value={guruSearchTerm}
                                    onChange={(e) => setGuruSearchTerm(e.target.value)}
                                    autoFocus
                                    className="w-full bg-gray-800 border border-gray-500 rounded px-2 py-1.5 text-sm text-white focus:outline-none focus:border-primary placeholder-gray-500"
                                    onClick={(e) => e.stopPropagation()} // Prevent closing when clicking input
                                />
                             </div>

                             {/* List Options */}
                             {filteredGuruList.length > 0 ? (
                                filteredGuruList.map(g => (
                                    <div 
                                        key={g.id}
                                        onClick={() => {
                                            setSelectedGuru(g.id);
                                            setIsGuruDropdownOpen(false);
                                            setGuruSearchTerm(''); // Optional: clear search after select
                                        }}
                                        className={`px-4 py-2 cursor-pointer text-sm flex flex-col hover:bg-gray-600 transition-colors ${selectedGuru === g.id ? 'bg-primary/20 text-primary' : 'text-white'}`}
                                    >
                                        <span className="font-medium">{g.nama}</span>
                                        <span className="text-xs text-gray-400">{g.nip || 'No NIP'}</span>
                                    </div>
                                ))
                             ) : (
                                <div className="px-4 py-3 text-gray-400 text-sm text-center">
                                    Guru tidak ditemukan.
                                </div>
                             )}
                        </div>
                    </>
                )}
            </div>

            {selectedGuru && (
                 <span className="text-sm text-green-400 bg-green-900/30 px-3 py-1 rounded-full border border-green-800 font-medium animate-pulse">
                    ✅ Guru Terpilih
                 </span>
            )}
        </div>
        {!selectedGuru && <p className="text-yellow-500 text-sm mt-2">Silakan cari dan pilih guru terlebih dahulu untuk mengelola siswa binaannya.</p>}
      </div>

      {/* Siswa List Section */}
      {selectedGuru && (
        <>
          <div className="flex flex-col md:flex-row gap-4 mb-4">
            <div className="flex-1">
              <input
                type="text"
                placeholder="Cari Siswa / NISN..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white placeholder-gray-400"
              />
            </div>
            <div className="w-full md:w-64">
              <select
                value={filterKelas}
                onChange={(e) => setFilterKelas(e.target.value)}
                className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white"
              >
                <option value="">Semua Kelas</option>
                {kelasOptions.map(k => <option key={k.id} value={k.id}>{k.nama}</option>)}
              </select>
            </div>
          </div>

          <div className="bg-gray-800 shadow overflow-hidden rounded-lg border border-gray-700">
            {loading ? <p className="p-4 text-gray-400">Memuat data bimbingan...</p> : (
              <table className="min-w-full divide-y divide-gray-700">
                <thead className="bg-gray-700">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase w-10">Pilih</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Nama Siswa</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Kelas</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Status</th>
                  </tr>
                </thead>
                <tbody className="bg-gray-800 divide-y divide-gray-700">
                  {filteredSiswa.map(siswa => {
                    const isAssignedToMe = assignedSiswaIds.has(siswa.id);
                    const ownerGuruId = allAssignments.get(siswa.id);
                    // Locked jika punya guru wali TAPI bukan guru yang sedang dipilih
                    const isLocked = ownerGuruId && ownerGuruId !== selectedGuru;
                    const ownerName = isLocked ? getGuruName(ownerGuruId) : '';

                    return (
                      <tr 
                        key={siswa.id} 
                        className={`transition-all duration-300 ${
                            isAssignedToMe 
                                ? 'bg-green-500/10 shadow-[0_0_15px_rgba(34,197,94,0.15)] border-l-4 border-green-500' // Binaan Sendiri
                                : isLocked 
                                    ? 'bg-gray-900 opacity-60' // Terkunci (Punya Orang Lain)
                                    : 'hover:bg-gray-700 border-l-4 border-transparent' // Available
                        }`}
                      >
                        <td className="px-6 py-4 whitespace-nowrap">
                          <input
                            type="checkbox"
                            checked={isAssignedToMe}
                            onChange={() => handleToggleClick(siswa, isAssignedToMe)}
                            disabled={!!isLocked}
                            className={`w-5 h-5 rounded focus:ring-offset-0 ${
                                isLocked 
                                ? 'cursor-not-allowed bg-gray-600 text-gray-500' 
                                : 'cursor-pointer text-green-500 focus:ring-green-500 bg-gray-700 accent-green-600'
                            }`}
                          />
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                            <div className={`font-medium ${
                                isAssignedToMe ? 'text-green-400' : isLocked ? 'text-gray-400' : 'text-white'
                            }`}>
                              {siswa.nama}
                            </div>
                            <div className="text-xs text-gray-500">{siswa.nisn}</div>

                            {/* Keterangan Terkunci */}
                            {isLocked && (
                                <div className="text-xs text-red-400 mt-1 font-semibold flex items-center gap-1">
                                    <span>⛔ Binaan: {ownerName}</span>
                                </div>
                            )}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-gray-300">
                            {siswa.kelas?.nama || '-'}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          {isAssignedToMe ? (
                            <span className="bg-green-900 text-green-200 text-xs px-2 py-1 rounded-full font-bold border border-green-700 shadow-[0_0_5px_rgba(34,197,94,0.4)]">
                                ✓ Binaan Anda
                            </span>
                          ) : isLocked ? (
                            <span className="bg-gray-700 text-gray-400 text-xs px-2 py-1 rounded-full font-bold border border-gray-600">
                                🔒 Terkunci
                            </span>
                          ) : (
                            <span className="text-gray-500 text-xs">-</span>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                  {filteredSiswa.length === 0 && (
                    <tr><td colSpan={4} className="p-6 text-center text-gray-500">
                        Siswa tidak ditemukan.
                    </td></tr>
                  )}
                </tbody>
              </table>
            )}
          </div>
        </>
      )}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { supabase } from '../../supabaseClient';
import { Guru } from '../../types';
import * as XLSX from 'xlsx';

interface Props {
  currentUser: Guru;
  showToast: (msg: string, type: 'success' | 'error') => void;
}

export const ImportKehadiranTemplate: React.FC<Props> = ({ currentUser, showToast }) => {
  const [selectedDates, setSelectedDates] = useState<string[]>([]);

  // State Input
  const [singleDate, setSingleDate] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  const [loading, setLoading] = useState(false);
  const [importProgress, setImportProgress] = useState(0); 
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- LOGIC TANGGAL ---

  // 1. Tambah Satu Tanggal
  const handleAddSingleDate = () => {
    if (!singleDate) return;
    if (selectedDates.includes(singleDate)) {
      showToast('Tanggal sudah ada dalam daftar', 'error');
      return;
    }
    const newDates = [...selectedDates, singleDate].sort();
    setSelectedDates(newDates);
    setSingleDate('');
  };

  // 2. Tambah Rentang Tanggal (Multiselect Logic)
  const handleAddRange = () => {
    if (!startDate || !endDate) {
        showToast('Mohon isi Tanggal Mulai dan Tanggal Akhir', 'error');
        return;
    }

    const start = new Date(startDate);
    const end = new Date(endDate);

    if (start > end) {
        showToast('Tanggal Mulai tidak boleh lebih besar dari Tanggal Akhir', 'error');
        return;
    }

    const tempDates: string[] = [];
    let current = new Date(start);

    // Loop dari start sampai end
    while (current <= end) {
        const dateStr = current.toISOString().split('T')[0];
        if (!selectedDates.includes(dateStr)) {
            tempDates.push(dateStr);
        }
        // Increment hari +1
        current.setDate(current.getDate() + 1);
    }

    if (tempDates.length === 0) {
        showToast('Semua tanggal dalam rentang ini sudah terpilih.', 'error');
    } else {
        const combinedDates = [...selectedDates, ...tempDates].sort();
        setSelectedDates(combinedDates);
        setStartDate('');
        setEndDate('');
        showToast(`Berhasil menambahkan ${tempDates.length} tanggal.`, 'success');
    }
  };

  const handleRemoveDate = (dateToRemove: string) => {
    setSelectedDates(selectedDates.filter(d => d !== dateToRemove));
  };

  const handleClearDates = () => {
      setSelectedDates([]);
  };

  // --- LOGIC GENERATE & IMPORT ---

  const handleGenerateTemplate = async () => {
    if (selectedDates.length === 0) {
      showToast('Pilih minimal satu tanggal terlebih dahulu', 'error');
      return;
    }

    setLoading(true);
    try {
      const { data: siswaData, error } = await supabase
        .from('bimbingan')
        .select('*, siswa(id, nama, nisn, kelas(nama))')
        .eq('id_guru', currentUser.id)
        .order('created_at', { ascending: true });

      if (error) throw error;

      if (!siswaData || siswaData.length === 0) {
        showToast('Anda belum memiliki siswa binaan', 'error');
        setLoading(false);
        return;
      }

      const rows = siswaData.map((item, index) => {
        const row: any = {
          NO: index + 1,
          NISN: item.siswa?.nisn || '', 
          NAMA: item.siswa?.nama || '',
          KELAS: item.siswa?.kelas?.nama || '',
        };
        selectedDates.forEach(date => {
          row[date] = ''; 
        });
        return row;
      });

      const ws = XLSX.utils.json_to_sheet(rows);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Kehadiran");

      const filename = `Template_Kehadiran_${new Date().toISOString().split('T')[0]}.xlsx`;
      XLSX.writeFile(wb, filename);

      showToast('Template berhasil dibuat!', 'success');
    } catch (err: any) {
      console.error(err);
      showToast('Gagal membuat template: ' + err.message, 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setImportProgress(0); 
    const reader = new FileReader();

    reader.onload = async (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsName = wb.SheetNames[0];
        const ws = wb.Sheets[wsName];

        const data = XLSX.utils.sheet_to_json(ws);

        if (data.length === 0) {
          showToast('File Excel kosong', 'error');
          setLoading(false);
          return;
        }

        let processedCount = 0;
        let errorCount = 0;
        const totalRows = data.length;

        for (let i = 0; i < totalRows; i++) {
          const row: any = data[i];
          const nisn = row['NISN'] ? String(row['NISN']).trim() : '';
          const nama = row['NAMA'] ? String(row['NAMA']).trim() : '';

          if (!nisn && !nama) {
             const currentProgress = Math.round(((i + 1) / totalRows) * 100);
             setImportProgress(currentProgress);
             continue; 
          }

          let studentId = '';
          const { data: foundSiswa } = await supabase
             .from('siswa')
             .select('id')
             .eq('nisn', nisn)
             .maybeSingle();

          if (foundSiswa) {
            studentId = foundSiswa.id;
          } else {
            const { data: foundSiswaByName } = await supabase
                .from('siswa')
                .select('id')
                .ilike('nama', nama)
                .maybeSingle();
            if (foundSiswaByName) studentId = foundSiswaByName.id;
          }

          if (!studentId) {
            errorCount++;
          } else {
            const keys = Object.keys(row);
            const dateRegex = /^\d{4}-\d{2}-\d{2}$/; 

            for (const key of keys) {
               if (dateRegex.test(key)) {
                  const rawStatus = row[key] ? String(row[key]).trim().toUpperCase() : '';
                  let statusDb: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA' | null = null;

                  if (['H', 'HADIR'].includes(rawStatus)) statusDb = 'HADIR';
                  else if (['S', 'SAKIT'].includes(rawStatus)) statusDb = 'SAKIT';
                  else if (['I', 'IZIN'].includes(rawStatus)) statusDb = 'IZIN';
                  else if (['A', 'ALPHA', 'ALPA'].includes(rawStatus)) statusDb = 'ALPHA';

                  if (statusDb) {
                      const { data: existing } = await supabase
                          .from('kehadiran')
                          .select('id')
                          .eq('id_guru', currentUser.id)
                          .eq('id_siswa', studentId)
                          .eq('tanggal', key)
                          .maybeSingle();

                      if (existing) {
                          await supabase.from('kehadiran').update({ status: statusDb }).eq('id', existing.id);
                      } else {
                          await supabase.from('kehadiran').insert([{
                              id_guru: currentUser.id,
                              id_siswa: studentId,
                              tanggal: key,
                              status: statusDb
                          }]);
                      }
                  }
               }
            }
            processedCount++;
          }

          const currentProgress = Math.round(((i + 1) / totalRows) * 100);
          setImportProgress(currentProgress);
        }

        showToast(`Import selesai. ${processedCount} siswa diproses.`, 'success');
        if (errorCount > 0) {
            setTimeout(() => showToast(`${errorCount} siswa tidak ditemukan di database.`, 'error'), 2000);
        }

      } catch (err: any) {
        console.error(err);
        showToast('Gagal memproses file: ' + err.message, 'error');
      } finally {
        setLoading(false);
        setImportProgress(0);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };

    reader.readAsBinaryString(file);
  };

  return (
    <div className="max-w-4xl mx-auto p-4">
      <h2 className="text-3xl font-bold text-white mb-2">Import Kehadiran (Custom)</h2>
      <p className="text-gray-400 mb-8">
        Fitur ini memungkinkan Anda mengisi absensi untuk beberapa tanggal sekaligus menggunakan Excel.
      </p>

      {/* STEP 1: PILIH TANGGAL */}
      <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-lg mb-6">
        <h3 className="text-lg font-semibold text-blue-400 mb-4">1. Pilih Tanggal & Buat Template</h3>

        <div className="space-y-6">

            {/* OPSI A: Tambah Rentang (Multiselect Logic) */}
            <div className="bg-gray-700/50 p-4 rounded-lg border border-gray-600">
                <label className="block text-sm font-bold text-white mb-3">🅰️ Opsi Cepat: Pilih Rentang Tanggal</label>
                <div className="flex flex-col md:flex-row gap-4 items-end">
                    <div className="flex-1 w-full">
                        <label className="text-xs text-gray-400 block mb-1">Dari Tanggal</label>
                        <input 
                            type="date" 
                            value={startDate}
                            onChange={(e) => setStartDate(e.target.value)}
                            className="bg-gray-700 border border-gray-500 text-white rounded px-3 py-2 w-full focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                        />
                    </div>
                    <div className="flex items-center justify-center pb-2 text-gray-400">
                        ➡️
                    </div>
                    <div className="flex-1 w-full">
                        <label className="text-xs text-gray-400 block mb-1">Sampai Tanggal</label>
                        <input 
                            type="date" 
                            value={endDate}
                            onChange={(e) => setEndDate(e.target.value)}
                            className="bg-gray-700 border border-gray-500 text-white rounded px-3 py-2 w-full focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                        />
                    </div>
                    <button 
                        onClick={handleAddRange}
                        className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded font-medium transition w-full md:w-auto h-[42px]"
                    >
                        + Tambahkan Rentang
                    </button>
                </div>
                <p className="text-xs text-gray-400 mt-2">
                    *Semua tanggal di antara tanggal mulai dan akhir akan ditambahkan ke daftar.
                </p>
            </div>

            {/* OPSI B: Tambah Manual */}
            <div className="bg-gray-700/30 p-4 rounded-lg border border-gray-600 border-dashed">
                <label className="block text-sm font-bold text-gray-300 mb-3">🅱️ Opsi Manual: Tambah Satuan</label>
                <div className="flex flex-col md:flex-row gap-4">
                    <input 
                        type="date" 
                        value={singleDate}
                        onChange={(e) => setSingleDate(e.target.value)}
                        className="bg-gray-700 border border-gray-500 text-white rounded px-3 py-2 w-full md:w-64"
                    />
                    <button 
                        onClick={handleAddSingleDate}
                        className="bg-gray-600 hover:bg-gray-500 text-white px-4 py-2 rounded font-medium transition w-full md:w-auto"
                    >
                        + Tambah
                    </button>
                </div>
            </div>

            {/* Selected Dates Chips */}
            {selectedDates.length > 0 && (
                <div className="bg-gray-900/50 p-4 rounded-lg border border-gray-700">
                    <div className="flex justify-between items-center mb-2">
                        <span className="text-sm font-bold text-gray-300">Daftar Tanggal Terpilih ({selectedDates.length}):</span>
                        <button onClick={handleClearDates} className="text-xs text-red-400 hover:text-red-300 underline">Hapus Semua</button>
                    </div>
                    <div className="flex flex-wrap gap-2 max-h-40 overflow-y-auto custom-scrollbar">
                        {selectedDates.map(date => (
                            <div key={date} className="bg-primary/20 text-primary px-3 py-1 rounded-full text-sm flex items-center gap-2 border border-primary/30">
                                <span>🗓️ {date}</span>
                                <button 
                                    onClick={() => handleRemoveDate(date)}
                                    className="text-red-400 hover:text-red-300 font-bold px-1 hover:bg-white/10 rounded"
                                >
                                    &times;
                                </button>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            <div className="border-t border-gray-700 pt-4">
                <button 
                    onClick={handleGenerateTemplate}
                    disabled={loading || selectedDates.length === 0}
                    className="w-full bg-green-600 hover:bg-green-700 text-white px-6 py-3 rounded-lg font-bold transition shadow-lg flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    {loading ? 'Memproses...' : '📥 Buat & Download Template Excel'}
                </button>
            </div>
        </div>
      </div>

      {/* STEP 2: UPLOAD */}
      <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-lg">
        <h3 className="text-lg font-semibold text-green-400 mb-4">2. Upload & Import Data</h3>
        <p className="text-sm text-gray-400 mb-4">
            Isi file Excel yang telah diunduh dengan kode: <strong>H</strong> (Hadir), <strong>S</strong> (Sakit), <strong>I</strong> (Izin), <strong>A</strong> (Alpha).
        </p>

        <div className="flex flex-col items-center justify-center border-2 border-dashed border-gray-600 rounded-lg p-10 bg-gray-700/30 hover:bg-gray-700/50 transition relative">
            <input 
                type="file" 
                accept=".xlsx, .xls"
                ref={fileInputRef}
                onChange={handleFileUpload}
                disabled={loading}
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" 
                id="file-upload"
            />
            <div className="text-center pointer-events-none">
                <span className="text-4xl mb-2 block">📂</span>
                <span className="text-white font-medium mb-1 block">Klik atau Seret File Excel ke Sini</span>
                <span className="text-xs text-gray-500 block">Format .xlsx atau .xls</span>
            </div>
        </div>
      </div>

      {/* PROGRESS OVERLAY */}
      {loading && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-80">
          <div className="bg-gray-800 p-6 rounded-lg border border-gray-700 w-80 md:w-96 text-center">
            <h3 className="text-white font-bold mb-4 text-lg">Memproses Data...</h3>
            <div className="w-full bg-gray-700 rounded-full h-4 mb-2 overflow-hidden">
               <div 
                 className="bg-green-500 h-4 rounded-full transition-all duration-300" 
                 style={{ width: `${importProgress}%` }}
               ></div>
            </div>
            <p className="text-gray-300 font-medium">{importProgress}%</p>
            <p className="text-gray-500 text-sm mt-1">Mohon jangan tutup halaman ini.</p>
          </div>
        </div>
      )}

    </div>
  );
};

import React, { useEffect, useState, useRef } from 'react';
import { supabase } from '../supabaseClient';
import { Guru, Siswa, Kelas } from '../types';
import { ConfirmDialog } from './ConfirmDialog';

interface CrudAnggotaGurwalProps {
  showToast: (msg: string, type: 'success' | 'error', duration?: number, position?: 'top-right' | 'center') => void;
}

export const CrudAnggotaGurwal: React.FC<CrudAnggotaGurwalProps> = ({ showToast }) => {
  const [guruWaliList, setGuruWaliList] = useState<Guru[]>([]);
  const [siswaList, setSiswaList] = useState<Siswa[]>([]);
  const [kelasOptions, setKelasOptions] = useState<Kelas[]>([]);

  const [selectedGuru, setSelectedGuru] = useState<string>('');
  const [assignedSiswaIds, setAssignedSiswaIds] = useState<Set<string>>(new Set());

  // State untuk Custom Dropdown Guru
  const [isGuruDropdownOpen, setIsGuruDropdownOpen] = useState(false);
  const [guruSearchTerm, setGuruSearchTerm] = useState('');

  // State untuk menyimpan pemetaan global: StudentID -> GuruID
  const [allAssignments, setAllAssignments] = useState<Map<string, string>>(new Map());

  // Confirmation State for Removal (Uncheck)
  const [pendingRemoval, setPendingRemoval] = useState<{ id: string; nama: string } | null>(null);

  // Confirmation State for Transfer (Pindah Guru)
  const [pendingTransfer, setPendingTransfer] = useState<{ 
      siswaId: string; 
      siswaNama: string; 
      oldGuruId: string; 
      oldGuruNama: string 
  } | null>(null);

  // Filters
  const [filterKelas, setFilterKelas] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(false);

  // 1. Initial Load: Gurus & Kelas & All Assignments
  useEffect(() => {
    const fetchInitial = async () => {
      // Mengambil data guru dengan peran 'GURU' 
      const { data: gurus } = await supabase
        .from('guru')
        .select('*')
        .eq('peran', 'GURU') 
        .order('nama');

      const { data: kelas } = await supabase.from('kelas').select('*').order('nama');
      const { data: siswa } = await supabase.from('siswa').select('*, kelas(nama)').order('nama');

      if (gurus) setGuruWaliList(gurus);
      if (kelas) setKelasOptions(kelas);
      // @ts-ignore
      if (siswa) setSiswaList(siswa);

      fetchGlobalAssignments();
    };
    fetchInitial();
  }, []);

  // Fetch seluruh data bimbingan untuk validasi global
  const fetchGlobalAssignments = async () => {
      const { data } = await supabase.from('bimbingan').select('id_siswa, id_guru');
      if (data) {
          const map = new Map<string, string>();
          data.forEach(item => map.set(item.id_siswa, item.id_guru));
          setAllAssignments(map);
      }
  };

  // 2. Load Bimbingan when Guru Selected
  useEffect(() => {
    if (selectedGuru) {
      fetchBimbingan();
    } else {
      setAssignedSiswaIds(new Set());
    }
     // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedGuru]);

  const fetchBimbingan = async () => {
    if (!selectedGuru) return;
    setLoading(true);
    const { data } = await supabase.from('bimbingan').select('id_siswa').eq('id_guru', selectedGuru);
    if (data) {
      setAssignedSiswaIds(new Set(data.map(item => item.id_siswa)));
    }
    setLoading(false);
  };

  // Logic to execute DB changes (Add/Remove for current guru)
  const executeToggle = async (id_siswa: string, nama_siswa: string, isAssigned: boolean) => {
    try {
      if (isAssigned) {
        // Remove assignment
        const { error } = await supabase
          .from('bimbingan')
          .delete()
          .eq('id_guru', selectedGuru)
          .eq('id_siswa', id_siswa);
        if (error) throw error;

        showToast(`Berhasil menghapus ${nama_siswa} dari binaan`, 'success');
      } else {
        // Add assignment
        const { error } = await supabase
          .from('bimbingan')
          .insert([{ id_guru: selectedGuru, id_siswa: id_siswa }]);
        if (error) throw error;

        // Tambahkan Toast Sukses
        showToast(`Berhasil menambahkan ${nama_siswa} ke binaan`, 'success', 2000, 'center');
        setSearchTerm(''); 
      }

      // Optimistic update for UI responsiveness
      const newSet = new Set(assignedSiswaIds);
      if (isAssigned) newSet.delete(id_siswa);
      else newSet.add(id_siswa);
      setAssignedSiswaIds(newSet);

      // Refresh global map untuk validasi terbaru
      fetchGlobalAssignments();

    } catch (e) {
      showToast('Gagal mengubah data', 'error');
      fetchBimbingan(); // Revert on error
    }
  };

  // Logic to execute Transfer (Move from Old Guru -> Current Guru)
  const executeTransfer = async () => {
      if (!pendingTransfer || !selectedGuru) return;

      try {
          // 1. Hapus data bimbingan lama (berdasarkan id_siswa, karena 1 siswa 1 wali)
          const { error: delError } = await supabase
            .from('bimbingan')
            .delete()
            .eq('id_siswa', pendingTransfer.siswaId);

          if (delError) throw delError;

          // 2. Tambahkan data bimbingan baru
          const { error: insError } = await supabase
            .from('bimbingan')
            .insert([{ id_guru: selectedGuru, id_siswa: pendingTransfer.siswaId }]);

          if (insError) throw insError;

          showToast(`Berhasil memindahkan ${pendingTransfer.siswaNama} ke guru ini.`, 'success');

          // Update UI
          const newSet = new Set(assignedSiswaIds);
          newSet.add(pendingTransfer.siswaId);
          setAssignedSiswaIds(newSet);

          fetchGlobalAssignments();
          setPendingTransfer(null);

      } catch (error) {
          console.error(error);
          showToast('Gagal memindahkan siswa.', 'error');
      }
  };

  // Handler triggered by checkbox click
  const handleToggleClick = (siswa: Siswa, isAssigned: boolean) => {
    if (!selectedGuru) {
      showToast('Pilih Guru Wali terlebih dahulu', 'error');
      return;
    }

    // Cek apakah milik orang lain
    const existingGuruId = allAssignments.get(siswa.id);
    if (existingGuruId && existingGuruId !== selectedGuru) {
        // Tombol checkbox didisable untuk kasus ini, 
        // tapi jika dipanggil manual, kita blokir.
        // Logika pindah ada di tombol "Pindah" terpisah.
        return; 
    }

    if (isAssigned) {
      // Uncheck / Hapus
      setPendingRemoval({ id: siswa.id, nama: siswa.nama });
    } else {
      // Check / Tambah
      executeToggle(siswa.id, siswa.nama, false);
    }
  };

  const handleConfirmRemoval = () => {
    if (pendingRemoval) {
      executeToggle(pendingRemoval.id, pendingRemoval.nama, true);
      setPendingRemoval(null);
    }
  };

  const filteredSiswa = siswaList
    .filter(s => {
      // Filter Pencarian & Kelas
      const matchSearch = s.nama.toLowerCase().includes(searchTerm.toLowerCase()) || s.nisn.includes(searchTerm);
      const matchKelas = filterKelas === '' || s.id_kelas === filterKelas;
      return matchSearch && matchKelas;
    })
    .sort((a, b) => {
      const aAssigned = assignedSiswaIds.has(a.id);
      const bAssigned = assignedSiswaIds.has(b.id);

      const aLocked = allAssignments.has(a.id) && allAssignments.get(a.id) !== selectedGuru;
      const bLocked = allAssignments.has(b.id) && allAssignments.get(b.id) !== selectedGuru;

      if (aAssigned && !bAssigned) return -1;
      if (!aAssigned && bAssigned) return 1;

      if (!aLocked && bLocked) return -1;
      if (aLocked && !bLocked) return 1;

      return a.nama.localeCompare(b.nama);
    });

  // Helper untuk mendapatkan nama guru berdasarkan ID
  const getGuruName = (guruId: string) => {
      const guru = guruWaliList.find(g => g.id === guruId);
      return guru ? guru.nama : 'Guru Lain';
  };

  // --- LOGIC CUSTOM SEARCH DROPDOWN ---
  const filteredGuruList = guruWaliList.filter(g => 
    g.nama.toLowerCase().includes(guruSearchTerm.toLowerCase()) || 
    (g.nip && g.nip.includes(guruSearchTerm))
  );

  const selectedGuruObj = guruWaliList.find(g => g.id === selectedGuru);
  const selectedGuruLabel = selectedGuruObj 
    ? `${selectedGuruObj.nama} - ${selectedGuruObj.nip || 'No NIP'}`
    : '-- Pilih Guru --';

  return (
    <div>
      {/* Dialog Konfirmasi Hapus Anggota */}
      <ConfirmDialog 
        isOpen={!!pendingRemoval}
        message={`Apakah Anda yakin menghapus anggota ${pendingRemoval?.nama} dari binaan guru ini?`}
        onConfirm={handleConfirmRemoval}
        onCancel={() => setPendingRemoval(null)}
      />

      {/* Dialog Konfirmasi Pindah Anggota */}
      <ConfirmDialog 
        isOpen={!!pendingTransfer}
        message={`Konfirmasi Pindah: Apakah Anda yakin ingin memindahkan siswa "${pendingTransfer?.siswaNama}" dari ${pendingTransfer?.oldGuruNama} ke guru yang sedang dipilih?`}
        onConfirm={executeTransfer}
        onCancel={() => setPendingTransfer(null)}
      />

      <h2 className="text-2xl font-bold text-white mb-6">Manajemen Anggota GurWal</h2>
      <p className="text-gray-400 mb-4">
        Tetapkan siswa binaan kepada guru.
      </p>

      {/* Main Filter Section */}
      <div className="bg-gray-800 p-6 rounded-lg border border-gray-700 mb-6 relative">
        <label className="block text-sm font-medium text-gray-300 mb-2">Pilih Guru (Calon Guru Wali)</label>

        <div className="flex flex-col md:flex-row gap-4 items-center">
            {/* Custom Searchable Select */}
            <div className="w-full md:w-1/2 relative">
                {/* Trigger Button */}
                <button 
                  onClick={() => setIsGuruDropdownOpen(!isGuruDropdownOpen)}
                  className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white text-left flex justify-between items-center focus:outline-none focus:border-primary"
                >
                    <span className={!selectedGuru ? 'text-gray-400' : 'text-white font-medium'}>
                        {selectedGuruLabel}
                    </span>
                    <span className="text-gray-400 text-xs">▼</span>
                </button>

                {/* Dropdown Content */}
                {isGuruDropdownOpen && (
                    <>
                        {/* Backdrop to close on click outside */}
                        <div 
                           className="fixed inset-0 z-10 cursor-default" 
                           onClick={() => setIsGuruDropdownOpen(false)}
                        ></div>

                        <div className="absolute z-20 w-full bg-gray-700 border border-gray-500 mt-1 rounded shadow-2xl max-h-60 overflow-y-auto overflow-x-hidden">
                             {/* Search Input Sticky Header */}
                             <div className="p-2 sticky top-0 bg-gray-700 border-b border-gray-600">
                                <input
                                    type="text"
                                    placeholder="Cari nama atau NIP..."
                                    value={guruSearchTerm}
                                    onChange={(e) => setGuruSearchTerm(e.target.value)}
                                    autoFocus
                                    className="w-full bg-gray-800 border border-gray-500 rounded px-2 py-1.5 text-sm text-white focus:outline-none focus:border-primary placeholder-gray-500"
                                    onClick={(e) => e.stopPropagation()} // Prevent closing when clicking input
                                />
                             </div>

                             {/* List Options */}
                             {filteredGuruList.length > 0 ? (
                                filteredGuruList.map(g => (
                                    <div 
                                        key={g.id}
                                        onClick={() => {
                                            setSelectedGuru(g.id);
                                            setIsGuruDropdownOpen(false);
                                            setGuruSearchTerm(''); // Optional: clear search after select
                                        }}
                                        className={`px-4 py-2 cursor-pointer text-sm flex flex-col hover:bg-gray-600 transition-colors ${selectedGuru === g.id ? 'bg-primary/20 text-primary' : 'text-white'}`}
                                    >
                                        <span className="font-medium">{g.nama}</span>
                                        <span className="text-xs text-gray-400">{g.nip || 'No NIP'}</span>
                                    </div>
                                ))
                             ) : (
                                <div className="px-4 py-3 text-gray-400 text-sm text-center">
                                    Guru tidak ditemukan.
                                </div>
                             )}
                        </div>
                    </>
                )}
            </div>

            {selectedGuru && (
                 <span className="text-sm text-green-400 bg-green-900/30 px-3 py-1 rounded-full border border-green-800 font-medium animate-pulse">
                    ✅ Guru Terpilih
                 </span>
            )}
        </div>
        {!selectedGuru && <p className="text-yellow-500 text-sm mt-2">Silakan cari dan pilih guru terlebih dahulu untuk mengelola siswa binaannya.</p>}
      </div>

      {/* Siswa List Section */}
      {selectedGuru && (
        <>
          <div className="flex flex-col md:flex-row gap-4 mb-4">
            <div className="flex-1">
              <input
                type="text"
                placeholder="Cari Siswa / NISN..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white placeholder-gray-400"
              />
            </div>
            <div className="w-full md:w-64">
              <select
                value={filterKelas}
                onChange={(e) => setFilterKelas(e.target.value)}
                className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white"
              >
                <option value="">Semua Kelas</option>
                {kelasOptions.map(k => <option key={k.id} value={k.id}>{k.nama}</option>)}
              </select>
            </div>
          </div>

          <div className="bg-gray-800 shadow overflow-hidden rounded-lg border border-gray-700">
            {loading ? <p className="p-4 text-gray-400">Memuat data bimbingan...</p> : (
              <table className="min-w-full divide-y divide-gray-700">
                <thead className="bg-gray-700">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase w-10">Pilih</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Nama Siswa</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Kelas</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Aksi</th>
                  </tr>
                </thead>
                <tbody className="bg-gray-800 divide-y divide-gray-700">
                  {filteredSiswa.map(siswa => {
                    const isAssignedToMe = assignedSiswaIds.has(siswa.id);
                    const ownerGuruId = allAssignments.get(siswa.id);
                    // Locked jika punya guru wali TAPI bukan guru yang sedang dipilih
                    const isLocked = ownerGuruId && ownerGuruId !== selectedGuru;
                    const ownerName = isLocked ? getGuruName(ownerGuruId) : '';

                    return (
                      <tr 
                        key={siswa.id} 
                        className={`transition-all duration-300 ${
                            isAssignedToMe 
                                ? 'bg-green-500/10 shadow-[0_0_15px_rgba(34,197,94,0.15)] border-l-4 border-green-500' // Binaan Sendiri
                                : isLocked 
                                    ? 'bg-gray-900/50' // Milik orang lain (agak gelap)
                                    : 'hover:bg-gray-700 border-l-4 border-transparent' // Available
                        }`}
                      >
                        <td className="px-6 py-4 whitespace-nowrap">
                          <input
                            type="checkbox"
                            checked={isAssignedToMe}
                            onChange={() => handleToggleClick(siswa, isAssignedToMe)}
                            disabled={!!isLocked}
                            className={`w-5 h-5 rounded focus:ring-offset-0 ${
                                isLocked 
                                ? 'cursor-not-allowed bg-gray-600 text-gray-500' 
                                : 'cursor-pointer text-green-500 focus:ring-green-500 bg-gray-700 accent-green-600'
                            }`}
                          />
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                            <div className={`font-medium ${
                                isAssignedToMe ? 'text-green-400' : isLocked ? 'text-gray-300' : 'text-white'
                            }`}>
                              {siswa.nama}
                            </div>
                            <div className="text-xs text-gray-500">{siswa.nisn}</div>

                            {/* Keterangan Terkunci */}
                            {isLocked && (
                                <div className="text-xs text-yellow-500 mt-1 flex items-center gap-1 italic">
                                    <span>🔒 Telah menjadi anggota {ownerName}</span>
                                </div>
                            )}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-gray-300">
                            {siswa.kelas?.nama || '-'}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          {isAssignedToMe ? (
                            <span className="bg-green-900 text-green-200 text-xs px-2 py-1 rounded-full font-bold border border-green-700 shadow-[0_0_5px_rgba(34,197,94,0.4)]">
                                ✓ Binaan Anda
                            </span>
                          ) : isLocked ? (
                            <button
                                onClick={() => setPendingTransfer({
                                    siswaId: siswa.id,
                                    siswaNama: siswa.nama,
                                    oldGuruId: ownerGuruId!,
                                    oldGuruNama: ownerName
                                })}
                                className="bg-yellow-700 hover:bg-yellow-600 text-white text-xs px-3 py-1.5 rounded-full font-medium transition shadow-sm border border-yellow-600"
                            >
                                ↔ Pindah Anggota
                            </button>
                          ) : (
                            <span className="text-gray-500 text-xs">-</span>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                  {filteredSiswa.length === 0 && (
                    <tr><td colSpan={4} className="p-6 text-center text-gray-500">
                        Siswa tidak ditemukan.
                    </td></tr>
                  )}
                </tbody>
              </table>
            )}
          </div>
        </>
      )}
    </div>
  );
};

import React, { useEffect, useState, useRef } from 'react';
import { supabase } from '../supabaseClient';
import { Guru, Siswa, Kelas } from '../types';
import { ConfirmDialog } from './ConfirmDialog';
import * as XLSX from 'xlsx';

interface CrudAnggotaGurwalProps {
  showToast: (msg: string, type: 'success' | 'error', duration?: number, position?: 'top-right' | 'center') => void;
}

export const CrudAnggotaGurwal: React.FC<CrudAnggotaGurwalProps> = ({ showToast }) => {
  const [guruWaliList, setGuruWaliList] = useState<Guru[]>([]);
  const [siswaList, setSiswaList] = useState<Siswa[]>([]);
  const [kelasOptions, setKelasOptions] = useState<Kelas[]>([]);

  const [selectedGuru, setSelectedGuru] = useState<string>('');
  const [assignedSiswaIds, setAssignedSiswaIds] = useState<Set<string>>(new Set());

  // State untuk Custom Dropdown Guru
  const [isGuruDropdownOpen, setIsGuruDropdownOpen] = useState(false);
  const [guruSearchTerm, setGuruSearchTerm] = useState('');

  // State untuk menyimpan pemetaan global: StudentID -> GuruID
  const [allAssignments, setAllAssignments] = useState<Map<string, string>>(new Map());

  // Confirmation State for Removal (Uncheck)
  const [pendingRemoval, setPendingRemoval] = useState<{ id: string; nama: string } | null>(null);

  // Confirmation State for Transfer (Pindah Guru)
  const [pendingTransfer, setPendingTransfer] = useState<{ 
      siswaId: string; 
      siswaNama: string; 
      oldGuruId: string; 
      oldGuruNama: string 
  } | null>(null);

  // Filters
  const [filterKelas, setFilterKelas] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(false);

  // 1. Initial Load: Gurus & Kelas & All Assignments
  useEffect(() => {
    const fetchInitial = async () => {
      // Mengambil data guru dengan peran 'GURU' 
      const { data: gurus } = await supabase
        .from('guru')
        .select('*')
        .eq('peran', 'GURU') 
        .order('nama');

      const { data: kelas } = await supabase.from('kelas').select('*').order('nama');
      const { data: siswa } = await supabase.from('siswa').select('*, kelas(nama)').order('nama');

      if (gurus) setGuruWaliList(gurus);
      if (kelas) setKelasOptions(kelas);
      // @ts-ignore
      if (siswa) setSiswaList(siswa);

      fetchGlobalAssignments();
    };
    fetchInitial();
  }, []);

  // Fetch seluruh data bimbingan untuk validasi global
  const fetchGlobalAssignments = async () => {
      const { data } = await supabase.from('bimbingan').select('id_siswa, id_guru');
      if (data) {
          const map = new Map<string, string>();
          data.forEach(item => map.set(item.id_siswa, item.id_guru));
          setAllAssignments(map);
      }
  };

  // 2. Load Bimbingan when Guru Selected
  useEffect(() => {
    if (selectedGuru) {
      fetchBimbingan();
    } else {
      setAssignedSiswaIds(new Set());
    }
     // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedGuru]);

  const fetchBimbingan = async () => {
    if (!selectedGuru) return;
    setLoading(true);
    const { data } = await supabase.from('bimbingan').select('id_siswa').eq('id_guru', selectedGuru);
    if (data) {
      setAssignedSiswaIds(new Set(data.map(item => item.id_siswa)));
    }
    setLoading(false);
  };

  // Logic to execute DB changes (Add/Remove for current guru)
  const executeToggle = async (id_siswa: string, nama_siswa: string, isAssigned: boolean) => {
    try {
      if (isAssigned) {
        // Remove assignment
        const { error } = await supabase
          .from('bimbingan')
          .delete()
          .eq('id_guru', selectedGuru)
          .eq('id_siswa', id_siswa);
        if (error) throw error;

        showToast(`Berhasil menghapus ${nama_siswa} dari binaan`, 'success');
      } else {
        // Add assignment
        const { error } = await supabase
          .from('bimbingan')
          .insert([{ id_guru: selectedGuru, id_siswa: id_siswa }]);
        if (error) throw error;

        // Tambahkan Toast Sukses
        showToast(`Berhasil menambahkan ${nama_siswa} ke binaan`, 'success', 2000, 'center');
        setSearchTerm(''); 
      }

      // Optimistic update for UI responsiveness
      const newSet = new Set(assignedSiswaIds);
      if (isAssigned) newSet.delete(id_siswa);
      else newSet.add(id_siswa);
      setAssignedSiswaIds(newSet);

      // Refresh global map untuk validasi terbaru
      fetchGlobalAssignments();

    } catch (e) {
      showToast('Gagal mengubah data', 'error');
      fetchBimbingan(); // Revert on error
    }
  };

  // Logic to execute Transfer (Move from Old Guru -> Current Guru)
  const executeTransfer = async () => {
      if (!pendingTransfer || !selectedGuru) return;

      try {
          // 1. Hapus data bimbingan lama (berdasarkan id_siswa, karena 1 siswa 1 wali)
          const { error: delError } = await supabase
            .from('bimbingan')
            .delete()
            .eq('id_siswa', pendingTransfer.siswaId);

          if (delError) throw delError;

          // 2. Tambahkan data bimbingan baru
          const { error: insError } = await supabase
            .from('bimbingan')
            .insert([{ id_guru: selectedGuru, id_siswa: pendingTransfer.siswaId }]);

          if (insError) throw insError;

          showToast(`Berhasil memindahkan ${pendingTransfer.siswaNama} ke guru ini.`, 'success');

          // Update UI
          const newSet = new Set(assignedSiswaIds);
          newSet.add(pendingTransfer.siswaId);
          setAssignedSiswaIds(newSet);

          fetchGlobalAssignments();
          setPendingTransfer(null);

      } catch (error) {
          console.error(error);
          showToast('Gagal memindahkan siswa.', 'error');
      }
  };

  // Handler triggered by checkbox click
  const handleToggleClick = (siswa: Siswa, isAssigned: boolean) => {
    if (!selectedGuru) {
      showToast('Pilih Guru Wali terlebih dahulu', 'error');
      return;
    }

    // Cek apakah milik orang lain
    const existingGuruId = allAssignments.get(siswa.id);
    if (existingGuruId && existingGuruId !== selectedGuru) {
        // Tombol checkbox didisable untuk kasus ini, 
        // tapi jika dipanggil manual, kita blokir.
        // Logika pindah ada di tombol "Pindah" terpisah.
        return; 
    }

    if (isAssigned) {
      // Uncheck / Hapus
      setPendingRemoval({ id: siswa.id, nama: siswa.nama });
    } else {
      // Check / Tambah
      executeToggle(siswa.id, siswa.nama, false);
    }
  };

  const handleConfirmRemoval = () => {
    if (pendingRemoval) {
      executeToggle(pendingRemoval.id, pendingRemoval.nama, true);
      setPendingRemoval(null);
    }
  };

  // --- EXPORT FUNCTION ---
  const handleExport = () => {
    if (allAssignments.size === 0) {
        showToast('Belum ada data anggota yang terdaftar.', 'error');
        return;
    }

    let dataToExport: any[] = [];
    let fileName = '';

    if (selectedGuru) {
        // 1. EKSPOR PER GURU
        const guru = guruWaliList.find(g => g.id === selectedGuru);
        const guruName = guru ? guru.nama : 'Unknown';
        fileName = `Binaan_${guruName.replace(/\s+/g, '_')}.xlsx`;

        // Filter siswa yang dipetakan ke guru ini
        const myStudentIds = Array.from(allAssignments.entries())
            .filter(([_, gId]) => gId === selectedGuru)
            .map(([sId, _]) => sId);

        const myStudents = siswaList.filter(s => myStudentIds.includes(s.id));

        dataToExport = myStudents.map((s, index) => ({
            'No': index + 1,
            'Nama Guru Wali': guruName,
            'Nama Siswa Binaan': s.nama,
            'NISN': s.nisn,
            'Kelas': s.kelas?.nama || '-'
        }));

    } else {
        // 2. EKSPOR SEMUA
        fileName = `Semua_Anggota_Gurwal_${new Date().toISOString().split('T')[0]}.xlsx`;

        const allEntries = Array.from(allAssignments.entries());

        let counter = 1;
        dataToExport = allEntries.map(([studentId, guruId]) => {
            const guru = guruWaliList.find(g => g.id === guruId);
            const siswa = siswaList.find(s => s.id === studentId);

            if (!guru || !siswa) return null;

            return {
                'No': 0, // Placeholder, will set later
                'Nama Guru Wali': guru.nama,
                'Nama Siswa Binaan': siswa.nama,
                'NISN': siswa.nisn,
                'Kelas': siswa.kelas?.nama || '-'
            };
        })
        .filter(item => item !== null)
        .sort((a: any, b: any) => {
             // Sort by Guru Name first, then Student Name
             const guruCompare = a['Nama Guru Wali'].localeCompare(b['Nama Guru Wali']);
             if (guruCompare !== 0) return guruCompare;
             return a['Nama Siswa Binaan'].localeCompare(b['Nama Siswa Binaan']);
        })
        .map((item: any, index) => ({ ...item, 'No': index + 1 })); // Re-index after sort
    }

    if (dataToExport.length === 0) {
        showToast('Tidak ada data siswa binaan untuk diekspor.', 'error');
        return;
    }

    // Create Excel
    const ws = XLSX.utils.json_to_sheet(dataToExport);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Data Binaan");
    XLSX.writeFile(wb, fileName);

    showToast('Data berhasil diekspor!', 'success');
  };

  const filteredSiswa = siswaList
    .filter(s => {
      // Filter Pencarian & Kelas
      const matchSearch = s.nama.toLowerCase().includes(searchTerm.toLowerCase()) || s.nisn.includes(searchTerm);
      const matchKelas = filterKelas === '' || s.id_kelas === filterKelas;
      return matchSearch && matchKelas;
    })
    .sort((a, b) => {
      const aAssigned = assignedSiswaIds.has(a.id);
      const bAssigned = assignedSiswaIds.has(b.id);

      const aLocked = allAssignments.has(a.id) && allAssignments.get(a.id) !== selectedGuru;
      const bLocked = allAssignments.has(b.id) && allAssignments.get(b.id) !== selectedGuru;

      if (aAssigned && !bAssigned) return -1;
      if (!aAssigned && bAssigned) return 1;

      if (!aLocked && bLocked) return -1;
      if (aLocked && !bLocked) return 1;

      return a.nama.localeCompare(b.nama);
    });

  // Helper untuk mendapatkan nama guru berdasarkan ID
  const getGuruName = (guruId: string) => {
      const guru = guruWaliList.find(g => g.id === guruId);
      return guru ? guru.nama : 'Guru Lain';
  };

  // --- LOGIC CUSTOM SEARCH DROPDOWN ---
  const filteredGuruList = guruWaliList.filter(g => 
    g.nama.toLowerCase().includes(guruSearchTerm.toLowerCase()) || 
    (g.nip && g.nip.includes(guruSearchTerm))
  );

  const selectedGuruObj = guruWaliList.find(g => g.id === selectedGuru);
  const selectedGuruLabel = selectedGuruObj 
    ? `${selectedGuruObj.nama} - ${selectedGuruObj.nip || 'No NIP'}`
    : '-- Pilih Guru --';

  return (
    <div>
      {/* Dialog Konfirmasi Hapus Anggota */}
      <ConfirmDialog 
        isOpen={!!pendingRemoval}
        message={`Apakah Anda yakin menghapus anggota ${pendingRemoval?.nama} dari binaan guru ini?`}
        onConfirm={handleConfirmRemoval}
        onCancel={() => setPendingRemoval(null)}
      />

      {/* Dialog Konfirmasi Pindah Anggota */}
      <ConfirmDialog 
        isOpen={!!pendingTransfer}
        message={`Konfirmasi Pindah: Apakah Anda yakin ingin memindahkan siswa "${pendingTransfer?.siswaNama}" dari ${pendingTransfer?.oldGuruNama} ke guru yang sedang dipilih?`}
        onConfirm={executeTransfer}
        onCancel={() => setPendingTransfer(null)}
      />

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <div>
            <h2 className="text-2xl font-bold text-white">Manajemen Anggota GurWal</h2>
            <p className="text-gray-400 mt-1">
                Tetapkan siswa binaan kepada guru.
            </p>
        </div>
        <button 
            onClick={handleExport}
            className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg font-medium transition shadow-lg flex items-center gap-2"
        >
            <span>📊</span>
            {selectedGuru ? 'Ekspor Data (Guru Ini)' : 'Ekspor Semua Data'}
        </button>
      </div>

      {/* Main Filter Section */}
      <div className="bg-gray-800 p-6 rounded-lg border border-gray-700 mb-6 relative">
        <label className="block text-sm font-medium text-gray-300 mb-2">Pilih Guru (Calon Guru Wali)</label>

        <div className="flex flex-col md:flex-row gap-4 items-center">
            {/* Custom Searchable Select */}
            <div className="w-full md:w-1/2 relative">
                {/* Trigger Button */}
                <button 
                  onClick={() => setIsGuruDropdownOpen(!isGuruDropdownOpen)}
                  className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white text-left flex justify-between items-center focus:outline-none focus:border-primary"
                >
                    <span className={!selectedGuru ? 'text-gray-400' : 'text-white font-medium'}>
                        {selectedGuruLabel}
                    </span>
                    <span className="text-gray-400 text-xs">▼</span>
                </button>

                {/* Dropdown Content */}
                {isGuruDropdownOpen && (
                    <>
                        {/* Backdrop to close on click outside */}
                        <div 
                           className="fixed inset-0 z-10 cursor-default" 
                           onClick={() => setIsGuruDropdownOpen(false)}
                        ></div>

                        <div className="absolute z-20 w-full bg-gray-700 border border-gray-500 mt-1 rounded shadow-2xl max-h-60 overflow-y-auto overflow-x-hidden">
                             {/* Search Input Sticky Header */}
                             <div className="p-2 sticky top-0 bg-gray-700 border-b border-gray-600">
                                <input
                                    type="text"
                                    placeholder="Cari nama atau NIP..."
                                    value={guruSearchTerm}
                                    onChange={(e) => setGuruSearchTerm(e.target.value)}
                                    autoFocus
                                    className="w-full bg-gray-800 border border-gray-500 rounded px-2 py-1.5 text-sm text-white focus:outline-none focus:border-primary placeholder-gray-500"
                                    onClick={(e) => e.stopPropagation()} // Prevent closing when clicking input
                                />
                             </div>

                             {/* List Options */}
                             {filteredGuruList.length > 0 ? (
                                filteredGuruList.map(g => (
                                    <div 
                                        key={g.id}
                                        onClick={() => {
                                            setSelectedGuru(g.id);
                                            setIsGuruDropdownOpen(false);
                                            setGuruSearchTerm(''); // Optional: clear search after select
                                        }}
                                        className={`px-4 py-2 cursor-pointer text-sm flex flex-col hover:bg-gray-600 transition-colors ${selectedGuru === g.id ? 'bg-primary/20 text-primary' : 'text-white'}`}
                                    >
                                        <span className="font-medium">{g.nama}</span>
                                        <span className="text-xs text-gray-400">{g.nip || 'No NIP'}</span>
                                    </div>
                                ))
                             ) : (
                                <div className="px-4 py-3 text-gray-400 text-sm text-center">
                                    Guru tidak ditemukan.
                                </div>
                             )}
                        </div>
                    </>
                )}
            </div>

            {selectedGuru && (
                 <span className="text-sm text-green-400 bg-green-900/30 px-3 py-1 rounded-full border border-green-800 font-medium animate-pulse">
                    ✅ Guru Terpilih
                 </span>
            )}
        </div>
        {!selectedGuru && <p className="text-yellow-500 text-sm mt-2">Silakan cari dan pilih guru terlebih dahulu untuk mengelola siswa binaannya.</p>}
      </div>

      {/* Siswa List Section */}
      {selectedGuru && (
        <>
          <div className="flex flex-col md:flex-row gap-4 mb-4">
            <div className="flex-1">
              <input
                type="text"
                placeholder="Cari Siswa / NISN..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white placeholder-gray-400"
              />
            </div>
            <div className="w-full md:w-64">
              <select
                value={filterKelas}
                onChange={(e) => setFilterKelas(e.target.value)}
                className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white"
              >
                <option value="">Semua Kelas</option>
                {kelasOptions.map(k => <option key={k.id} value={k.id}>{k.nama}</option>)}
              </select>
            </div>
          </div>

          <div className="bg-gray-800 shadow overflow-hidden rounded-lg border border-gray-700">
            {loading ? <p className="p-4 text-gray-400">Memuat data bimbingan...</p> : (
              <table className="min-w-full divide-y divide-gray-700">
                <thead className="bg-gray-700">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase w-10">Pilih</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Nama Siswa</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Kelas</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Aksi</th>
                  </tr>
                </thead>
                <tbody className="bg-gray-800 divide-y divide-gray-700">
                  {filteredSiswa.map(siswa => {
                    const isAssignedToMe = assignedSiswaIds.has(siswa.id);
                    const ownerGuruId = allAssignments.get(siswa.id);
                    // Locked jika punya guru wali TAPI bukan guru yang sedang dipilih
                    const isLocked = ownerGuruId && ownerGuruId !== selectedGuru;
                    const ownerName = isLocked ? getGuruName(ownerGuruId) : '';

                    return (
                      <tr 
                        key={siswa.id} 
                        className={`transition-all duration-300 ${
                            isAssignedToMe 
                                ? 'bg-green-500/10 shadow-[0_0_15px_rgba(34,197,94,0.15)] border-l-4 border-green-500' // Binaan Sendiri
                                : isLocked 
                                    ? 'bg-gray-900/50' // Milik orang lain (agak gelap)
                                    : 'hover:bg-gray-700 border-l-4 border-transparent' // Available
                        }`}
                      >
                        <td className="px-6 py-4 whitespace-nowrap">
                          <input
                            type="checkbox"
                            checked={isAssignedToMe}
                            onChange={() => handleToggleClick(siswa, isAssignedToMe)}
                            disabled={!!isLocked}
                            className={`w-5 h-5 rounded focus:ring-offset-0 ${
                                isLocked 
                                ? 'cursor-not-allowed bg-gray-600 text-gray-500' 
                                : 'cursor-pointer text-green-500 focus:ring-green-500 bg-gray-700 accent-green-600'
                            }`}
                          />
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                            <div className={`font-medium ${
                                isAssignedToMe ? 'text-green-400' : isLocked ? 'text-gray-300' : 'text-white'
                            }`}>
                              {siswa.nama}
                            </div>
                            <div className="text-xs text-gray-500">{siswa.nisn}</div>

                            {/* Keterangan Terkunci */}
                            {isLocked && (
                                <div className="text-xs text-yellow-500 mt-1 flex items-center gap-1 italic">
                                    <span>🔒 Telah menjadi anggota {ownerName}</span>
                                </div>
                            )}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-gray-300">
                            {siswa.kelas?.nama || '-'}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          {isAssignedToMe ? (
                            <span className="bg-green-900 text-green-200 text-xs px-2 py-1 rounded-full font-bold border border-green-700 shadow-[0_0_5px_rgba(34,197,94,0.4)]">
                                ✓ Binaan Anda
                            </span>
                          ) : isLocked ? (
                            <button
                                onClick={() => setPendingTransfer({
                                    siswaId: siswa.id,
                                    siswaNama: siswa.nama,
                                    oldGuruId: ownerGuruId!,
                                    oldGuruNama: ownerName
                                })}
                                className="bg-yellow-700 hover:bg-yellow-600 text-white text-xs px-3 py-1.5 rounded-full font-medium transition shadow-sm border border-yellow-600"
                            >
                                ↔ Pindah Anggota
                            </button>
                          ) : (
                            <span className="text-gray-500 text-xs">-</span>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                  {filteredSiswa.length === 0 && (
                    <tr><td colSpan={4} className="p-6 text-center text-gray-500">
                        Siswa tidak ditemukan.
                    </td></tr>
                  )}
                </tbody>
              </table>
            )}
          </div>
        </>
      )}
    </div>
  );
};

export interface Guru {
  id: string;
  nip: string | null;
  nama: string;
  jenis_kelamin: 'L' | 'P' | null;
  no_hp: string | null;
  username: string;
  password?: string;
  peran: string;
  created_at?: string;
}

export interface Siswa {
  id: string;
  nisn: string;
  nama: string;
  jenis_kelamin: 'L' | 'P' | null;
  tanggal_lahir: string | null;
  no_hp: string | null;
  id_kelas: string | null;
  created_at?: string;
  kelas?: {
    nama: string;
  } | null;
}

export interface Kelas {
  id: string;
  kode: string;
  nama: string;
}

export interface Mapel {
  id: string;
  kode: string;
  nama: string;
}

export interface Bimbingan {
  id: string;
  id_guru: string;
  id_siswa: string;
  siswa?: Siswa;
}

export interface Kehadiran {
  id: string;
  id_siswa: string;
  id_guru: string;
  tanggal: string;
  status: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA';
  catatan?: string;
  siswa?: Siswa; // For join
}

export interface Pelanggaran {
  id: string;
  id_siswa: string;
  id_guru: string;
  deskripsi: string;
  tindakan?: string;
  tanggal: string;
  siswa?: Siswa; // For join
}

export interface Prestasi {
  id: string;
  id_siswa: string;
  id_guru: string;
  deskripsi: string;
  tingkat?: string;
  tanggal: string;
  siswa?: Siswa; // For join
}

export interface Pengajaran {
  id: string;
  id_guru: string;
  id_mapel: string;
  id_kelas: string;
  mapel?: Mapel;
  kelas?: Kelas;
  guru?: Guru; // For join
}

export interface Nilai {
  id: string;
  id_siswa: string;
  id_guru: string;
  id_mapel: string;
  jenis: 'FORMATIF' | 'SUMATIF' | 'AKHIR_SUMATIF';
  nilai: number;
  tanggal: string;
  siswa?: Siswa;
}

export interface Sekolah {
  id: string; // UUID
  nama: string;
  npsn: string | null;
  alamat: string | null;
  email: string | null;
