import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Login } from './components/Login';
// Admin Components
import { AdminDashboard } from './components/AdminDashboard';
import { CrudGuru } from './components/CrudGuru';
import { CrudSiswa } from './components/CrudSiswa';
import { CrudKelas } from './components/CrudKelas';
import { CrudMapel } from './components/CrudMapel';
import { CrudAnggotaGurwal } from './components/CrudAnggotaGurwal';
import { CrudDataPengajar } from './components/CrudDataPengajar';
import { CrudSekolah } from './components/CrudSekolah';
import { RekapKehadiranAdmin } from './components/RekapKehadiranAdmin';

// Unified Guru Components
import { GuruDashboard } from './components/GuruDashboard';
// Binaan
import { DaftarBinaan } from './components/GuruBinaan/DaftarBinaan';
import { KehadiranBinaan } from './components/GuruBinaan/KehadiranBinaan';
import { ImportKehadiranTemplate } from './components/GuruBinaan/ImportKehadiranTemplate';
import { PelanggaranBinaan } from './components/GuruBinaan/PelanggaranBinaan';
import { PrestasiBinaan } from './components/GuruBinaan/PrestasiBinaan';
import { LaporanBinaan } from './components/GuruBinaan/LaporanBinaan';
// Pengajar
import { DaftarKelasAjar } from './components/GuruPengajar/DaftarKelasAjar';
import { InputNilai } from './components/GuruPengajar/InputNilai';
import { RekapNilai } from './components/GuruPengajar/RekapNilai';

import { Toast } from './components/Toast';
import { Guru, ViewState } from './types';

interface ToastState {
  message: string;
  type: 'success' | 'error';
  duration?: number;
  position?: 'top-right' | 'center';
}

function App() {
  const [session, setSession] = useState<Guru | null>(null);
  const [currentView, setCurrentView] = useState<ViewState>('DASHBOARD');
  const [toast, setToast] = useState<ToastState | null>(null);

  useEffect(() => {
    // Check localStorage for persisted session
    const storedUser = localStorage.getItem('gurwal_admin_user');
    const storedView = localStorage.getItem('gurwal_current_view') as ViewState;

    if (storedUser) {
      try {
        const user = JSON.parse(storedUser);
        setSession(user);

        if (storedView) {
          setCurrentView(storedView);
        } else {
          // Default views
          if (user.peran === 'ADMIN') setCurrentView('DASHBOARD');
          else setCurrentView('GURU_DASHBOARD');
        }
      } catch (e) {
        localStorage.removeItem('gurwal_admin_user');
        localStorage.removeItem('gurwal_current_view');
      }
    }
  }, []);

  const handleLoginSuccess = (user: Guru) => {
    setSession(user);
    localStorage.setItem('gurwal_admin_user', JSON.stringify(user));

    let defaultView: ViewState = 'DASHBOARD';
    if (user.peran !== 'ADMIN') defaultView = 'GURU_DASHBOARD';

    setCurrentView(defaultView);
    localStorage.setItem('gurwal_current_view', defaultView);
  };

  const handleLogout = () => {
    setSession(null);
    localStorage.removeItem('gurwal_admin_user');
    localStorage.removeItem('gurwal_current_view');
    showToast('Anda telah keluar', 'success');
  };

  const handleChangeView = (view: ViewState) => {
    setCurrentView(view);
    localStorage.setItem('gurwal_current_view', view);
  };

  const showToast = (
    message: string, 
    type: 'success' | 'error', 
    duration: number = 3000, 
    position: 'top-right' | 'center' = 'top-right'
  ) => {
    setToast({ message, type, duration, position });
  };

  // Render Logic
  if (!session) {
    return (
      <>
        <Login onLoginSuccess={handleLoginSuccess} showToast={showToast} />
        {toast && (
          <Toast
            message={toast.message}
            type={toast.type}
            duration={toast.duration}
            position={toast.position}
            onClose={() => setToast(null)}
          />
        )}
      </>
    );
  }

  const renderContent = () => {
    switch (currentView) {
      // ADMIN
      case 'GURU': return <CrudGuru showToast={showToast} />;
      case 'SISWA': return <CrudSiswa showToast={showToast} />;
      case 'KELAS': return <CrudKelas showToast={showToast} />;
      case 'MAPEL': return <CrudMapel showToast={showToast} />;
      case 'ANGGOTA_GURWAL': return <CrudAnggotaGurwal showToast={showToast} />;
      case 'DATA_PENGAJAR': return <CrudDataPengajar showToast={showToast} />;
      case 'PENGATURAN_SEKOLAH': return <CrudSekolah showToast={showToast} />;
      case 'REKAP_KEHADIRAN': return <RekapKehadiranAdmin showToast={showToast} />;
      case 'DASHBOARD': return <AdminDashboard />;

      // UNIFIED GURU
      case 'GURU_DASHBOARD': return <GuruDashboard currentUser={session} />;

      // BINAAN (WALI)
      case 'GURU_BINAAN_LIST': return <DaftarBinaan currentUser={session} showToast={showToast} />;
      case 'GURU_BINAAN_KEHADIRAN': return <KehadiranBinaan currentUser={session} showToast={showToast} />;
      case 'GURU_IMPORT_KEHADIRAN': return <ImportKehadiranTemplate currentUser={session} showToast={showToast} />;
      case 'GURU_BINAAN_PELANGGARAN': return <PelanggaranBinaan currentUser={session} showToast={showToast} />;
      case 'GURU_BINAAN_PRESTASI': return <PrestasiBinaan currentUser={session} showToast={showToast} />;
      case 'GURU_BINAAN_LAPORAN': return <LaporanBinaan currentUser={session} />;

      // PENGAJAR
      case 'GURU_PENGAJAR_JADWAL': return <DaftarKelasAjar currentUser={session} />;
      case 'GURU_PENGAJAR_NILAI': return <InputNilai currentUser={session} showToast={showToast} />;
      case 'GURU_PENGAJAR_REKAP': return <RekapNilai currentUser={session} />;

      default:
        return <div className="p-6 text-white">Halaman tidak ditemukan</div>;
    }
  };

  return (
    <Layout
      currentUser={session}
      currentView={currentView}
      onChangeView={handleChangeView}
      onLogout={handleLogout}
    >
      {renderContent()}
      {toast && (
        <Toast
          message={toast.message}
          type={toast.type}
          duration={toast.duration}
          position={toast.position}
          onClose={() => setToast(null)}
        />
      )}
    </Layout>
  );
}

export default App;

import React, { useEffect, useState } from 'react';
import { supabase } from '../supabaseClient';
import { Guru, Kelas } from '../types';
import * as XLSX from 'xlsx';
import jsPDF from 'jspdf';
import 'jspdf-autotable';
import { useSekolah } from '../hooks/useSekolah';

interface RekapKehadiranAdminProps {
  showToast: (msg: string, type: 'success' | 'error') => void;
}

interface RekapRow {
  id_siswa: string;
  nama_siswa: string;
  nisn: string;
  kelas: string;
  nama_wali: string;
  nip_wali: string | null;
  hadir: number;
  sakit: number;
  izin: number;
  alpha: number;
}

export const RekapKehadiranAdmin: React.FC<RekapKehadiranAdminProps> = ({ showToast }) => {
  const sekolah = useSekolah();

  // Data State
  const [data, setData] = useState<RekapRow[]>([]);
  const [loading, setLoading] = useState(true);

  // Filter State
  const [gurus, setGurus] = useState<Guru[]>([]);
  const [kelasOptions, setKelasOptions] = useState<Kelas[]>([]);
  const [selectedGuru, setSelectedGuru] = useState<string>('');
  const [selectedKelas, setSelectedKelas] = useState<string>('');

  useEffect(() => {
    // 1. Fetch Option Filters (Guru & Kelas)
    const fetchOptions = async () => {
      const { data: g } = await supabase.from('guru').select('*').eq('peran', 'GURU').order('nama');
      const { data: k } = await supabase.from('kelas').select('*').order('nama');
      if (g) setGurus(g);
      if (k) setKelasOptions(k);
    };

    fetchOptions();
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      // 1. Get All Students with Class info
      const { data: siswaData, error: siswaError } = await supabase
        .from('siswa')
        .select('id, nama, nisn, kelas(nama)');

      if (siswaError) throw siswaError;

      // 2. Get All Assignments (Bimbingan) to map to Wali
      const { data: bimbinganData } = await supabase
        .from('bimbingan')
        .select('id_siswa, id_guru, guru(nama, nip)');

      // Create Map: SiswaID -> { NamaWali, NIPWali, GuruID }
      const waliMap = new Map();
      bimbinganData?.forEach((b: any) => {
        waliMap.set(b.id_siswa, {
            nama: b.guru?.nama || 'Belum Ada',
            nip: b.guru?.nip,
            id_guru: b.id_guru
        });
      });

      // 3. Get All Attendance Summaries
      // Note: fetching all rows might be heavy for large datasets.
      // Optimization: Fetch only id_siswa and status
      const { data: kehadiranData } = await supabase
        .from('kehadiran')
        .select('id_siswa, status');

      // Aggregate in memory
      const attendanceMap = new Map();
      kehadiranData?.forEach(k => {
          if (!attendanceMap.has(k.id_siswa)) {
              attendanceMap.set(k.id_siswa, { H: 0, S: 0, I: 0, A: 0 });
          }
          const stats = attendanceMap.get(k.id_siswa);
          if (k.status === 'HADIR') stats.H++;
          else if (k.status === 'SAKIT') stats.S++;
          else if (k.status === 'IZIN') stats.I++;
          else if (k.status === 'ALPHA') stats.A++;
      });

      // 4. Combine all data
      const rows: RekapRow[] = siswaData?.map((s: any) => {
          const wali = waliMap.get(s.id) || { nama: '-', nip: null, id_guru: null };
          const stats = attendanceMap.get(s.id) || { H: 0, S: 0, I: 0, A: 0 };

          return {
              id_siswa: s.id,
              nama_siswa: s.nama,
              nisn: s.nisn,
              kelas: s.kelas?.nama || '-',
              nama_wali: wali.nama,
              nip_wali: wali.nip,
              // Hidden field for filtering purposes
              _id_guru: wali.id_guru, 
              _id_kelas: s.kelas?.id, // Assuming join returns object, needed purely for filter logic if `kelas` param is ID not name
              hadir: stats.H,
              sakit: stats.S,
              izin: stats.I,
              alpha: stats.A
          };
      }) || [];

      setData(rows);

    } catch (e) {
      console.error(e);
      showToast('Gagal memuat data rekap', 'error');
    } finally {
      setLoading(false);
    }
  };

  // --- Filtering Logic ---
  const filteredData = data.filter(row => {
      // @ts-ignore
      const matchGuru = selectedGuru === '' || row._id_guru === selectedGuru;
      // Filter by Kelas Name (since we displayed Name) or match logic with option.
      // Here we match by checking if the row.kelas includes the selected option text or by re-fetching class ID.
      // Simplest: use the Class Name from options to filter the string
      const selectedClassObj = kelasOptions.find(k => k.id === selectedKelas);
      const matchKelas = selectedKelas === '' || row.kelas === selectedClassObj?.nama;

      return matchGuru && matchKelas;
  });

  // --- EXPORT FUNCTIONS ---

  const handleExportExcel = () => {
    if (filteredData.length === 0) {
        showToast('Tidak ada data untuk diekspor', 'error');
        return;
    }

    const exportData = filteredData.map((row, idx) => ({
        'No': idx + 1,
        'Nama Siswa': row.nama_siswa,
        'NISN': row.nisn,
        'Kelas': row.kelas,
        'Guru Wali': row.nama_wali,
        'Hadir': row.hadir,
        'Sakit': row.sakit,
        'Izin': row.izin,
        'Alpha': row.alpha
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Rekap Kehadiran");
    XLSX.writeFile(wb, `Rekap_Kehadiran_Admin_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleExportPDFList = () => {
    if (filteredData.length === 0) return;

    const doc = new jsPDF();

    // Header
    doc.setFontSize(16);
    doc.text('REKAPITULASI KEHADIRAN SISWA', 105, 15, { align: 'center' });
    doc.setFontSize(12);
    doc.text(`${sekolah.nama || 'Sekolah'}`, 105, 22, { align: 'center' });
    doc.setFontSize(10);
    doc.text(`Dicetak pada: ${new Date().toLocaleDateString('id-ID')}`, 105, 28, { align: 'center' });

    const tableColumn = ["No", "Nama Siswa", "NISN", "Kelas", "Wali Kelas", "H", "S", "I", "A"];
    const tableRows: any[] = [];

    filteredData.forEach((row, index) => {
        const rowData = [
            index + 1,
            row.nama_siswa,
            row.nisn,
            row.kelas,
            row.nama_wali,
            row.hadir,
            row.sakit,
            row.izin,
            row.alpha
        ];
        tableRows.push(rowData);
    });

    // @ts-ignore
    doc.autoTable({
        head: [tableColumn],
        body: tableRows,
        startY: 35,
        theme: 'grid',
        styles: { fontSize: 8 },
        headStyles: { fillColor: [79, 70, 229] } // Indigo-600
    });

    doc.save(`rekap_kehadiran_list.pdf`);
  };

  const handleExportPDFIndividual = (row: RekapRow) => {
    const doc = new jsPDF();

    // --- KOP SURAT ---
    const pageWidth = doc.internal.pageSize.getWidth();
    let yPos = 15;

    // Logo (If exists, try to add it. If URL causes security error, it might fail silently or we need proxy. 
    // Using a placeholder logic or drawing a box if image fails is safer for client-side without proxy)
    // For simplicity in this demo, we assume the logo_url is accessible or we skip it.
    // doc.addImage is synchronous and needs Base64 or accessible URL.

    // Text Kop
    doc.setFont("helvetica", "bold");
    doc.setFontSize(18);
    doc.text((sekolah.nama || "NAMA SEKOLAH").toUpperCase(), pageWidth / 2, yPos, { align: "center" });

    yPos += 7;
    doc.setFontSize(10);
    doc.setFont("helvetica", "normal");
    doc.text(sekolah.alamat || "Alamat Sekolah...", pageWidth / 2, yPos, { align: "center" });

    yPos += 5;
    doc.text(`Telp: ${sekolah.no_telp || '-'} | Email: ${sekolah.email || '-'}`, pageWidth / 2, yPos, { align: "center" });

    yPos += 5;
    doc.setLineWidth(0.5);
    doc.line(10, yPos, pageWidth - 10, yPos); // Garis Kop

    // --- CONTENT ---
    yPos += 15;
    doc.setFontSize(14);
    doc.setFont("helvetica", "bold");
    doc.text("LAPORAN KEHADIRAN SISWA", pageWidth / 2, yPos, { align: "center" });

    yPos += 15;
    doc.setFontSize(11);
    doc.setFont("helvetica", "normal");

    // Student Info
    doc.text(`Nama Siswa : ${row.nama_siswa}`, 20, yPos);
    doc.text(`Kelas        : ${row.kelas}`, 120, yPos);
    yPos += 7;
