            >
                <span>📊</span> <span className="hidden md:inline">Export</span>
            </button>
        </div>
      </div>

      {loading ? (
          <div className="flex justify-center py-20">
              <span className="text-gray-400 animate-pulse">Sedang menghitung data...</span>
