  no_telp: string | null;
  logo_url: string | null;
  hari_sekolah: number; // 5 atau 6
  latitude: number | null;
  longitude: number | null;
}

export interface KalenderPendidikan {
  id: string;
  tanggal: string;
  jenis: 'LIBUR_NASIONAL' | 'LIBUR_SEKOLAH' | 'CUTI_BERSAMA';
  keterangan: string | null;
  created_at?: string;
}

export type ViewState = 
  // Admin
  | 'DASHBOARD' 
  | 'GURU' 
  | 'SISWA' 
  | 'KELAS' 
  | 'MAPEL'
  | 'KALENDER_PENDIDIKAN' // NEW
  | 'ANGGOTA_GURWAL' 
  | 'DATA_PENGAJAR'
  | 'INPUT_KEHADIRAN_ADMIN'
  | 'REKAP_KEHADIRAN'
  | 'PENGATURAN_SEKOLAH'
  // Unified Guru (Binaan + Pengajar)
  | 'GURU_DASHBOARD'
  | 'GURU_BINAAN_LIST'
  | 'GURU_BINAAN_KEHADIRAN'
  | 'GURU_IMPORT_KEHADIRAN'
  | 'GURU_BINAAN_PELANGGARAN'
  | 'GURU_BINAAN_PRESTASI'
  | 'GURU_BINAAN_LAPORAN'
  | 'GURU_PENGAJAR_JADWAL'
  | 'GURU_PENGAJAR_NILAI'
  | 'GURU_PENGAJAR_REKAP';

import React, { useEffect, useState } from 'react';
import { supabase } from '../supabaseClient';
import { Sekolah } from '../types';

interface CrudSekolahProps {
  showToast: (msg: string, type: 'success' | 'error', duration?: number, position?: 'top-right' | 'center') => void;
}

export const CrudSekolah: React.FC<CrudSekolahProps> = ({ showToast }) => {
  const [loading, setLoading] = useState(false);

  // Initialize with default values
  const [formData, setFormData] = useState<Partial<Sekolah>>({
    nama: '',
    npsn: '',
    alamat: '',
    email: '',
    no_telp: '',
    logo_url: '',
    hari_sekolah: 5, // Default 5 hari
    latitude: null,
    longitude: null
  });

  useEffect(() => {
    fetchData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      // Mengambil 1 data saja karena singleton
      const { data, error } = await supabase
        .from('sekolah')
        .select('*')
        .limit(1)
        .maybeSingle();

      if (error) throw error;

      if (data) {
        setFormData(data);
      }
    } catch (error: any) {
      console.error('Error fetching data sekolah:', error);
      showToast('Gagal memuat data sekolah', 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleNumberChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    const numValue = value === '' ? null : parseFloat(value);
    setFormData(prev => ({ ...prev, [name]: numValue }));
  };

  const handleRadioChange = (days: number) => {
    setFormData(prev => ({ ...prev, hari_sekolah: days }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // VALIDASI INPUT
    if (!formData.nama) {
        showToast('Nama Sekolah wajib diisi.', 'error');
        return;
    }

    if (formData.latitude && (formData.latitude < -90 || formData.latitude > 90)) {
        showToast('Latitude harus antara -90 dan 90.', 'error');
        return;
    }

    if (formData.longitude && (formData.longitude < -180 || formData.longitude > 180)) {
        showToast('Longitude harus antara -180 dan 180.', 'error');
        return;
    }

    setLoading(true);

    try {
      const payload = {
        nama: formData.nama,
        npsn: formData.npsn || null,
        alamat: formData.alamat || null,
        email: formData.email || null,
        no_telp: formData.no_telp || null,
        logo_url: formData.logo_url || null,
        hari_sekolah: formData.hari_sekolah || 5,
        latitude: formData.latitude,
        longitude: formData.longitude
      };

      let error;

      if (formData.id) {
        // UPDATE Existing
        const { error: updateError } = await supabase
          .from('sekolah')
          .update(payload)
          .eq('id', formData.id);
        error = updateError;
      } else {
        // INSERT New
        const { error: insertError } = await supabase
          .from('sekolah')
          .insert([payload]);
        error = insertError;
      }

      if (error) throw error;

      showToast('✅ Pengaturan sekolah berhasil disimpan!', 'success');
      fetchData(); // Refresh data to get generated ID if insert
    } catch (error: any) {
      console.error('Error saving data:', error);
      showToast('❌ Gagal menyimpan data: ' + (error.message || 'Unknown error'), 'error');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-5xl mx-auto">
      <div className="flex items-center justify-between mb-6">
        <div>
            <h2 className="text-3xl font-bold text-white mb-2">🏫 Pengaturan Sekolah</h2>
            <p className="text-gray-400">Kelola identitas instansi, jadwal operasional, dan lokasi.</p>
        </div>
      </div>

      <div className="bg-gray-800 rounded-lg shadow-lg border border-gray-700">
        <form onSubmit={handleSubmit}>
          <div className="p-8 space-y-8">

            {/* SECTION 1: IDENTITAS & LOGO */}
            <div className="flex flex-col md:flex-row gap-8 items-start border-b border-gray-700 pb-8">
                {/* Logo Preview & Input */}
                <div className="w-full md:w-1/3 flex flex-col items-center">
                    <label className="block text-sm font-medium text-gray-300 mb-3">Logo Sekolah</label>
                    <div className="relative w-48 h-48 bg-gray-900 border-2 border-dashed border-gray-600 rounded-xl flex items-center justify-center overflow-hidden mb-4 shadow-inner">
                        {formData.logo_url ? (
                            <img 
                            src={formData.logo_url} 
                            alt="Logo Sekolah" 
                            className="w-full h-full object-contain p-2"
                            onError={(e) => {
                                (e.target as HTMLImageElement).style.display = 'none';
                            }}
                            />
                        ) : (
                            <div className="text-center p-4 text-gray-500">
                                <span className="text-5xl block mb-2 opacity-50">🏫</span>
                                <span className="text-xs">Preview Logo</span>
                            </div>
                        )}
                    </div>

                    <div className="w-full">
                        <label className="block text-xs font-medium text-gray-400 mb-1">URL Logo (Link Gambar)</label>
                        <input 
                            type="text" 
                            name="logo_url"
                            value={formData.logo_url || ''}
                            onChange={handleInputChange}
                            placeholder="https://example.com/logo.png"
                            className="w-full bg-gray-700 border border-gray-600 rounded p-2.5 text-white focus:ring-primary focus:border-primary text-sm transition"
                        />
                    </div>
                </div>

                {/* Main Fields */}
                <div className="w-full md:w-2/3 space-y-5">
                    <div>
                        <label className="block text-sm font-bold text-white mb-1">Nama Sekolah <span className="text-red-500">*</span></label>
                        <input
                            type="text"
                            name="nama"
                            required
                            value={formData.nama || ''}
                            onChange={handleInputChange}
                            placeholder="Contoh: SMKN 1 NUSANTARA"
                            className="w-full bg-gray-700 border border-gray-600 rounded-lg p-3 text-white focus:ring-2 focus:ring-primary focus:border-transparent transition text-lg"
                        />
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                        <div>
                            <label className="block text-sm font-medium text-gray-300 mb-1">NPSN</label>
                            <input
                                type="text"
                                name="npsn"
                                value={formData.npsn || ''}
                                onChange={handleInputChange}
                                placeholder="8 Digit Angka"
                                className="w-full bg-gray-700 border border-gray-600 rounded-lg p-2.5 text-white focus:ring-primary focus:border-primary"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-300 mb-1">Hari Sekolah <span className="text-red-500">*</span></label>
                            <div className="flex gap-4 mt-2">
                                <label className={`flex items-center gap-2 cursor-pointer px-4 py-2 rounded-lg border transition ${formData.hari_sekolah === 5 ? 'bg-primary/20 border-primary text-white' : 'bg-gray-700 border-gray-600 text-gray-400 hover:bg-gray-600'}`}>
                                    <input 
                                        type="radio" 
                                        name="hari_sekolah" 
                                        checked={formData.hari_sekolah === 5} 
                                        onChange={() => handleRadioChange(5)}
                                        className="hidden" 
                                    />
                                    <span className="font-bold">5 Hari</span>
                                    <span className="text-xs opacity-70">(Senin-Jumat)</span>
                                </label>
                                <label className={`flex items-center gap-2 cursor-pointer px-4 py-2 rounded-lg border transition ${formData.hari_sekolah === 6 ? 'bg-primary/20 border-primary text-white' : 'bg-gray-700 border-gray-600 text-gray-400 hover:bg-gray-600'}`}>
                                    <input 
                                        type="radio" 
                                        name="hari_sekolah" 
                                        checked={formData.hari_sekolah === 6} 
                                        onChange={() => handleRadioChange(6)}
                                        className="hidden" 
                                    />
                                    <span className="font-bold">6 Hari</span>
                                    <span className="text-xs opacity-70">(Senin-Sabtu)</span>
                                </label>
                            </div>
                        </div>
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-gray-300 mb-1">Alamat Lengkap</label>
                        <textarea
                            name="alamat"
                            rows={3}
                            value={formData.alamat || ''}
                            onChange={handleInputChange}
                            placeholder="Jl. Raya No. 123, Kel. Apa, Kec. Dimana..."
                            className="w-full bg-gray-700 border border-gray-600 rounded-lg p-2.5 text-white focus:ring-primary focus:border-primary"
                        />
                    </div>
                </div>
            </div>

            {/* SECTION 2: KONTAK & LOKASI */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Kontak */}
                <div className="space-y-4">
                    <h3 className="text-lg font-semibold text-blue-400 border-b border-gray-700 pb-2 mb-4">📞 Kontak</h3>
                    <div>
                        <label className="block text-sm font-medium text-gray-300 mb-1">Email Sekolah</label>
                        <input
                            type="email"
                            name="email"
                            value={formData.email || ''}
                            onChange={handleInputChange}
                            placeholder="admin@sekolah.sch.id"
                            className="w-full bg-gray-700 border border-gray-600 rounded-lg p-2.5 text-white focus:ring-primary focus:border-primary"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-300 mb-1">Nomor Telepon</label>
                        <input
                            type="text"
                            name="no_telp"
                            value={formData.no_telp || ''}
                            onChange={handleInputChange}
                            placeholder="021-xxxxxxx"
                            className="w-full bg-gray-700 border border-gray-600 rounded-lg p-2.5 text-white focus:ring-primary focus:border-primary"
                        />
                    </div>
                </div>

                {/* Lokasi */}
                <div className="space-y-4">
                    <h3 className="text-lg font-semibold text-green-400 border-b border-gray-700 pb-2 mb-4">📍 Lokasi (Koordinat Maps)</h3>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-300 mb-1">Latitude</label>
                            <input
                                type="number"
                                step="any"
                                name="latitude"
                                min="-90"
                                max="90"
                                value={formData.latitude ?? ''}
                                onChange={handleNumberChange}
                                placeholder="-6.200000"
                                className="w-full bg-gray-700 border border-gray-600 rounded-lg p-2.5 text-white focus:ring-primary focus:border-primary"
                            />
                            <p className="text-[10px] text-gray-500 mt-1">Min: -90, Max: 90</p>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-300 mb-1">Longitude</label>
                            <input
                                type="number"
                                step="any"
                                name="longitude"
                                min="-180"
                                max="180"
                                value={formData.longitude ?? ''}
                                onChange={handleNumberChange}
                                placeholder="106.800000"
                                className="w-full bg-gray-700 border border-gray-600 rounded-lg p-2.5 text-white focus:ring-primary focus:border-primary"
                            />
                            <p className="text-[10px] text-gray-500 mt-1">Min: -180, Max: 180</p>
                        </div>
                    </div>
                    <div className="bg-blue-900/20 p-3 rounded border border-blue-800 text-xs text-blue-200">
                        💡 Tips: Koordinat digunakan untuk fitur presensi berbasis lokasi di masa mendatang.
                    </div>
                </div>
            </div>

          </div>

          {/* Footer Actions */}
          <div className="bg-gray-750 px-8 py-5 rounded-b-lg border-t border-gray-700 flex justify-end">
            <button
                type="submit"
                disabled={loading}
                className="bg-primary hover:bg-secondary text-white font-bold py-3 px-8 rounded-lg shadow-lg flex items-center gap-2 transition disabled:opacity-50 transform hover:scale-[1.02]"
            >
                {loading ? (
                    <>
                        <span className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
                        Menyimpan...
                    </>
                ) : (
                    <>
                        <span>💾</span> Simpan Pengaturan
                    </>
                )}
            </button>
          </div>

        </form>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../supabaseClient';
import { Guru, Bimbingan, Kehadiran } from '../../types';
import { ConfirmDialog } from '../ConfirmDialog';

interface Props {
  currentUser: Guru;
  showToast: (msg: string, type: 'success' | 'error') => void;
}

// Tipe Data Form Lokal
interface FormState {
  [id_siswa: string]: {
    id?: string; // ID Kehadiran (jika ada)
    status: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA';
    catatan: string;
  };
}

// Tipe Info Libur
interface HolidayInfo {
  jenis: string;
  keterangan: string | null;
}

type ModeType = 'INPUT' | 'VIEW' | 'EDIT';

export const KehadiranBinaan: React.FC<Props> = ({ currentUser, showToast }) => {
  // Data Utama
  const [siswaList, setSiswaList] = useState<Bimbingan[]>([]);
  const [tanggal, setTanggal] = useState(new Date().toISOString().split('T')[0]);

  // State UI & Logic
  const [mode, setMode] = useState<ModeType>('INPUT');
  const [formData, setFormData] = useState<FormState>({});
  const [loading, setLoading] = useState(false);
  const [processing, setProcessing] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  // State Hari Libur
  const [isHoliday, setIsHoliday] = useState(false);
  const [holidayInfo, setHolidayInfo] = useState<HolidayInfo | null>(null);

  // 1. Fetch Daftar Siswa (Sekali saat mount)
  useEffect(() => {
    const fetchSiswa = async () => {
      setLoading(true);
      const { data, error } = await supabase
        .from('bimbingan')
        .select('*, siswa(id, nama, nisn, jenis_kelamin, kelas(nama))')
        .eq('id_guru', currentUser.id)
        .order('created_at', { ascending: true });

      if (!error && data) {
         // @ts-ignore
         setSiswaList(data);
      }
      setLoading(false);
    };
    fetchSiswa();
  }, [currentUser.id]);

  // 2. Fetch Kehadiran & Cek Libur saat Tanggal Berubah
  useEffect(() => {
    if (siswaList.length > 0) {
      fetchDataAndCheckHoliday();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tanggal, siswaList]);

  const fetchDataAndCheckHoliday = async () => {
    setLoading(true);
    setMode('INPUT'); // Reset asumsi awal ke INPUT
    setIsHoliday(false);
    setHolidayInfo(null);

    try {
      // Parallel Request: Cek Kehadiran & Cek Kalender Pendidikan
      const [kehadiranRes, kalenderRes] = await Promise.all([
        supabase
          .from('kehadiran')
          .select('*')
          .eq('id_guru', currentUser.id)
          .eq('tanggal', tanggal),
        supabase
          .from('kalender_pendidikan')
          .select('jenis, keterangan')
          .eq('tanggal', tanggal)
          .maybeSingle()
      ]);

      // 1. Handle Cek Libur
      if (kalenderRes.data) {
        setIsHoliday(true);
        setHolidayInfo(kalenderRes.data);
      }

      // 2. Handle Data Kehadiran
      const existingData = kehadiranRes.data as Kehadiran[] || [];
      const newFormState: FormState = {};

      if (existingData.length > 0) {
        // DATA ADA -> MODE VIEW
        setMode('VIEW');

        siswaList.forEach(item => {
          const record = existingData.find(k => k.id_siswa === item.id_siswa);
          if (record) {
            newFormState[item.id_siswa] = {
              id: record.id,
              status: record.status,
              catatan: record.catatan || ''
            };
          } else {
            newFormState[item.id_siswa] = { status: 'HADIR', catatan: '' };
          }
        });
      } else {
        // DATA KOSONG -> MODE INPUT (Default HADIR)
        setMode('INPUT');
        siswaList.forEach(item => {
          newFormState[item.id_siswa] = { status: 'HADIR', catatan: '' };
        });
      }

      setFormData(newFormState);

    } catch (error) {
      console.error(error);
      showToast('Gagal memuat data', 'error');
    } finally {
      setLoading(false);
    }
  };

  // --- Handlers ---

  const handleStatusChange = (id_siswa: string, val: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA') => {
    if (isHoliday) return; // Prevent change if holiday
    setFormData(prev => ({
      ...prev,
      [id_siswa]: { ...prev[id_siswa], status: val }
    }));
  };

  const handleCatatanChange = (id_siswa: string, val: string) => {
    if (isHoliday) return; // Prevent change if holiday
    setFormData(prev => ({
      ...prev,
      [id_siswa]: { ...prev[id_siswa], catatan: val }
    }));
  };

  const handleSave = async () => {
    // VALIDASI FINAL SEBELUM SAVE
    if (isHoliday) {
        showToast(`Gagal: Tanggal ini adalah hari libur (${holidayInfo?.jenis}).`, 'error');
        return;
    }

    setProcessing(true);
    try {
      const payload = siswaList.map(item => ({
        id_guru: currentUser.id,
        id_siswa: item.id_siswa,
        tanggal: tanggal,
        status: formData[item.id_siswa].status,
        catatan: formData[item.id_siswa].catatan
      }));

      const { error } = await supabase.from('kehadiran').insert(payload);
      if (error) throw error;

      showToast('✅ Kehadiran berhasil disimpan', 'success');
      await fetchDataAndCheckHoliday(); // Refresh ke mode VIEW
    } catch (e) {
      showToast('Gagal menyimpan data', 'error');
    } finally {
      setProcessing(false);
    }
  };

  const handleUpdate = async () => {
    // VALIDASI FINAL SEBELUM UPDATE
    if (isHoliday) {
        showToast(`Gagal: Tanggal ini adalah hari libur (${holidayInfo?.jenis}).`, 'error');
        return;
    }

    setProcessing(true);
    try {
      // Upsert: Jika ID ada (update), jika tidak (insert - kasus siswa baru)
      const payload = siswaList.map(item => {
        const form = formData[item.id_siswa];
        return {
          id: form.id, // Supabase Upsert pakai ID ini untuk update
          id_guru: currentUser.id,
          id_siswa: item.id_siswa,
          tanggal: tanggal,
          status: form.status,
          catatan: form.catatan
        };
      });

      const { error } = await supabase.from('kehadiran').upsert(payload);
      if (error) throw error;

      showToast('✅ Kehadiran berhasil diperbarui', 'success');
      await fetchDataAndCheckHoliday(); // Kembali ke mode VIEW
    } catch (e) {
      showToast('Gagal memperbarui data', 'error');
    } finally {
      setProcessing(false);
    }
  };

  const handleDelete = async () => {
    setProcessing(true);
    try {
      const { error } = await supabase
        .from('kehadiran')
        .delete()
        .eq('id_guru', currentUser.id)
        .eq('tanggal', tanggal);

      if (error) throw error;

      showToast('🗑️ Data kehadiran dihapus', 'success');
      setShowDeleteConfirm(false);
      await fetchDataAndCheckHoliday(); // Kembali ke mode INPUT
    } catch (e) {
      showToast('Gagal menghapus data', 'error');
    } finally {
      setProcessing(false);
    }
  };

  // --- Components ---

  const RadioButton = ({ id_siswa, val, label, colorClass }: any) => {
    const isSelected = formData[id_siswa]?.status === val;
    const isDisabled = mode === 'VIEW' || isHoliday; // Disabled if VIEW mode OR Holiday

    return (
      <label className={`
        relative flex items-center justify-center w-10 h-10 rounded-lg transition-all duration-200
        ${isSelected 
          ? `${colorClass} text-white shadow-lg scale-110 font-bold ring-2 ring-white` 
          : 'bg-gray-700 text-gray-400 border border-gray-600'}
        ${isDisabled ? 'cursor-not-allowed opacity-60' : 'cursor-pointer hover:bg-gray-600'}
      `}>
        <input
          type="radio"
          name={`status-${id_siswa}`}
          value={val}
          checked={isSelected}
          onChange={() => !isDisabled && handleStatusChange(id_siswa, val)}
          disabled={isDisabled}
          className="hidden"
        />
        {label}
      </label>
    );
  };

  return (
    <div>
      <ConfirmDialog
        isOpen={showDeleteConfirm}
        message={`Yakin ingin menghapus seluruh data kehadiran pada tanggal ${tanggal}?`}
        onConfirm={handleDelete}
        onCancel={() => setShowDeleteConfirm(false)}
      />

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <div>
           <h2 className="text-2xl font-bold text-white">Input Kehadiran</h2>
           <p className="text-gray-400 text-sm">Kelola absensi harian siswa binaan.</p>
        </div>
      </div>

      {/* --- CONTROL PANEL (Sticky) --- */}
      <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 shadow-xl mb-6 sticky top-0 z-20">
        <div className="flex flex-col gap-4">
            <div className="flex flex-col lg:flex-row justify-between items-center gap-4">

            {/* Date Picker & Badge */}
            <div className="flex items-center gap-4 w-full lg:w-auto">
                <div className="relative">
                    <input
                    type="date"
                    value={tanggal}
                    onChange={(e) => setTanggal(e.target.value)}
                    className="bg-gray-900 border border-gray-600 text-white rounded-lg px-4 py-2 pl-10 focus:ring-2 focus:ring-primary focus:border-transparent shadow-inner"
                    />
                    <span className="absolute left-3 top-2.5 text-gray-400">📅</span>
                </div>

                {/* Mode Badge */}
                {mode === 'INPUT' && !isHoliday && (
                <span className="px-3 py-1 bg-green-500/20 text-green-400 border border-green-500/50 rounded-full text-xs font-bold uppercase tracking-wider animate-pulse">
                    Mode Input
                </span>
                )}
                {mode === 'VIEW' && !isHoliday && (
                <span className="px-3 py-1 bg-blue-500/20 text-blue-400 border border-blue-500/50 rounded-full text-xs font-bold uppercase tracking-wider">
                    Mode Lihat
                </span>
                )}
                {mode === 'EDIT' && !isHoliday && (
                <span className="px-3 py-1 bg-yellow-500/20 text-yellow-400 border border-yellow-500/50 rounded-full text-xs font-bold uppercase tracking-wider animate-pulse">
                    Mode Edit
                </span>
                )}
                {isHoliday && (
                    <span className="px-3 py-1 bg-red-500/20 text-red-400 border border-red-500/50 rounded-full text-xs font-bold uppercase tracking-wider animate-pulse">
                        ⛔ HARI LIBUR
                    </span>
                )}
            </div>

            {/* Action Buttons based on Mode */}
            <div className="flex gap-2 w-full lg:w-auto justify-end">

                {/* 1. Jika Mode INPUT (Belum ada data) */}
                {mode === 'INPUT' && (
                <button
                    onClick={handleSave}
                    disabled={processing || siswaList.length === 0 || isHoliday}
                    className="bg-green-600 hover:bg-green-700 text-white px-6 py-2 rounded-lg font-bold shadow-lg transition flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    {processing ? 'Menyimpan...' : '💾 Simpan Kehadiran'}
                </button>
                )}

                {/* 2. Jika Mode VIEW (Data ada, hanya lihat) */}
                {mode === 'VIEW' && (
                <>
                    <button
                        onClick={() => setShowDeleteConfirm(true)}
                        // Tetap izinkan hapus data meskipun hari libur (misal salah input di masa lalu)
                        className="bg-red-900/50 hover:bg-red-900 text-red-200 border border-red-800 px-4 py-2 rounded-lg font-medium transition flex items-center gap-2"
                    >
                        🗑️ Hapus
                    </button>
                    {!isHoliday && (
                        <button
                            onClick={() => setMode('EDIT')}
                            className="bg-yellow-600 hover:bg-yellow-700 text-white px-5 py-2 rounded-lg font-bold shadow-lg transition flex items-center gap-2"
                        >
                            ✏️ Ubah Data
                        </button>
                    )}
                </>
                )}

                {/* 3. Jika Mode EDIT (Sedang mengedit) */}
                {mode === 'EDIT' && (
                <>
                    <button
                        onClick={() => { setMode('VIEW'); fetchDataAndCheckHoliday(); }} 
                        className="bg-gray-600 hover:bg-gray-500 text-white px-4 py-2 rounded-lg font-medium transition"
                        disabled={processing}
                    >
                        ❌ Batal
                    </button>
                    <button
                        onClick={handleUpdate}
                        disabled={processing || isHoliday}
                        className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg font-bold shadow-lg transition flex items-center gap-2 disabled:opacity-50"
                    >
                        {processing ? 'Memproses...' : '✅ Perbarui Kehadiran'}
                    </button>
                </>
                )}
            </div>
            </div>

            {/* ALERT HARI LIBUR */}
            {isHoliday && holidayInfo && (
                <div className="w-full bg-red-900/30 border border-red-600/50 text-red-200 p-3 rounded-lg flex items-start gap-3 animate-slide-in">
                    <span className="text-2xl">🚫</span>
                    <div>
                        <h4 className="font-bold text-red-100">Tidak dapat menginput kehadiran</h4>
                        <p className="text-sm">
                            Tanggal ini tercatat sebagai <strong>{holidayInfo.jenis.replace(/_/g, ' ')}</strong>.
                            {holidayInfo.keterangan && <span className="block mt-1 italic opacity-80">"{holidayInfo.keterangan}"</span>}
                        </p>
                    </div>
                </div>
            )}
        </div>
      </div>

      {/* --- TABLE CONTENT --- */}
      <div className="bg-gray-800 shadow-xl overflow-hidden rounded-xl border border-gray-700">
        {loading ? (
          <div className="p-10 flex justify-center items-center text-gray-400 gap-3">
            <span className="animate-spin text-2xl">⏳</span> Memuat data...
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-700">
              <thead className="bg-gray-750 text-gray-400">
                <tr>
                  <th className="px-6 py-4 text-center text-xs font-bold uppercase w-12">No</th>
                  <th className="px-6 py-4 text-left text-xs font-bold uppercase">Siswa</th>
                  <th className="px-6 py-4 text-center text-xs font-bold uppercase">Status Kehadiran</th>
                  <th className="px-6 py-4 text-left text-xs font-bold uppercase">Catatan</th>
                </tr>
              </thead>
              <tbody className="bg-gray-800 divide-y divide-gray-700">
                {siswaList.map((item, index) => {
                  const currentStatus = formData[item.id_siswa]?.status;
                  // Highlight row based on status
                  let rowBg = 'hover:bg-gray-750';
                  if (currentStatus === 'SAKIT') rowBg = 'bg-yellow-900/10 hover:bg-yellow-900/20';
                  if (currentStatus === 'IZIN') rowBg = 'bg-blue-900/10 hover:bg-blue-900/20';
                  if (currentStatus === 'ALPHA') rowBg = 'bg-red-900/10 hover:bg-red-900/20';

                  // Dimmed row if holiday
                  if (isHoliday) rowBg = 'bg-gray-900 opacity-60';

                  return (
                    <tr key={item.id} className={`transition-colors duration-200 ${rowBg}`}>
                      <td className="px-6 py-4 text-center text-gray-500 text-sm">
                        {index + 1}
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex flex-col">
                          <span className="text-sm font-bold text-white">{item.siswa?.nama}</span>
                          <span className="text-xs text-gray-400 flex gap-2">
                             <span>{item.siswa?.nisn}</span>
                             <span className="text-gray-600">•</span>
                             <span>{item.siswa?.jenis_kelamin}</span>
                          </span>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex items-center justify-center gap-3">
                          <RadioButton 
                            id_siswa={item.id_siswa} val="HADIR" label="H" 
                            colorClass="bg-green-600" 
                          />
                          <RadioButton 
                            id_siswa={item.id_siswa} val="SAKIT" label="S" 
                            colorClass="bg-yellow-500" 
                          />
                          <RadioButton 
                            id_siswa={item.id_siswa} val="IZIN" label="I" 
                            colorClass="bg-blue-500" 
                          />
                          <RadioButton 
                            id_siswa={item.id_siswa} val="ALPHA" label="A" 
                            colorClass="bg-red-500" 
                          />
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <input
                          type="text"
                          value={formData[item.id_siswa]?.catatan || ''}
                          onChange={(e) => handleCatatanChange(item.id_siswa, e.target.value)}
                          placeholder={mode === 'VIEW' ? "" : "Keterangan tambahan..."}
                          disabled={mode === 'VIEW' || isHoliday}
                          className={`
                            w-full bg-gray-900 border border-gray-600 text-white text-sm rounded-lg px-3 py-2
                            focus:ring-1 focus:ring-primary focus:border-primary transition
                            disabled:opacity-50 disabled:bg-gray-800 disabled:border-transparent
                            disabled:cursor-not-allowed
                          `}
                        />
                      </td>
                    </tr>
                  );
                })}
                {siswaList.length === 0 && (
                  <tr>
                    <td colSpan={4} className="p-10 text-center text-gray-500 italic flex flex-col items-center">
                      <span className="text-4xl mb-2">📭</span>
                      Belum ada siswa binaan yang ditugaskan kepada Anda.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Legend */}
      <div className="mt-4 flex gap-6 justify-center text-xs text-gray-400 font-medium">
         <span className="flex items-center gap-1"><div className="w-3 h-3 rounded bg-green-600"></div> H (Hadir)</span>
         <span className="flex items-center gap-1"><div className="w-3 h-3 rounded bg-yellow-500"></div> S (Sakit)</span>
         <span className="flex items-center gap-1"><div className="w-3 h-3 rounded bg-blue-500"></div> I (Izin)</span>
         <span className="flex items-center gap-1"><div className="w-3 h-3 rounded bg-red-500"></div> A (Alpha)</span>
      </div>

    </div>
  );
};

import React, { useState, useRef } from 'react';
import { supabase } from '../../supabaseClient';
import { Guru } from '../../types';
import * as XLSX from 'xlsx';

interface Props {
  currentUser: Guru;
  showToast: (msg: string, type: 'success' | 'error') => void;
}

export const ImportKehadiranTemplate: React.FC<Props> = ({ currentUser, showToast }) => {
  const [selectedDates, setSelectedDates] = useState<string[]>([]);

  // State Input
  const [singleDate, setSingleDate] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  const [loading, setLoading] = useState(false);
  const [importProgress, setImportProgress] = useState(0); 
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- LOGIC TANGGAL ---

  // 1. Tambah Satu Tanggal
  const handleAddSingleDate = () => {
    if (!singleDate) return;
    if (selectedDates.includes(singleDate)) {
      showToast('Tanggal sudah ada dalam daftar', 'error');
      return;
    }
    const newDates = [...selectedDates, singleDate].sort();
    setSelectedDates(newDates);
    setSingleDate('');
  };

  // 2. Tambah Rentang Tanggal (Multiselect Logic)
  const handleAddRange = () => {
    if (!startDate || !endDate) {
        showToast('Mohon isi Tanggal Mulai dan Tanggal Akhir', 'error');
        return;
    }

    const start = new Date(startDate);
    const end = new Date(endDate);

    if (start > end) {
        showToast('Tanggal Mulai tidak boleh lebih besar dari Tanggal Akhir', 'error');
        return;
    }

    const tempDates: string[] = [];
    let current = new Date(start);

    // Loop dari start sampai end
    while (current <= end) {
        const dateStr = current.toISOString().split('T')[0];
        if (!selectedDates.includes(dateStr)) {
            tempDates.push(dateStr);
        }
        // Increment hari +1
        current.setDate(current.getDate() + 1);
    }

    if (tempDates.length === 0) {
        showToast('Semua tanggal dalam rentang ini sudah terpilih.', 'error');
    } else {
        const combinedDates = [...selectedDates, ...tempDates].sort();
        setSelectedDates(combinedDates);
        setStartDate('');
        setEndDate('');
        showToast(`Berhasil menambahkan ${tempDates.length} tanggal.`, 'success');
    }
  };

  const handleRemoveDate = (dateToRemove: string) => {
    setSelectedDates(selectedDates.filter(d => d !== dateToRemove));
  };

  const handleClearDates = () => {
      setSelectedDates([]);
  };

  // --- HELPER: FILTER TANGGAL EFEKTIF ---
  const getValidSchoolDates = async (dates: string[]) => {
      // 1. Fetch Setting Sekolah (Hari Sekolah)
      const { data: sekolahData } = await supabase
        .from('sekolah')
        .select('hari_sekolah')
        .limit(1)
        .maybeSingle();

      const hariSekolah = sekolahData?.hari_sekolah || 5; // Default 5 hari

      // 2. Fetch Hari Libur dari Kalender Pendidikan
      const { data: holidays } = await supabase
        .from('kalender_pendidikan')
        .select('tanggal, jenis')
        .in('tanggal', dates);

      const holidayMap = new Map();
      holidays?.forEach(h => holidayMap.set(h.tanggal, h.jenis));

      const validDates: string[] = [];
      const excludedDates: string[] = [];

      dates.forEach(dateStr => {
          const dateObj = new Date(dateStr);
          const dayOfWeek = dateObj.getDay(); // 0 = Minggu, 6 = Sabtu

          let isValid = true;
          let reason = '';

          // Cek Akhir Pekan sesuai Hari Sekolah
          if (dayOfWeek === 0) {
              isValid = false;
              reason = 'Hari Minggu';
          } else if (hariSekolah === 5 && dayOfWeek === 6) {
              isValid = false;
              reason = 'Hari Sabtu (Libur)';
          }

          // Cek Kalender Pendidikan
          if (isValid && holidayMap.has(dateStr)) {
              isValid = false;
              reason = `Libur: ${holidayMap.get(dateStr).replace(/_/g, ' ')}`;
          }

          if (isValid) {
              validDates.push(dateStr);
          } else {
              excludedDates.push(`${dateStr} (${reason})`);
          }
      });

      return { validDates, excludedDates };
  };

  // --- LOGIC GENERATE & IMPORT ---

  const handleGenerateTemplate = async () => {
    if (selectedDates.length === 0) {
      showToast('Pilih minimal satu tanggal terlebih dahulu', 'error');
      return;
    }

    setLoading(true);
    try {
      // PROSES FILTERISASI OTOMATIS
      const { validDates, excludedDates } = await getValidSchoolDates(selectedDates);

      if (validDates.length === 0) {
          showToast('Tidak ada tanggal efektif sekolah dalam pilihan Anda (Semua libur/akhir pekan).', 'error');
          setLoading(false);
          return;
      }

      // Ambil data siswa
      const { data: siswaData, error } = await supabase
        .from('bimbingan')
        .select('*, siswa(id, nama, nisn, kelas(nama))')
        .eq('id_guru', currentUser.id)
        .order('created_at', { ascending: true });

      if (error) throw error;

      if (!siswaData || siswaData.length === 0) {
        showToast('Anda belum memiliki siswa binaan', 'error');
        setLoading(false);
        return;
      }

      const rows = siswaData.map((item, index) => {
        const row: any = {
          NO: index + 1,
          NISN: item.siswa?.nisn || '', 
          NAMA: item.siswa?.nama || '',
          KELAS: item.siswa?.kelas?.nama || '',
        };
        // Gunakan hanya tanggal valid sebagai header
        validDates.forEach(date => {
          row[date] = ''; 
        });
        return row;
      });

      const ws = XLSX.utils.json_to_sheet(rows);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Kehadiran");

      const filename = `Template_Kehadiran_${new Date().toISOString().split('T')[0]}.xlsx`;
      XLSX.writeFile(wb, filename);

      // Feedback UX
      if (excludedDates.length > 0) {
          showToast(`Template dibuat. ${excludedDates.length} tanggal libur/akhir pekan otomatis dikecualikan.`, 'success');
          console.log('Excluded Dates:', excludedDates);
      } else {
          showToast('Template berhasil dibuat!', 'success');
      }

    } catch (err: any) {
      console.error(err);
      showToast('Gagal membuat template: ' + err.message, 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setImportProgress(0); 
    const reader = new FileReader();

    reader.onload = async (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsName = wb.SheetNames[0];
        const ws = wb.Sheets[wsName];

        const data = XLSX.utils.sheet_to_json(ws);

        if (data.length === 0) {
          showToast('File Excel kosong', 'error');
          setLoading(false);
          return;
        }

        // --- VALIDASI HEADER TANGGAL SEBELUM IMPORT ---
        const firstRow = data[0] as any;
        const keys = Object.keys(firstRow);
        const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
        const dateColumns = keys.filter(k => dateRegex.test(k));

        if (dateColumns.length > 0) {
            // Cek apakah ada tanggal libur di kolom Excel
            const { data: holidays } = await supabase
                .from('kalender_pendidikan')
                .select('tanggal, jenis')
                .in('tanggal', dateColumns);

            if (holidays && holidays.length > 0) {
                const holidayDates = holidays.map(h => `${h.tanggal} (${h.jenis})`).join(', ');
                showToast(`GAGAL IMPORT! File mengandung tanggal libur: ${holidayDates}. Silakan hapus kolom tersebut.`, 'error');
                setLoading(false);
                if (fileInputRef.current) fileInputRef.current.value = '';
                return;
            }
        }
        // ----------------------------------------------

        let processedCount = 0;
        let errorCount = 0;
        const totalRows = data.length;

        for (let i = 0; i < totalRows; i++) {
          const row: any = data[i];
          const nisn = row['NISN'] ? String(row['NISN']).trim() : '';
          const nama = row['NAMA'] ? String(row['NAMA']).trim() : '';

          if (!nisn && !nama) {
             const currentProgress = Math.round(((i + 1) / totalRows) * 100);
             setImportProgress(currentProgress);
             continue; 
          }

          let studentId = '';
          const { data: foundSiswa } = await supabase
             .from('siswa')
             .select('id')
             .eq('nisn', nisn)
             .maybeSingle();

          if (foundSiswa) {
            studentId = foundSiswa.id;
          } else {
            const { data: foundSiswaByName } = await supabase
                .from('siswa')
                .select('id')
                .ilike('nama', nama)
                .maybeSingle();
            if (foundSiswaByName) studentId = foundSiswaByName.id;
          }

          if (!studentId) {
            errorCount++;
          } else {
            for (const key of keys) {
               if (dateRegex.test(key)) {
                  const rawStatus = row[key] ? String(row[key]).trim().toUpperCase() : '';
                  let statusDb: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA' | null = null;

                  if (['H', 'HADIR'].includes(rawStatus)) statusDb = 'HADIR';
                  else if (['S', 'SAKIT'].includes(rawStatus)) statusDb = 'SAKIT';
                  else if (['I', 'IZIN'].includes(rawStatus)) statusDb = 'IZIN';
                  else if (['A', 'ALPHA', 'ALPA'].includes(rawStatus)) statusDb = 'ALPHA';

                  if (statusDb) {
                      // Upsert Kehadiran
                      const { error: upsertError } = await supabase.from('kehadiran').upsert({
                          id_guru: currentUser.id,
                          id_siswa: studentId,
                          tanggal: key,
                          status: statusDb
                      }, { onConflict: 'id_siswa, tanggal' }); // Asumsi ada unique constraint composite (id_siswa, tanggal) atau handling manual via select-update

                      // Fallback manual upsert logic jika tidak ada unique constraint composite
                      if (upsertError) {
                          const { data: existing } = await supabase
                              .from('kehadiran')
                              .select('id')
                              .eq('id_guru', currentUser.id)
                              .eq('id_siswa', studentId)
                              .eq('tanggal', key)
                              .maybeSingle();

                          if (existing) {
                              await supabase.from('kehadiran').update({ status: statusDb }).eq('id', existing.id);
                          } else {
                              await supabase.from('kehadiran').insert([{
                                  id_guru: currentUser.id,
                                  id_siswa: studentId,
                                  tanggal: key,
                                  status: statusDb
                              }]);
                          }
                      }
                  }
               }
            }
            processedCount++;
          }

          const currentProgress = Math.round(((i + 1) / totalRows) * 100);
          setImportProgress(currentProgress);
        }

        showToast(`Import selesai. ${processedCount} siswa diproses.`, 'success');
        if (errorCount > 0) {
            setTimeout(() => showToast(`${errorCount} siswa tidak ditemukan di database.`, 'error'), 2000);
        }

      } catch (err: any) {
        console.error(err);
        showToast('Gagal memproses file: ' + err.message, 'error');
      } finally {
        setLoading(false);
        setImportProgress(0);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };

    reader.readAsBinaryString(file);
  };

  return (
    <div className="max-w-4xl mx-auto p-4">
      <h2 className="text-3xl font-bold text-white mb-2">Import Kehadiran (Custom)</h2>
      <p className="text-gray-400 mb-8">
        Fitur ini memungkinkan Anda mengisi absensi untuk beberapa tanggal sekaligus menggunakan Excel.
        <br />
        <span className="text-yellow-500 text-xs">
            * Sistem otomatis memfilter hari libur dan akhir pekan dari template.
        </span>
      </p>

      {/* STEP 1: PILIH TANGGAL */}
      <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-lg mb-6">
        <h3 className="text-lg font-semibold text-blue-400 mb-4">1. Pilih Tanggal & Buat Template</h3>

        <div className="space-y-6">

            {/* OPSI A: Tambah Rentang (Multiselect Logic) */}
            <div className="bg-gray-700/50 p-4 rounded-lg border border-gray-600">
                <label className="block text-sm font-bold text-white mb-3">🅰️ Opsi Cepat: Pilih Rentang Tanggal</label>
                <div className="flex flex-col md:flex-row gap-4 items-end">
                    <div className="flex-1 w-full">
                        <label className="text-xs text-gray-400 block mb-1">Dari Tanggal</label>
                        <input 
                            type="date" 
                            value={startDate}
                            onChange={(e) => setStartDate(e.target.value)}
                            className="bg-gray-700 border border-gray-500 text-white rounded px-3 py-2 w-full focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                        />
                    </div>
                    <div className="flex items-center justify-center pb-2 text-gray-400">
                        ➡️
                    </div>
                    <div className="flex-1 w-full">
                        <label className="text-xs text-gray-400 block mb-1">Sampai Tanggal</label>
                        <input 
                            type="date" 
                            value={endDate}
                            onChange={(e) => setEndDate(e.target.value)}
                            className="bg-gray-700 border border-gray-500 text-white rounded px-3 py-2 w-full focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                        />
                    </div>
                    <button 
                        onClick={handleAddRange}
                        className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded font-medium transition w-full md:w-auto h-[42px]"
                    >
                        + Tambahkan Rentang
                    </button>
                </div>
                <p className="text-xs text-gray-400 mt-2">
                    *Semua tanggal di antara tanggal mulai dan akhir akan ditambahkan ke daftar.
                </p>
            </div>

            {/* OPSI B: Tambah Manual */}
            <div className="bg-gray-700/30 p-4 rounded-lg border border-gray-600 border-dashed">
                <label className="block text-sm font-bold text-gray-300 mb-3">🅱️ Opsi Manual: Tambah Satuan</label>
                <div className="flex flex-col md:flex-row gap-4">
                    <input 
                        type="date" 
                        value={singleDate}
                        onChange={(e) => setSingleDate(e.target.value)}
                        className="bg-gray-700 border border-gray-500 text-white rounded px-3 py-2 w-full md:w-64"
                    />
                    <button 
                        onClick={handleAddSingleDate}
                        className="bg-gray-600 hover:bg-gray-500 text-white px-4 py-2 rounded font-medium transition w-full md:w-auto"
                    >
                        + Tambah
                    </button>
                </div>
            </div>

            {/* Selected Dates Chips */}
            {selectedDates.length > 0 && (
                <div className="bg-gray-900/50 p-4 rounded-lg border border-gray-700">
                    <div className="flex justify-between items-center mb-2">
                        <span className="text-sm font-bold text-gray-300">Daftar Tanggal Terpilih ({selectedDates.length}):</span>
                        <button onClick={handleClearDates} className="text-xs text-red-400 hover:text-red-300 underline">Hapus Semua</button>
                    </div>
                    <div className="flex flex-wrap gap-2 max-h-40 overflow-y-auto custom-scrollbar">
                        {selectedDates.map(date => (
                            <div key={date} className="bg-primary/20 text-primary px-3 py-1 rounded-full text-sm flex items-center gap-2 border border-primary/30">
                                <span>🗓️ {date}</span>
                                <button 
                                    onClick={() => handleRemoveDate(date)}
                                    className="text-red-400 hover:text-red-300 font-bold px-1 hover:bg-white/10 rounded"
                                >
                                    &times;
                                </button>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            <div className="border-t border-gray-700 pt-4">
                <button 
                    onClick={handleGenerateTemplate}
                    disabled={loading || selectedDates.length === 0}
                    className="w-full bg-green-600 hover:bg-green-700 text-white px-6 py-3 rounded-lg font-bold transition shadow-lg flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    {loading ? 'Memvalidasi Tanggal...' : '📥 Buat & Download Template Excel'}
                </button>
                <p className="text-xs text-center text-gray-500 mt-2">
                    Sistem akan otomatis menghapus hari libur/akhir pekan sebelum membuat file Excel.
                </p>
            </div>
        </div>
      </div>

      {/* STEP 2: UPLOAD */}
      <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-lg">
        <h3 className="text-lg font-semibold text-green-400 mb-4">2. Upload & Import Data</h3>
        <p className="text-sm text-gray-400 mb-4">
            Isi file Excel yang telah diunduh dengan kode: <strong>H</strong> (Hadir), <strong>S</strong> (Sakit), <strong>I</strong> (Izin), <strong>A</strong> (Alpha).
        </p>

        <div className="flex flex-col items-center justify-center border-2 border-dashed border-gray-600 rounded-lg p-10 bg-gray-700/30 hover:bg-gray-700/50 transition relative">
            <input 
                type="file" 
                accept=".xlsx, .xls"
                ref={fileInputRef}
                onChange={handleFileUpload}
                disabled={loading}
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" 
                id="file-upload"
            />
            <div className="text-center pointer-events-none">
                <span className="text-4xl mb-2 block">📂</span>
                <span className="text-white font-medium mb-1 block">Klik atau Seret File Excel ke Sini</span>
                <span className="text-xs text-gray-500 block">Format .xlsx atau .xls</span>
            </div>
        </div>
      </div>

      {/* PROGRESS OVERLAY */}
      {loading && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-80">
          <div className="bg-gray-800 p-6 rounded-lg border border-gray-700 w-80 md:w-96 text-center">
            <h3 className="text-white font-bold mb-4 text-lg">Memproses Data...</h3>
            <div className="w-full bg-gray-700 rounded-full h-4 mb-2 overflow-hidden">
               <div 
                 className="bg-green-500 h-4 rounded-full transition-all duration-300" 
                 style={{ width: `${importProgress}%` }}
               ></div>
            </div>
            <p className="text-gray-300 font-medium">{importProgress}%</p>
            <p className="text-gray-500 text-sm mt-1">Mohon jangan tutup halaman ini.</p>
          </div>
        </div>
      )}

    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { supabase } from '../../supabaseClient';
import { Guru } from '../../types';
import * as XLSX from 'xlsx';

interface Props {
  currentUser: Guru;
  showToast: (msg: string, type: 'success' | 'error') => void;
}

export const ImportKehadiranTemplate: React.FC<Props> = ({ currentUser, showToast }) => {
  const [selectedDates, setSelectedDates] = useState<string[]>([]);

  // State Input
  const [singleDate, setSingleDate] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [hariSekolah, setHariSekolah] = useState<number>(5); // Default 5 hari

  const [loading, setLoading] = useState(false);
  const [importProgress, setImportProgress] = useState(0); 
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- INITIAL LOAD: Get Hari Sekolah ---
  useEffect(() => {
    const fetchSettings = async () => {
      const { data } = await supabase
        .from('sekolah')
        .select('hari_sekolah')
        .limit(1)
        .maybeSingle();
      if (data) {
        setHariSekolah(data.hari_sekolah);
      }
    };
    fetchSettings();
  }, []);

  // --- LOGIC TANGGAL ---

  // 1. Tambah Satu Tanggal dengan Validasi Live
  const handleAddSingleDate = async () => {
    if (!singleDate) return;

    // Cek Duplikasi Lokal
    if (selectedDates.includes(singleDate)) {
      showToast('Tanggal sudah ada dalam daftar', 'error');
      return;
    }

    setLoading(true);
    try {
        const dateObj = new Date(singleDate);
        const dayOfWeek = dateObj.getDay(); // 0 = Minggu

        // 1. Cek Akhir Pekan (Lokal)
        if (dayOfWeek === 0) {
            showToast('Gagal: Tanggal yang dipilih adalah hari Minggu.', 'error');
            return;
        }
        if (hariSekolah === 5 && dayOfWeek === 6) {
            showToast('Gagal: Tanggal yang dipilih adalah hari Sabtu (Libur Sekolah).', 'error');
            return;
        }

        // 2. Cek Kalender Pendidikan (Database)
        const { data: libur } = await supabase
            .from('kalender_pendidikan')
            .select('jenis, keterangan')
            .eq('tanggal', singleDate)
            .maybeSingle();

        if (libur) {
            showToast(`Gagal: Tanggal ini libur (${libur.jenis.replace(/_/g, ' ')}). ${libur.keterangan || ''}`, 'error');
            return;
        }

        // Lolos Validasi
        const newDates = [...selectedDates, singleDate].sort();
        setSelectedDates(newDates);
        setSingleDate('');
        showToast('Tanggal berhasil ditambahkan', 'success');

    } catch (error) {
        console.error(error);
        showToast('Terjadi kesalahan saat memvalidasi tanggal', 'error');
    } finally {
        setLoading(false);
    }
  };

  // 2. Tambah Rentang Tanggal dengan Filter Otomatis
  const handleAddRange = async () => {
    if (!startDate || !endDate) {
        showToast('Mohon isi Tanggal Mulai dan Tanggal Akhir', 'error');
        return;
    }

    const start = new Date(startDate);
    const end = new Date(endDate);

    if (start > end) {
        showToast('Tanggal Mulai tidak boleh lebih besar dari Tanggal Akhir', 'error');
        return;
    }

    setLoading(true);
    try {
        // Ambil Data Libur dalam rentang tersebut dari DB
        const { data: holidays } = await supabase
            .from('kalender_pendidikan')
            .select('tanggal, jenis')
            .gte('tanggal', startDate)
            .lte('tanggal', endDate);

        const holidayMap = new Set(holidays?.map(h => h.tanggal));

        const validDatesToAdd: string[] = [];
        let skippedCount = 0;
        let skippedReason = '';

        let current = new Date(start);

        // Loop dari start sampai end
        while (current <= end) {
            const dateStr = current.toISOString().split('T')[0];
            const dayOfWeek = current.getDay();

            let isValid = true;

            // Cek Akhir Pekan
            if (dayOfWeek === 0 || (hariSekolah === 5 && dayOfWeek === 6)) {
                isValid = false;
            }
            // Cek Kalender Libur
            else if (holidayMap.has(dateStr)) {
                isValid = false;
                skippedReason = 'Hari Libur Nasional/Sekolah';
            }
            // Cek Duplikasi State
            else if (selectedDates.includes(dateStr)) {
                isValid = false; // Sudah ada, skip diam-diam
            }

            if (isValid) {
                validDatesToAdd.push(dateStr);
            } else {
                // Hanya hitung skip jika bukan karena duplikasi (agar pesan toast relevan untuk filter libur)
                if (!selectedDates.includes(dateStr)) skippedCount++;
            }

            // Increment hari +1
            current.setDate(current.getDate() + 1);
        }

        if (validDatesToAdd.length === 0) {
            showToast('Tidak ada tanggal yang ditambahkan (Semua tanggal dalam rentang ini adalah hari libur/akhir pekan/sudah terpilih).', 'error');
        } else {
            const combinedDates = [...selectedDates, ...validDatesToAdd].sort();
            setSelectedDates(combinedDates);
            setStartDate('');
            setEndDate('');

            if (skippedCount > 0) {
                showToast(`Berhasil menambah ${validDatesToAdd.length} tanggal. (${skippedCount} tanggal dilewati karena Libur/Akhir Pekan)`, 'success');
            } else {
                showToast(`Berhasil menambah ${validDatesToAdd.length} tanggal.`, 'success');
            }
        }

    } catch (err) {
        showToast('Gagal memproses rentang tanggal', 'error');
    } finally {
        setLoading(false);
    }
  };

  const handleRemoveDate = (dateToRemove: string) => {
    setSelectedDates(selectedDates.filter(d => d !== dateToRemove));
  };

  const handleClearDates = () => {
      setSelectedDates([]);
  };

  // --- LOGIC GENERATE & IMPORT ---

  const handleGenerateTemplate = async () => {
    if (selectedDates.length === 0) {
      showToast('Pilih minimal satu tanggal terlebih dahulu', 'error');
      return;
    }

    setLoading(true);
    try {
      // Ambil data siswa
      const { data: siswaData, error } = await supabase
        .from('bimbingan')
        .select('*, siswa(id, nama, nisn, kelas(nama))')
        .eq('id_guru', currentUser.id)
        .order('created_at', { ascending: true });

      if (error) throw error;

      if (!siswaData || siswaData.length === 0) {
        showToast('Anda belum memiliki siswa binaan', 'error');
        setLoading(false);
        return;
      }

      const rows = siswaData.map((item, index) => {
        const row: any = {
          NO: index + 1,
          NISN: item.siswa?.nisn || '', 
          NAMA: item.siswa?.nama || '',
          KELAS: item.siswa?.kelas?.nama || '',
        };
        // Gunakan selectedDates sebagai header
        selectedDates.forEach(date => {
          row[date] = ''; 
        });
        return row;
      });

      const ws = XLSX.utils.json_to_sheet(rows);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Kehadiran");

      const filename = `Template_Kehadiran_${new Date().toISOString().split('T')[0]}.xlsx`;
      XLSX.writeFile(wb, filename);

      showToast('Template berhasil dibuat!', 'success');

    } catch (err: any) {
      console.error(err);
      showToast('Gagal membuat template: ' + err.message, 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setImportProgress(0); 
    const reader = new FileReader();

    reader.onload = async (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsName = wb.SheetNames[0];
        const ws = wb.Sheets[wsName];

        const data = XLSX.utils.sheet_to_json(ws);

        if (data.length === 0) {
          showToast('File Excel kosong', 'error');
          setLoading(false);
          return;
        }

        // --- VALIDASI HEADER TANGGAL SEBELUM IMPORT ---
        const firstRow = data[0] as any;
        const keys = Object.keys(firstRow);
        const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
        const dateColumns = keys.filter(k => dateRegex.test(k));

        if (dateColumns.length > 0) {
            // Cek apakah ada tanggal libur di kolom Excel (Double check server side)
            const { data: holidays } = await supabase
                .from('kalender_pendidikan')
                .select('tanggal, jenis')
                .in('tanggal', dateColumns);

            if (holidays && holidays.length > 0) {
                const holidayDates = holidays.map(h => `${h.tanggal} (${h.jenis})`).join(', ');
                showToast(`GAGAL IMPORT! File mengandung tanggal libur: ${holidayDates}. Silakan hapus kolom tersebut.`, 'error');
                setLoading(false);
                if (fileInputRef.current) fileInputRef.current.value = '';
                return;
            }
        }
        // ----------------------------------------------

        let processedCount = 0;
        let errorCount = 0;
        const totalRows = data.length;

        for (let i = 0; i < totalRows; i++) {
          const row: any = data[i];
          const nisn = row['NISN'] ? String(row['NISN']).trim() : '';
          const nama = row['NAMA'] ? String(row['NAMA']).trim() : '';

          if (!nisn && !nama) {
             const currentProgress = Math.round(((i + 1) / totalRows) * 100);
             setImportProgress(currentProgress);
             continue; 
          }

          let studentId = '';
          const { data: foundSiswa } = await supabase
             .from('siswa')
             .select('id')
             .eq('nisn', nisn)
             .maybeSingle();

          if (foundSiswa) {
            studentId = foundSiswa.id;
          } else {
            const { data: foundSiswaByName } = await supabase
                .from('siswa')
                .select('id')
                .ilike('nama', nama)
                .maybeSingle();
            if (foundSiswaByName) studentId = foundSiswaByName.id;
          }

          if (!studentId) {
            errorCount++;
          } else {
            for (const key of keys) {
               if (dateRegex.test(key)) {
                  const rawStatus = row[key] ? String(row[key]).trim().toUpperCase() : '';
                  let statusDb: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA' | null = null;

                  if (['H', 'HADIR'].includes(rawStatus)) statusDb = 'HADIR';
                  else if (['S', 'SAKIT'].includes(rawStatus)) statusDb = 'SAKIT';
                  else if (['I', 'IZIN'].includes(rawStatus)) statusDb = 'IZIN';
                  else if (['A', 'ALPHA', 'ALPA'].includes(rawStatus)) statusDb = 'ALPHA';

                  if (statusDb) {
                      // Upsert Kehadiran
                      const { error: upsertError } = await supabase.from('kehadiran').upsert({
                          id_guru: currentUser.id,
                          id_siswa: studentId,
                          tanggal: key,
                          status: statusDb
                      }, { onConflict: 'id_siswa, tanggal' });

                      // Fallback manual upsert logic jika tidak ada unique constraint composite
                      if (upsertError) {
                          const { data: existing } = await supabase
                              .from('kehadiran')
                              .select('id')
                              .eq('id_guru', currentUser.id)
                              .eq('id_siswa', studentId)
                              .eq('tanggal', key)
                              .maybeSingle();

                          if (existing) {
                              await supabase.from('kehadiran').update({ status: statusDb }).eq('id', existing.id);
                          } else {
                              await supabase.from('kehadiran').insert([{
                                  id_guru: currentUser.id,
                                  id_siswa: studentId,
                                  tanggal: key,
                                  status: statusDb
                              }]);
                          }
                      }
                  }
               }
            }
            processedCount++;
          }

          const currentProgress = Math.round(((i + 1) / totalRows) * 100);
          setImportProgress(currentProgress);
        }

        showToast(`Import selesai. ${processedCount} siswa diproses.`, 'success');
        if (errorCount > 0) {
            setTimeout(() => showToast(`${errorCount} siswa tidak ditemukan di database.`, 'error'), 2000);
        }

      } catch (err: any) {
        console.error(err);
        showToast('Gagal memproses file: ' + err.message, 'error');
      } finally {
        setLoading(false);
        setImportProgress(0);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };

    reader.readAsBinaryString(file);
  };

  return (
    <div className="max-w-4xl mx-auto p-4">
      <h2 className="text-3xl font-bold text-white mb-2">Import Kehadiran (Custom)</h2>
      <p className="text-gray-400 mb-8">
        Fitur ini memungkinkan Anda mengisi absensi untuk beberapa tanggal sekaligus menggunakan Excel.
        <br />
        <span className="text-yellow-500 text-xs">
            * Sistem otomatis memblokir penambahan tanggal libur/akhir pekan pada template.
        </span>
      </p>

      {/* STEP 1: PILIH TANGGAL */}
      <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-lg mb-6">
        <h3 className="text-lg font-semibold text-blue-400 mb-4">1. Pilih Tanggal & Buat Template</h3>

        <div className="space-y-6">

            {/* OPSI A: Tambah Rentang (Multiselect Logic) */}
            <div className="bg-gray-700/50 p-4 rounded-lg border border-gray-600">
                <label className="block text-sm font-bold text-white mb-3">🅰️ Opsi Cepat: Pilih Rentang Tanggal</label>
                <div className="flex flex-col md:flex-row gap-4 items-end">
                    <div className="flex-1 w-full">
                        <label className="text-xs text-gray-400 block mb-1">Dari Tanggal</label>
                        <input 
                            type="date" 
                            value={startDate}
                            onChange={(e) => setStartDate(e.target.value)}
                            className="bg-gray-700 border border-gray-500 text-white rounded px-3 py-2 w-full focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                        />
                    </div>
                    <div className="flex items-center justify-center pb-2 text-gray-400">
                        ➡️
                    </div>
                    <div className="flex-1 w-full">
                        <label className="text-xs text-gray-400 block mb-1">Sampai Tanggal</label>
                        <input 
                            type="date" 
                            value={endDate}
                            onChange={(e) => setEndDate(e.target.value)}
                            className="bg-gray-700 border border-gray-500 text-white rounded px-3 py-2 w-full focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                        />
                    </div>
                    <button 
                        onClick={handleAddRange}
                        disabled={loading}
                        className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded font-medium transition w-full md:w-auto h-[42px] disabled:opacity-50"
                    >
                        {loading ? 'Memvalidasi...' : '+ Tambahkan Rentang'}
                    </button>
                </div>
                <p className="text-xs text-gray-400 mt-2">
                    * Tanggal libur/akhir pekan di antara rentang ini akan otomatis dilewati.
                </p>
            </div>

            {/* OPSI B: Tambah Manual */}
            <div className="bg-gray-700/30 p-4 rounded-lg border border-gray-600 border-dashed">
                <label className="block text-sm font-bold text-gray-300 mb-3">🅱️ Opsi Manual: Tambah Satuan</label>
                <div className="flex flex-col md:flex-row gap-4">
                    <input 
                        type="date" 
                        value={singleDate}
                        onChange={(e) => setSingleDate(e.target.value)}
                        className="bg-gray-700 border border-gray-500 text-white rounded px-3 py-2 w-full md:w-64"
                    />
                    <button 
                        onClick={handleAddSingleDate}
                        disabled={loading}
                        className="bg-gray-600 hover:bg-gray-500 text-white px-4 py-2 rounded font-medium transition w-full md:w-auto disabled:opacity-50"
                    >
                        {loading ? 'Cek...' : '+ Tambah'}
                    </button>
                </div>
            </div>

            {/* Selected Dates Chips */}
            {selectedDates.length > 0 && (
                <div className="bg-gray-900/50 p-4 rounded-lg border border-gray-700">
                    <div className="flex justify-between items-center mb-2">
                        <span className="text-sm font-bold text-gray-300">Daftar Tanggal Terpilih ({selectedDates.length}):</span>
                        <button onClick={handleClearDates} className="text-xs text-red-400 hover:text-red-300 underline">Hapus Semua</button>
                    </div>
                    <div className="flex flex-wrap gap-2 max-h-40 overflow-y-auto custom-scrollbar">
                        {selectedDates.map(date => (
                            <div key={date} className="bg-primary/20 text-primary px-3 py-1 rounded-full text-sm flex items-center gap-2 border border-primary/30">
                                <span>🗓️ {date}</span>
                                <button 
                                    onClick={() => handleRemoveDate(date)}
                                    className="text-red-400 hover:text-red-300 font-bold px-1 hover:bg-white/10 rounded"
                                >
                                    &times;
                                </button>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            <div className="border-t border-gray-700 pt-4">
                <button 
                    onClick={handleGenerateTemplate}
                    disabled={loading || selectedDates.length === 0}
                    className="w-full bg-green-600 hover:bg-green-700 text-white px-6 py-3 rounded-lg font-bold transition shadow-lg flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    {loading ? 'Memproses...' : '📥 Buat & Download Template Excel'}
                </button>
            </div>
        </div>
      </div>

      {/* STEP 2: UPLOAD */}
      <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-lg">
        <h3 className="text-lg font-semibold text-green-400 mb-4">2. Upload & Import Data</h3>
        <p className="text-sm text-gray-400 mb-4">
            Isi file Excel yang telah diunduh dengan kode: <strong>H</strong> (Hadir), <strong>S</strong> (Sakit), <strong>I</strong> (Izin), <strong>A</strong> (Alpha).
        </p>

        <div className="flex flex-col items-center justify-center border-2 border-dashed border-gray-600 rounded-lg p-10 bg-gray-700/30 hover:bg-gray-700/50 transition relative">
            <input 
                type="file" 
                accept=".xlsx, .xls"
                ref={fileInputRef}
                onChange={handleFileUpload}
                disabled={loading}
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" 
                id="file-upload"
            />
            <div className="text-center pointer-events-none">
                <span className="text-4xl mb-2 block">📂</span>
                <span className="text-white font-medium mb-1 block">Klik atau Seret File Excel ke Sini</span>
                <span className="text-xs text-gray-500 block">Format .xlsx atau .xls</span>
            </div>
        </div>
      </div>

      {/* PROGRESS OVERLAY */}
      {loading && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-80">
          <div className="bg-gray-800 p-6 rounded-lg border border-gray-700 w-80 md:w-96 text-center">
            <h3 className="text-white font-bold mb-4 text-lg">Memproses Data...</h3>
            <div className="w-full bg-gray-700 rounded-full h-4 mb-2 overflow-hidden">
               <div 
                 className="bg-green-500 h-4 rounded-full transition-all duration-300" 
                 style={{ width: `${importProgress}%` }}
               ></div>
            </div>
            <p className="text-gray-300 font-medium">{importProgress}%</p>
            <p className="text-gray-500 text-sm mt-1">Mohon jangan tutup halaman ini.</p>
          </div>
        </div>
      )}

    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../supabaseClient';
import { Guru, Bimbingan, Kehadiran } from '../../types';
import { ConfirmDialog } from '../ConfirmDialog';

interface Props {
  currentUser: Guru;
  showToast: (msg: string, type: 'success' | 'error') => void;
}

// Tipe Data Form Lokal
interface FormState {
  [id_siswa: string]: {
    id?: string; // ID Kehadiran (jika ada)
    status: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA';
    catatan: string;
  };
}

// Tipe Info Libur
interface HolidayInfo {
  jenis: string;
  keterangan: string | null;
}

type ModeType = 'INPUT' | 'VIEW' | 'EDIT';

export const KehadiranBinaan: React.FC<Props> = ({ currentUser, showToast }) => {
  // Data Utama
  const [siswaList, setSiswaList] = useState<Bimbingan[]>([]);
  const [tanggal, setTanggal] = useState(new Date().toISOString().split('T')[0]);

  // State UI & Logic
  const [mode, setMode] = useState<ModeType>('INPUT');
  const [formData, setFormData] = useState<FormState>({});
  const [loading, setLoading] = useState(false);
  const [processing, setProcessing] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  // State Hari Libur & Sekolah
  const [isHoliday, setIsHoliday] = useState(false);
  const [holidayInfo, setHolidayInfo] = useState<HolidayInfo | null>(null);
  const [hariSekolah, setHariSekolah] = useState<number>(5); // Default 5 hari

  // 1. Fetch Daftar Siswa & Setting Sekolah (Sekali saat mount)
  useEffect(() => {
    const fetchInitialData = async () => {
      setLoading(true);

      // Fetch Siswa
      const siswaPromise = supabase
        .from('bimbingan')
        .select('*, siswa(id, nama, nisn, jenis_kelamin, kelas(nama))')
        .eq('id_guru', currentUser.id)
        .order('created_at', { ascending: true });

      // Fetch Setting Sekolah
      const sekolahPromise = supabase
        .from('sekolah')
        .select('hari_sekolah')
        .limit(1)
        .maybeSingle();

      const [siswaRes, sekolahRes] = await Promise.all([siswaPromise, sekolahPromise]);

      if (siswaRes.data) {
         // @ts-ignore
         setSiswaList(siswaRes.data);
      }
      if (sekolahRes.data) {
         setHariSekolah(sekolahRes.data.hari_sekolah);
      }

      setLoading(false);
    };
    fetchInitialData();
  }, [currentUser.id]);

  // 2. Fetch Kehadiran & Cek Libur saat Tanggal/Siswa/HariSekolah Berubah
  useEffect(() => {
    if (siswaList.length > 0) {
      fetchDataAndCheckHoliday();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tanggal, siswaList, hariSekolah]);

  const fetchDataAndCheckHoliday = async () => {
    setLoading(true);
    setMode('INPUT'); 
    setIsHoliday(false);
    setHolidayInfo(null);

    try {
      // --- LOGIC 1: CEK HARI SEKOLAH (SENIN-JUMAT / SABTU) ---
      const dateObj = new Date(tanggal);
      const dayOfWeek = dateObj.getDay(); // 0=Minggu, 6=Sabtu

      let isWeekend = false;
      let weekendLabel = '';

      if (dayOfWeek === 0) {
          isWeekend = true;
          weekendLabel = 'Hari Minggu';
      } else if (hariSekolah === 5 && dayOfWeek === 6) {
          isWeekend = true;
          weekendLabel = 'Hari Sabtu (Sekolah 5 Hari Kerja)';
      }

      if (isWeekend) {
          setIsHoliday(true);
          setHolidayInfo({ 
              jenis: 'HARI_NON_AKTIF', 
              keterangan: weekendLabel 
          });
          // Jangan return dulu, kita tetap cek jika ada data historis yang perlu ditampilkan (Mode VIEW)
          // Tapi input tetap didisable lewat state isHoliday
      }

      // Parallel Request: Cek Kehadiran & Cek Kalender Pendidikan
      // Jika sudah weekend, cek kalender pendidikan mungkin tidak perlu, tapi tidak ada salahnya
      const queries: any[] = [
        supabase
          .from('kehadiran')
          .select('*')
          .eq('id_guru', currentUser.id)
          .eq('tanggal', tanggal)
      ];

      // Hanya query kalender jika belum terdeteksi weekend
      if (!isWeekend) {
          queries.push(
            supabase
              .from('kalender_pendidikan')
              .select('jenis, keterangan')
              .eq('tanggal', tanggal)
              .maybeSingle()
          );
      }

      const results = await Promise.all(queries);
      const kehadiranRes = results[0];
      const kalenderRes = results[1]; // Undefined jika isWeekend=true

      // --- LOGIC 2: CEK KALENDER PENDIDIKAN ---
      if (!isWeekend && kalenderRes?.data) {
        setIsHoliday(true);
        setHolidayInfo(kalenderRes.data);
      }

      // 3. Handle Data Kehadiran
      const existingData = kehadiranRes.data as Kehadiran[] || [];
      const newFormState: FormState = {};

      if (existingData.length > 0) {
        // DATA ADA -> MODE VIEW
        setMode('VIEW');

        siswaList.forEach(item => {
          const record = existingData.find(k => k.id_siswa === item.id_siswa);
          if (record) {
            newFormState[item.id_siswa] = {
              id: record.id,
              status: record.status,
              catatan: record.catatan || ''
            };
          } else {
            newFormState[item.id_siswa] = { status: 'HADIR', catatan: '' };
          }
        });
      } else {
        // DATA KOSONG -> MODE INPUT (Default HADIR)
        setMode('INPUT');
        siswaList.forEach(item => {
          newFormState[item.id_siswa] = { status: 'HADIR', catatan: '' };
        });
      }

      setFormData(newFormState);

    } catch (error) {
      console.error(error);
      showToast('Gagal memuat data', 'error');
    } finally {
      setLoading(false);
    }
  };

  // --- Handlers ---

  const handleStatusChange = (id_siswa: string, val: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA') => {
    if (isHoliday) return; // Prevent change if holiday
    setFormData(prev => ({
      ...prev,
      [id_siswa]: { ...prev[id_siswa], status: val }
    }));
  };

  const handleCatatanChange = (id_siswa: string, val: string) => {
    if (isHoliday) return; // Prevent change if holiday
    setFormData(prev => ({
      ...prev,
      [id_siswa]: { ...prev[id_siswa], catatan: val }
    }));
  };

  const handleSave = async () => {
    // VALIDASI FINAL SEBELUM SAVE
    if (isHoliday) {
        showToast(`Gagal: ${holidayInfo?.keterangan || 'Hari Libur'}.`, 'error');
        return;
    }

    setProcessing(true);
    try {
      const payload = siswaList.map(item => ({
        id_guru: currentUser.id,
        id_siswa: item.id_siswa,
        tanggal: tanggal,
        status: formData[item.id_siswa].status,
        catatan: formData[item.id_siswa].catatan
      }));

      const { error } = await supabase.from('kehadiran').insert(payload);
      if (error) throw error;

      showToast('✅ Kehadiran berhasil disimpan', 'success');
      await fetchDataAndCheckHoliday(); // Refresh ke mode VIEW
    } catch (e) {
      showToast('Gagal menyimpan data', 'error');
    } finally {
      setProcessing(false);
    }
  };

  const handleUpdate = async () => {
    // VALIDASI FINAL SEBELUM UPDATE
    if (isHoliday) {
        showToast(`Gagal: ${holidayInfo?.keterangan || 'Hari Libur'}.`, 'error');
        return;
    }

    setProcessing(true);
    try {
      // Upsert: Jika ID ada (update), jika tidak (insert - kasus siswa baru)
      const payload = siswaList.map(item => {
        const form = formData[item.id_siswa];
        return {
          id: form.id, // Supabase Upsert pakai ID ini untuk update
          id_guru: currentUser.id,
          id_siswa: item.id_siswa,
          tanggal: tanggal,
          status: form.status,
          catatan: form.catatan
        };
      });

      const { error } = await supabase.from('kehadiran').upsert(payload);
      if (error) throw error;

      showToast('✅ Kehadiran berhasil diperbarui', 'success');
      await fetchDataAndCheckHoliday(); // Kembali ke mode VIEW
    } catch (e) {
      showToast('Gagal memperbarui data', 'error');
    } finally {
      setProcessing(false);
    }
  };

  const handleDelete = async () => {
    setProcessing(true);
    try {
      const { error } = await supabase
        .from('kehadiran')
        .delete()
        .eq('id_guru', currentUser.id)
        .eq('tanggal', tanggal);

      if (error) throw error;

      showToast('🗑️ Data kehadiran dihapus', 'success');
      setShowDeleteConfirm(false);
      await fetchDataAndCheckHoliday(); // Kembali ke mode INPUT
    } catch (e) {
      showToast('Gagal menghapus data', 'error');
    } finally {
      setProcessing(false);
    }
  };

  // --- Components ---

  const RadioButton = ({ id_siswa, val, label, colorClass }: any) => {
    const isSelected = formData[id_siswa]?.status === val;
    const isDisabled = mode === 'VIEW' || isHoliday; // Disabled if VIEW mode OR Holiday

    return (
      <label className={`
        relative flex items-center justify-center w-10 h-10 rounded-lg transition-all duration-200
        ${isSelected 
          ? `${colorClass} text-white shadow-lg scale-110 font-bold ring-2 ring-white` 
          : 'bg-gray-700 text-gray-400 border border-gray-600'}
        ${isDisabled ? 'cursor-not-allowed opacity-60' : 'cursor-pointer hover:bg-gray-600'}
      `}>
        <input
          type="radio"
          name={`status-${id_siswa}`}
          value={val}
          checked={isSelected}
          onChange={() => !isDisabled && handleStatusChange(id_siswa, val)}
          disabled={isDisabled}
          className="hidden"
        />
        {label}
      </label>
    );
  };

  return (
    <div>
      <ConfirmDialog
        isOpen={showDeleteConfirm}
        message={`Yakin ingin menghapus seluruh data kehadiran pada tanggal ${tanggal}?`}
        onConfirm={handleDelete}
        onCancel={() => setShowDeleteConfirm(false)}
      />

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <div>
           <h2 className="text-2xl font-bold text-white">Input Kehadiran</h2>
           <p className="text-gray-400 text-sm">Kelola absensi harian siswa binaan.</p>
        </div>
      </div>

      {/* --- CONTROL PANEL (Sticky) --- */}
      <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 shadow-xl mb-6 sticky top-0 z-20">
        <div className="flex flex-col gap-4">
            <div className="flex flex-col lg:flex-row justify-between items-center gap-4">

            {/* Date Picker & Badge */}
            <div className="flex items-center gap-4 w-full lg:w-auto">
                <div className="relative">
                    <input
                    type="date"
                    value={tanggal}
                    onChange={(e) => setTanggal(e.target.value)}
                    className="bg-gray-900 border border-gray-600 text-white rounded-lg px-4 py-2 pl-10 focus:ring-2 focus:ring-primary focus:border-transparent shadow-inner"
                    />
                    <span className="absolute left-3 top-2.5 text-gray-400">📅</span>
                </div>

                {/* Mode Badge */}
                {mode === 'INPUT' && !isHoliday && (
                <span className="px-3 py-1 bg-green-500/20 text-green-400 border border-green-500/50 rounded-full text-xs font-bold uppercase tracking-wider animate-pulse">
                    Mode Input
                </span>
                )}
                {mode === 'VIEW' && !isHoliday && (
                <span className="px-3 py-1 bg-blue-500/20 text-blue-400 border border-blue-500/50 rounded-full text-xs font-bold uppercase tracking-wider">
                    Mode Lihat
                </span>
                )}
                {mode === 'EDIT' && !isHoliday && (
                <span className="px-3 py-1 bg-yellow-500/20 text-yellow-400 border border-yellow-500/50 rounded-full text-xs font-bold uppercase tracking-wider animate-pulse">
                    Mode Edit
                </span>
                )}
                {isHoliday && (
                    <span className="px-3 py-1 bg-red-500/20 text-red-400 border border-red-500/50 rounded-full text-xs font-bold uppercase tracking-wider animate-pulse">
                        ⛔ {holidayInfo?.jenis === 'HARI_NON_AKTIF' ? 'HARI LIBUR' : 'LIBUR NASIONAL'}
                    </span>
                )}
            </div>

            {/* Action Buttons based on Mode */}
            <div className="flex gap-2 w-full lg:w-auto justify-end">

                {/* 1. Jika Mode INPUT (Belum ada data) */}
                {mode === 'INPUT' && (
                <button
                    onClick={handleSave}
                    disabled={processing || siswaList.length === 0 || isHoliday}
                    className="bg-green-600 hover:bg-green-700 text-white px-6 py-2 rounded-lg font-bold shadow-lg transition flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    {processing ? 'Menyimpan...' : '💾 Simpan Kehadiran'}
                </button>
                )}

                {/* 2. Jika Mode VIEW (Data ada, hanya lihat) */}
                {mode === 'VIEW' && (
                <>
                    <button
                        onClick={() => setShowDeleteConfirm(true)}
                        // Tetap izinkan hapus data meskipun hari libur (misal salah input di masa lalu)
                        className="bg-red-900/50 hover:bg-red-900 text-red-200 border border-red-800 px-4 py-2 rounded-lg font-medium transition flex items-center gap-2"
                    >
                        🗑️ Hapus
                    </button>
                    {!isHoliday && (
                        <button
                            onClick={() => setMode('EDIT')}
                            className="bg-yellow-600 hover:bg-yellow-700 text-white px-5 py-2 rounded-lg font-bold shadow-lg transition flex items-center gap-2"
                        >
                            ✏️ Ubah Data
                        </button>
                    )}
                </>
                )}

                {/* 3. Jika Mode EDIT (Sedang mengedit) */}
                {mode === 'EDIT' && (
                <>
                    <button
                        onClick={() => { setMode('VIEW'); fetchDataAndCheckHoliday(); }} 
                        className="bg-gray-600 hover:bg-gray-500 text-white px-4 py-2 rounded-lg font-medium transition"
                        disabled={processing}
                    >
                        ❌ Batal
                    </button>
                    <button
                        onClick={handleUpdate}
                        disabled={processing || isHoliday}
                        className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg font-bold shadow-lg transition flex items-center gap-2 disabled:opacity-50"
                    >
                        {processing ? 'Memproses...' : '✅ Perbarui Kehadiran'}
                    </button>
                </>
                )}
            </div>
            </div>

            {/* ALERT HARI LIBUR */}
            {isHoliday && holidayInfo && (
                <div className="w-full bg-red-900/30 border border-red-600/50 text-red-200 p-3 rounded-lg flex items-start gap-3 animate-slide-in">
                    <span className="text-2xl">🚫</span>
                    <div>
                        <h4 className="font-bold text-red-100">Tidak dapat menginput kehadiran</h4>
                        <p className="text-sm">
                            Status Tanggal: <strong>{holidayInfo.jenis.replace(/_/g, ' ')}</strong>.
                            {holidayInfo.keterangan && <span className="block mt-1 italic opacity-80">"{holidayInfo.keterangan}"</span>}
                        </p>
                    </div>
                </div>
            )}
        </div>
      </div>

      {/* --- TABLE CONTENT --- */}
      <div className="bg-gray-800 shadow-xl overflow-hidden rounded-xl border border-gray-700">
        {loading ? (
          <div className="p-10 flex justify-center items-center text-gray-400 gap-3">
            <span className="animate-spin text-2xl">⏳</span> Memuat data...
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-700">
              <thead className="bg-gray-750 text-gray-400">
                <tr>
                  <th className="px-6 py-4 text-center text-xs font-bold uppercase w-12">No</th>
                  <th className="px-6 py-4 text-left text-xs font-bold uppercase">Siswa</th>
                  <th className="px-6 py-4 text-center text-xs font-bold uppercase">Status Kehadiran</th>
                  <th className="px-6 py-4 text-left text-xs font-bold uppercase">Catatan</th>
                </tr>
              </thead>
              <tbody className="bg-gray-800 divide-y divide-gray-700">
                {siswaList.map((item, index) => {
                  const currentStatus = formData[item.id_siswa]?.status;
                  // Highlight row based on status
                  let rowBg = 'hover:bg-gray-750';
                  if (currentStatus === 'SAKIT') rowBg = 'bg-yellow-900/10 hover:bg-yellow-900/20';
                  if (currentStatus === 'IZIN') rowBg = 'bg-blue-900/10 hover:bg-blue-900/20';
                  if (currentStatus === 'ALPHA') rowBg = 'bg-red-900/10 hover:bg-red-900/20';

                  // Dimmed row if holiday
                  if (isHoliday) rowBg = 'bg-gray-900 opacity-60';

                  return (
                    <tr key={item.id} className={`transition-colors duration-200 ${rowBg}`}>
                      <td className="px-6 py-4 text-center text-gray-500 text-sm">
                        {index + 1}
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex flex-col">
                          <span className="text-sm font-bold text-white">{item.siswa?.nama}</span>
                          <span className="text-xs text-gray-400 flex gap-2">
                             <span>{item.siswa?.nisn}</span>
                             <span className="text-gray-600">•</span>
                             <span>{item.siswa?.jenis_kelamin}</span>
                          </span>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex items-center justify-center gap-3">
                          <RadioButton 
                            id_siswa={item.id_siswa} val="HADIR" label="H" 
                            colorClass="bg-green-600" 
                          />
                          <RadioButton 
                            id_siswa={item.id_siswa} val="SAKIT" label="S" 
                            colorClass="bg-yellow-500" 
                          />
                          <RadioButton 
                            id_siswa={item.id_siswa} val="IZIN" label="I" 
                            colorClass="bg-blue-500" 
                          />
                          <RadioButton 
                            id_siswa={item.id_siswa} val="ALPHA" label="A" 
                            colorClass="bg-red-500" 
                          />
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <input
                          type="text"
                          value={formData[item.id_siswa]?.catatan || ''}
                          onChange={(e) => handleCatatanChange(item.id_siswa, e.target.value)}
                          placeholder={mode === 'VIEW' ? "" : "Keterangan tambahan..."}
                          disabled={mode === 'VIEW' || isHoliday}
                          className={`
                            w-full bg-gray-900 border border-gray-600 text-white text-sm rounded-lg px-3 py-2
                            focus:ring-1 focus:ring-primary focus:border-primary transition
                            disabled:opacity-50 disabled:bg-gray-800 disabled:border-transparent
                            disabled:cursor-not-allowed
                          `}
                        />
                      </td>
                    </tr>
                  );
                })}
                {siswaList.length === 0 && (
                  <tr>
                    <td colSpan={4} className="p-10 text-center text-gray-500 italic flex flex-col items-center">
                      <span className="text-4xl mb-2">📭</span>
                      Belum ada siswa binaan yang ditugaskan kepada Anda.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Legend */}
      <div className="mt-4 flex gap-6 justify-center text-xs text-gray-400 font-medium">
         <span className="flex items-center gap-1"><div className="w-3 h-3 rounded bg-green-600"></div> H (Hadir)</span>
         <span className="flex items-center gap-1"><div className="w-3 h-3 rounded bg-yellow-500"></div> S (Sakit)</span>
         <span className="flex items-center gap-1"><div className="w-3 h-3 rounded bg-blue-500"></div> I (Izin)</span>
         <span className="flex items-center gap-1"><div className="w-3 h-3 rounded bg-red-500"></div> A (Alpha)</span>
      </div>

    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { supabase } from '../../supabaseClient';
import { Guru } from '../../types';
import * as XLSX from 'xlsx';

interface Props {
  currentUser: Guru;
  showToast: (msg: string, type: 'success' | 'error') => void;
}

export const ImportKehadiranTemplate: React.FC<Props> = ({ currentUser, showToast }) => {
  const [selectedDates, setSelectedDates] = useState<string[]>([]);

  // State Input
  const [singleDate, setSingleDate] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [hariSekolah, setHariSekolah] = useState<number>(5); // Default 5 hari

  const [loading, setLoading] = useState(false);
  const [importProgress, setImportProgress] = useState(0); 
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- INITIAL LOAD: Get Hari Sekolah ---
  useEffect(() => {
    const fetchSettings = async () => {
      const { data } = await supabase
        .from('sekolah')
        .select('hari_sekolah')
        .limit(1)
        .maybeSingle();
      if (data) {
        setHariSekolah(data.hari_sekolah);
      }
    };
    fetchSettings();
  }, []);

  // --- LOGIC TANGGAL ---

  // 1. Tambah Satu Tanggal dengan Validasi Live
  const handleAddSingleDate = async () => {
    if (!singleDate) return;

    // Cek Duplikasi Lokal
    if (selectedDates.includes(singleDate)) {
      showToast('Tanggal sudah ada dalam daftar', 'error');
      return;
    }

    setLoading(true);
    try {
        const dateObj = new Date(singleDate);
        const dayOfWeek = dateObj.getDay(); // 0 = Minggu

        // 1. Cek Akhir Pekan (Lokal)
        if (dayOfWeek === 0) {
            showToast('Gagal: Tanggal yang dipilih adalah hari Minggu.', 'error');
            return;
        }
        if (hariSekolah === 5 && dayOfWeek === 6) {
            showToast('Gagal: Tanggal yang dipilih adalah hari Sabtu (Libur Sekolah).', 'error');
            return;
        }

        // 2. Cek Kalender Pendidikan (Database)
        const { data: libur } = await supabase
            .from('kalender_pendidikan')
            .select('jenis, keterangan')
            .eq('tanggal', singleDate)
            .maybeSingle();

        if (libur) {
            showToast(`Gagal: Tanggal ini libur (${libur.jenis.replace(/_/g, ' ')}). ${libur.keterangan || ''}`, 'error');
            return;
        }

        // Lolos Validasi
        const newDates = [...selectedDates, singleDate].sort();
        setSelectedDates(newDates);
        setSingleDate('');
        showToast('Tanggal berhasil ditambahkan', 'success');

    } catch (error) {
        console.error(error);
        showToast('Terjadi kesalahan saat memvalidasi tanggal', 'error');
    } finally {
        setLoading(false);
    }
  };

  // 2. Tambah Rentang Tanggal dengan Filter Otomatis
  const handleAddRange = async () => {
    if (!startDate || !endDate) {
        showToast('Mohon isi Tanggal Mulai dan Tanggal Akhir', 'error');
        return;
    }

    const start = new Date(startDate);
    const end = new Date(endDate);

    if (start > end) {
        showToast('Tanggal Mulai tidak boleh lebih besar dari Tanggal Akhir', 'error');
        return;
    }

    setLoading(true);
    try {
        // Ambil Data Libur dalam rentang tersebut dari DB
        const { data: holidays } = await supabase
            .from('kalender_pendidikan')
            .select('tanggal, jenis')
            .gte('tanggal', startDate)
            .lte('tanggal', endDate);

        const holidayMap = new Set(holidays?.map(h => h.tanggal));

        const validDatesToAdd: string[] = [];
        let skippedCount = 0;
        let skippedReason = '';

        let current = new Date(start);

        // Loop dari start sampai end
        while (current <= end) {
            const dateStr = current.toISOString().split('T')[0];
            const dayOfWeek = current.getDay();

            let isValid = true;

            // Cek Akhir Pekan
            if (dayOfWeek === 0 || (hariSekolah === 5 && dayOfWeek === 6)) {
                isValid = false;
            }
            // Cek Kalender Libur
            else if (holidayMap.has(dateStr)) {
                isValid = false;
                skippedReason = 'Hari Libur Nasional/Sekolah';
            }
            // Cek Duplikasi State
            else if (selectedDates.includes(dateStr)) {
                isValid = false; // Sudah ada, skip diam-diam
            }

            if (isValid) {
                validDatesToAdd.push(dateStr);
            } else {
                // Hanya hitung skip jika bukan karena duplikasi (agar pesan toast relevan untuk filter libur)
                if (!selectedDates.includes(dateStr)) skippedCount++;
            }

            // Increment hari +1
            current.setDate(current.getDate() + 1);
        }

        if (validDatesToAdd.length === 0) {
            showToast('Tidak ada tanggal yang ditambahkan (Semua tanggal dalam rentang ini adalah hari libur/akhir pekan/sudah terpilih).', 'error');
        } else {
            const combinedDates = [...selectedDates, ...validDatesToAdd].sort();
            setSelectedDates(combinedDates);
            setStartDate('');
            setEndDate('');

            if (skippedCount > 0) {
                showToast(`Berhasil menambah ${validDatesToAdd.length} tanggal. (${skippedCount} tanggal dilewati karena Libur/Akhir Pekan)`, 'success');
            } else {
                showToast(`Berhasil menambah ${validDatesToAdd.length} tanggal.`, 'success');
            }
        }

    } catch (err) {
        showToast('Gagal memproses rentang tanggal', 'error');
    } finally {
        setLoading(false);
    }
  };

  const handleRemoveDate = (dateToRemove: string) => {
    setSelectedDates(selectedDates.filter(d => d !== dateToRemove));
  };

  const handleClearDates = () => {
      setSelectedDates([]);
  };

  // --- LOGIC GENERATE & IMPORT ---

  const handleGenerateTemplate = async () => {
    if (selectedDates.length === 0) {
      showToast('Pilih minimal satu tanggal terlebih dahulu', 'error');
      return;
    }

    setLoading(true);
    try {
      // Ambil data siswa
      const { data: siswaData, error } = await supabase
        .from('bimbingan')
        .select('*, siswa(id, nama, nisn, kelas(nama))')
        .eq('id_guru', currentUser.id)
        .order('created_at', { ascending: true });

      if (error) throw error;

      if (!siswaData || siswaData.length === 0) {
        showToast('Anda belum memiliki siswa binaan', 'error');
        setLoading(false);
        return;
      }

      const rows = siswaData.map((item, index) => {
        const row: any = {
          NO: index + 1,
          NISN: item.siswa?.nisn || '', 
          NAMA: item.siswa?.nama || '',
          KELAS: item.siswa?.kelas?.nama || '',
        };
        // Gunakan selectedDates sebagai header
        selectedDates.forEach(date => {
          row[date] = ''; 
        });
        return row;
      });

      const ws = XLSX.utils.json_to_sheet(rows);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Kehadiran");

      const filename = `Template_Kehadiran_${new Date().toISOString().split('T')[0]}.xlsx`;
      XLSX.writeFile(wb, filename);

      showToast('Template berhasil dibuat!', 'success');

    } catch (err: any) {
      console.error(err);
      showToast('Gagal membuat template: ' + err.message, 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setImportProgress(0); 
    const reader = new FileReader();

    reader.onload = async (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsName = wb.SheetNames[0];
        const ws = wb.Sheets[wsName];

        const data = XLSX.utils.sheet_to_json(ws);

        if (data.length === 0) {
          showToast('File Excel kosong', 'error');
          setLoading(false);
          return;
        }

        // --- VALIDASI HEADER TANGGAL SEBELUM IMPORT ---
        const firstRow = data[0] as any;
        const keys = Object.keys(firstRow);
        const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
        const dateColumns = keys.filter(k => dateRegex.test(k));

        if (dateColumns.length > 0) {
            // 1. Validasi Hari Libur (Weekend) sesuai pengaturan sekolah
            const invalidSchoolDays = dateColumns.filter(d => {
                const day = new Date(d).getDay();
                if (day === 0) return true; // Minggu
                if (hariSekolah === 5 && day === 6) return true; // Sabtu
                return false;
            });

            if (invalidSchoolDays.length > 0) {
                showToast(`GAGAL IMPORT! File mengandung tanggal libur sekolah (Sabtu/Minggu): ${invalidSchoolDays.join(', ')}`, 'error');
                setLoading(false);
                if (fileInputRef.current) fileInputRef.current.value = '';
                return;
            }

            // 2. Cek apakah ada tanggal libur (Kalender Pendidikan) di kolom Excel
            const { data: holidays } = await supabase
                .from('kalender_pendidikan')
                .select('tanggal, jenis')
                .in('tanggal', dateColumns);

            if (holidays && holidays.length > 0) {
                const holidayDates = holidays.map(h => `${h.tanggal} (${h.jenis})`).join(', ');
                showToast(`GAGAL IMPORT! File mengandung tanggal libur nasional: ${holidayDates}.`, 'error');
                setLoading(false);
                if (fileInputRef.current) fileInputRef.current.value = '';
                return;
            }
        }
        // ----------------------------------------------

        let processedCount = 0;
        let errorCount = 0;
        const totalRows = data.length;

        for (let i = 0; i < totalRows; i++) {
          const row: any = data[i];
          const nisn = row['NISN'] ? String(row['NISN']).trim() : '';
          const nama = row['NAMA'] ? String(row['NAMA']).trim() : '';

          if (!nisn && !nama) {
             const currentProgress = Math.round(((i + 1) / totalRows) * 100);
             setImportProgress(currentProgress);
             continue; 
          }

          let studentId = '';
          const { data: foundSiswa } = await supabase
             .from('siswa')
             .select('id')
             .eq('nisn', nisn)
             .maybeSingle();

          if (foundSiswa) {
            studentId = foundSiswa.id;
          } else {
            const { data: foundSiswaByName } = await supabase
                .from('siswa')
                .select('id')
                .ilike('nama', nama)
                .maybeSingle();
            if (foundSiswaByName) studentId = foundSiswaByName.id;
          }

          if (!studentId) {
            errorCount++;
          } else {
            for (const key of keys) {
               if (dateRegex.test(key)) {
                  const rawStatus = row[key] ? String(row[key]).trim().toUpperCase() : '';
                  let statusDb: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA' | null = null;

                  if (['H', 'HADIR'].includes(rawStatus)) statusDb = 'HADIR';
                  else if (['S', 'SAKIT'].includes(rawStatus)) statusDb = 'SAKIT';
                  else if (['I', 'IZIN'].includes(rawStatus)) statusDb = 'IZIN';
                  else if (['A', 'ALPHA', 'ALPA'].includes(rawStatus)) statusDb = 'ALPHA';

                  if (statusDb) {
                      // Upsert Kehadiran
                      const { error: upsertError } = await supabase.from('kehadiran').upsert({
                          id_guru: currentUser.id,
                          id_siswa: studentId,
                          tanggal: key,
                          status: statusDb
                      }, { onConflict: 'id_siswa, tanggal' });

                      // Fallback manual upsert logic jika tidak ada unique constraint composite
                      if (upsertError) {
                          const { data: existing } = await supabase
                              .from('kehadiran')
                              .select('id')
                              .eq('id_guru', currentUser.id)
                              .eq('id_siswa', studentId)
                              .eq('tanggal', key)
                              .maybeSingle();

                          if (existing) {
                              await supabase.from('kehadiran').update({ status: statusDb }).eq('id', existing.id);
                          } else {
                              await supabase.from('kehadiran').insert([{
                                  id_guru: currentUser.id,
                                  id_siswa: studentId,
                                  tanggal: key,
                                  status: statusDb
                              }]);
                          }
                      }
                  }
               }
            }
            processedCount++;
          }

          const currentProgress = Math.round(((i + 1) / totalRows) * 100);
          setImportProgress(currentProgress);
        }

        showToast(`Import selesai. ${processedCount} siswa diproses.`, 'success');
        if (errorCount > 0) {
            setTimeout(() => showToast(`${errorCount} siswa tidak ditemukan di database.`, 'error'), 2000);
        }

      } catch (err: any) {
        console.error(err);
        showToast('Gagal memproses file: ' + err.message, 'error');
      } finally {
        setLoading(false);
        setImportProgress(0);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };

    reader.readAsBinaryString(file);
  };

  return (
    <div className="max-w-4xl mx-auto p-4">
      <h2 className="text-3xl font-bold text-white mb-2">Import Kehadiran (Custom)</h2>
      <p className="text-gray-400 mb-8">
        Fitur ini memungkinkan Anda mengisi absensi untuk beberapa tanggal sekaligus menggunakan Excel.
        <br />
        <span className="text-yellow-500 text-xs">
            * Sistem otomatis memblokir penambahan tanggal libur/akhir pekan pada template.
        </span>
      </p>

      {/* STEP 1: PILIH TANGGAL */}
      <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-lg mb-6">
        <h3 className="text-lg font-semibold text-blue-400 mb-4">1. Pilih Tanggal & Buat Template</h3>

        <div className="space-y-6">

            {/* OPSI A: Tambah Rentang (Multiselect Logic) */}
            <div className="bg-gray-700/50 p-4 rounded-lg border border-gray-600">
                <label className="block text-sm font-bold text-white mb-3">🅰️ Opsi Cepat: Pilih Rentang Tanggal</label>
                <div className="flex flex-col md:flex-row gap-4 items-end">
                    <div className="flex-1 w-full">
                        <label className="text-xs text-gray-400 block mb-1">Dari Tanggal</label>
                        <input 
                            type="date" 
                            value={startDate}
                            onChange={(e) => setStartDate(e.target.value)}
                            className="bg-gray-700 border border-gray-500 text-white rounded px-3 py-2 w-full focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                        />
                    </div>
                    <div className="flex items-center justify-center pb-2 text-gray-400">
                        ➡️
                    </div>
                    <div className="flex-1 w-full">
                        <label className="text-xs text-gray-400 block mb-1">Sampai Tanggal</label>
                        <input 
                            type="date" 
                            value={endDate}
                            onChange={(e) => setEndDate(e.target.value)}
                            className="bg-gray-700 border border-gray-500 text-white rounded px-3 py-2 w-full focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                        />
                    </div>
                    <button 
                        onClick={handleAddRange}
                        disabled={loading}
                        className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded font-medium transition w-full md:w-auto h-[42px] disabled:opacity-50"
                    >
                        {loading ? 'Memvalidasi...' : '+ Tambahkan Rentang'}
                    </button>
                </div>
                <p className="text-xs text-gray-400 mt-2">
                    * Tanggal libur/akhir pekan di antara rentang ini akan otomatis dilewati.
                </p>
            </div>

            {/* OPSI B: Tambah Manual */}
            <div className="bg-gray-700/30 p-4 rounded-lg border border-gray-600 border-dashed">
                <label className="block text-sm font-bold text-gray-300 mb-3">🅱️ Opsi Manual: Tambah Satuan</label>
                <div className="flex flex-col md:flex-row gap-4">
                    <input 
                        type="date" 
                        value={singleDate}
                        onChange={(e) => setSingleDate(e.target.value)}
                        className="bg-gray-700 border border-gray-500 text-white rounded px-3 py-2 w-full md:w-64"
                    />
                    <button 
                        onClick={handleAddSingleDate}
                        disabled={loading}
                        className="bg-gray-600 hover:bg-gray-500 text-white px-4 py-2 rounded font-medium transition w-full md:w-auto disabled:opacity-50"
                    >
                        {loading ? 'Cek...' : '+ Tambah'}
                    </button>
                </div>
            </div>

            {/* Selected Dates Chips */}
            {selectedDates.length > 0 && (
                <div className="bg-gray-900/50 p-4 rounded-lg border border-gray-700">
                    <div className="flex justify-between items-center mb-2">
                        <span className="text-sm font-bold text-gray-300">Daftar Tanggal Terpilih ({selectedDates.length}):</span>
                        <button onClick={handleClearDates} className="text-xs text-red-400 hover:text-red-300 underline">Hapus Semua</button>
                    </div>
                    <div className="flex flex-wrap gap-2 max-h-40 overflow-y-auto custom-scrollbar">
                        {selectedDates.map(date => (
                            <div key={date} className="bg-primary/20 text-primary px-3 py-1 rounded-full text-sm flex items-center gap-2 border border-primary/30">
                                <span>🗓️ {date}</span>
                                <button 
                                    onClick={() => handleRemoveDate(date)}
                                    className="text-red-400 hover:text-red-300 font-bold px-1 hover:bg-white/10 rounded"
                                >
                                    &times;
                                </button>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            <div className="border-t border-gray-700 pt-4">
                <button 
                    onClick={handleGenerateTemplate}
                    disabled={loading || selectedDates.length === 0}
                    className="w-full bg-green-600 hover:bg-green-700 text-white px-6 py-3 rounded-lg font-bold transition shadow-lg flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    {loading ? 'Memproses...' : '📥 Buat & Download Template Excel'}
                </button>
            </div>
        </div>
      </div>

      {/* STEP 2: UPLOAD */}
      <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-lg">
        <h3 className="text-lg font-semibold text-green-400 mb-4">2. Upload & Import Data</h3>
        <p className="text-sm text-gray-400 mb-4">
            Isi file Excel yang telah diunduh dengan kode: <strong>H</strong> (Hadir), <strong>S</strong> (Sakit), <strong>I</strong> (Izin), <strong>A</strong> (Alpha).
        </p>

        <div className="flex flex-col items-center justify-center border-2 border-dashed border-gray-600 rounded-lg p-10 bg-gray-700/30 hover:bg-gray-700/50 transition relative">
            <input 
                type="file" 
                accept=".xlsx, .xls"
                ref={fileInputRef}
                onChange={handleFileUpload}
                disabled={loading}
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" 
                id="file-upload"
            />
            <div className="text-center pointer-events-none">
                <span className="text-4xl mb-2 block">📂</span>
                <span className="text-white font-medium mb-1 block">Klik atau Seret File Excel ke Sini</span>
                <span className="text-xs text-gray-500 block">Format .xlsx atau .xls</span>
            </div>
        </div>
      </div>

      {/* PROGRESS OVERLAY */}
      {loading && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-80">
          <div className="bg-gray-800 p-6 rounded-lg border border-gray-700 w-80 md:w-96 text-center">
            <h3 className="text-white font-bold mb-4 text-lg">Memproses Data...</h3>
            <div className="w-full bg-gray-700 rounded-full h-4 mb-2 overflow-hidden">
               <div 
                 className="bg-green-500 h-4 rounded-full transition-all duration-300" 
                 style={{ width: `${importProgress}%` }}
               ></div>
            </div>
            <p className="text-gray-300 font-medium">{importProgress}%</p>
            <p className="text-gray-500 text-sm mt-1">Mohon jangan tutup halaman ini.</p>
          </div>
        </div>
      )}

    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../supabaseClient';
import { Guru, Bimbingan, Kehadiran } from '../../types';
import { ConfirmDialog } from '../ConfirmDialog';

interface Props {
  currentUser: Guru;
  showToast: (msg: string, type: 'success' | 'error') => void;
}

// Tipe Data Form Lokal
interface FormState {
  [id_siswa: string]: {
    id?: string; // ID Kehadiran (jika ada)
    status: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA';
    catatan: string;
  };
}

// Tipe Info Libur
interface HolidayInfo {
  jenis: string;
  keterangan: string | null;
}

type ModeType = 'INPUT' | 'VIEW' | 'EDIT';

export const KehadiranBinaan: React.FC<Props> = ({ currentUser, showToast }) => {
  // Data Utama
  const [siswaList, setSiswaList] = useState<Bimbingan[]>([]);
  const [tanggal, setTanggal] = useState(new Date().toISOString().split('T')[0]);

  // State UI & Logic
  const [mode, setMode] = useState<ModeType>('INPUT');
  const [formData, setFormData] = useState<FormState>({});
  const [loading, setLoading] = useState(false);
  const [processing, setProcessing] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  // State Hari Libur & Sekolah & Masa Depan
  const [isHoliday, setIsHoliday] = useState(false);
  const [holidayInfo, setHolidayInfo] = useState<HolidayInfo | null>(null);
  const [hariSekolah, setHariSekolah] = useState<number>(5); // Default 5 hari

  // Variable Today untuk batasan
  const todayStr = new Date().toISOString().split('T')[0];

  // 1. Fetch Daftar Siswa & Setting Sekolah (Sekali saat mount)
  useEffect(() => {
    const fetchInitialData = async () => {
      setLoading(true);

      // Fetch Siswa
      const siswaPromise = supabase
        .from('bimbingan')
        .select('*, siswa(id, nama, nisn, jenis_kelamin, kelas(nama))')
        .eq('id_guru', currentUser.id)
        .order('created_at', { ascending: true });

      // Fetch Setting Sekolah
      const sekolahPromise = supabase
        .from('sekolah')
        .select('hari_sekolah')
        .limit(1)
        .maybeSingle();

      const [siswaRes, sekolahRes] = await Promise.all([siswaPromise, sekolahPromise]);

      if (siswaRes.data) {
         // @ts-ignore
         setSiswaList(siswaRes.data);
      }
      if (sekolahRes.data) {
         setHariSekolah(sekolahRes.data.hari_sekolah);
      }

      setLoading(false);
    };
    fetchInitialData();
  }, [currentUser.id]);

  // 2. Fetch Kehadiran & Cek Libur saat Tanggal/Siswa/HariSekolah Berubah
  useEffect(() => {
    if (siswaList.length > 0) {
      fetchDataAndCheckHoliday();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tanggal, siswaList, hariSekolah]);

  const fetchDataAndCheckHoliday = async () => {
    setLoading(true);
    setMode('INPUT'); 
    setIsHoliday(false);
    setHolidayInfo(null);

    try {
      // --- PRIORITY 1: CEK TANGGAL MASA DEPAN ---
      if (tanggal > todayStr) {
          setIsHoliday(true);
          setHolidayInfo({
              jenis: 'FUTURE_DATE',
              keterangan: 'Tanggal Masa Depan (Belum dapat diisi)'
          });
          setLoading(false);
          return; // Stop here, no need to fetch DB
      }

      // --- PRIORITY 2: CEK HARI SEKOLAH (SENIN-JUMAT / SABTU) ---
      const dateObj = new Date(tanggal);
      const dayOfWeek = dateObj.getDay(); // 0=Minggu, 6=Sabtu

      let isWeekend = false;
      let weekendLabel = '';

      if (dayOfWeek === 0) {
          isWeekend = true;
          weekendLabel = 'Hari Minggu';
      } else if (hariSekolah === 5 && dayOfWeek === 6) {
          isWeekend = true;
          weekendLabel = 'Hari Sabtu (Sekolah 5 Hari Kerja)';
      }

      if (isWeekend) {
          setIsHoliday(true);
          setHolidayInfo({ 
              jenis: 'HARI_NON_AKTIF', 
              keterangan: weekendLabel 
          });
          // Lanjut fetch data (mungkin ada data historis salah input yg mau dilihat)
      }

      // Parallel Request: Cek Kehadiran & Cek Kalender Pendidikan
      const queries: any[] = [
        supabase
          .from('kehadiran')
          .select('*')
          .eq('id_guru', currentUser.id)
          .eq('tanggal', tanggal)
      ];

      // Hanya query kalender jika belum terdeteksi weekend
      if (!isWeekend) {
          queries.push(
            supabase
              .from('kalender_pendidikan')
              .select('jenis, keterangan')
              .eq('tanggal', tanggal)
              .maybeSingle()
          );
      }

      const results = await Promise.all(queries);
      const kehadiranRes = results[0];
      const kalenderRes = results[1]; // Undefined jika isWeekend=true

      // --- PRIORITY 3: CEK KALENDER PENDIDIKAN ---
      if (!isWeekend && kalenderRes?.data) {
        setIsHoliday(true);
        setHolidayInfo(kalenderRes.data);
      }

      // 3. Handle Data Kehadiran
      const existingData = kehadiranRes.data as Kehadiran[] || [];
      const newFormState: FormState = {};

      if (existingData.length > 0) {
        // DATA ADA -> MODE VIEW
        setMode('VIEW');

        siswaList.forEach(item => {
          const record = existingData.find(k => k.id_siswa === item.id_siswa);
          if (record) {
            newFormState[item.id_siswa] = {
              id: record.id,
              status: record.status,
              catatan: record.catatan || ''
            };
          } else {
            newFormState[item.id_siswa] = { status: 'HADIR', catatan: '' };
          }
        });
      } else {
        // DATA KOSONG -> MODE INPUT (Default HADIR)
        setMode('INPUT');
        siswaList.forEach(item => {
          newFormState[item.id_siswa] = { status: 'HADIR', catatan: '' };
        });
      }

      setFormData(newFormState);

    } catch (error) {
      console.error(error);
      showToast('Gagal memuat data', 'error');
    } finally {
      setLoading(false);
    }
  };

  // --- Handlers ---

  const handleStatusChange = (id_siswa: string, val: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA') => {
    if (isHoliday) return; // Prevent change if holiday/future
    setFormData(prev => ({
      ...prev,
      [id_siswa]: { ...prev[id_siswa], status: val }
    }));
  };

  const handleCatatanChange = (id_siswa: string, val: string) => {
    if (isHoliday) return; // Prevent change if holiday/future
    setFormData(prev => ({
      ...prev,
      [id_siswa]: { ...prev[id_siswa], catatan: val }
    }));
  };

  const handleSave = async () => {
    // VALIDASI FINAL SEBELUM SAVE
    if (isHoliday) {
        showToast(`Gagal: ${holidayInfo?.keterangan || 'Hari Libur / Masa Depan'}.`, 'error');
        return;
    }

    setProcessing(true);
    try {
      const payload = siswaList.map(item => ({
        id_guru: currentUser.id,
        id_siswa: item.id_siswa,
        tanggal: tanggal,
        status: formData[item.id_siswa].status,
        catatan: formData[item.id_siswa].catatan
      }));

      const { error } = await supabase.from('kehadiran').insert(payload);
      if (error) throw error;

      showToast('✅ Kehadiran berhasil disimpan', 'success');
      await fetchDataAndCheckHoliday(); // Refresh ke mode VIEW
    } catch (e) {
      showToast('Gagal menyimpan data', 'error');
    } finally {
      setProcessing(false);
    }
  };

  const handleUpdate = async () => {
    // VALIDASI FINAL SEBELUM UPDATE
    if (isHoliday) {
        showToast(`Gagal: ${holidayInfo?.keterangan || 'Hari Libur / Masa Depan'}.`, 'error');
        return;
    }

    setProcessing(true);
    try {
      // Upsert: Jika ID ada (update), jika tidak (insert - kasus siswa baru)
      const payload = siswaList.map(item => {
        const form = formData[item.id_siswa];
        return {
          id: form.id, // Supabase Upsert pakai ID ini untuk update
          id_guru: currentUser.id,
          id_siswa: item.id_siswa,
          tanggal: tanggal,
          status: form.status,
          catatan: form.catatan
        };
      });

      const { error } = await supabase.from('kehadiran').upsert(payload);
      if (error) throw error;

      showToast('✅ Kehadiran berhasil diperbarui', 'success');
      await fetchDataAndCheckHoliday(); // Kembali ke mode VIEW
    } catch (e) {
      showToast('Gagal memperbarui data', 'error');
    } finally {
      setProcessing(false);
    }
  };

  const handleDelete = async () => {
    // Validasi Delete: Tidak boleh hapus masa depan (meskipun datanya anehnya ada)
    if (tanggal > todayStr) {
        showToast('Tidak dapat menghapus data masa depan.', 'error');
        return;
    }

    setProcessing(true);
    try {
      const { error } = await supabase
        .from('kehadiran')
        .delete()
        .eq('id_guru', currentUser.id)
        .eq('tanggal', tanggal);

      if (error) throw error;

      showToast('🗑️ Data kehadiran dihapus', 'success');
      setShowDeleteConfirm(false);
      await fetchDataAndCheckHoliday(); // Kembali ke mode INPUT
    } catch (e) {
      showToast('Gagal menghapus data', 'error');
    } finally {
      setProcessing(false);
    }
  };

  // --- Components ---

  const RadioButton = ({ id_siswa, val, label, colorClass }: any) => {
    const isSelected = formData[id_siswa]?.status === val;
    const isDisabled = mode === 'VIEW' || isHoliday; // Disabled if VIEW mode OR Holiday/Future

    return (
      <label className={`
        relative flex items-center justify-center w-10 h-10 rounded-lg transition-all duration-200
        ${isSelected 
          ? `${colorClass} text-white shadow-lg scale-110 font-bold ring-2 ring-white` 
          : 'bg-gray-700 text-gray-400 border border-gray-600'}
        ${isDisabled ? 'cursor-not-allowed opacity-60' : 'cursor-pointer hover:bg-gray-600'}
      `}>
        <input
          type="radio"
          name={`status-${id_siswa}`}
          value={val}
          checked={isSelected}
          onChange={() => !isDisabled && handleStatusChange(id_siswa, val)}
          disabled={isDisabled}
          className="hidden"
        />
        {label}
      </label>
    );
  };

  return (
    <div>
      <ConfirmDialog
        isOpen={showDeleteConfirm}
        message={`Yakin ingin menghapus seluruh data kehadiran pada tanggal ${tanggal}?`}
        onConfirm={handleDelete}
        onCancel={() => setShowDeleteConfirm(false)}
      />

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <div>
           <h2 className="text-2xl font-bold text-white">Input Kehadiran</h2>
           <p className="text-gray-400 text-sm">Kelola absensi harian siswa binaan.</p>
        </div>
      </div>

      {/* --- CONTROL PANEL (Sticky) --- */}
      <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 shadow-xl mb-6 sticky top-0 z-20">
        <div className="flex flex-col gap-4">
            <div className="flex flex-col lg:flex-row justify-between items-center gap-4">

            {/* Date Picker & Badge */}
            <div className="flex items-center gap-4 w-full lg:w-auto">
                <div className="relative">
                    <input
                    type="date"
                    value={tanggal}
                    max={todayStr} // Prevent selecting future dates via UI
                    onChange={(e) => setTanggal(e.target.value)}
                    className="bg-gray-900 border border-gray-600 text-white rounded-lg px-4 py-2 pl-10 focus:ring-2 focus:ring-primary focus:border-transparent shadow-inner"
                    />
                    <span className="absolute left-3 top-2.5 text-gray-400">📅</span>
                </div>

                {/* Mode Badge */}
                {mode === 'INPUT' && !isHoliday && (
                <span className="px-3 py-1 bg-green-500/20 text-green-400 border border-green-500/50 rounded-full text-xs font-bold uppercase tracking-wider animate-pulse">
                    Mode Input
                </span>
                )}
                {mode === 'VIEW' && !isHoliday && (
                <span className="px-3 py-1 bg-blue-500/20 text-blue-400 border border-blue-500/50 rounded-full text-xs font-bold uppercase tracking-wider">
                    Mode Lihat
                </span>
                )}
                {mode === 'EDIT' && !isHoliday && (
                <span className="px-3 py-1 bg-yellow-500/20 text-yellow-400 border border-yellow-500/50 rounded-full text-xs font-bold uppercase tracking-wider animate-pulse">
                    Mode Edit
                </span>
                )}
                {isHoliday && (
                    <span className={`px-3 py-1 text-xs font-bold uppercase tracking-wider rounded-full border ${
                        holidayInfo?.jenis === 'FUTURE_DATE' 
                        ? 'bg-gray-700 text-gray-400 border-gray-500' 
                        : 'bg-red-500/20 text-red-400 border-red-500/50 animate-pulse'
                    }`}>
                        ⛔ {holidayInfo?.jenis === 'HARI_NON_AKTIF' ? 'HARI LIBUR' : holidayInfo?.jenis === 'FUTURE_DATE' ? 'MASA DEPAN' : 'LIBUR NASIONAL'}
                    </span>
                )}
            </div>

            {/* Action Buttons based on Mode */}
            <div className="flex gap-2 w-full lg:w-auto justify-end">

                {/* 1. Jika Mode INPUT (Belum ada data) */}
                {mode === 'INPUT' && (
                <button
                    onClick={handleSave}
                    disabled={processing || siswaList.length === 0 || isHoliday}
                    className="bg-green-600 hover:bg-green-700 text-white px-6 py-2 rounded-lg font-bold shadow-lg transition flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    {processing ? 'Menyimpan...' : '💾 Simpan Kehadiran'}
                </button>
                )}

                {/* 2. Jika Mode VIEW (Data ada, hanya lihat) */}
                {mode === 'VIEW' && (
                <>
                    <button
                        onClick={() => setShowDeleteConfirm(true)}
                        disabled={isHoliday && holidayInfo?.jenis === 'FUTURE_DATE'} // Disable hapus jika future date
                        className="bg-red-900/50 hover:bg-red-900 text-red-200 border border-red-800 px-4 py-2 rounded-lg font-medium transition flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        🗑️ Hapus
                    </button>
                    {!isHoliday && (
                        <button
                            onClick={() => setMode('EDIT')}
                            className="bg-yellow-600 hover:bg-yellow-700 text-white px-5 py-2 rounded-lg font-bold shadow-lg transition flex items-center gap-2"
                        >
                            ✏️ Ubah Data
                        </button>
                    )}
                </>
                )}

                {/* 3. Jika Mode EDIT (Sedang mengedit) */}
                {mode === 'EDIT' && (
                <>
                    <button
                        onClick={() => { setMode('VIEW'); fetchDataAndCheckHoliday(); }} 
                        className="bg-gray-600 hover:bg-gray-500 text-white px-4 py-2 rounded-lg font-medium transition"
                        disabled={processing}
                    >
                        ❌ Batal
                    </button>
                    <button
                        onClick={handleUpdate}
                        disabled={processing || isHoliday}
                        className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg font-bold shadow-lg transition flex items-center gap-2 disabled:opacity-50"
                    >
                        {processing ? 'Memproses...' : '✅ Perbarui Kehadiran'}
                    </button>
                </>
                )}
            </div>
            </div>

            {/* ALERT HARI LIBUR / FUTURE */}
            {isHoliday && holidayInfo && (
                <div className={`w-full p-3 rounded-lg flex items-start gap-3 animate-slide-in border ${
                    holidayInfo.jenis === 'FUTURE_DATE' 
                    ? 'bg-gray-700/50 border-gray-600 text-gray-300' 
                    : 'bg-red-900/30 border-red-600/50 text-red-200'
                }`}>
                    <span className="text-2xl">{holidayInfo.jenis === 'FUTURE_DATE' ? '⏳' : '🚫'}</span>
                    <div>
                        <h4 className={`font-bold ${holidayInfo.jenis === 'FUTURE_DATE' ? 'text-gray-200' : 'text-red-100'}`}>
                            {holidayInfo.jenis === 'FUTURE_DATE' ? 'Tanggal Belum Dapat Diisi' : 'Tidak dapat menginput kehadiran'}
                        </h4>
                        <p className="text-sm">
                            Status: <strong>{holidayInfo.jenis === 'FUTURE_DATE' ? 'Masa Depan' : holidayInfo.jenis.replace(/_/g, ' ')}</strong>.
                            {holidayInfo.keterangan && <span className="block mt-1 italic opacity-80">"{holidayInfo.keterangan}"</span>}
                        </p>
                    </div>
                </div>
            )}
        </div>
      </div>

      {/* --- TABLE CONTENT --- */}
      <div className="bg-gray-800 shadow-xl overflow-hidden rounded-xl border border-gray-700">
        {loading ? (
          <div className="p-10 flex justify-center items-center text-gray-400 gap-3">
            <span className="animate-spin text-2xl">⏳</span> Memuat data...
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-700">
              <thead className="bg-gray-750 text-gray-400">
                <tr>
                  <th className="px-6 py-4 text-center text-xs font-bold uppercase w-12">No</th>
                  <th className="px-6 py-4 text-left text-xs font-bold uppercase">Siswa</th>
                  <th className="px-6 py-4 text-center text-xs font-bold uppercase">Status Kehadiran</th>
                  <th className="px-6 py-4 text-left text-xs font-bold uppercase">Catatan</th>
                </tr>
              </thead>
              <tbody className="bg-gray-800 divide-y divide-gray-700">
                {siswaList.map((item, index) => {
                  const currentStatus = formData[item.id_siswa]?.status;
                  // Highlight row based on status
                  let rowBg = 'hover:bg-gray-750';
                  if (currentStatus === 'SAKIT') rowBg = 'bg-yellow-900/10 hover:bg-yellow-900/20';
                  if (currentStatus === 'IZIN') rowBg = 'bg-blue-900/10 hover:bg-blue-900/20';
                  if (currentStatus === 'ALPHA') rowBg = 'bg-red-900/10 hover:bg-red-900/20';

                  // Dimmed row if holiday
                  if (isHoliday) rowBg = 'bg-gray-900 opacity-60';

                  return (
                    <tr key={item.id} className={`transition-colors duration-200 ${rowBg}`}>
                      <td className="px-6 py-4 text-center text-gray-500 text-sm">
                        {index + 1}
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex flex-col">
                          <span className="text-sm font-bold text-white">{item.siswa?.nama}</span>
                          <span className="text-xs text-gray-400 flex gap-2">
                             <span>{item.siswa?.nisn}</span>
                             <span className="text-gray-600">•</span>
                             <span>{item.siswa?.jenis_kelamin}</span>
                          </span>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex items-center justify-center gap-3">
                          <RadioButton 
                            id_siswa={item.id_siswa} val="HADIR" label="H" 
                            colorClass="bg-green-600" 
                          />
                          <RadioButton 
                            id_siswa={item.id_siswa} val="SAKIT" label="S" 
                            colorClass="bg-yellow-500" 
                          />
                          <RadioButton 
                            id_siswa={item.id_siswa} val="IZIN" label="I" 
                            colorClass="bg-blue-500" 
                          />
                          <RadioButton 
                            id_siswa={item.id_siswa} val="ALPHA" label="A" 
                            colorClass="bg-red-500" 
                          />
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <input
                          type="text"
                          value={formData[item.id_siswa]?.catatan || ''}
                          onChange={(e) => handleCatatanChange(item.id_siswa, e.target.value)}
                          placeholder={mode === 'VIEW' ? "" : "Keterangan tambahan..."}
                          disabled={mode === 'VIEW' || isHoliday}
                          className={`
                            w-full bg-gray-900 border border-gray-600 text-white text-sm rounded-lg px-3 py-2
                            focus:ring-1 focus:ring-primary focus:border-primary transition
                            disabled:opacity-50 disabled:bg-gray-800 disabled:border-transparent
                            disabled:cursor-not-allowed
                          `}
                        />
                      </td>
                    </tr>
                  );
                })}
                {siswaList.length === 0 && (
                  <tr>
                    <td colSpan={4} className="p-10 text-center text-gray-500 italic flex flex-col items-center">
                      <span className="text-4xl mb-2">📭</span>
                      Belum ada siswa binaan yang ditugaskan kepada Anda.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Legend */}
      <div className="mt-4 flex gap-6 justify-center text-xs text-gray-400 font-medium">
         <span className="flex items-center gap-1"><div className="w-3 h-3 rounded bg-green-600"></div> H (Hadir)</span>
         <span className="flex items-center gap-1"><div className="w-3 h-3 rounded bg-yellow-500"></div> S (Sakit)</span>
         <span className="flex items-center gap-1"><div className="w-3 h-3 rounded bg-blue-500"></div> I (Izin)</span>
         <span className="flex items-center gap-1"><div className="w-3 h-3 rounded bg-red-500"></div> A (Alpha)</span>
      </div>

    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { supabase } from '../../supabaseClient';
import { Guru } from '../../types';
import * as XLSX from 'xlsx';

interface Props {
  currentUser: Guru;
  showToast: (msg: string, type: 'success' | 'error') => void;
}

export const ImportKehadiranTemplate: React.FC<Props> = ({ currentUser, showToast }) => {
  const [selectedDates, setSelectedDates] = useState<string[]>([]);

  // State Input
  const [singleDate, setSingleDate] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [hariSekolah, setHariSekolah] = useState<number>(5); // Default 5 hari

  const [loading, setLoading] = useState(false);
  const [importProgress, setImportProgress] = useState(0); 
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Constants
  const todayStr = new Date().toISOString().split('T')[0];

  // --- INITIAL LOAD: Get Hari Sekolah ---
  useEffect(() => {
    const fetchSettings = async () => {
      const { data } = await supabase
        .from('sekolah')
        .select('hari_sekolah')
        .limit(1)
        .maybeSingle();
      if (data) {
        setHariSekolah(data.hari_sekolah);
      }
    };
    fetchSettings();
  }, []);

  // --- LOGIC TANGGAL ---

  // 1. Tambah Satu Tanggal dengan Validasi Live
  const handleAddSingleDate = async () => {
    if (!singleDate) return;

    // Cek Tanggal Masa Depan
    if (singleDate > todayStr) {
        showToast('Gagal: Tidak dapat memilih tanggal masa depan (besok atau setelahnya).', 'error');
        return;
    }

    // Cek Duplikasi Lokal
    if (selectedDates.includes(singleDate)) {
      showToast('Tanggal sudah ada dalam daftar', 'error');
      return;
    }

    setLoading(true);
    try {
        const dateObj = new Date(singleDate);
        const dayOfWeek = dateObj.getDay(); // 0 = Minggu

        // 1. Cek Akhir Pekan (Lokal)
        if (dayOfWeek === 0) {
            showToast('Gagal: Tanggal yang dipilih adalah hari Minggu.', 'error');
            return;
        }
        if (hariSekolah === 5 && dayOfWeek === 6) {
            showToast('Gagal: Tanggal yang dipilih adalah hari Sabtu (Libur Sekolah).', 'error');
            return;
        }

        // 2. Cek Kalender Pendidikan (Database)
        const { data: libur } = await supabase
            .from('kalender_pendidikan')
            .select('jenis, keterangan')
            .eq('tanggal', singleDate)
            .maybeSingle();

        if (libur) {
            showToast(`Gagal: Tanggal ini libur (${libur.jenis.replace(/_/g, ' ')}). ${libur.keterangan || ''}`, 'error');
            return;
        }

        // Lolos Validasi
        const newDates = [...selectedDates, singleDate].sort();
        setSelectedDates(newDates);
        setSingleDate('');
        showToast('Tanggal berhasil ditambahkan', 'success');

    } catch (error) {
        console.error(error);
        showToast('Terjadi kesalahan saat memvalidasi tanggal', 'error');
    } finally {
        setLoading(false);
    }
  };

  // 2. Tambah Rentang Tanggal dengan Filter Otomatis
  const handleAddRange = async () => {
    if (!startDate || !endDate) {
        showToast('Mohon isi Tanggal Mulai dan Tanggal Akhir', 'error');
        return;
    }

    const start = new Date(startDate);
    const end = new Date(endDate);

    if (start > end) {
        showToast('Tanggal Mulai tidak boleh lebih besar dari Tanggal Akhir', 'error');
        return;
    }

    setLoading(true);
    try {
        // Ambil Data Libur dalam rentang tersebut dari DB
        const { data: holidays } = await supabase
            .from('kalender_pendidikan')
            .select('tanggal, jenis')
            .gte('tanggal', startDate)
            .lte('tanggal', endDate);

        const holidayMap = new Set(holidays?.map(h => h.tanggal));

        const validDatesToAdd: string[] = [];
        let skippedCount = 0;
        let skippedReason = '';

        let current = new Date(start);

        // Loop dari start sampai end
        while (current <= end) {
            const dateStr = current.toISOString().split('T')[0];
            const dayOfWeek = current.getDay();

            let isValid = true;

            // Cek Tanggal Masa Depan
            if (dateStr > todayStr) {
                isValid = false;
                // Jangan break, lanjut loop (siapa tahu range berantakan, tapi idealnya urut)
                // Sebenarnya jika sorted, bisa break. Tapi aman continue.
            }
            // Cek Akhir Pekan
            else if (dayOfWeek === 0 || (hariSekolah === 5 && dayOfWeek === 6)) {
                isValid = false;
            }
            // Cek Kalender Libur
            else if (holidayMap.has(dateStr)) {
                isValid = false;
                skippedReason = 'Hari Libur Nasional/Sekolah';
            }
            // Cek Duplikasi State
            else if (selectedDates.includes(dateStr)) {
                isValid = false; // Sudah ada, skip diam-diam
            }

            if (isValid) {
                validDatesToAdd.push(dateStr);
            } else {
                // Hanya hitung skip jika bukan karena duplikasi
                if (!selectedDates.includes(dateStr)) skippedCount++;
            }

            // Increment hari +1
            current.setDate(current.getDate() + 1);
        }

        if (validDatesToAdd.length === 0) {
            showToast('Tidak ada tanggal yang ditambahkan (Semua tanggal dalam rentang ini libur/masa depan/sudah terpilih).', 'error');
        } else {
            const combinedDates = [...selectedDates, ...validDatesToAdd].sort();
            setSelectedDates(combinedDates);
            setStartDate('');
            setEndDate('');

            if (skippedCount > 0) {
                showToast(`Berhasil menambah ${validDatesToAdd.length} tanggal. (${skippedCount} dilewati karena Libur/Masa Depan)`, 'success');
            } else {
                showToast(`Berhasil menambah ${validDatesToAdd.length} tanggal.`, 'success');
            }
        }

    } catch (err) {
        showToast('Gagal memproses rentang tanggal', 'error');
    } finally {
        setLoading(false);
    }
  };

  const handleRemoveDate = (dateToRemove: string) => {
    setSelectedDates(selectedDates.filter(d => d !== dateToRemove));
  };

  const handleClearDates = () => {
      setSelectedDates([]);
  };

  // --- LOGIC GENERATE & IMPORT ---

  const handleGenerateTemplate = async () => {
    if (selectedDates.length === 0) {
      showToast('Pilih minimal satu tanggal terlebih dahulu', 'error');
      return;
    }

    setLoading(true);
    try {
      // Ambil data siswa
      const { data: siswaData, error } = await supabase
        .from('bimbingan')
        .select('*, siswa(id, nama, nisn, kelas(nama))')
        .eq('id_guru', currentUser.id)
        .order('created_at', { ascending: true });

      if (error) throw error;

      if (!siswaData || siswaData.length === 0) {
        showToast('Anda belum memiliki siswa binaan', 'error');
        setLoading(false);
        return;
      }

      const rows = siswaData.map((item, index) => {
        const row: any = {
          NO: index + 1,
          NISN: item.siswa?.nisn || '', 
          NAMA: item.siswa?.nama || '',
          KELAS: item.siswa?.kelas?.nama || '',
        };
        // Gunakan selectedDates sebagai header
        selectedDates.forEach(date => {
          row[date] = ''; 
        });
        return row;
      });

      const ws = XLSX.utils.json_to_sheet(rows);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Kehadiran");

      const filename = `Template_Kehadiran_${new Date().toISOString().split('T')[0]}.xlsx`;
      XLSX.writeFile(wb, filename);

      showToast('Template berhasil dibuat!', 'success');

    } catch (err: any) {
      console.error(err);
      showToast('Gagal membuat template: ' + err.message, 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setImportProgress(0); 
    const reader = new FileReader();

    reader.onload = async (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsName = wb.SheetNames[0];
        const ws = wb.Sheets[wsName];

        const data = XLSX.utils.sheet_to_json(ws);

        if (data.length === 0) {
          showToast('File Excel kosong', 'error');
          setLoading(false);
          return;
        }

        // --- VALIDASI HEADER TANGGAL SEBELUM IMPORT ---
        const firstRow = data[0] as any;
        const keys = Object.keys(firstRow);
        const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
        const dateColumns = keys.filter(k => dateRegex.test(k));

        if (dateColumns.length > 0) {
            // 1. Validasi Tanggal Masa Depan
            const futureDates = dateColumns.filter(d => d > todayStr);
            if (futureDates.length > 0) {
                showToast(`GAGAL IMPORT! File mengandung tanggal masa depan: ${futureDates.join(', ')}.`, 'error');
                setLoading(false);
                if (fileInputRef.current) fileInputRef.current.value = '';
                return;
            }

            // 2. Validasi Hari Libur (Weekend) sesuai pengaturan sekolah
            const invalidSchoolDays = dateColumns.filter(d => {
                const day = new Date(d).getDay();
                if (day === 0) return true; // Minggu
                if (hariSekolah === 5 && day === 6) return true; // Sabtu
                return false;
            });

            if (invalidSchoolDays.length > 0) {
                showToast(`GAGAL IMPORT! File mengandung tanggal libur sekolah (Sabtu/Minggu): ${invalidSchoolDays.join(', ')}`, 'error');
                setLoading(false);
                if (fileInputRef.current) fileInputRef.current.value = '';
                return;
            }

            // 3. Cek apakah ada tanggal libur (Kalender Pendidikan) di kolom Excel
            const { data: holidays } = await supabase
                .from('kalender_pendidikan')
                .select('tanggal, jenis')
                .in('tanggal', dateColumns);

            if (holidays && holidays.length > 0) {
                const holidayDates = holidays.map(h => `${h.tanggal} (${h.jenis})`).join(', ');
                showToast(`GAGAL IMPORT! File mengandung tanggal libur nasional: ${holidayDates}.`, 'error');
                setLoading(false);
                if (fileInputRef.current) fileInputRef.current.value = '';
                return;
            }
        }
        // ----------------------------------------------

        let processedCount = 0;
        let errorCount = 0;
        const totalRows = data.length;

        for (let i = 0; i < totalRows; i++) {
          const row: any = data[i];
          const nisn = row['NISN'] ? String(row['NISN']).trim() : '';
          const nama = row['NAMA'] ? String(row['NAMA']).trim() : '';

          if (!nisn && !nama) {
             const currentProgress = Math.round(((i + 1) / totalRows) * 100);
             setImportProgress(currentProgress);
             continue; 
          }

          let studentId = '';
          const { data: foundSiswa } = await supabase
             .from('siswa')
             .select('id')
             .eq('nisn', nisn)
             .maybeSingle();

          if (foundSiswa) {
            studentId = foundSiswa.id;
          } else {
            const { data: foundSiswaByName } = await supabase
                .from('siswa')
                .select('id')
                .ilike('nama', nama)
                .maybeSingle();
            if (foundSiswaByName) studentId = foundSiswaByName.id;
          }

          if (!studentId) {
            errorCount++;
          } else {
            for (const key of keys) {
               if (dateRegex.test(key)) {
                  const rawStatus = row[key] ? String(row[key]).trim().toUpperCase() : '';
                  let statusDb: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA' | null = null;

                  if (['H', 'HADIR'].includes(rawStatus)) statusDb = 'HADIR';
                  else if (['S', 'SAKIT'].includes(rawStatus)) statusDb = 'SAKIT';
                  else if (['I', 'IZIN'].includes(rawStatus)) statusDb = 'IZIN';
                  else if (['A', 'ALPHA', 'ALPA'].includes(rawStatus)) statusDb = 'ALPHA';

                  if (statusDb) {
                      // Upsert Kehadiran
                      const { error: upsertError } = await supabase.from('kehadiran').upsert({
                          id_guru: currentUser.id,
                          id_siswa: studentId,
                          tanggal: key,
                          status: statusDb
                      }, { onConflict: 'id_siswa, tanggal' });

                      // Fallback manual upsert logic jika tidak ada unique constraint composite
                      if (upsertError) {
                          const { data: existing } = await supabase
                              .from('kehadiran')
                              .select('id')
                              .eq('id_guru', currentUser.id)
                              .eq('id_siswa', studentId)
                              .eq('tanggal', key)
                              .maybeSingle();

                          if (existing) {
                              await supabase.from('kehadiran').update({ status: statusDb }).eq('id', existing.id);
                          } else {
                              await supabase.from('kehadiran').insert([{
                                  id_guru: currentUser.id,
                                  id_siswa: studentId,
                                  tanggal: key,
                                  status: statusDb
                              }]);
                          }
                      }
                  }
               }
            }
            processedCount++;
          }

          const currentProgress = Math.round(((i + 1) / totalRows) * 100);
          setImportProgress(currentProgress);
        }

        showToast(`Import selesai. ${processedCount} siswa diproses.`, 'success');
        if (errorCount > 0) {
            setTimeout(() => showToast(`${errorCount} siswa tidak ditemukan di database.`, 'error'), 2000);
        }

      } catch (err: any) {
        console.error(err);
        showToast('Gagal memproses file: ' + err.message, 'error');
      } finally {
        setLoading(false);
        setImportProgress(0);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };

    reader.readAsBinaryString(file);
  };

  return (
    <div className="max-w-4xl mx-auto p-4">
      <h2 className="text-3xl font-bold text-white mb-2">Import Kehadiran (Custom)</h2>
      <p className="text-gray-400 mb-8">
        Fitur ini memungkinkan Anda mengisi absensi untuk beberapa tanggal sekaligus menggunakan Excel.
        <br />
        <span className="text-yellow-500 text-xs">
            * Sistem otomatis memblokir penambahan tanggal libur/akhir pekan pada template.
        </span>
      </p>

      {/* STEP 1: PILIH TANGGAL */}
      <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-lg mb-6">
        <h3 className="text-lg font-semibold text-blue-400 mb-4">1. Pilih Tanggal & Buat Template</h3>

        <div className="space-y-6">

            {/* OPSI A: Tambah Rentang (Multiselect Logic) */}
            <div className="bg-gray-700/50 p-4 rounded-lg border border-gray-600">
                <label className="block text-sm font-bold text-white mb-3">🅰️ Opsi Cepat: Pilih Rentang Tanggal</label>
                <div className="flex flex-col md:flex-row gap-4 items-end">
                    <div className="flex-1 w-full">
                        <label className="text-xs text-gray-400 block mb-1">Dari Tanggal</label>
                        <input 
                            type="date" 
                            max={todayStr}
                            value={startDate}
                            onChange={(e) => setStartDate(e.target.value)}
                            className="bg-gray-700 border border-gray-500 text-white rounded px-3 py-2 w-full focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                        />
                    </div>
                    <div className="flex items-center justify-center pb-2 text-gray-400">
                        ➡️
                    </div>
                    <div className="flex-1 w-full">
                        <label className="text-xs text-gray-400 block mb-1">Sampai Tanggal</label>
                        <input 
                            type="date" 
                            max={todayStr}
                            value={endDate}
                            onChange={(e) => setEndDate(e.target.value)}
                            className="bg-gray-700 border border-gray-500 text-white rounded px-3 py-2 w-full focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                        />
                    </div>
                    <button 
                        onClick={handleAddRange}
                        disabled={loading}
                        className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded font-medium transition w-full md:w-auto h-[42px] disabled:opacity-50"
                    >
                        {loading ? 'Memvalidasi...' : '+ Tambahkan Rentang'}
                    </button>
                </div>
                <p className="text-xs text-gray-400 mt-2">
                    * Tanggal libur/akhir pekan di antara rentang ini akan otomatis dilewati.
                </p>
            </div>

            {/* OPSI B: Tambah Manual */}
            <div className="bg-gray-700/30 p-4 rounded-lg border border-gray-600 border-dashed">
                <label className="block text-sm font-bold text-gray-300 mb-3">🅱️ Opsi Manual: Tambah Satuan</label>
                <div className="flex flex-col md:flex-row gap-4">
                    <input 
                        type="date" 
                        max={todayStr}
                        value={singleDate}
                        onChange={(e) => setSingleDate(e.target.value)}
                        className="bg-gray-700 border border-gray-500 text-white rounded px-3 py-2 w-full md:w-64"
                    />
                    <button 
                        onClick={handleAddSingleDate}
                        disabled={loading}
                        className="bg-gray-600 hover:bg-gray-500 text-white px-4 py-2 rounded font-medium transition w-full md:w-auto disabled:opacity-50"
                    >
                        {loading ? 'Cek...' : '+ Tambah'}
                    </button>
                </div>
            </div>

            {/* Selected Dates Chips */}
            {selectedDates.length > 0 && (
                <div className="bg-gray-900/50 p-4 rounded-lg border border-gray-700">
                    <div className="flex justify-between items-center mb-2">
                        <span className="text-sm font-bold text-gray-300">Daftar Tanggal Terpilih ({selectedDates.length}):</span>
                        <button onClick={handleClearDates} className="text-xs text-red-400 hover:text-red-300 underline">Hapus Semua</button>
                    </div>
                    <div className="flex flex-wrap gap-2 max-h-40 overflow-y-auto custom-scrollbar">
                        {selectedDates.map(date => (
                            <div key={date} className="bg-primary/20 text-primary px-3 py-1 rounded-full text-sm flex items-center gap-2 border border-primary/30">
                                <span>🗓️ {date}</span>
                                <button 
                                    onClick={() => handleRemoveDate(date)}
                                    className="text-red-400 hover:text-red-300 font-bold px-1 hover:bg-white/10 rounded"
                                >
                                    &times;
                                </button>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            <div className="border-t border-gray-700 pt-4">
                <button 
                    onClick={handleGenerateTemplate}
                    disabled={loading || selectedDates.length === 0}
                    className="w-full bg-green-600 hover:bg-green-700 text-white px-6 py-3 rounded-lg font-bold transition shadow-lg flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    {loading ? 'Memproses...' : '📥 Buat & Download Template Excel'}
                </button>
            </div>
        </div>
      </div>

      {/* STEP 2: UPLOAD */}
      <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-lg">
        <h3 className="text-lg font-semibold text-green-400 mb-4">2. Upload & Import Data</h3>
        <p className="text-sm text-gray-400 mb-4">
            Isi file Excel yang telah diunduh dengan kode: <strong>H</strong> (Hadir), <strong>S</strong> (Sakit), <strong>I</strong> (Izin), <strong>A</strong> (Alpha).
        </p>

        <div className="flex flex-col items-center justify-center border-2 border-dashed border-gray-600 rounded-lg p-10 bg-gray-700/30 hover:bg-gray-700/50 transition relative">
            <input 
                type="file" 
                accept=".xlsx, .xls"
                ref={fileInputRef}
                onChange={handleFileUpload}
                disabled={loading}
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" 
                id="file-upload"
            />
            <div className="text-center pointer-events-none">
                <span className="text-4xl mb-2 block">📂</span>
                <span className="text-white font-medium mb-1 block">Klik atau Seret File Excel ke Sini</span>
                <span className="text-xs text-gray-500 block">Format .xlsx atau .xls</span>
            </div>
        </div>
      </div>

      {/* PROGRESS OVERLAY */}
      {loading && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-80">
          <div className="bg-gray-800 p-6 rounded-lg border border-gray-700 w-80 md:w-96 text-center">
            <h3 className="text-white font-bold mb-4 text-lg">Memproses Data...</h3>
            <div className="w-full bg-gray-700 rounded-full h-4 mb-2 overflow-hidden">
               <div 
                 className="bg-green-500 h-4 rounded-full transition-all duration-300" 
                 style={{ width: `${importProgress}%` }}
               ></div>
            </div>
            <p className="text-gray-300 font-medium">{importProgress}%</p>
            <p className="text-gray-500 text-sm mt-1">Mohon jangan tutup halaman ini.</p>
          </div>
        </div>
      )}

    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../supabaseClient';
import { Guru, Siswa, Kelas, Kehadiran } from '../types';
import { ConfirmDialog } from './ConfirmDialog';

interface Props {
  currentUser: Guru;
  showToast: (msg: string, type: 'success' | 'error') => void;
}

interface AttendanceFormState {
  [id_siswa: string]: {
    id?: string;
    status: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA' | null;
    catatan: string;
  };
}

interface HolidayInfo {
  jenis: string;
  keterangan: string | null;
}

export const InputKehadiranAdmin: React.FC<Props> = ({ currentUser, showToast }) => {
  const [kelasOptions, setKelasOptions] = useState<Kelas[]>([]);
  const [selectedKelas, setSelectedKelas] = useState<string>('ALL');

  const [siswaList, setSiswaList] = useState<Siswa[]>([]);
  const [tanggal, setTanggal] = useState(new Date().toISOString().split('T')[0]);

  const [loadingSiswa, setLoadingSiswa] = useState(false);
  const [processing, setProcessing] = useState(false);

  // Pagination State
  const [currentPage, setCurrentPage] = useState(1);
  const [rowsPerPage, setRowsPerPage] = useState(100);
  const [totalStudents, setTotalStudents] = useState(0);

  // Form State
  const [formData, setFormData] = useState<AttendanceFormState>({});
  const [isDataSaved, setIsDataSaved] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  // Validation State
  const [hariSekolah, setHariSekolah] = useState<number>(5);
  const [isHoliday, setIsHoliday] = useState(false);
  const [holidayInfo, setHolidayInfo] = useState<HolidayInfo | null>(null);

  const todayStr = new Date().toISOString().split('T')[0];

  // 1. Fetch Class Options & School Settings
  useEffect(() => {
    const fetchInitial = async () => {
      const { data: k } = await supabase.from('kelas').select('*').order('nama');
      if (k) setKelasOptions(k);

      const { data: s } = await supabase.from('sekolah').select('hari_sekolah').limit(1).maybeSingle();
      if (s) setHariSekolah(s.hari_sekolah);
    };
    fetchInitial();
  }, []);

  // 2. Fetch Students when Class, Page, or RowsPerPage changes
  useEffect(() => {
    // Reset page to 1 if class changes (handled in handleClassChange)
    if (selectedKelas) {
      fetchStudents();
    } else {
      setSiswaList([]);
      setTotalStudents(0);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedKelas, currentPage, rowsPerPage]);

  // 3. Check Validity & Fetch Attendance when Date or Student List changes
  useEffect(() => {
    if (siswaList.length > 0 && selectedKelas) {
      validateDateAndFetch();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tanggal, siswaList, hariSekolah]);

  const validateDateAndFetch = async () => {
      // RESET STATE
      setIsHoliday(false);
      setHolidayInfo(null);
      setIsEditing(false); // Reset edit mode on date change

      // --- VALIDASI 1: TANGGAL MASA DEPAN ---
      if (tanggal > todayStr) {
          setIsHoliday(true);
          setHolidayInfo({ jenis: 'FUTURE_DATE', keterangan: 'Tanggal Masa Depan (Belum dapat diisi)' });
          // Walaupun masa depan, kita coba fetch data (siapa tau ada data aneh masuk)
          await fetchKehadiran(); 
          return;
      }

      // --- VALIDASI 2: HARI SEKOLAH ---
      const dateObj = new Date(tanggal);
      const dayOfWeek = dateObj.getDay(); // 0=Minggu, 6=Sabtu

      if (dayOfWeek === 0) {
          setIsHoliday(true);
          setHolidayInfo({ jenis: 'HARI_NON_AKTIF', keterangan: 'Hari Minggu' });
      } else if (hariSekolah === 5 && dayOfWeek === 6) {
          setIsHoliday(true);
          setHolidayInfo({ jenis: 'HARI_NON_AKTIF', keterangan: 'Hari Sabtu (Sekolah 5 Hari Kerja)' });
      }

      // Jika sudah terdeteksi libur sekolah, lanjut fetch kehadiran (mode view only)
      if (dayOfWeek === 0 || (hariSekolah === 5 && dayOfWeek === 6)) {
          await fetchKehadiran();
          return;
      }

      // --- VALIDASI 3: KALENDER PENDIDIKAN ---
      // Cek DB untuk hari libur nasional dll
      const { data: libur } = await supabase
          .from('kalender_pendidikan')
          .select('jenis, keterangan')
          .eq('tanggal', tanggal)
          .maybeSingle();

      if (libur) {
          setIsHoliday(true);
          setHolidayInfo(libur);
      }

      // Akhirnya fetch data kehadiran
      await fetchKehadiran();
  };

  const handleClassChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
      setSelectedKelas(e.target.value);
      setCurrentPage(1); // Reset to page 1 on filter change
  };

  const fetchStudents = async () => {
    setLoadingSiswa(true);
    try {
        let query = supabase
          .from('siswa')
          .select('id, nama, nisn, jenis_kelamin, kelas(nama)', { count: 'exact' });

        if (selectedKelas !== 'ALL') {
            // Filter by specific class
            query = query.eq('id_kelas', selectedKelas).order('nama');
        } else {
            // ALL CLASSES -> Apply Pagination
            const from = (currentPage - 1) * rowsPerPage;
            const to = from + rowsPerPage - 1;

            query = query
                .order('id_kelas', { ascending: true }) 
                .order('nama', { ascending: true })
                .range(from, to);
        }

        const { data, count, error } = await query;

        if (error) throw error;

        // @ts-ignore
        if (data) setSiswaList(data);
        else setSiswaList([]);

        if (count !== null) setTotalStudents(count);

    } catch (error) {
        showToast('Gagal memuat data siswa', 'error');
    } finally {
        setLoadingSiswa(false);
    }
  };

  const fetchKehadiran = async () => {
    try {
        const studentIds = siswaList.map(s => s.id);

        // Fetch existing attendance for these students on this date
        const { data } = await supabase
          .from('kehadiran')
          .select('*')
          .in('id_siswa', studentIds)
          .eq('tanggal', tanggal);

        const currentData = data as Kehadiran[] || [];
        const newFormState: AttendanceFormState = {};
        const hasData = currentData.length > 0;

        setIsDataSaved(hasData);

        siswaList.forEach(s => {
            const record = currentData.find(k => k.id_siswa === s.id);
            if (record) {
                newFormState[s.id] = {
                    id: record.id,
                    status: record.status,
                    catatan: record.catatan || ''
                };
            } else {
                newFormState[s.id] = {
                    status: null, 
                    catatan: ''
                };
            }
        });

        setFormData(newFormState);

    } catch (error) {
        console.error(error);
    }
  };

  const handleRadioChange = (id_siswa: string, value: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA') => {
    if (isHoliday) return; // Prevent change if holiday/future
    setFormData(prev => ({
        ...prev,
        [id_siswa]: { ...prev[id_siswa], status: value }
    }));
  };

  const handleCatatanChange = (id_siswa: string, value: string) => {
    if (isHoliday) return; // Prevent change if holiday/future
    setFormData(prev => ({
        ...prev,
        [id_siswa]: { ...prev[id_siswa], catatan: value }
    }));
  };

  const handleSaveOrUpdate = async () => {
    if (isHoliday) {
        showToast(`Gagal: ${holidayInfo?.keterangan || 'Hari Libur / Masa Depan'}`, 'error');
        return;
    }

    setProcessing(true);
    try {
        // Hanya ambil data yang statusnya dipilih (tidak null)
        const payload = siswaList
            .filter(s => formData[s.id]?.status !== null)
            .map(s => {
                const form = formData[s.id];
                const record: any = {
                    id_guru: currentUser.id, // Admin ID as the recorder
                    id_siswa: s.id,
                    tanggal: tanggal,
                    status: form.status,
                    catatan: form.catatan
                };
                if (form.id) record.id = form.id;
                return record;
            });

        if (payload.length === 0) {
            showToast('⚠️ Tidak ada status kehadiran yang dipilih.', 'error');
            setProcessing(false);
            return;
        }

        const { error } = await supabase.from('kehadiran').upsert(payload);
        if (error) throw error;

        showToast(isDataSaved ? '✅ Data diperbarui' : '✅ Data disimpan', 'success');
        await fetchKehadiran();
    } catch (error) {
        showToast('❌ Gagal menyimpan data', 'error');
    } finally {
        setProcessing(false);
    }
  };

  const handleDelete = async () => {
    // Prevent delete on future dates (unless overridden, but logic says block)
    if (tanggal > todayStr) {
        showToast('Tidak dapat menghapus data masa depan.', 'error');
        return;
    }

    setProcessing(true);
    try {
        const studentIds = siswaList.map(s => s.id);
        const { error } = await supabase
            .from('kehadiran')
            .delete()
            .in('id_siswa', studentIds)
            .eq('tanggal', tanggal);

        if (error) throw error;
        showToast('✅ Data dihapus', 'success');
        setShowDeleteConfirm(false);
        await fetchKehadiran();
    } catch (error) {
        showToast('❌ Gagal menghapus', 'error');
    } finally {
        setProcessing(false);
    }
  };

  const RadioOption = ({ id_siswa, val, label, activeColorClass }: any) => {
      const isChecked = formData[id_siswa]?.status === val;
      // Disable if: Holiday OR (Data Saved AND Not Editing)
      const isDisabled = isHoliday || (isDataSaved && !isEditing);

      return (
          <label className={`
            cursor-pointer flex items-center justify-center w-8 h-8 md:w-10 md:h-10 rounded-lg border-2 transition-all select-none
            ${isChecked ? `${activeColorClass} border-transparent text-white shadow-md transform scale-110` : 'border-gray-600 text-gray-400 hover:bg-gray-700'}
            ${isDisabled ? 'opacity-50 cursor-not-allowed' : ''}
          `}>
              <input 
                type="radio" 
                name={`status-${id_siswa}`} 
                value={val}
                checked={isChecked}
                onChange={() => !isDisabled && handleRadioChange(id_siswa, val)}
                className="hidden"
                disabled={isDisabled}
              />
              <span className="font-bold text-xs md:text-sm">{label}</span>
          </label>
      );
  };

  // Pagination Logic Helpers
  const totalPages = Math.ceil(totalStudents / rowsPerPage);
  const startRowIndex = (currentPage - 1) * rowsPerPage;

  return (
    <div>
      <ConfirmDialog 
        isOpen={showDeleteConfirm} 
        message={`Hapus data kehadiran siswa yang tampil ini pada tanggal ${tanggal}?`} 
        onConfirm={handleDelete} 
        onCancel={() => setShowDeleteConfirm(false)} 
      />

      <h2 className="text-2xl font-bold text-white mb-6">Input Kehadiran (Admin)</h2>

      {/* Filter Section */}
      <div className="bg-gray-800 p-4 rounded-lg border border-gray-700 mb-6 flex flex-col md:flex-row gap-4">
        <div className="flex-1">
            <label className="text-gray-300 text-sm block mb-1">Pilih Kelas</label>
            <select
                value={selectedKelas}
                onChange={handleClassChange}
                className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white focus:border-primary"
            >
                <option value="">-- Pilih Kelas --</option>
                <option value="ALL">🌟 Semua Kelas (Tampilkan Semua Siswa)</option>
                <optgroup label="Kelas Spesifik">
                    {kelasOptions.map(k => (
                        <option key={k.id} value={k.id}>{k.nama}</option>
                    ))}
                </optgroup>
            </select>
        </div>
        <div className="flex-1">
             <label className="text-gray-300 text-sm block mb-1">Tanggal</label>
             <input 
                type="date" 
                value={tanggal}
                max={todayStr} // UI constraint for future dates
                onChange={(e) => setTanggal(e.target.value)}
                className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white focus:border-primary"
             />
        </div>
      </div>

      {/* Alert Block for Holiday/Future */}
      {isHoliday && holidayInfo && (
        <div className={`mb-6 p-4 rounded-lg flex items-start gap-3 border ${
            holidayInfo.jenis === 'FUTURE_DATE' 
            ? 'bg-gray-700/50 border-gray-600 text-gray-300' 
            : 'bg-red-900/30 border-red-600/50 text-red-200'
        }`}>
            <span className="text-2xl">{holidayInfo.jenis === 'FUTURE_DATE' ? '⏳' : '🚫'}</span>
            <div>
                <h4 className={`font-bold ${holidayInfo.jenis === 'FUTURE_DATE' ? 'text-gray-200' : 'text-red-100'}`}>
                    {holidayInfo.jenis === 'FUTURE_DATE' ? 'Tanggal Belum Dapat Diisi' : 'Tidak dapat menginput kehadiran'}
                </h4>
                <p className="text-sm">
                    Status: <strong>{holidayInfo.jenis === 'FUTURE_DATE' ? 'Masa Depan' : holidayInfo.jenis.replace(/_/g, ' ')}</strong>.
                    {holidayInfo.keterangan && <span className="block mt-1 italic opacity-80">"{holidayInfo.keterangan}"</span>}
                </p>
            </div>
        </div>
      )}

      {/* Main Content */}
      {!selectedKelas ? (
          <div className="p-10 text-center text-gray-500 border-2 border-dashed border-gray-700 rounded-lg">
              Silakan pilih kelas terlebih dahulu.
          </div>
      ) : loadingSiswa ? (
          <div className="p-10 text-center text-gray-400">Memuat data siswa...</div>
      ) : siswaList.length === 0 ? (
          <div className="p-10 text-center text-gray-500 bg-gray-800 rounded-lg">
              Tidak ada siswa ditemukan.
          </div>
      ) : (
          <div className="space-y-4">
               {/* Action Buttons */}
               <div className="flex flex-col md:flex-row justify-between items-center bg-gray-800 p-4 rounded-lg border border-gray-700 sticky top-0 z-10 gap-3">
                   <div className="text-gray-300 text-sm">
                       Total Siswa: <span className="text-white font-bold">{selectedKelas === 'ALL' ? totalStudents : siswaList.length}</span>
                       {selectedKelas === 'ALL' && <span className="text-gray-500 text-xs ml-2">(Menampilkan {siswaList.length} baris)</span>}
                       {isDataSaved && isEditing && <span className="ml-3 px-2 py-1 bg-yellow-600 text-white rounded text-xs font-bold animate-pulse">MODE EDIT</span>}
                   </div>
                   <div className="flex gap-2">
                       {/* BUTTON LOGIC:
                           If Holiday: ALL DISABLED (Except maybe cancel if editing active, but editing disabled anyway)
                           Else If Saved & Not Editing: Show Edit/Delete
                           Else (Not Saved OR Editing): Show Save/Cancel
                       */}
                       {isHoliday ? (
                           <span className="text-red-400 text-sm font-bold italic py-2">Input Dikunci</span>
                       ) : isDataSaved && !isEditing ? (
                           <>
                               <button onClick={() => setIsEditing(true)} className="bg-yellow-600 hover:bg-yellow-700 text-white px-4 py-2 rounded font-medium shadow-lg text-sm">✏️ Edit</button>
                               <button onClick={() => setShowDeleteConfirm(true)} className="bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded font-medium shadow-lg text-sm">🗑️ Hapus</button>
                           </>
                       ) : (
                           <>
                               {isEditing && (
                                   <button onClick={() => { setIsEditing(false); fetchKehadiran(); }} className="bg-gray-600 hover:bg-gray-500 text-white px-4 py-2 rounded text-sm">Batal</button>
                               )}
                               <button onClick={handleSaveOrUpdate} disabled={processing} className="bg-green-600 hover:bg-green-700 text-white px-6 py-2 rounded font-bold shadow-lg disabled:opacity-50 text-sm">
                                   {processing ? 'Menyimpan...' : '💾 Simpan Data'}
                               </button>
                           </>
                       )}
                   </div>
               </div>

               {/* Table */}
               <div className="bg-gray-800 shadow overflow-hidden rounded-lg border border-gray-700">
                  <div className="overflow-x-auto">
                      <table className="min-w-full divide-y divide-gray-700">
                          <thead className="bg-gray-700">
                              <tr>
                                  <th className="px-6 py-3 text-center text-xs font-medium text-gray-300 uppercase w-10">No</th>
                                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Nama Siswa</th>
                                  {selectedKelas === 'ALL' && (
                                     <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Kelas</th>
                                  )}
                                  <th className="px-6 py-3 text-center text-xs font-medium text-gray-300 uppercase w-20">L/P</th>
                                  <th className="px-6 py-3 text-center text-xs font-medium text-gray-300 uppercase">Status</th>
                                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Catatan</th>
                              </tr>
                          </thead>
                          <tbody className={`bg-gray-800 divide-y divide-gray-700 ${isHoliday ? 'opacity-60 grayscale-[50%]' : ''}`}>
                              {siswaList.map((s, idx) => {
                                  // Row numbering calculation based on pagination
                                  const rowNumber = selectedKelas === 'ALL' ? startRowIndex + idx + 1 : idx + 1;

                                  return (
                                  <tr key={s.id} className="hover:bg-gray-750">
                                      <td className="px-6 py-4 text-center text-gray-500 text-sm">{rowNumber}</td>
                                      <td className="px-6 py-4">
                                          <div className="text-sm font-bold text-white">{s.nama}</div>
                                          <div className="text-xs text-gray-400">{s.nisn}</div>
                                      </td>
                                      {selectedKelas === 'ALL' && (
                                         <td className="px-6 py-4 text-sm text-blue-300">
                                             {s.kelas?.nama || '-'}
                                         </td>
                                      )}
                                      <td className="px-6 py-4 text-center text-sm text-gray-300">{s.jenis_kelamin}</td>
                                      <td className="px-6 py-4">
                                          <div className="flex items-center justify-center gap-2 md:gap-4">
                                              <RadioOption id_siswa={s.id} val="HADIR" label="H" activeColorClass="bg-green-600" />
                                              <RadioOption id_siswa={s.id} val="IZIN" label="I" activeColorClass="bg-blue-600" />
                                              <RadioOption id_siswa={s.id} val="SAKIT" label="S" activeColorClass="bg-yellow-600" />
                                              <RadioOption id_siswa={s.id} val="ALPHA" label="A" activeColorClass="bg-red-600" />
                                          </div>
                                      </td>
                                      <td className="px-6 py-4">
                                          <input 
                                              type="text"
                                              value={formData[s.id]?.catatan || ''}
                                              onChange={(e) => handleCatatanChange(s.id, e.target.value)}
                                              disabled={isHoliday || (isDataSaved && !isEditing)}
                                              placeholder={isHoliday ? "Terkunci" : "Ket..."}
                                              className="bg-gray-700 border border-gray-600 text-white text-sm rounded px-3 py-2 w-full disabled:opacity-50 disabled:cursor-not-allowed"
                                          />
                                      </td>
                                  </tr>
                              )})}
                          </tbody>
                      </table>
                  </div>

                  {/* Pagination Controls - Only show if ALL Classes selected */}
                  {selectedKelas === 'ALL' && (
                      <div className="bg-gray-700 px-4 py-3 border-t border-gray-600 flex flex-col md:flex-row items-center justify-between gap-4">
                          <div className="flex items-center gap-2">
                              <span className="text-sm text-gray-300">Tampilkan</span>
                              <select 
                                value={rowsPerPage}
                                onChange={(e) => {
                                    setRowsPerPage(Number(e.target.value));
                                    setCurrentPage(1);
                                }}
                                className="bg-gray-800 border border-gray-500 text-white text-sm rounded px-2 py-1 focus:outline-none"
                              >
                                  <option value={10}>10</option>
                                  <option value={50}>50</option>
                                  <option value={100}>100</option>
                                  <option value={200}>200</option>
                              </select>
                              <span className="text-sm text-gray-300">baris per halaman</span>
                          </div>

                          <div className="flex items-center gap-4">
                              <span className="text-sm text-gray-300">
                                  Halaman <strong>{currentPage}</strong> dari <strong>{totalPages}</strong>
                              </span>
                              <div className="flex gap-1">
                                  <button
                                    onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                                    disabled={currentPage === 1}
                                    className="px-3 py-1 bg-gray-600 hover:bg-gray-500 text-white rounded disabled:opacity-50 disabled:cursor-not-allowed"
                                  >
                                      &laquo; Prev
                                  </button>
                                  <button
                                    onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
                                    disabled={currentPage === totalPages}
                                    className="px-3 py-1 bg-gray-600 hover:bg-gray-500 text-white rounded disabled:opacity-50 disabled:cursor-not-allowed"
                                  >
                                      Next &raquo;
                                  </button>
                              </div>
                          </div>
                      </div>
                  )}
               </div>
          </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../supabaseClient';
import { Guru, Bimbingan, Kehadiran } from '../../types';
import { ConfirmDialog } from '../ConfirmDialog';

interface Props {
  currentUser: Guru;
  showToast: (msg: string, type: 'success' | 'error') => void;
}

// Tipe Data Form Lokal
interface FormState {
  [id_siswa: string]: {
    id?: string; // ID Kehadiran (jika ada)
    status: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA';
    catatan: string;
  };
}

// Tipe Info Libur
interface HolidayInfo {
  jenis: string;
  keterangan: string | null;
}

type ModeType = 'INPUT' | 'VIEW' | 'EDIT';

export const KehadiranBinaan: React.FC<Props> = ({ currentUser, showToast }) => {
  // Data Utama
  const [siswaList, setSiswaList] = useState<Bimbingan[]>([]);
  const [tanggal, setTanggal] = useState(new Date().toISOString().split('T')[0]);

  // State UI & Logic
  const [mode, setMode] = useState<ModeType>('INPUT');
  const [formData, setFormData] = useState<FormState>({});
  const [loading, setLoading] = useState(false);
  const [processing, setProcessing] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  // State Hari Libur & Sekolah & Masa Depan
  const [isHoliday, setIsHoliday] = useState(false);
  const [holidayInfo, setHolidayInfo] = useState<HolidayInfo | null>(null);
  const [hariSekolah, setHariSekolah] = useState<number>(5); // Default 5 hari

  // Variable Today untuk batasan
  const todayStr = new Date().toISOString().split('T')[0];

  // 1. Fetch Daftar Siswa & Setting Sekolah (Sekali saat mount)
  useEffect(() => {
    const fetchInitialData = async () => {
      setLoading(true);

      // Fetch Siswa
      const siswaPromise = supabase
        .from('bimbingan')
        .select('*, siswa(id, nama, nisn, jenis_kelamin, kelas(nama))')
        .eq('id_guru', currentUser.id)
        .order('created_at', { ascending: true });

      // Fetch Setting Sekolah
      const sekolahPromise = supabase
        .from('sekolah')
        .select('hari_sekolah')
        .limit(1)
        .maybeSingle();

      const [siswaRes, sekolahRes] = await Promise.all([siswaPromise, sekolahPromise]);

      if (siswaRes.data) {
         // @ts-ignore
         setSiswaList(siswaRes.data);
      }
      if (sekolahRes.data) {
         setHariSekolah(sekolahRes.data.hari_sekolah);
      }

      setLoading(false);
    };
    fetchInitialData();
  }, [currentUser.id]);

  // 2. Fetch Kehadiran & Cek Libur saat Tanggal/Siswa/HariSekolah Berubah
  useEffect(() => {
    if (siswaList.length > 0) {
      fetchDataAndCheckHoliday();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tanggal, siswaList, hariSekolah]);

  const fetchDataAndCheckHoliday = async () => {
    setLoading(true);
    setMode('INPUT'); 
    setIsHoliday(false);
    setHolidayInfo(null);

    try {
      // --- PRIORITY 1: CEK TANGGAL MASA DEPAN ---
      if (tanggal > todayStr) {
          setIsHoliday(true);
          setHolidayInfo({
              jenis: 'FUTURE_DATE',
              keterangan: 'Tanggal Masa Depan (Belum dapat diisi)'
          });
          // Jangan return, tetap fetch data jika ada (walau harusnya kosong) agar UI konsisten
          // Tapi input tetap disable karena isHoliday=true
      }

      // --- PRIORITY 2: CEK HARI SEKOLAH (SENIN-JUMAT / SABTU) ---
      const dateObj = new Date(tanggal);
      const dayOfWeek = dateObj.getDay(); // 0=Minggu, 6=Sabtu

      let isWeekend = false;
      let weekendLabel = '';

      if (dayOfWeek === 0) {
          isWeekend = true;
          weekendLabel = 'Hari Minggu';
      } else if (hariSekolah === 5 && dayOfWeek === 6) {
          isWeekend = true;
          weekendLabel = 'Hari Sabtu (Sekolah 5 Hari Kerja)';
      }

      if (isWeekend) {
          // Jika sudah terdeteksi masa depan, biarkan error masa depan prioritas.
          // Jika tidak, baru set weekend.
          if (tanggal <= todayStr) {
              setIsHoliday(true);
              setHolidayInfo({ 
                  jenis: 'HARI_NON_AKTIF', 
                  keterangan: weekendLabel 
              });
          }
      }

      // Parallel Request: Cek Kehadiran & Cek Kalender Pendidikan
      const queries: any[] = [
        supabase
          .from('kehadiran')
          .select('*')
          .eq('id_guru', currentUser.id)
          .eq('tanggal', tanggal)
      ];

      // Hanya query kalender jika valid date (bukan masa depan, bukan weekend)
      const shouldCheckCalendar = tanggal <= todayStr && !isWeekend;

      if (shouldCheckCalendar) {
          queries.push(
            supabase
              .from('kalender_pendidikan')
              .select('jenis, keterangan')
              .eq('tanggal', tanggal)
              .maybeSingle()
          );
      }

      const results = await Promise.all(queries);
      const kehadiranRes = results[0];
      const kalenderRes = shouldCheckCalendar ? results[1] : null;

      // --- PRIORITY 3: CEK KALENDER PENDIDIKAN ---
      if (kalenderRes?.data) {
        setIsHoliday(true);
        setHolidayInfo(kalenderRes.data);
      }

      // 3. Handle Data Kehadiran
      const existingData = kehadiranRes.data as Kehadiran[] || [];
      const newFormState: FormState = {};

      if (existingData.length > 0) {
        // DATA ADA -> MODE VIEW
        setMode('VIEW');

        siswaList.forEach(item => {
          const record = existingData.find(k => k.id_siswa === item.id_siswa);
          if (record) {
            newFormState[item.id_siswa] = {
              id: record.id,
              status: record.status,
              catatan: record.catatan || ''
            };
          } else {
            newFormState[item.id_siswa] = { status: 'HADIR', catatan: '' };
          }
        });
      } else {
        // DATA KOSONG -> MODE INPUT (Default HADIR)
        setMode('INPUT');
        siswaList.forEach(item => {
          newFormState[item.id_siswa] = { status: 'HADIR', catatan: '' };
        });
      }

      setFormData(newFormState);

    } catch (error) {
      console.error(error);
      showToast('Gagal memuat data', 'error');
    } finally {
      setLoading(false);
    }
  };

  // --- Handlers ---

  const handleStatusChange = (id_siswa: string, val: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA') => {
    if (isHoliday) return; // Prevent change if holiday/future
    setFormData(prev => ({
      ...prev,
      [id_siswa]: { ...prev[id_siswa], status: val }
    }));
  };

  const handleCatatanChange = (id_siswa: string, val: string) => {
    if (isHoliday) return; // Prevent change if holiday/future
    setFormData(prev => ({
      ...prev,
      [id_siswa]: { ...prev[id_siswa], catatan: val }
    }));
  };

  const handleSave = async () => {
    // VALIDASI FINAL SEBELUM SAVE
    if (isHoliday) {
        showToast(`Gagal: ${holidayInfo?.keterangan || 'Hari Libur / Masa Depan'}.`, 'error');
        return;
    }

    setProcessing(true);
    try {
      const payload = siswaList.map(item => ({
        id_guru: currentUser.id,
        id_siswa: item.id_siswa,
        tanggal: tanggal,
        status: formData[item.id_siswa].status,
        catatan: formData[item.id_siswa].catatan
      }));

      const { error } = await supabase.from('kehadiran').insert(payload);
      if (error) throw error;

      showToast('✅ Kehadiran berhasil disimpan', 'success');
      await fetchDataAndCheckHoliday(); // Refresh ke mode VIEW
    } catch (e) {
      showToast('Gagal menyimpan data', 'error');
    } finally {
      setProcessing(false);
    }
  };

  const handleUpdate = async () => {
    // VALIDASI FINAL SEBELUM UPDATE
    if (isHoliday) {
        showToast(`Gagal: ${holidayInfo?.keterangan || 'Hari Libur / Masa Depan'}.`, 'error');
        return;
    }

    setProcessing(true);
    try {
      // Upsert: Jika ID ada (update), jika tidak (insert - kasus siswa baru)
      const payload = siswaList.map(item => {
        const form = formData[item.id_siswa];
        return {
          id: form.id, // Supabase Upsert pakai ID ini untuk update
          id_guru: currentUser.id,
          id_siswa: item.id_siswa,
          tanggal: tanggal,
          status: form.status,
          catatan: form.catatan
        };
      });

      const { error } = await supabase.from('kehadiran').upsert(payload);
      if (error) throw error;

      showToast('✅ Kehadiran berhasil diperbarui', 'success');
      await fetchDataAndCheckHoliday(); // Kembali ke mode VIEW
    } catch (e) {
      showToast('Gagal memperbarui data', 'error');
    } finally {
      setProcessing(false);
    }
  };

  const handleDelete = async () => {
    // Validasi Delete: Tidak boleh hapus masa depan (meskipun datanya anehnya ada)
    if (tanggal > todayStr) {
        showToast('Tidak dapat menghapus data masa depan.', 'error');
        return;
    }

    setProcessing(true);
    try {
      const { error } = await supabase
        .from('kehadiran')
        .delete()
        .eq('id_guru', currentUser.id)
        .eq('tanggal', tanggal);

      if (error) throw error;

      showToast('🗑️ Data kehadiran dihapus', 'success');
      setShowDeleteConfirm(false);
      await fetchDataAndCheckHoliday(); // Kembali ke mode INPUT
    } catch (e) {
      showToast('Gagal menghapus data', 'error');
    } finally {
      setProcessing(false);
    }
  };

  // --- Components ---

  const RadioButton = ({ id_siswa, val, label, colorClass }: any) => {
    const isSelected = formData[id_siswa]?.status === val;
    const isDisabled = mode === 'VIEW' || isHoliday; // Disabled if VIEW mode OR Holiday/Future

    return (
      <label className={`
        relative flex items-center justify-center w-10 h-10 rounded-lg transition-all duration-200
        ${isSelected 
          ? `${colorClass} text-white shadow-lg scale-110 font-bold ring-2 ring-white` 
          : 'bg-gray-700 text-gray-400 border border-gray-600'}
        ${isDisabled ? 'cursor-not-allowed opacity-60' : 'cursor-pointer hover:bg-gray-600'}
      `}>
        <input
          type="radio"
          name={`status-${id_siswa}`}
          value={val}
          checked={isSelected}
          onChange={() => !isDisabled && handleStatusChange(id_siswa, val)}
          disabled={isDisabled}
          className="hidden"
        />
        {label}
      </label>
    );
  };

  return (
    <div>
      <ConfirmDialog
        isOpen={showDeleteConfirm}
        message={`Yakin ingin menghapus seluruh data kehadiran pada tanggal ${tanggal}?`}
        onConfirm={handleDelete}
        onCancel={() => setShowDeleteConfirm(false)}
      />

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <div>
           <h2 className="text-2xl font-bold text-white">Input Kehadiran</h2>
           <p className="text-gray-400 text-sm">Kelola absensi harian siswa binaan.</p>
        </div>
      </div>

      {/* --- CONTROL PANEL (Sticky) --- */}
      <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 shadow-xl mb-6 sticky top-0 z-20">
        <div className="flex flex-col gap-4">
            <div className="flex flex-col lg:flex-row justify-between items-center gap-4">

            {/* Date Picker & Badge */}
            <div className="flex items-center gap-4 w-full lg:w-auto">
                <div className="relative">
                    <input
                    type="date"
                    value={tanggal}
                    max={todayStr} // Prevent selecting future dates via UI
                    onChange={(e) => setTanggal(e.target.value)}
                    className="bg-gray-900 border border-gray-600 text-white rounded-lg px-4 py-2 pl-10 focus:ring-2 focus:ring-primary focus:border-transparent shadow-inner"
                    />
                    <span className="absolute left-3 top-2.5 text-gray-400">📅</span>
                </div>

                {/* Mode Badge */}
                {mode === 'INPUT' && !isHoliday && (
                <span className="px-3 py-1 bg-green-500/20 text-green-400 border border-green-500/50 rounded-full text-xs font-bold uppercase tracking-wider animate-pulse">
                    Mode Input
                </span>
                )}
                {mode === 'VIEW' && !isHoliday && (
                <span className="px-3 py-1 bg-blue-500/20 text-blue-400 border border-blue-500/50 rounded-full text-xs font-bold uppercase tracking-wider">
                    Mode Lihat
                </span>
                )}
                {mode === 'EDIT' && !isHoliday && (
                <span className="px-3 py-1 bg-yellow-500/20 text-yellow-400 border border-yellow-500/50 rounded-full text-xs font-bold uppercase tracking-wider animate-pulse">
                    Mode Edit
                </span>
                )}
                {isHoliday && (
                    <span className={`px-3 py-1 text-xs font-bold uppercase tracking-wider rounded-full border ${
                        holidayInfo?.jenis === 'FUTURE_DATE' 
                        ? 'bg-gray-700 text-gray-400 border-gray-500' 
                        : 'bg-red-500/20 text-red-400 border-red-500/50 animate-pulse'
                    }`}>
                        ⛔ {holidayInfo?.jenis === 'HARI_NON_AKTIF' ? 'HARI LIBUR' : holidayInfo?.jenis === 'FUTURE_DATE' ? 'MASA DEPAN' : 'LIBUR NASIONAL'}
                    </span>
                )}
            </div>

            {/* Action Buttons based on Mode */}
            <div className="flex gap-2 w-full lg:w-auto justify-end">

                {/* 1. Jika Mode INPUT (Belum ada data) */}
                {mode === 'INPUT' && (
                <button
                    onClick={handleSave}
                    disabled={processing || siswaList.length === 0 || isHoliday}
                    className="bg-green-600 hover:bg-green-700 text-white px-6 py-2 rounded-lg font-bold shadow-lg transition flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    {processing ? 'Menyimpan...' : '💾 Simpan Kehadiran'}
                </button>
                )}

                {/* 2. Jika Mode VIEW (Data ada, hanya lihat) */}
                {mode === 'VIEW' && (
                <>
                    <button
                        onClick={() => setShowDeleteConfirm(true)}
                        disabled={isHoliday && holidayInfo?.jenis === 'FUTURE_DATE'} // Disable hapus jika future date
                        className="bg-red-900/50 hover:bg-red-900 text-red-200 border border-red-800 px-4 py-2 rounded-lg font-medium transition flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        🗑️ Hapus
                    </button>
                    {!isHoliday && (
                        <button
                            onClick={() => setMode('EDIT')}
                            className="bg-yellow-600 hover:bg-yellow-700 text-white px-5 py-2 rounded-lg font-bold shadow-lg transition flex items-center gap-2"
                        >
                            ✏️ Ubah Data
                        </button>
                    )}
                </>
                )}

                {/* 3. Jika Mode EDIT (Sedang mengedit) */}
                {mode === 'EDIT' && (
                <>
                    <button
                        onClick={() => { setMode('VIEW'); fetchDataAndCheckHoliday(); }} 
                        className="bg-gray-600 hover:bg-gray-500 text-white px-4 py-2 rounded-lg font-medium transition"
                        disabled={processing}
                    >
                        ❌ Batal
                    </button>
                    <button
                        onClick={handleUpdate}
                        disabled={processing || isHoliday}
                        className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg font-bold shadow-lg transition flex items-center gap-2 disabled:opacity-50"
                    >
                        {processing ? 'Memproses...' : '✅ Perbarui Kehadiran'}
                    </button>
                </>
                )}
            </div>
            </div>

            {/* ALERT HARI LIBUR / FUTURE */}
            {isHoliday && holidayInfo && (
                <div className={`w-full p-3 rounded-lg flex items-start gap-3 animate-slide-in border ${
                    holidayInfo.jenis === 'FUTURE_DATE' 
                    ? 'bg-gray-700/50 border-gray-600 text-gray-300' 
                    : 'bg-red-900/30 border-red-600/50 text-red-200'
                }`}>
                    <span className="text-2xl">{holidayInfo.jenis === 'FUTURE_DATE' ? '⏳' : '🚫'}</span>
                    <div>
                        <h4 className={`font-bold ${holidayInfo.jenis === 'FUTURE_DATE' ? 'text-gray-200' : 'text-red-100'}`}>
                            {holidayInfo.jenis === 'FUTURE_DATE' ? 'Tanggal Belum Dapat Diisi' : 'Tidak dapat menginput kehadiran'}
                        </h4>
                        <p className="text-sm">
                            Status: <strong>{holidayInfo.jenis === 'FUTURE_DATE' ? 'Masa Depan' : holidayInfo.jenis.replace(/_/g, ' ')}</strong>.
                            {holidayInfo.keterangan && <span className="block mt-1 italic opacity-80">"{holidayInfo.keterangan}"</span>}
                        </p>
                    </div>
                </div>
            )}
        </div>
      </div>

      {/* --- TABLE CONTENT --- */}
      <div className="bg-gray-800 shadow-xl overflow-hidden rounded-xl border border-gray-700">
        {loading ? (
          <div className="p-10 flex justify-center items-center text-gray-400 gap-3">
            <span className="animate-spin text-2xl">⏳</span> Memuat data...
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-700">
              <thead className="bg-gray-750 text-gray-400">
                <tr>
                  <th className="px-6 py-4 text-center text-xs font-bold uppercase w-12">No</th>
                  <th className="px-6 py-4 text-left text-xs font-bold uppercase">Siswa</th>
                  <th className="px-6 py-4 text-center text-xs font-bold uppercase">Status Kehadiran</th>
                  <th className="px-6 py-4 text-left text-xs font-bold uppercase">Catatan</th>
                </tr>
              </thead>
              <tbody className="bg-gray-800 divide-y divide-gray-700">
                {siswaList.map((item, index) => {
                  const currentStatus = formData[item.id_siswa]?.status;
                  // Highlight row based on status
                  let rowBg = 'hover:bg-gray-750';
                  if (currentStatus === 'SAKIT') rowBg = 'bg-yellow-900/10 hover:bg-yellow-900/20';
                  if (currentStatus === 'IZIN') rowBg = 'bg-blue-900/10 hover:bg-blue-900/20';
                  if (currentStatus === 'ALPHA') rowBg = 'bg-red-900/10 hover:bg-red-900/20';

                  // Dimmed row if holiday
                  if (isHoliday) rowBg = 'bg-gray-900 opacity-60';

                  return (
                    <tr key={item.id} className={`transition-colors duration-200 ${rowBg}`}>
                      <td className="px-6 py-4 text-center text-gray-500 text-sm">
                        {index + 1}
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex flex-col">
                          <span className="text-sm font-bold text-white">{item.siswa?.nama}</span>
                          <span className="text-xs text-gray-400 flex gap-2">
                             <span>{item.siswa?.nisn}</span>
                             <span className="text-gray-600">•</span>
                             <span>{item.siswa?.jenis_kelamin}</span>
                          </span>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex items-center justify-center gap-3">
                          <RadioButton 
                            id_siswa={item.id_siswa} val="HADIR" label="H" 
                            colorClass="bg-green-600" 
                          />
                          <RadioButton 
                            id_siswa={item.id_siswa} val="SAKIT" label="S" 
                            colorClass="bg-yellow-500" 
                          />
                          <RadioButton 
                            id_siswa={item.id_siswa} val="IZIN" label="I" 
                            colorClass="bg-blue-500" 
                          />
                          <RadioButton 
                            id_siswa={item.id_siswa} val="ALPHA" label="A" 
                            colorClass="bg-red-500" 
                          />
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <input
                          type="text"
                          value={formData[item.id_siswa]?.catatan || ''}
                          onChange={(e) => handleCatatanChange(item.id_siswa, e.target.value)}
                          placeholder={mode === 'VIEW' ? "" : "Keterangan tambahan..."}
                          disabled={mode === 'VIEW' || isHoliday}
                          className={`
                            w-full bg-gray-900 border border-gray-600 text-white text-sm rounded-lg px-3 py-2
                            focus:ring-1 focus:ring-primary focus:border-primary transition
                            disabled:opacity-50 disabled:bg-gray-800 disabled:border-transparent
                            disabled:cursor-not-allowed
                          `}
                        />
                      </td>
                    </tr>
                  );
                })}
                {siswaList.length === 0 && (
                  <tr>
                    <td colSpan={4} className="p-10 text-center text-gray-500 italic flex flex-col items-center">
                      <span className="text-4xl mb-2">📭</span>
                      Belum ada siswa binaan yang ditugaskan kepada Anda.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Legend */}
      <div className="mt-4 flex gap-6 justify-center text-xs text-gray-400 font-medium">
         <span className="flex items-center gap-1"><div className="w-3 h-3 rounded bg-green-600"></div> H (Hadir)</span>
         <span className="flex items-center gap-1"><div className="w-3 h-3 rounded bg-yellow-500"></div> S (Sakit)</span>
         <span className="flex items-center gap-1"><div className="w-3 h-3 rounded bg-blue-500"></div> I (Izin)</span>
         <span className="flex items-center gap-1"><div className="w-3 h-3 rounded bg-red-500"></div> A (Alpha)</span>
      </div>

    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { supabase } from '../../supabaseClient';
import { Guru } from '../../types';
import * as XLSX from 'xlsx';

interface Props {
  currentUser: Guru;
  showToast: (msg: string, type: 'success' | 'error') => void;
}

export const ImportKehadiranTemplate: React.FC<Props> = ({ currentUser, showToast }) => {
  const [selectedDates, setSelectedDates] = useState<string[]>([]);

  // State Input
  const [singleDate, setSingleDate] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [hariSekolah, setHariSekolah] = useState<number>(5); // Default 5 hari

  const [loading, setLoading] = useState(false);
  const [importProgress, setImportProgress] = useState(0); 
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Constants
  const todayStr = new Date().toISOString().split('T')[0];

  // --- INITIAL LOAD: Get Hari Sekolah ---
  useEffect(() => {
    const fetchSettings = async () => {
      const { data } = await supabase
        .from('sekolah')
        .select('hari_sekolah')
        .limit(1)
        .maybeSingle();
      if (data) {
        setHariSekolah(data.hari_sekolah);
      }
    };
    fetchSettings();
  }, []);

  // --- LOGIC TANGGAL ---

  // 1. Tambah Satu Tanggal dengan Validasi Live
  const handleAddSingleDate = async () => {
    if (!singleDate) return;

    // Cek Tanggal Masa Depan
    if (singleDate > todayStr) {
        showToast('Gagal: Tidak dapat memilih tanggal masa depan (besok atau setelahnya).', 'error');
        return;
    }

    // Cek Duplikasi Lokal
    if (selectedDates.includes(singleDate)) {
      showToast('Tanggal sudah ada dalam daftar', 'error');
      return;
    }

    setLoading(true);
    try {
        const dateObj = new Date(singleDate);
        const dayOfWeek = dateObj.getDay(); // 0 = Minggu

        // 1. Cek Akhir Pekan (Lokal)
        if (dayOfWeek === 0) {
            showToast('Gagal: Tanggal yang dipilih adalah hari Minggu.', 'error');
            return;
        }
        if (hariSekolah === 5 && dayOfWeek === 6) {
            showToast('Gagal: Tanggal yang dipilih adalah hari Sabtu (Libur Sekolah).', 'error');
            return;
        }

        // 2. Cek Kalender Pendidikan (Database)
        const { data: libur } = await supabase
            .from('kalender_pendidikan')
            .select('jenis, keterangan')
            .eq('tanggal', singleDate)
            .maybeSingle();

        if (libur) {
            showToast(`Gagal: Tanggal ini libur (${libur.jenis.replace(/_/g, ' ')}). ${libur.keterangan || ''}`, 'error');
            return;
        }

        // Lolos Validasi
        const newDates = [...selectedDates, singleDate].sort();
        setSelectedDates(newDates);
        setSingleDate('');
        showToast('Tanggal berhasil ditambahkan', 'success');

    } catch (error) {
        console.error(error);
        showToast('Terjadi kesalahan saat memvalidasi tanggal', 'error');
    } finally {
        setLoading(false);
    }
  };

  // 2. Tambah Rentang Tanggal dengan Filter Otomatis
  const handleAddRange = async () => {
    if (!startDate || !endDate) {
        showToast('Mohon isi Tanggal Mulai dan Tanggal Akhir', 'error');
        return;
    }

    const start = new Date(startDate);
    const end = new Date(endDate);

    if (start > end) {
        showToast('Tanggal Mulai tidak boleh lebih besar dari Tanggal Akhir', 'error');
        return;
    }

    setLoading(true);
    try {
        // Ambil Data Libur dalam rentang tersebut dari DB
        const { data: holidays } = await supabase
            .from('kalender_pendidikan')
            .select('tanggal, jenis')
            .gte('tanggal', startDate)
            .lte('tanggal', endDate);

        const holidayMap = new Set(holidays?.map(h => h.tanggal));

        const validDatesToAdd: string[] = [];
        let skippedCount = 0;
        let skippedReason = '';

        let current = new Date(start);

        // Loop dari start sampai end
        while (current <= end) {
            const dateStr = current.toISOString().split('T')[0];
            const dayOfWeek = current.getDay();

            let isValid = true;

            // Cek Tanggal Masa Depan
            if (dateStr > todayStr) {
                isValid = false;
                // Jangan break, lanjut loop (siapa tahu range berantakan, tapi idealnya urut)
                // Sebenarnya jika sorted, bisa break. Tapi aman continue.
            }
            // Cek Akhir Pekan
            else if (dayOfWeek === 0 || (hariSekolah === 5 && dayOfWeek === 6)) {
                isValid = false;
            }
            // Cek Kalender Libur
            else if (holidayMap.has(dateStr)) {
                isValid = false;
                skippedReason = 'Hari Libur Nasional/Sekolah';
            }
            // Cek Duplikasi State
            else if (selectedDates.includes(dateStr)) {
                isValid = false; // Sudah ada, skip diam-diam
            }

            if (isValid) {
                validDatesToAdd.push(dateStr);
            } else {
                // Hanya hitung skip jika bukan karena duplikasi
                if (!selectedDates.includes(dateStr)) skippedCount++;
            }

            // Increment hari +1
            current.setDate(current.getDate() + 1);
        }

        if (validDatesToAdd.length === 0) {
            showToast('Tidak ada tanggal yang ditambahkan (Semua tanggal dalam rentang ini libur/masa depan/sudah terpilih).', 'error');
        } else {
            const combinedDates = [...selectedDates, ...validDatesToAdd].sort();
            setSelectedDates(combinedDates);
            setStartDate('');
            setEndDate('');

            if (skippedCount > 0) {
                showToast(`Berhasil menambah ${validDatesToAdd.length} tanggal. (${skippedCount} dilewati karena Libur/Masa Depan)`, 'success');
            } else {
                showToast(`Berhasil menambah ${validDatesToAdd.length} tanggal.`, 'success');
            }
        }

    } catch (err) {
        showToast('Gagal memproses rentang tanggal', 'error');
    } finally {
        setLoading(false);
    }
  };

  const handleRemoveDate = (dateToRemove: string) => {
    setSelectedDates(selectedDates.filter(d => d !== dateToRemove));
  };

  const handleClearDates = () => {
      setSelectedDates([]);
  };

  // --- LOGIC GENERATE & IMPORT ---

  const handleGenerateTemplate = async () => {
    if (selectedDates.length === 0) {
      showToast('Pilih minimal satu tanggal terlebih dahulu', 'error');
      return;
    }

    setLoading(true);
    try {
      // Ambil data siswa
      const { data: siswaData, error } = await supabase
        .from('bimbingan')
        .select('*, siswa(id, nama, nisn, kelas(nama))')
        .eq('id_guru', currentUser.id)
        .order('created_at', { ascending: true });

      if (error) throw error;

      if (!siswaData || siswaData.length === 0) {
        showToast('Anda belum memiliki siswa binaan', 'error');
        setLoading(false);
        return;
      }

      const rows = siswaData.map((item, index) => {
        const row: any = {
          NO: index + 1,
          NISN: item.siswa?.nisn || '', 
          NAMA: item.siswa?.nama || '',
          KELAS: item.siswa?.kelas?.nama || '',
        };
        // Gunakan selectedDates sebagai header
        selectedDates.forEach(date => {
          row[date] = ''; 
        });
        return row;
      });

      const ws = XLSX.utils.json_to_sheet(rows);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Kehadiran");

      const filename = `Template_Kehadiran_${new Date().toISOString().split('T')[0]}.xlsx`;
      XLSX.writeFile(wb, filename);

      showToast('Template berhasil dibuat!', 'success');

    } catch (err: any) {
      console.error(err);
      showToast('Gagal membuat template: ' + err.message, 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setImportProgress(0); 
    const reader = new FileReader();

    reader.onload = async (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsName = wb.SheetNames[0];
        const ws = wb.Sheets[wsName];

        const data = XLSX.utils.sheet_to_json(ws);

        if (data.length === 0) {
          showToast('File Excel kosong', 'error');
          setLoading(false);
          return;
        }

        // --- VALIDASI HEADER TANGGAL SEBELUM IMPORT ---
        const firstRow = data[0] as any;
        const keys = Object.keys(firstRow);
        const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
        const dateColumns = keys.filter(k => dateRegex.test(k));

        if (dateColumns.length > 0) {
            // 1. Validasi Tanggal Masa Depan
            const futureDates = dateColumns.filter(d => d > todayStr);
            if (futureDates.length > 0) {
                showToast(`GAGAL IMPORT! File mengandung tanggal masa depan: ${futureDates.join(', ')}.`, 'error');
                setLoading(false);
                if (fileInputRef.current) fileInputRef.current.value = '';
                return;
            }

            // 2. Validasi Hari Libur (Weekend) sesuai pengaturan sekolah
            const invalidSchoolDays = dateColumns.filter(d => {
                const day = new Date(d).getDay();
                if (day === 0) return true; // Minggu
                if (hariSekolah === 5 && day === 6) return true; // Sabtu
                return false;
            });

            if (invalidSchoolDays.length > 0) {
                showToast(`GAGAL IMPORT! File mengandung tanggal libur sekolah (Sabtu/Minggu): ${invalidSchoolDays.join(', ')}`, 'error');
                setLoading(false);
                if (fileInputRef.current) fileInputRef.current.value = '';
                return;
            }

            // 3. Cek apakah ada tanggal libur (Kalender Pendidikan) di kolom Excel
            const { data: holidays } = await supabase
                .from('kalender_pendidikan')
                .select('tanggal, jenis')
                .in('tanggal', dateColumns);

            if (holidays && holidays.length > 0) {
                const holidayDates = holidays.map(h => `${h.tanggal} (${h.jenis})`).join(', ');
                showToast(`GAGAL IMPORT! File mengandung tanggal libur nasional: ${holidayDates}.`, 'error');
                setLoading(false);
                if (fileInputRef.current) fileInputRef.current.value = '';
                return;
            }
        }
        // ----------------------------------------------

        let processedCount = 0;
        let errorCount = 0;
        const totalRows = data.length;

        for (let i = 0; i < totalRows; i++) {
          const row: any = data[i];
          const nisn = row['NISN'] ? String(row['NISN']).trim() : '';
          const nama = row['NAMA'] ? String(row['NAMA']).trim() : '';

          if (!nisn && !nama) {
             const currentProgress = Math.round(((i + 1) / totalRows) * 100);
             setImportProgress(currentProgress);
             continue; 
          }

          let studentId = '';
          const { data: foundSiswa } = await supabase
             .from('siswa')
             .select('id')
             .eq('nisn', nisn)
             .maybeSingle();

          if (foundSiswa) {
            studentId = foundSiswa.id;
          } else {
            const { data: foundSiswaByName } = await supabase
                .from('siswa')
                .select('id')
                .ilike('nama', nama)
                .maybeSingle();
            if (foundSiswaByName) studentId = foundSiswaByName.id;
          }

          if (!studentId) {
            errorCount++;
          } else {
            for (const key of keys) {
               if (dateRegex.test(key)) {
                  const rawStatus = row[key] ? String(row[key]).trim().toUpperCase() : '';
                  let statusDb: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA' | null = null;

                  if (['H', 'HADIR'].includes(rawStatus)) statusDb = 'HADIR';
                  else if (['S', 'SAKIT'].includes(rawStatus)) statusDb = 'SAKIT';
                  else if (['I', 'IZIN'].includes(rawStatus)) statusDb = 'IZIN';
                  else if (['A', 'ALPHA', 'ALPA'].includes(rawStatus)) statusDb = 'ALPHA';

                  if (statusDb) {
                      // Upsert Kehadiran
                      const { error: upsertError } = await supabase.from('kehadiran').upsert({
                          id_guru: currentUser.id,
                          id_siswa: studentId,
                          tanggal: key,
                          status: statusDb
                      }, { onConflict: 'id_siswa, tanggal' });

                      // Fallback manual upsert logic jika tidak ada unique constraint composite
                      if (upsertError) {
                          const { data: existing } = await supabase
                              .from('kehadiran')
                              .select('id')
                              .eq('id_guru', currentUser.id)
                              .eq('id_siswa', studentId)
                              .eq('tanggal', key)
                              .maybeSingle();

                          if (existing) {
                              await supabase.from('kehadiran').update({ status: statusDb }).eq('id', existing.id);
                          } else {
                              await supabase.from('kehadiran').insert([{
                                  id_guru: currentUser.id,
                                  id_siswa: studentId,
                                  tanggal: key,
                                  status: statusDb
                              }]);
                          }
                      }
                  }
               }
            }
            processedCount++;
          }

          const currentProgress = Math.round(((i + 1) / totalRows) * 100);
          setImportProgress(currentProgress);
        }

        showToast(`Import selesai. ${processedCount} siswa diproses.`, 'success');
        if (errorCount > 0) {
            setTimeout(() => showToast(`${errorCount} siswa tidak ditemukan di database.`, 'error'), 2000);
        }

      } catch (err: any) {
        console.error(err);
        showToast('Gagal memproses file: ' + err.message, 'error');
      } finally {
        setLoading(false);
        setImportProgress(0);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };

    reader.readAsBinaryString(file);
  };

  return (
    <div className="max-w-4xl mx-auto p-4">
      <h2 className="text-3xl font-bold text-white mb-2">Import Kehadiran (Custom)</h2>
      <p className="text-gray-400 mb-8">
        Fitur ini memungkinkan Anda mengisi absensi untuk beberapa tanggal sekaligus menggunakan Excel.
        <br />
        <span className="text-yellow-500 text-xs">
            * Sistem otomatis memblokir penambahan tanggal libur/akhir pekan pada template.
        </span>
      </p>

      {/* STEP 1: PILIH TANGGAL */}
      <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-lg mb-6">
        <h3 className="text-lg font-semibold text-blue-400 mb-4">1. Pilih Tanggal & Buat Template</h3>

        <div className="space-y-6">

            {/* OPSI A: Tambah Rentang (Multiselect Logic) */}
            <div className="bg-gray-700/50 p-4 rounded-lg border border-gray-600">
                <label className="block text-sm font-bold text-white mb-3">🅰️ Opsi Cepat: Pilih Rentang Tanggal</label>
                <div className="flex flex-col md:flex-row gap-4 items-end">
                    <div className="flex-1 w-full">
                        <label className="text-xs text-gray-400 block mb-1">Dari Tanggal</label>
                        <input 
                            type="date" 
                            max={todayStr}
                            value={startDate}
                            onChange={(e) => setStartDate(e.target.value)}
                            className="bg-gray-700 border border-gray-500 text-white rounded px-3 py-2 w-full focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                        />
                    </div>
                    <div className="flex items-center justify-center pb-2 text-gray-400">
                        ➡️
                    </div>
                    <div className="flex-1 w-full">
                        <label className="text-xs text-gray-400 block mb-1">Sampai Tanggal</label>
                        <input 
                            type="date" 
                            max={todayStr}
                            value={endDate}
                            onChange={(e) => setEndDate(e.target.value)}
                            className="bg-gray-700 border border-gray-500 text-white rounded px-3 py-2 w-full focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                        />
                    </div>
                    <button 
                        onClick={handleAddRange}
                        disabled={loading}
                        className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded font-medium transition w-full md:w-auto h-[42px] disabled:opacity-50"
                    >
                        {loading ? 'Memvalidasi...' : '+ Tambahkan Rentang'}
                    </button>
                </div>
                <p className="text-xs text-gray-400 mt-2">
                    * Tanggal libur/akhir pekan di antara rentang ini akan otomatis dilewati.
                </p>
            </div>

            {/* OPSI B: Tambah Manual */}
            <div className="bg-gray-700/30 p-4 rounded-lg border border-gray-600 border-dashed">
                <label className="block text-sm font-bold text-gray-300 mb-3">🅱️ Opsi Manual: Tambah Satuan</label>
                <div className="flex flex-col md:flex-row gap-4">
                    <input 
                        type="date" 
                        max={todayStr}
                        value={singleDate}
                        onChange={(e) => setSingleDate(e.target.value)}
                        className="bg-gray-700 border border-gray-500 text-white rounded px-3 py-2 w-full md:w-64"
                    />
                    <button 
                        onClick={handleAddSingleDate}
                        disabled={loading}
                        className="bg-gray-600 hover:bg-gray-500 text-white px-4 py-2 rounded font-medium transition w-full md:w-auto disabled:opacity-50"
                    >
                        {loading ? 'Cek...' : '+ Tambah'}
                    </button>
                </div>
            </div>

            {/* Selected Dates Chips */}
            {selectedDates.length > 0 && (
                <div className="bg-gray-900/50 p-4 rounded-lg border border-gray-700">
                    <div className="flex justify-between items-center mb-2">
                        <span className="text-sm font-bold text-gray-300">Daftar Tanggal Terpilih ({selectedDates.length}):</span>
                        <button onClick={handleClearDates} className="text-xs text-red-400 hover:text-red-300 underline">Hapus Semua</button>
                    </div>
                    <div className="flex flex-wrap gap-2 max-h-40 overflow-y-auto custom-scrollbar">
                        {selectedDates.map(date => (
                            <div key={date} className="bg-primary/20 text-primary px-3 py-1 rounded-full text-sm flex items-center gap-2 border border-primary/30">
                                <span>🗓️ {date}</span>
                                <button 
                                    onClick={() => handleRemoveDate(date)}
                                    className="text-red-400 hover:text-red-300 font-bold px-1 hover:bg-white/10 rounded"
                                >
                                    &times;
                                </button>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            <div className="border-t border-gray-700 pt-4">
                <button 
                    onClick={handleGenerateTemplate}
                    disabled={loading || selectedDates.length === 0}
                    className="w-full bg-green-600 hover:bg-green-700 text-white px-6 py-3 rounded-lg font-bold transition shadow-lg flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    {loading ? 'Memproses...' : '📥 Buat & Download Template Excel'}
                </button>
            </div>
        </div>
      </div>

      {/* STEP 2: UPLOAD */}
      <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-lg">
        <h3 className="text-lg font-semibold text-green-400 mb-4">2. Upload & Import Data</h3>
        <p className="text-sm text-gray-400 mb-4">
            Isi file Excel yang telah diunduh dengan kode: <strong>H</strong> (Hadir), <strong>S</strong> (Sakit), <strong>I</strong> (Izin), <strong>A</strong> (Alpha).
        </p>

        <div className="flex flex-col items-center justify-center border-2 border-dashed border-gray-600 rounded-lg p-10 bg-gray-700/30 hover:bg-gray-700/50 transition relative">
            <input 
                type="file" 
                accept=".xlsx, .xls"
                ref={fileInputRef}
                onChange={handleFileUpload}
                disabled={loading}
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" 
                id="file-upload"
            />
            <div className="text-center pointer-events-none">
                <span className="text-4xl mb-2 block">📂</span>
                <span className="text-white font-medium mb-1 block">Klik atau Seret File Excel ke Sini</span>
                <span className="text-xs text-gray-500 block">Format .xlsx atau .xls</span>
            </div>
        </div>
      </div>

      {/* PROGRESS OVERLAY */}
      {loading && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-80">
          <div className="bg-gray-800 p-6 rounded-lg border border-gray-700 w-80 md:w-96 text-center">
            <h3 className="text-white font-bold mb-4 text-lg">Memproses Data...</h3>
            <div className="w-full bg-gray-700 rounded-full h-4 mb-2 overflow-hidden">
               <div 
                 className="bg-green-500 h-4 rounded-full transition-all duration-300" 
                 style={{ width: `${importProgress}%` }}
               ></div>
            </div>
            <p className="text-gray-300 font-medium">{importProgress}%</p>
            <p className="text-gray-500 text-sm mt-1">Mohon jangan tutup halaman ini.</p>
          </div>
        </div>
      )}

    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../supabaseClient';
import { Guru, Siswa, Kelas, Kehadiran } from '../types';
import { ConfirmDialog } from './ConfirmDialog';

interface Props {
  currentUser: Guru;
  showToast: (msg: string, type: 'success' | 'error') => void;
}

interface AttendanceFormState {
  [id_siswa: string]: {
    id?: string;
    status: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA' | null;
    catatan: string;
  };
}

interface HolidayInfo {
  jenis: string;
  keterangan: string | null;
}

export const InputKehadiranAdmin: React.FC<Props> = ({ currentUser, showToast }) => {
  const [kelasOptions, setKelasOptions] = useState<Kelas[]>([]);
  const [selectedKelas, setSelectedKelas] = useState<string>('ALL');

  const [siswaList, setSiswaList] = useState<Siswa[]>([]);
  const [tanggal, setTanggal] = useState(new Date().toISOString().split('T')[0]);

  const [loadingSiswa, setLoadingSiswa] = useState(false);
  const [processing, setProcessing] = useState(false);

  // Pagination State
  const [currentPage, setCurrentPage] = useState(1);
  const [rowsPerPage, setRowsPerPage] = useState(100);
  const [totalStudents, setTotalStudents] = useState(0);

  // Form State
  const [formData, setFormData] = useState<AttendanceFormState>({});
  const [isDataSaved, setIsDataSaved] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  // Validation State
  const [hariSekolah, setHariSekolah] = useState<number>(5);
  const [isHoliday, setIsHoliday] = useState(false);
  const [holidayInfo, setHolidayInfo] = useState<HolidayInfo | null>(null);

  const todayStr = new Date().toISOString().split('T')[0];

  // 1. Fetch Class Options & School Settings
  useEffect(() => {
    const fetchInitial = async () => {
      const { data: k } = await supabase.from('kelas').select('*').order('nama');
      if (k) setKelasOptions(k);

      const { data: s } = await supabase.from('sekolah').select('hari_sekolah').limit(1).maybeSingle();
      if (s) setHariSekolah(s.hari_sekolah);
    };
    fetchInitial();
  }, []);

  // 2. Fetch Students when Class, Page, or RowsPerPage changes
  useEffect(() => {
    // Reset page to 1 if class changes (handled in handleClassChange)
    if (selectedKelas) {
      fetchStudents();
    } else {
      setSiswaList([]);
      setTotalStudents(0);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedKelas, currentPage, rowsPerPage]);

  // 3. Check Validity & Fetch Attendance when Date or Student List changes
  useEffect(() => {
    if (siswaList.length > 0 && selectedKelas) {
      validateDateAndFetch();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tanggal, siswaList, hariSekolah]);

  const validateDateAndFetch = async () => {
      // RESET STATE
      setIsHoliday(false);
      setHolidayInfo(null);
      setIsEditing(false); // Reset edit mode on date change

      // --- VALIDASI 1: TANGGAL MASA DEPAN ---
      if (tanggal > todayStr) {
          setIsHoliday(true);
          setHolidayInfo({ jenis: 'FUTURE_DATE', keterangan: 'Tanggal Masa Depan (Belum dapat diisi)' });
          // Walaupun masa depan, kita coba fetch data (siapa tau ada data aneh masuk)
          await fetchKehadiran(); 
          return;
      }

      // --- VALIDASI 2: HARI SEKOLAH ---
      const dateObj = new Date(tanggal);
      const dayOfWeek = dateObj.getDay(); // 0=Minggu, 6=Sabtu

      if (dayOfWeek === 0) {
          setIsHoliday(true);
          setHolidayInfo({ jenis: 'HARI_NON_AKTIF', keterangan: 'Hari Minggu' });
      } else if (hariSekolah === 5 && dayOfWeek === 6) {
          setIsHoliday(true);
          setHolidayInfo({ jenis: 'HARI_NON_AKTIF', keterangan: 'Hari Sabtu (Sekolah 5 Hari Kerja)' });
      }

      // Jika sudah terdeteksi libur sekolah, lanjut fetch kehadiran (mode view only)
      if (dayOfWeek === 0 || (hariSekolah === 5 && dayOfWeek === 6)) {
          await fetchKehadiran();
          return;
      }

      // --- VALIDASI 3: KALENDER PENDIDIKAN ---
      // Cek DB untuk hari libur nasional dll
      const { data: libur } = await supabase
          .from('kalender_pendidikan')
          .select('jenis, keterangan')
          .eq('tanggal', tanggal)
          .maybeSingle();

      if (libur) {
          setIsHoliday(true);
          setHolidayInfo(libur);
      }

      // Akhirnya fetch data kehadiran
      await fetchKehadiran();
  };

  const handleClassChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
      setSelectedKelas(e.target.value);
      setCurrentPage(1); // Reset to page 1 on filter change
  };

  const fetchStudents = async () => {
    setLoadingSiswa(true);
    try {
        let query = supabase
          .from('siswa')
          .select('id, nama, nisn, jenis_kelamin, kelas(nama)', { count: 'exact' });

        if (selectedKelas !== 'ALL') {
            // Filter by specific class
            query = query.eq('id_kelas', selectedKelas).order('nama');
        } else {
            // ALL CLASSES -> Apply Pagination
            const from = (currentPage - 1) * rowsPerPage;
            const to = from + rowsPerPage - 1;

            query = query
                .order('id_kelas', { ascending: true }) 
                .order('nama', { ascending: true })
                .range(from, to);
        }

        const { data, count, error } = await query;

        if (error) throw error;

        // @ts-ignore
        if (data) setSiswaList(data);
        else setSiswaList([]);

        if (count !== null) setTotalStudents(count);

    } catch (error) {
        showToast('Gagal memuat data siswa', 'error');
    } finally {
        setLoadingSiswa(false);
    }
  };

  const fetchKehadiran = async () => {
    try {
        const studentIds = siswaList.map(s => s.id);

        // Fetch existing attendance for these students on this date
        const { data } = await supabase
          .from('kehadiran')
          .select('*')
          .in('id_siswa', studentIds)
          .eq('tanggal', tanggal);

        const currentData = data as Kehadiran[] || [];
        const newFormState: AttendanceFormState = {};
        const hasData = currentData.length > 0;

        setIsDataSaved(hasData);

        siswaList.forEach(s => {
            const record = currentData.find(k => k.id_siswa === s.id);
            if (record) {
                newFormState[s.id] = {
                    id: record.id,
                    status: record.status,
                    catatan: record.catatan || ''
                };
            } else {
                newFormState[s.id] = {
                    status: null, 
                    catatan: ''
                };
            }
        });

        setFormData(newFormState);

    } catch (error) {
        console.error(error);
    }
  };

  const handleRadioChange = (id_siswa: string, value: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA') => {
    if (isHoliday) return; // Prevent change if holiday/future
    setFormData(prev => ({
        ...prev,
        [id_siswa]: { ...prev[id_siswa], status: value }
    }));
  };

  const handleCatatanChange = (id_siswa: string, value: string) => {
    if (isHoliday) return; // Prevent change if holiday/future
    setFormData(prev => ({
        ...prev,
        [id_siswa]: { ...prev[id_siswa], catatan: value }
    }));
  };

  const handleSaveOrUpdate = async () => {
    if (isHoliday) {
        showToast(`Gagal: ${holidayInfo?.keterangan || 'Hari Libur / Masa Depan'}`, 'error');
        return;
    }

    setProcessing(true);
    try {
        // Hanya ambil data yang statusnya dipilih (tidak null)
        const payload = siswaList
            .filter(s => formData[s.id]?.status !== null)
            .map(s => {
                const form = formData[s.id];
                const record: any = {
                    id_guru: currentUser.id, // Admin ID as the recorder
                    id_siswa: s.id,
                    tanggal: tanggal,
                    status: form.status,
                    catatan: form.catatan
                };
                if (form.id) record.id = form.id;
                return record;
            });

        if (payload.length === 0) {
            showToast('⚠️ Tidak ada status kehadiran yang dipilih.', 'error');
            setProcessing(false);
            return;
        }

        const { error } = await supabase.from('kehadiran').upsert(payload);
        if (error) throw error;

        showToast(isDataSaved ? '✅ Data diperbarui' : '✅ Data disimpan', 'success');
        await fetchKehadiran();
    } catch (error) {
        showToast('❌ Gagal menyimpan data', 'error');
    } finally {
        setProcessing(false);
    }
  };

  const handleDelete = async () => {
    // Prevent delete on future dates (unless overridden, but logic says block)
    if (tanggal > todayStr) {
        showToast('Tidak dapat menghapus data masa depan.', 'error');
        return;
    }

    setProcessing(true);
    try {
        const studentIds = siswaList.map(s => s.id);
        const { error } = await supabase
            .from('kehadiran')
            .delete()
            .in('id_siswa', studentIds)
            .eq('tanggal', tanggal);

        if (error) throw error;
        showToast('✅ Data dihapus', 'success');
        setShowDeleteConfirm(false);
        await fetchKehadiran();
    } catch (error) {
        showToast('❌ Gagal menghapus', 'error');
    } finally {
        setProcessing(false);
    }
  };

  const RadioOption = ({ id_siswa, val, label, activeColorClass }: any) => {
      const isChecked = formData[id_siswa]?.status === val;
      // Disable if: Holiday OR (Data Saved AND Not Editing)
      const isDisabled = isHoliday || (isDataSaved && !isEditing);

      return (
          <label className={`
            cursor-pointer flex items-center justify-center w-8 h-8 md:w-10 md:h-10 rounded-lg border-2 transition-all select-none
            ${isChecked ? `${activeColorClass} border-transparent text-white shadow-md transform scale-110` : 'border-gray-600 text-gray-400 hover:bg-gray-700'}
            ${isDisabled ? 'opacity-50 cursor-not-allowed' : ''}
          `}>
              <input 
                type="radio" 
                name={`status-${id_siswa}`} 
                value={val}
                checked={isChecked}
                onChange={() => !isDisabled && handleRadioChange(id_siswa, val)}
                className="hidden"
                disabled={isDisabled}
              />
              <span className="font-bold text-xs md:text-sm">{label}</span>
          </label>
      );
  };

  // Pagination Logic Helpers
  const totalPages = Math.ceil(totalStudents / rowsPerPage);
  const startRowIndex = (currentPage - 1) * rowsPerPage;

  return (
    <div>
      <ConfirmDialog 
        isOpen={showDeleteConfirm} 
        message={`Hapus data kehadiran siswa yang tampil ini pada tanggal ${tanggal}?`} 
        onConfirm={handleDelete} 
        onCancel={() => setShowDeleteConfirm(false)} 
      />

      <h2 className="text-2xl font-bold text-white mb-6">Input Kehadiran (Admin)</h2>

      {/* Filter Section */}
      <div className="bg-gray-800 p-4 rounded-lg border border-gray-700 mb-6 flex flex-col md:flex-row gap-4">
        <div className="flex-1">
            <label className="text-gray-300 text-sm block mb-1">Pilih Kelas</label>
            <select
                value={selectedKelas}
                onChange={handleClassChange}
                className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white focus:border-primary"
            >
                <option value="">-- Pilih Kelas --</option>
                <option value="ALL">🌟 Semua Kelas (Tampilkan Semua Siswa)</option>
                <optgroup label="Kelas Spesifik">
                    {kelasOptions.map(k => (
                        <option key={k.id} value={k.id}>{k.nama}</option>
                    ))}
                </optgroup>
            </select>
        </div>
        <div className="flex-1">
             <label className="text-gray-300 text-sm block mb-1">Tanggal</label>
             <input 
                type="date" 
                value={tanggal}
                max={todayStr} // UI constraint for future dates
                onChange={(e) => setTanggal(e.target.value)}
                className="w-full bg-gray-700 border border-gray-600 rounded px-3 py-2 text-white focus:border-primary"
             />
        </div>
      </div>

      {/* Alert Block for Holiday/Future */}
      {isHoliday && holidayInfo && (
        <div className={`mb-6 p-4 rounded-lg flex items-start gap-3 border ${
            holidayInfo.jenis === 'FUTURE_DATE' 
            ? 'bg-gray-700/50 border-gray-600 text-gray-300' 
            : 'bg-red-900/30 border-red-600/50 text-red-200'
        }`}>
            <span className="text-2xl">{holidayInfo.jenis === 'FUTURE_DATE' ? '⏳' : '🚫'}</span>
            <div>
                <h4 className={`font-bold ${holidayInfo.jenis === 'FUTURE_DATE' ? 'text-gray-200' : 'text-red-100'}`}>
                    {holidayInfo.jenis === 'FUTURE_DATE' ? 'Tanggal Belum Dapat Diisi' : 'Tidak dapat menginput kehadiran'}
                </h4>
                <p className="text-sm">
                    Status: <strong>{holidayInfo.jenis === 'FUTURE_DATE' ? 'Masa Depan' : holidayInfo.jenis.replace(/_/g, ' ')}</strong>.
                    {holidayInfo.keterangan && <span className="block mt-1 italic opacity-80">"{holidayInfo.keterangan}"</span>}
                </p>
            </div>
        </div>
      )}

      {/* Main Content */}
      {!selectedKelas ? (
          <div className="p-10 text-center text-gray-500 border-2 border-dashed border-gray-700 rounded-lg">
              Silakan pilih kelas terlebih dahulu.
          </div>
      ) : loadingSiswa ? (
          <div className="p-10 text-center text-gray-400">Memuat data siswa...</div>
      ) : siswaList.length === 0 ? (
          <div className="p-10 text-center text-gray-500 bg-gray-800 rounded-lg">
              Tidak ada siswa ditemukan.
          </div>
      ) : (
          <div className="space-y-4">
               {/* Action Buttons */}
               <div className="flex flex-col md:flex-row justify-between items-center bg-gray-800 p-4 rounded-lg border border-gray-700 sticky top-0 z-10 gap-3">
                   <div className="text-gray-300 text-sm">
                       Total Siswa: <span className="text-white font-bold">{selectedKelas === 'ALL' ? totalStudents : siswaList.length}</span>
                       {selectedKelas === 'ALL' && <span className="text-gray-500 text-xs ml-2">(Menampilkan {siswaList.length} baris)</span>}
                       {isDataSaved && isEditing && <span className="ml-3 px-2 py-1 bg-yellow-600 text-white rounded text-xs font-bold animate-pulse">MODE EDIT</span>}
                   </div>
                   <div className="flex gap-2">
                       {/* BUTTON LOGIC:
                           If Holiday: ALL DISABLED (Except maybe cancel if editing active, but editing disabled anyway)
                           Else If Saved & Not Editing: Show Edit/Delete
                           Else (Not Saved OR Editing): Show Save/Cancel
                       */}
                       {isHoliday ? (
                           <span className="text-red-400 text-sm font-bold italic py-2">Input Dikunci</span>
                       ) : isDataSaved && !isEditing ? (
                           <>
                               <button onClick={() => setIsEditing(true)} className="bg-yellow-600 hover:bg-yellow-700 text-white px-4 py-2 rounded font-medium shadow-lg text-sm">✏️ Edit</button>
                               <button onClick={() => setShowDeleteConfirm(true)} className="bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded font-medium shadow-lg text-sm">🗑️ Hapus</button>
                           </>
                       ) : (
                           <>
                               {isEditing && (
                                   <button onClick={() => { setIsEditing(false); fetchKehadiran(); }} className="bg-gray-600 hover:bg-gray-500 text-white px-4 py-2 rounded text-sm">Batal</button>
                               )}
                               <button onClick={handleSaveOrUpdate} disabled={processing} className="bg-green-600 hover:bg-green-700 text-white px-6 py-2 rounded font-bold shadow-lg disabled:opacity-50 text-sm">
                                   {processing ? 'Menyimpan...' : '💾 Simpan Data'}
                               </button>
                           </>
                       )}
                   </div>
               </div>

               {/* Table */}
               <div className="bg-gray-800 shadow overflow-hidden rounded-lg border border-gray-700">
                  <div className="overflow-x-auto">
                      <table className="min-w-full divide-y divide-gray-700">
                          <thead className="bg-gray-700">
                              <tr>
                                  <th className="px-6 py-3 text-center text-xs font-medium text-gray-300 uppercase w-10">No</th>
                                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Nama Siswa</th>
                                  {selectedKelas === 'ALL' && (
                                     <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Kelas</th>
                                  )}
                                  <th className="px-6 py-3 text-center text-xs font-medium text-gray-300 uppercase w-20">L/P</th>
                                  <th className="px-6 py-3 text-center text-xs font-medium text-gray-300 uppercase">Status</th>
                                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-300 uppercase">Catatan</th>
                              </tr>
                          </thead>
                          <tbody className={`bg-gray-800 divide-y divide-gray-700 ${isHoliday ? 'opacity-60 grayscale-[50%]' : ''}`}>
                              {siswaList.map((s, idx) => {
                                  // Row numbering calculation based on pagination
                                  const rowNumber = selectedKelas === 'ALL' ? startRowIndex + idx + 1 : idx + 1;

                                  return (
                                  <tr key={s.id} className="hover:bg-gray-750">
                                      <td className="px-6 py-4 text-center text-gray-500 text-sm">{rowNumber}</td>
                                      <td className="px-6 py-4">
                                          <div className="text-sm font-bold text-white">{s.nama}</div>
                                          <div className="text-xs text-gray-400">{s.nisn}</div>
                                      </td>
                                      {selectedKelas === 'ALL' && (
                                         <td className="px-6 py-4 text-sm text-blue-300">
                                             {s.kelas?.nama || '-'}
                                         </td>
                                      )}
                                      <td className="px-6 py-4 text-center text-sm text-gray-300">{s.jenis_kelamin}</td>
                                      <td className="px-6 py-4">
                                          <div className="flex items-center justify-center gap-2 md:gap-4">
                                              <RadioOption id_siswa={s.id} val="HADIR" label="H" activeColorClass="bg-green-600" />
                                              <RadioOption id_siswa={s.id} val="IZIN" label="I" activeColorClass="bg-blue-600" />
                                              <RadioOption id_siswa={s.id} val="SAKIT" label="S" activeColorClass="bg-yellow-600" />
                                              <RadioOption id_siswa={s.id} val="ALPHA" label="A" activeColorClass="bg-red-600" />
                                          </div>
                                      </td>
                                      <td className="px-6 py-4">
                                          <input 
                                              type="text"
                                              value={formData[s.id]?.catatan || ''}
                                              onChange={(e) => handleCatatanChange(s.id, e.target.value)}
                                              disabled={isHoliday || (isDataSaved && !isEditing)}
                                              placeholder={isHoliday ? "Terkunci" : "Ket..."}
                                              className="bg-gray-700 border border-gray-600 text-white text-sm rounded px-3 py-2 w-full disabled:opacity-50 disabled:cursor-not-allowed"
                                          />
                                      </td>
                                  </tr>
                              )})}
                          </tbody>
                      </table>
                  </div>

                  {/* Pagination Controls - Only show if ALL Classes selected */}
                  {selectedKelas === 'ALL' && (
                      <div className="bg-gray-700 px-4 py-3 border-t border-gray-600 flex flex-col md:flex-row items-center justify-between gap-4">
                          <div className="flex items-center gap-2">
                              <span className="text-sm text-gray-300">Tampilkan</span>
                              <select 
                                value={rowsPerPage}
                                onChange={(e) => {
                                    setRowsPerPage(Number(e.target.value));
                                    setCurrentPage(1);
                                }}
                                className="bg-gray-800 border border-gray-500 text-white text-sm rounded px-2 py-1 focus:outline-none"
                              >
                                  <option value={10}>10</option>
                                  <option value={50}>50</option>
                                  <option value={100}>100</option>
                                  <option value={200}>200</option>
                              </select>
                              <span className="text-sm text-gray-300">baris per halaman</span>
                          </div>

                          <div className="flex items-center gap-4">
                              <span className="text-sm text-gray-300">
                                  Halaman <strong>{currentPage}</strong> dari <strong>{totalPages}</strong>
                              </span>
                              <div className="flex gap-1">
                                  <button
                                    onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                                    disabled={currentPage === 1}
                                    className="px-3 py-1 bg-gray-600 hover:bg-gray-500 text-white rounded disabled:opacity-50 disabled:cursor-not-allowed"
                                  >
                                      &laquo; Prev
                                  </button>
                                  <button
                                    onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
                                    disabled={currentPage === totalPages}
                                    className="px-3 py-1 bg-gray-600 hover:bg-gray-500 text-white rounded disabled:opacity-50 disabled:cursor-not-allowed"
                                  >
                                      Next &raquo;
                                  </button>
                              </div>
                          </div>
                      </div>
                  )}
               </div>
          </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../supabaseClient';

interface ActivityLog {
  id: string;
  created_at: string;
  status: 'HADIR' | 'SAKIT' | 'IZIN' | 'ALPHA';
  siswa: { nama: string };
  guru: { nama: string };
}

interface MissingRecord {
  tanggal: string;
  nama_siswa: string;
  nama_guru: string;
}

interface GroupedMissing {
  guru: string;
  items: MissingRecord[];
}

export const AdminDashboard: React.FC = () => {
  const [stats, setStats] = useState({ guru: 0, siswa: 0, kelas: 0, mapel: 0 });
  const [activities, setActivities] = useState<ActivityLog[]>([]);
  const [loading, setLoading] = useState(true);

  // Monitoring State
  const [isMonitorOpen, setIsMonitorOpen] = useState(false);
  const [monitorMonth, setMonitorMonth] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM
  const [monitorLoading, setMonitorLoading] = useState(false);
  const [missingData, setMissingData] = useState<GroupedMissing[]>([]);
  const [checkPerformed, setCheckPerformed] = useState(false);

  useEffect(() => {
    fetchStats();
    fetchActivities();

    // Realtime Subscription for Activities
    const channel = supabase
      .channel('dashboard_activities')
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'kehadiran' }, (payload) => {
         // When new attendance is inserted, fetch specific details to update UI
         fetchNewActivity(payload.new.id);
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  const fetchStats = async () => {
    try {
      const [guru, siswa, kelas, mapel] = await Promise.all([
        supabase.from('guru').select('*', { count: 'exact', head: true }),
        supabase.from('siswa').select('*', { count: 'exact', head: true }),
        supabase.from('kelas').select('*', { count: 'exact', head: true }),
        supabase.from('mapel').select('*', { count: 'exact', head: true }),
      ]);

      setStats({
        guru: guru.count || 0,
        siswa: siswa.count || 0,
        kelas: kelas.count || 0,
        mapel: mapel.count || 0,
      });
    } catch (error) {
      console.error('Error fetching stats:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchActivities = async () => {
    // Get start of yesterday
    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    yesterday.setHours(0, 0, 0, 0);
    const dateStr = yesterday.toISOString();

    const { data } = await supabase
      .from('kehadiran')
      .select('id, created_at, status, siswa(nama), guru(nama)')
      .gte('created_at', dateStr)
      .order('created_at', { ascending: false })
      .limit(10);

    if (data) {
        // @ts-ignore
        setActivities(data);
    }
  };

  const fetchNewActivity = async (id: string) => {
      const { data } = await supabase
        .from('kehadiran')
        .select('id, created_at, status, siswa(nama), guru(nama)')
        .eq('id', id)
        .single();

      if (data) {
          // @ts-ignore
          setActivities(prev => [data, ...prev].slice(0, 10));
      }
  };

  const timeAgo = (dateStr: string) => {
      const date = new Date(dateStr);
      const now = new Date();
      const diffInSeconds = Math.floor((now.getTime() - date.getTime()) / 1000);

      if (diffInSeconds < 60) return 'Baru saja';
      const minutes = Math.floor(diffInSeconds / 60);
      if (minutes < 60) return `${minutes} menit lalu`;
      const hours = Math.floor(minutes / 60);
      if (hours < 24) return `${hours} jam lalu`;
      return 'Kemarin';
  };

  const getStatusColor = (status: string) => {
      switch(status) {
          case 'HADIR': return 'bg-green-500/20 text-green-400 border-green-500/50';
          case 'SAKIT': return 'bg-yellow-500/20 text-yellow-400 border-yellow-500/50';
          case 'IZIN': return 'bg-blue-500/20 text-blue-400 border-blue-500/50';
          case 'ALPHA': return 'bg-red-500/20 text-red-400 border-red-500/50';
          default: return 'bg-gray-500/20 text-gray-400';
      }
  };

  const getStatusIcon = (status: string) => {
      switch(status) {
          case 'HADIR': return '✅';
          case 'SAKIT': return '🤒';
          case 'IZIN': return '📩';
          case 'ALPHA': return '❌';
          default: return '❓';
      }
  };

  // --- LOGIC MONITORING ---
  const handleCheckCompleteness = async () => {
      setMonitorLoading(true);
      setCheckPerformed(false);
      setMissingData([]);

      try {
          // 1. Get Settings (Hari Sekolah)
          const { data: sekolah } = await supabase.from('sekolah').select('hari_sekolah').limit(1).maybeSingle();
          const hariSekolah = sekolah?.hari_sekolah || 5;

          // 2. Define Date Range
          const [year, month] = monitorMonth.split('-');
          const startDate = new Date(parseInt(year), parseInt(month) - 1, 1);
          const endDate = new Date(parseInt(year), parseInt(month), 0); // Last day of month
          const today = new Date();
          today.setHours(0, 0, 0, 0);

          // Batasi endDate tidak boleh melebihi hari ini (karena masa depan belum wajib input)
          const checkUntil = endDate > today ? today : endDate;

          // 3. Get Holidays
          const { data: holidays } = await supabase
            .from('kalender_pendidikan')
            .select('tanggal')
            .gte('tanggal', startDate.toISOString())
            .lte('tanggal', checkUntil.toISOString());

          const holidaySet = new Set(holidays?.map(h => h.tanggal));

          // 4. Generate Valid Active Days
          const validDates: string[] = [];
          let current = new Date(startDate);

          while (current <= checkUntil) {
              const day = current.getDay(); // 0=Sun, 6=Sat
              const dateStr = current.toISOString().split('T')[0];

              let isSchoolDay = true;
              if (day === 0) isSchoolDay = false; // Minggu Libur
              if (hariSekolah === 5 && day === 6) isSchoolDay = false; // Sabtu Libur jika 5 hari

              if (isSchoolDay && !holidaySet.has(dateStr)) {
                  validDates.push(dateStr);
              }

              current.setDate(current.getDate() + 1);
          }

          if (validDates.length === 0) {
              setCheckPerformed(true);
              setMonitorLoading(false);
              return;
          }

          // 5. Get All Assignments (Siswa & Guru Wali)
          // Mengambil semua siswa yang punya guru wali
          const { data: assignments } = await supabase
            .from('bimbingan')
            .select('id_siswa, id_guru, siswa(nama), guru(nama)');

          if (!assignments || assignments.length === 0) {
              setCheckPerformed(true);
              setMonitorLoading(false);
              return;
          }

          // 6. Get Existing Attendance for this month
          // Optimasi: Hanya ambil field yang diperlukan untuk checking
          const { data: attendance } = await supabase
            .from('kehadiran')
            .select('id_siswa, tanggal')
            .gte('tanggal', validDates[0])
            .lte('tanggal', validDates[validDates.length - 1]);

          // Buat Set untuk lookup cepat: "YYYY-MM-DD_ID_SISWA"
          const attendanceSet = new Set(attendance?.map(a => `${a.tanggal}_${a.id_siswa}`));

          // 7. Cross Check
          const missing: MissingRecord[] = [];

          // Loop Tanggal Aktif -> Loop Siswa Binaan
          validDates.forEach(date => {
              assignments.forEach((b: any) => {
                  const key = `${date}_${b.id_siswa}`;
                  if (!attendanceSet.has(key)) {
                      missing.push({
                          tanggal: date,
                          nama_siswa: b.siswa?.nama || 'Unknown',
                          nama_guru: b.guru?.nama || 'Unknown'
                      });
                  }
              });
          });

          // 8. Grouping by Guru
          const groupedMap = new Map<string, MissingRecord[]>();
          missing.forEach(item => {
              if (!groupedMap.has(item.nama_guru)) {
                  groupedMap.set(item.nama_guru, []);
              }
              groupedMap.get(item.nama_guru)?.push(item);
          });

          // Sort by Date inside groups
          const groupedResult: GroupedMissing[] = [];
          groupedMap.forEach((items, guru) => {
              items.sort((a, b) => a.tanggal.localeCompare(b.tanggal));
              groupedResult.push({ guru, items });
          });

          // Sort Groups by Guru Name
          groupedResult.sort((a, b) => a.guru.localeCompare(b.guru));

          setMissingData(groupedResult);
          setCheckPerformed(true);

      } catch (error) {
          console.error("Error monitoring:", error);
      } finally {
          setMonitorLoading(false);
      }
  };

  const StatCard = ({ title, count, icon, color }: any) => (
    <div className={`bg-gray-800 p-6 rounded-xl shadow-lg border border-gray-700 relative overflow-hidden group hover:border-gray-500 transition-all duration-300`}>
      <div className={`absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity transform scale-150`}>
         <span className="text-6xl">{icon}</span>
      </div>
      <div>
        <h3 className="text-gray-400 text-sm font-bold uppercase tracking-wider">{title}</h3>
        <p className="text-4xl font-extrabold text-white mt-2">{loading ? '...' : count}</p>
      </div>
      <div className={`mt-4 h-1 w-full rounded bg-gray-700`}>
         <div className={`h-1 rounded ${color.replace('border-', 'bg-')} w-1/2`}></div>
      </div>
    </div>
  );

  return (
    <div className="p-2 md:p-6 space-y-8">
      <div>
        <h2 className="text-3xl font-bold text-white tracking-tight">Dashboard Overview</h2>
        <p className="text-gray-400 mt-1">Ringkasan data statistik dan aktivitas sistem.</p>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="Total Guru" count={stats.guru} icon="👩‍🏫" color="border-indigo-500" />
        <StatCard title="Total Siswa" count={stats.siswa} icon="🎓" color="border-green-500" />
        <StatCard title="Total Kelas" count={stats.kelas} icon="🏫" color="border-yellow-500" />
        <StatCard title="Mata Pelajaran" count={stats.mapel} icon="📘" color="border-red-500" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Left Column: System Status */}
          <div className="lg:col-span-1 space-y-6">
              {/* REPLACED WELCOME CARD WITH MONITORING BUTTON */}
              <div className="bg-gradient-to-br from-blue-900 to-indigo-900 p-6 rounded-xl border border-blue-700 shadow-lg text-white">
                  <h3 className="font-bold text-lg mb-2">👋 Kontrol Kehadiran</h3>
                  <p className="text-blue-200 text-sm mb-4">
                      Cek kelengkapan input kehadiran siswa oleh Wali Kelas secara otomatis.
                  </p>
                  <button 
                    onClick={() => setIsMonitorOpen(true)}
                    className="w-full bg-white text-blue-900 py-3 rounded-lg text-sm font-bold hover:bg-blue-50 transition shadow-md flex items-center justify-center gap-2"
                  >
                      <span>🔍</span> Monitoring Kehadiran
                  </button>
              </div>

              <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-lg">
                <h3 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
                    <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                    Status Server
                </h3>
                <div className="space-y-4">
                    <div className="flex justify-between items-center p-3 bg-gray-700/30 rounded-lg">
                        <span className="text-gray-400 text-sm">Database</span>
                        <span className="text-green-400 text-xs font-bold bg-green-900/30 px-2 py-1 rounded">ONLINE</span>
                    </div>
                    <div className="flex justify-between items-center p-3 bg-gray-700/30 rounded-lg">
                        <span className="text-gray-400 text-sm">Realtime Listener</span>
                        <span className="text-green-400 text-xs font-bold bg-green-900/30 px-2 py-1 rounded">ACTIVE</span>
                    </div>
                    <div className="flex justify-between items-center p-3 bg-gray-700/30 rounded-lg">
                        <span className="text-gray-400 text-sm">Versi Aplikasi</span>
                        <span className="text-blue-400 text-xs font-bold">v1.0.0</span>
                    </div>
                </div>
              </div>
          </div>

          {/* Right Column: Activity Feed */}
          <div className="lg:col-span-2">
              <div className="bg-gray-800 rounded-xl border border-gray-700 shadow-lg flex flex-col h-full max-h-[500px]">
                  <div className="p-6 border-b border-gray-700 flex justify-between items-center bg-gray-800/50 sticky top-0 z-10 backdrop-blur-sm rounded-t-xl">
                      <div>
                          <h3 className="text-lg font-bold text-white flex items-center gap-2">
                              ⚡ Aktivitas Terbaru
                          </h3>
                          <p className="text-xs text-gray-400 mt-1">Monitor input kehadiran (Hari ini & Kemarin)</p>
                      </div>
                      <span className="text-xs bg-gray-700 text-gray-300 px-2 py-1 rounded-full border border-gray-600">
                          Live Updates
                      </span>
                  </div>

                  <div className="overflow-y-auto p-4 space-y-3 custom-scrollbar">
                      {activities.length === 0 ? (
                          <div className="flex flex-col items-center justify-center h-40 text-gray-500">
                              <span className="text-3xl mb-2">💤</span>
                              <p className="text-sm">Belum ada aktivitas baru.</p>
                          </div>
                      ) : (
                          activities.map((act) => (
                              <div key={act.id} className="flex items-start gap-4 p-4 rounded-lg bg-gray-700/20 hover:bg-gray-700/40 border border-gray-700/50 transition-all duration-200 animate-slide-in">
                                  {/* Icon Avatar */}
                                  <div className={`w-10 h-10 rounded-full flex items-center justify-center text-lg flex-shrink-0 bg-gray-700 border border-gray-600 shadow-sm`}>
                                      {getStatusIcon(act.status)}
                                  </div>

                                  {/* Content */}
                                  <div className="flex-1 min-w-0">
                                      <div className="flex justify-between items-start">
                                          <p className="text-sm text-gray-200 leading-snug">
                                              <span className="font-bold text-blue-400">{act.guru?.nama || 'Guru'}</span>
                                              <span className="text-gray-400 mx-1">menginput</span>
                                              <span className="font-bold text-white">{act.siswa?.nama || 'Siswa'}</span>
                                          </p>
                                          <span className="text-[10px] font-medium text-gray-500 whitespace-nowrap ml-2">
                                              {timeAgo(act.created_at)}
                                          </span>
                                      </div>
                                      <div className="mt-2 flex items-center gap-2">
                                          <span className={`text-[10px] px-2 py-0.5 rounded border ${getStatusColor(act.status)} font-bold`}>
                                              {act.status}
                                          </span>
                                          <span className="text-[10px] text-gray-500">
                                              • {new Date(act.created_at).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' })}
                                          </span>
                                      </div>
                                  </div>
                              </div>
                          ))
                      )}
                  </div>

                  <div className="p-3 border-t border-gray-700 text-center bg-gray-800/50 rounded-b-xl">
                      <p className="text-[10px] text-gray-500">Menampilkan 10 aktivitas terakhir</p>
                  </div>
              </div>
          </div>
      </div>

      {/* --- MODAL MONITORING --- */}
      {isMonitorOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-80 p-4 backdrop-blur-sm">
            <div className="bg-gray-800 rounded-xl shadow-2xl border border-gray-700 w-full max-w-4xl max-h-[90vh] flex flex-col">
                {/* Header */}
                <div className="p-6 border-b border-gray-700 flex justify-between items-center bg-gray-800 rounded-t-xl">
                    <div>
                        <h3 className="text-xl font-bold text-white flex items-center gap-2">
                            <span>🕵️</span> Monitoring Kelengkapan Input
