                                                    </td>
                                                    <td className="px-4 py-2 text-gray-300">
                                                        {item.nama_siswa}
                                                    </td>
                                                    <td className="px-4 py-2 text-center">
                                                        <span className="text-xs font-bold text-red-400 border border-red-900/50 bg-red-900/20 px-2 py-1 rounded">
