            </div>
            <div className="bg-gray-800 p-6 rounded-lg border border-green-500 border-l-4">
                <h3 className="text-gray-400 text-sm uppercase font-bold">Total Siswa</h3>
                <p className="text-3xl font-bold text-white mt-1">{loading ? '...' : stats.siswa}</p>
            </div>
            <div className="bg-gray-800 p-6 rounded-lg border border-purple-500 border-l-4">
                <h3 className="text-gray-400 text-sm uppercase font-bold">Total Kelas</h3>
                <p className="text-3xl font-bold text-white mt-1">{loading ? '...' : stats.kelas}</p>
            </div>
             <div className="bg-gray-800 p-6 rounded-lg border border-yellow-500 border-l-4">
                <h3 className="text-gray-400 text-sm uppercase font-bold">Mata Pelajaran</h3>
                <p className="text-3xl font-bold text-white mt-1">{loading ? '...' : stats.mapel}</p>
